def model_short(name: str) -> str:
    for table in (MODELS, TILE_MODELS):
        if name in table:
            return str(table[name]["short"])
    return ""


def model_stack_key(model_name: str) -> str:
    return str(MODELS.get(model_name, {}).get("template_set", "krea"))


def model_supports(model_name: str, feature: str) -> bool:
    """True when the generation model supports a prompt-side feature
    ("templates" / "tags" / "loras" / "negative")."""
    return bool(model_features(model_name).get(feature, True))


