def resolve_theme_key(name: str) -> str:
    """Resolve legacy, display-name, or alias theme keys safely to a canonical flagship key."""
    raw = str(name or "").strip().lower().replace(" ", "_").replace("-", "_")
    raw = THEME_ALIASES.get(raw, raw)
    return raw if raw in THEMES else "seestation"


