# v19 unified dropdown scale system: 1.00 == clean 100% baseline (9.6pt base font —
# crisp on 800x600 laptops and scales smoothly up to 150% on HiDPI screens via the
# UI Scale % dropdown menu with ZERO clamping mismatch across QSS, delegates & chrome).
SCALE_REFERENCE: float = 1.00
SCALE_MIN: float = 0.75   # 75% compact display
SCALE_MAX: float = 1.50   # 150% large display
UI_SCALE_PRESETS: Tuple[int, ...] = (75, 80, 85, 90, 95, 100, 105, 110, 115, 120, 125, 135, 150)
_UI_SCALE: float = SCALE_REFERENCE
_LOW_POWER_MODE: bool = False


def low_power_mode() -> bool:
    return _LOW_POWER_MODE


def set_low_power_mode(enabled: bool) -> bool:
    global _LOW_POWER_MODE
    val = bool(enabled)
    if val != _LOW_POWER_MODE:
        _LOW_POWER_MODE = val
        _THEME_BACKDROP_CACHE.clear()
        _BEVEL_DECK_CACHE.clear()
        _QSS_CACHE.clear()
        if "VECTOR_ASSETS" in globals():
            try:
                VECTOR_ASSETS.invalidate_theme()
            except Exception:  # noqa: BLE001
                pass
    if "ANIM_CLOCK" in globals():
        ANIM_CLOCK.set_low_power(_LOW_POWER_MODE)
    return _LOW_POWER_MODE


def ui_scale() -> float:
    """Active global UI scale factor (0.75..1.50) shared uniformly by QSS & painters."""
    return _UI_SCALE


def set_ui_scale(scale: float) -> float:
    global _UI_SCALE
    _UI_SCALE = max(SCALE_MIN, min(SCALE_MAX, float(scale)))
    return _UI_SCALE


def scale_percent(eff: float) -> int:
    """Displayed percentage for an effective scale factor (1.00 -> 100%)."""
    return int(round((float(eff) / SCALE_REFERENCE) * 100.0))


def scale_for_percent(pct: int) -> float:
    """Convert an integer UI percentage (75..150) into the unified scale multiplier."""
    clamped = max(int(round(SCALE_MIN * 100)), min(int(round(SCALE_MAX * 100)), int(pct)))
    return round((clamped / 100.0) * SCALE_REFERENCE, 4)


def nearest_scale_preset(eff: float) -> int:
    """Return the closest preset percentage in UI_SCALE_PRESETS for clean dropdown sync."""
    target = scale_percent(eff)
    return min(UI_SCALE_PRESETS, key=lambda p: (abs(p - target), p))


def step_scale_preset(eff: float, direction: int) -> float:
    """Step cleanly up (+1) or down (-1) through UI_SCALE_PRESETS for Ctrl++/Ctrl+-."""
    cur_pct = nearest_scale_preset(eff)
    try:
        idx = UI_SCALE_PRESETS.index(cur_pct)
    except ValueError:
        idx = UI_SCALE_PRESETS.index(100)
    nxt_idx = max(0, min(len(UI_SCALE_PRESETS) - 1, idx + (1 if direction > 0 else -1)))
    return scale_for_percent(UI_SCALE_PRESETS[nxt_idx])


def default_scale_for_screen() -> float:
    """Pick an ideal crisp dropdown preset for the host display resolution
    (90% on 800x600 / 1024x600 compact laptops, 100% standard, 110% on 1080p+ displays)."""
    try:
        scr = QGuiApplication.primaryScreen()
        if scr is not None:
            av = scr.availableGeometry()
            if av.width() <= 860 or av.height() <= 620:
                return scale_for_percent(90)
            if av.width() <= 1152 or av.height() <= 740:
                return scale_for_percent(100)
            return scale_for_percent(110)
    except Exception:  # noqa: BLE001
        pass
    return SCALE_REFERENCE


def migrate_legacy_scale(raw: Any, is_v2: bool = False) -> float:
    """Migrate pre-v12 font_scale / font_scale_v2 cleanly into v12 unified range."""
    try:
        val = float(raw)
    except (TypeError, ValueError):
        return default_scale_for_screen()
    if val <= 0.0:
        return default_scale_for_screen()
    if is_v2:
        # v11 stored effective multiplier around 1.40 as 100%; normalize to v12
        val = val / 1.40
    return max(SCALE_MIN, min(SCALE_MAX, val))


