_THEME_BACKDROP_CACHE: "collections.OrderedDict[Tuple[str, int, int, bool], QPixmap]" = collections.OrderedDict()
_THEME_BACKDROP_MAX = 8
_BEVEL_DECK_CACHE: "collections.OrderedDict[Tuple[str, int, int, bool], QPixmap]" = collections.OrderedDict()
_BEVEL_DECK_MAX = 10
_QSS_CACHE: "collections.OrderedDict[Tuple[str, int, bool], str]" = collections.OrderedDict()
_QSS_CACHE_MAX = 16


def _chamfer_path(r: QRectF, ch: float) -> QPainterPath:
    """Crisp 45-degree Deus Ex: HR octagonal chamfered frame."""
    c = max(0.0, min(ch, r.width() * 0.35, r.height() * 0.35))
    path = QPainterPath()
    path.moveTo(r.left() + c, r.top())
    path.lineTo(r.right() - c, r.top())
    path.lineTo(r.right(), r.top() + c)
    path.lineTo(r.right(), r.bottom() - c)
    path.lineTo(r.right() - c, r.bottom())
    path.lineTo(r.left() + c, r.bottom())
    path.lineTo(r.left(), r.bottom() - c)
    path.lineTo(r.left(), r.top() + c)
    path.closeSubpath()
    return path


def _theme_frame_path(
    r: QRectF,
    tkey: Optional[str] = None,
    rad_see: float = 7.0,
    ch_gold: float = 5.0,
) -> QPainterPath:
    """Return the signature silhouette path for the active design language."""
    k = resolve_theme_key(tkey or C.get("key", "seestation"))
    path = QPainterPath()
    if k == "seestation":
        path.addRoundedRect(r, rad_see, rad_see)
        return path
    if k == "kreatendo":
        rad_k = min(r.width() * 0.35, r.height() * 0.45, rad_see + 3.0)
        path.addRoundedRect(r, rad_k, rad_k)
        return path
    if k == "mint":
        rad_m = min(r.width() * 0.35, r.height() * 0.42, max(4.5, rad_see - 0.5))
        path.addRoundedRect(r, rad_m, rad_m)
        return path
    if k == "timeless":
        rad_t = min(r.width() * 0.28, r.height() * 0.36, max(4.0, rad_see - 1.5))
        path.addRoundedRect(r, rad_t, rad_t)
        return path
    if k == "prestige":
        rad_p = min(r.width() * 0.32, r.height() * 0.44, max(5.5, rad_see + 1.0))
        path.addRoundedRect(r, rad_p, rad_p)
        return path
    if k == "gold":
        return _chamfer_path(r, ch_gold)
    path.addRect(r)
    return path


def paint_theme_backdrop(painter: QPainter, rect: QRect, theme_key: Optional[str] = None) -> None:
    """LRU-cached, low-RAM signature backdrop per flagship design language (v16.0):
    - SeeStation: Sony/SCE PS3 XMB silk-wave aurora, PS4 lightbar glow & 4 symbols
    - Sarif Gold: Deus Ex: HR cyber-renaissance isometric triangle mosaic & amber HUD
    - Oriental Spirit: Kuro-Urushi neutral jet-black lacquer, vermilion sun-ring, Asanoha & kintsugi gold trim
    - Kreatendo: Nintendo Wii / Wii U / DS / 3DS LIGHT porcelain channel glass with Aqua-Sky
      disc-slot lightbar, Miiverse Mint glow, Wii scanlines, channel tile grid & DS/3DS colorful emblem
    - Mint Serenity: Linux Mint Cinnamon / Mint-Y-Dark evergreen-charcoal botanical canvas
      with organic leaf-vein ribbons, canopy dew bokeh, alpine-jade mist & Mint Leaf emblem
    - Timeless Feel: Nostalgic art-house twilight limestone sanctuary with sunlit dust shafts,
      distant mist-wrapped viaduct arches, surreal silhouette horizon & delicate modern rings
    - Prestige: Classic late-2000s OS X & iOS brushed satin-aluminum studio canvas with soft
      overhead glass glow, fine pinstripe linen grain & refined Aqua sapphire horizon
    """
    w, h = max(1, rect.width()), max(1, rect.height())
    k = resolve_theme_key(theme_key or C.get("key", "seestation"))
    lp = low_power_mode()
    ck = (k, w, h, lp)
    pm = _THEME_BACKDROP_CACHE.get(ck)
    if pm is not None:
        _THEME_BACKDROP_CACHE.move_to_end(ck)
    else:
        pm = QPixmap(w, h)
        p = QPainter(pm)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, not lp)
        bg = QLinearGradient(0, 0, 0, h)
        if lp:
            bg.setColorAt(0.0, QColor(C["win"]))
            bg.setColorAt(1.0, QColor(C["win2"]))
            p.fillRect(0, 0, w, h, bg)
            bar = QLinearGradient(0, 0, w, 0)
            bar.setColorAt(0.0, QColor(0, 0, 0, 0))
            bar.setColorAt(0.24, QColor(C["acc_mid"]))
            bar.setColorAt(0.50, QColor(C["acc_hi"]))
            bar.setColorAt(0.76, QColor(C["info"] if k in ("kreatendo", "mint", "timeless", "prestige") else C["acc_mid"]))
            bar.setColorAt(1.0, QColor(0, 0, 0, 0))
            p.setPen(QPen(QBrush(bar), 2.0))
            p.drawLine(QPointF(12, 1.5), QPointF(max(12, w - 12), 1.5))
        elif k == "seestation":
            bg.setColorAt(0.0, QColor("#081a3b"))
            bg.setColorAt(0.42, QColor("#040e24"))
            bg.setColorAt(1.0, QColor("#02050d"))
            p.fillRect(0, 0, w, h, bg)
            rad = QRadialGradient(w * 0.24, h * 0.14, max(w, h) * 0.82)
            rad.setColorAt(0.0, QColor(0, 150, 255, 76))
            rad.setColorAt(0.46, QColor(12, 80, 174, 32))
            rad.setColorAt(1.0, QColor(0, 0, 0, 0))
            p.fillRect(0, 0, w, h, rad)
            rad2 = QRadialGradient(w * 0.82, h * 0.82, max(w, h) * 0.58)
            rad2.setColorAt(0.0, QColor(92, 208, 255, 40))
            rad2.setColorAt(1.0, QColor(0, 0, 0, 0))
            p.fillRect(0, 0, w, h, rad2)
            for y0, amp, alpha, lw in (
                (0.29, 0.14, 48, 2.3),
                (0.40, 0.18, 34, 1.7),
                (0.52, 0.12, 26, 1.25),
                (0.64, 0.15, 20, 1.0),
                (0.76, 0.10, 15, 0.8),
            ):
                ribbon = QPainterPath()
                ribbon.moveTo(-24, h * y0)
                ribbon.cubicTo(
                    w * 0.27, h * (y0 - amp),
                    w * 0.67, h * (y0 + amp * 1.18),
                    w + 24, h * (y0 - amp * 0.42),
                )
                band = QPainterPath(ribbon)
                band.lineTo(w + 24, h * (y0 + 0.14))
                band.cubicTo(
                    w * 0.65, h * (y0 + amp * 1.48),
                    w * 0.27, h * (y0 - amp * 0.44),
                    -24, h * (y0 + 0.11),
                )
                band.closeSubpath()
                fg = QLinearGradient(0, h * (y0 - amp), 0, h * (y0 + amp + 0.15))
                fg.setColorAt(0.0, QColor(102, 210, 255, alpha))
                fg.setColorAt(0.50, QColor(0, 120, 230, int(alpha * 0.54)))
                fg.setColorAt(1.0, QColor(0, 62, 140, 0))
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(fg)
                p.drawPath(band)
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.setPen(QPen(QColor(216, 244, 255, min(255, alpha + 38)), lw))
                p.drawPath(ribbon)
            p.setPen(Qt.PenStyle.NoPen)
            for mx, my, mr, ma in (
                (0.11, 0.19, 2.8, 52), (0.28, 0.67, 1.9, 44), (0.55, 0.25, 3.2, 38),
                (0.76, 0.46, 2.1, 48), (0.88, 0.18, 2.6, 42), (0.43, 0.81, 1.7, 36),
                (0.20, 0.43, 1.5, 58), (0.68, 0.73, 2.3, 40), (0.84, 0.61, 1.6, 46),
            ):
                p.setBrush(QColor(186, 234, 255, ma // 2))
                p.drawEllipse(QPointF(w * mx, h * my), mr * 2.1, mr * 2.1)
                p.setBrush(QColor(235, 250, 255, ma))
                p.drawEllipse(QPointF(w * mx, h * my), mr, mr)
            # PS4 vertical glass reflection sheen + DualShock top lightbar bloom
            pillar = QLinearGradient(w * 0.62, 0, w * 0.84, h)
            pillar.setColorAt(0.0, QColor(120, 212, 255, 22))
            pillar.setColorAt(0.55, QColor(0, 112, 209, 10))
            pillar.setColorAt(1.0, QColor(0, 0, 0, 0))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(pillar)
            p.drawPolygon(QPolygonF([
                QPointF(w * 0.64, 0), QPointF(w * 0.80, 0),
                QPointF(w * 0.66, h), QPointF(w * 0.50, h),
            ]))
            top_bar = QLinearGradient(0, 0, w, 0)
            top_bar.setColorAt(0.0, QColor(0, 140, 255, 0))
            top_bar.setColorAt(0.25, QColor(56, 178, 255, 108))
            top_bar.setColorAt(0.50, QColor(176, 236, 255, 152))
            top_bar.setColorAt(0.75, QColor(56, 178, 255, 108))
            top_bar.setColorAt(1.0, QColor(0, 140, 255, 0))
            p.setPen(QPen(QBrush(top_bar), 2.1))
            p.drawLine(QPointF(16, 2), QPointF(w - 16, 2))
            if w >= 220 and h >= 140:
                bx, by = w - 84.0, h - 24.0
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.setPen(QPen(QColor(86, 228, 152, 66), 1.45))
                p.drawPolygon(QPolygonF([QPointF(bx, by + 9), QPointF(bx + 5, by), QPointF(bx + 10, by + 9)]))
                p.setPen(QPen(QColor(246, 110, 110, 66), 1.45))
                p.drawEllipse(QPointF(bx + 23, by + 4.5), 4.6, 4.6)
                p.setPen(QPen(QColor(106, 194, 255, 72), 1.45))
                p.drawLine(QPointF(bx + 36, by + 0.5), QPointF(bx + 44, by + 8.5))
                p.drawLine(QPointF(bx + 44, by + 0.5), QPointF(bx + 36, by + 8.5))
                p.setPen(QPen(QColor(228, 130, 238, 66), 1.45))
                p.drawRect(QRectF(bx + 54, by + 0.5, 8.5, 8.5))
        elif k == "oriental":
            bg.setColorAt(0.0, QColor("#090909"))
            bg.setColorAt(0.45, QColor("#040404"))
            bg.setColorAt(1.0, QColor("#000000"))
            p.fillRect(0, 0, w, h, bg)
            mx_c, my_c = w * 0.78, h * 0.24
            aura = QRadialGradient(mx_c, my_c, max(w, h) * 0.46)
            aura.setColorAt(0.0, QColor(235, 10, 8, 52))
            aura.setColorAt(0.32, QColor(145, 0, 0, 20))
            aura.setColorAt(0.70, QColor(40, 0, 0, 7))
            aura.setColorAt(1.0, QColor(0, 0, 0, 0))
            p.fillRect(0, 0, w, h, aura)
            if w >= 200 and h >= 140:
                mr = min(w, h) * 0.17
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QColor(0, 0, 0, 224))
                p.drawEllipse(QPointF(mx_c, my_c), mr * 0.86, mr * 0.86)
                p.setBrush(Qt.BrushStyle.NoBrush)
                # Ceremonial vermilion Enso eclipse ring + Kintsugi gold halo
                p.setPen(QPen(QColor(248, 18, 12, 74), 2.1))
                p.drawArc(QRectF(mx_c - mr * 0.90, my_c - mr * 0.90, mr * 1.80, mr * 1.80), 32 * 16, 316 * 16)
                p.setPen(QPen(QColor(222, 174, 84, 38), 1.0))
                p.drawEllipse(QPointF(mx_c, my_c), mr * 1.11, mr * 1.11)
            # Subtle Kumiko Asanoha stars + Kintsugi Seigaiha traditional wave-arc weave
            p.setPen(QPen(QColor(225, 16, 12, 20), 0.75))
            p.setBrush(Qt.BrushStyle.NoBrush)
            step = 44.0
            for gy in range(0, int(h // step) + 2):
                for gx in range(0, int(w // step) + 2):
                    cx = gx * step + (step * 0.5 if gy % 2 else 0.0)
                    cy = gy * step
                    if (gx + gy) % 3 == 0:
                        d = step * 0.32
                        p.drawLine(QPointF(cx - d, cy), QPointF(cx + d, cy))
                        p.drawLine(QPointF(cx, cy - d), QPointF(cx, cy + d))
                        p.drawLine(QPointF(cx - d * 0.68, cy - d * 0.68), QPointF(cx + d * 0.68, cy + d * 0.68))
                        p.drawLine(QPointF(cx + d * 0.68, cy - d * 0.68), QPointF(cx - d * 0.68, cy + d * 0.68))
                    elif (gx * 2 + gy) % 5 == 0 and gy > 1:
                        p.setPen(QPen(QColor(220, 172, 82, 20), 0.75))
                        for rr in (10.0, 16.0):
                            p.drawArc(QRectF(cx - rr, cy - rr, rr * 2.0, rr * 2.0), 20 * 16, 140 * 16)
                        p.setPen(QPen(QColor(225, 16, 12, 20), 0.75))
            slash = QLinearGradient(w * 0.14, h * 0.92, w * 0.92, h * 0.10)
            slash.setColorAt(0.0, QColor(240, 0, 0, 0))
            slash.setColorAt(0.45, QColor(255, 22, 16, 40))
            slash.setColorAt(0.55, QColor(255, 224, 212, 62))
            slash.setColorAt(1.0, QColor(240, 0, 0, 0))
            p.setPen(QPen(QBrush(slash), 1.8))
            p.drawLine(QPointF(w * 0.12, h * 0.94), QPointF(w * 0.92, h * 0.08))
            # Top Torii-lacquer vermilion beam + parallel Kintsugi 24k gold hairline
            p.setPen(QPen(QColor(245, 16, 10, 132), 2.2))
            p.drawLine(QPointF(0, 1.5), QPointF(w, 1.5))
            p.setPen(QPen(QColor(222, 174, 84, 72), 0.95))
            p.drawLine(QPointF(18, 5.5), QPointF(w - 18, 5.5))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(255, 22, 16, 178))
            p.drawPolygon(QPolygonF([QPointF(0, 0), QPointF(17, 0), QPointF(0, 17)]))
            p.setBrush(QColor(196, 8, 6, 148))
            p.drawPolygon(QPolygonF([QPointF(w, h), QPointF(w - 15, h), QPointF(w, h - 15)]))
            # Authentic bottom-right Hanko vermilion lacquer chop seal emblem
            if w >= 220 and h >= 140:
                sx, sy, ssz = w - 42.0, h - 42.0, 22.0
                p.setBrush(QColor(214, 12, 8, 48))
                p.setPen(QPen(QColor(250, 34, 26, 128), 1.35))
                p.drawRect(QRectF(sx, sy, ssz, ssz))
                p.setPen(QPen(QColor(224, 178, 88, 96), 0.85))
                p.drawRect(QRectF(sx + 3.0, sy + 3.0, ssz - 6.0, ssz - 6.0))
                p.setPen(QPen(QColor(255, 86, 76, 136), 1.35))
                p.drawLine(QPointF(sx + 5.0, sy + 7.8), QPointF(sx + ssz - 5.0, sy + 7.8))
                p.drawLine(QPointF(sx + 6.4, sy + 11.2), QPointF(sx + ssz - 6.4, sy + 11.2))
                p.drawLine(QPointF(sx + 8.4, sy + 7.8), QPointF(sx + 8.4, sy + ssz - 5.0))
                p.drawLine(QPointF(sx + ssz - 8.4, sy + 7.8), QPointF(sx + ssz - 8.4, sy + ssz - 5.0))
        elif k == "kreatendo":
            # Nintendo Wii / Wii U / DS / 3DS LIGHT ceramic porcelain & sky-channel canvas
            bg.setColorAt(0.0, QColor("#fafdff"))
            bg.setColorAt(0.48, QColor("#ecf5fe"))
            bg.setColorAt(1.0, QColor("#dcebf9"))
            p.fillRect(0, 0, w, h, bg)
            # Joyful translucent Wii U WaraWara-style pastel atmospheric glows
            l_glow = QRadialGradient(w * 0.14, h * 0.14, max(w, h) * 0.68)
            l_glow.setColorAt(0.0, QColor(0, 178, 245, 48))
            l_glow.setColorAt(0.45, QColor(90, 205, 255, 18))
            l_glow.setColorAt(1.0, QColor(255, 255, 255, 0))
            p.fillRect(0, 0, w, h, l_glow)
            r_glow = QRadialGradient(w * 0.86, h * 0.82, max(w, h) * 0.58)
            r_glow.setColorAt(0.0, QColor(28, 206, 132, 42))
            r_glow.setColorAt(0.50, QColor(255, 190, 46, 18))
            r_glow.setColorAt(1.0, QColor(255, 255, 255, 0))
            p.fillRect(0, 0, w, h, r_glow)
            # Classic Wii Menu clean horizontal silver-sky pinstripe scanlines
            p.setPen(QPen(QColor(135, 178, 218, 30), 1.0))
            for sy in range(8, h, 10):
                p.drawLine(0, sy, w, sy)
            # Glossy white ceramic dome reflection sweep across top viewport
            arc = QPainterPath()
            arc.moveTo(-24, h * 0.30)
            arc.quadTo(w * 0.50, h * 0.10, w + 24, h * 0.28)
            arc.lineTo(w + 24, 0)
            arc.lineTo(-24, 0)
            arc.closeSubpath()
            hg = QLinearGradient(0, 0, 0, h * 0.32)
            hg.setColorAt(0.0, QColor(255, 255, 255, 178))
            hg.setColorAt(1.0, QColor(255, 255, 255, 0))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(hg)
            p.drawPath(arc)
            # Soft rounded Wii Channel / 3DS HOME grid tile cards with subtle corner gems
            tile_step = 72
            for gy in range(18, h - 24, tile_step):
                for gx in range(18, w - 24, tile_step):
                    idx_t = (gx // tile_step) + (gy // tile_step)
                    if idx_t % 3 == 0:
                        p.setBrush(QColor(255, 255, 255, 62))
                        p.setPen(QPen(QColor(115, 175, 224, 48), 1.0))
                        p.drawRoundedRect(QRectF(gx, gy, 46, 32), 9.5, 9.5)
                        accent_cols = ((0, 156, 224, 58), (22, 184, 119, 58), (245, 166, 0, 62), (232, 65, 82, 52))
                        p.setPen(Qt.PenStyle.NoPen)
                        p.setBrush(QColor(*accent_cols[(idx_t // 3) % 4]))
