def apply_palette(app: QApplication) -> None:
    """Install a matching QPalette so native pixels (tooltip, selection,
    disabled states) stay inside the lacquer aesthetic."""
    pal = QPalette()
    base = QColor(C["deep"])
    text = QColor(C["text"])
    hi = QColor(C["text_hi"])
    btn = QColor(C["btn_mid"])
    window = QColor(C["win"])
    accent = QColor(C["acc_mid"])
    pal.setColor(QPalette.ColorRole.Window, window)
    pal.setColor(QPalette.ColorRole.WindowText, text)
    pal.setColor(QPalette.ColorRole.Base, base)
    pal.setColor(QPalette.ColorRole.AlternateBase, QColor(C["win"]))
    pal.setColor(QPalette.ColorRole.Text, hi)
    pal.setColor(QPalette.ColorRole.Button, btn)
    pal.setColor(QPalette.ColorRole.ButtonText, text)
    pal.setColor(QPalette.ColorRole.Highlight, QColor(C["sel_bg"]))
    pal.setColor(QPalette.ColorRole.HighlightedText, hi)
    pal.setColor(QPalette.ColorRole.ToolTipBase, QColor(C["deep"]))
    pal.setColor(QPalette.ColorRole.ToolTipText, hi)
    pal.setColor(QPalette.ColorRole.PlaceholderText, QColor(C["dim"]))
    pal.setColor(QPalette.ColorRole.BrightText, QColor(C["acc_spec"]))
    pal.setColor(QPalette.ColorRole.Light, QColor(C["plate_edge_top"]))
    pal.setColor(QPalette.ColorRole.Midlight, QColor(C["plate_hi"]))
    pal.setColor(QPalette.ColorRole.Dark, QColor(C["plate_edge"]))
    pal.setColor(QPalette.ColorRole.Mid, QColor(C["line"]))
    pal.setColor(QPalette.ColorGroup.Disabled, QPalette.ColorRole.Window, window)
    pal.setColor(QPalette.ColorGroup.Disabled, QPalette.ColorRole.Base, QColor(C["plate_lo"]))
    pal.setColor(QPalette.ColorGroup.Disabled, QPalette.ColorRole.Button, QColor(C["btn_lo"]))
    pal.setColor(QPalette.ColorGroup.Disabled, QPalette.ColorRole.Text, QColor(C["dim"]))
    pal.setColor(QPalette.ColorGroup.Disabled, QPalette.ColorRole.ButtonText, QColor(C["dim"]))
    pal.setColor(QPalette.ColorGroup.Disabled, QPalette.ColorRole.WindowText, QColor(C["dim"]))
    pal.setColor(QPalette.ColorRole.Link, accent)
    pal.setColor(QPalette.ColorRole.LinkVisited, accent)
    app.setPalette(pal)


# =============================================================================
#  5. Embedded Multi-Layer Vector Artwork (v10.0 Corporate Icon Foundry)
#     Engineered for instant 50ms recognizability at 12px-28px across
#     SeeStation, Sarif Gold, and Oriental Spirit with 3x HiDPI supersampling.
# =============================================================================
def _svg_defs_common(p: Dict[str, str]) -> str:
    """Reusable metallic, lacquer, specular, and glow SVG gradients for active theme."""
    return (
        "<defs>"
        f"<linearGradient id='mGold' x1='0%' y1='0%' x2='100%' y2='100%'>"
        f"<stop offset='0%' stop-color='{p['svg_metal_1']}'/>"
        f"<stop offset='42%' stop-color='{p['svg_metal_2']}'/>"
        f"<stop offset='82%' stop-color='{p['svg_metal_3']}'/>"
        f"<stop offset='100%' stop-color='{p['svg_metal_4']}'/>"
        "</linearGradient>"
        f"<linearGradient id='mVert' x1='0%' y1='0%' x2='0%' y2='100%'>"
        f"<stop offset='0%' stop-color='{p['svg_metal_1']}'/>"
        f"<stop offset='48%' stop-color='{p['svg_metal_2']}'/>"
        f"<stop offset='54%' stop-color='{p['svg_metal_3']}'/>"
        f"<stop offset='100%' stop-color='{p['svg_metal_4']}'/>"
        "</linearGradient>"
        f"<linearGradient id='bodyLac' x1='0%' y1='0%' x2='0%' y2='100%'>"
        f"<stop offset='0%' stop-color='{p['svg_body_1']}'/>"
        f"<stop offset='55%' stop-color='{p['svg_body_2']}'/>"
        f"<stop offset='100%' stop-color='{p['svg_body_3']}'/>"
        "</linearGradient>"
        f"<linearGradient id='glassArc' x1='0%' y1='0%' x2='0%' y2='100%'>"
        f"<stop offset='0%' stop-color='{p['svg_glass']}' stop-opacity='0.58'/>"
        f"<stop offset='65%' stop-color='{p['svg_glass']}' stop-opacity='0.10'/>"
        f"<stop offset='100%' stop-color='{p['svg_glass']}' stop-opacity='0.0'/>"
        "</linearGradient>"
        f"<radialGradient id='coreGlow' cx='50%' cy='44%' r='52%'>"
        f"<stop offset='0%' stop-color='{p['svg_glass']}' stop-opacity='0.94'/>"
        f"<stop offset='34%' stop-color='{p['svg_metal_1']}' stop-opacity='0.88'/>"
        f"<stop offset='72%' stop-color='{p['svg_metal_2']}' stop-opacity='0.58'/>"
        f"<stop offset='100%' stop-color='{p['svg_metal_4']}' stop-opacity='0.0'/>"
        "</radialGradient>"
        f"<radialGradient id='bounce' cx='50%' cy='92%' r='55%'>"
        f"<stop offset='0%' stop-color='{p['svg_bounce']}' stop-opacity='0.44'/>"
        f"<stop offset='100%' stop-color='{p['svg_bounce']}' stop-opacity='0.0'/>"
        "</radialGradient>"
        f"<radialGradient id='rimLight' cx='50%' cy='8%' r='70%'>"
        f"<stop offset='0%' stop-color='{p['svg_glass']}' stop-opacity='0.24'/>"
        f"<stop offset='60%' stop-color='{p['svg_glass']}' stop-opacity='0.0'/>"
        "</radialGradient>"
        "</defs>"
    )


def _seestation_four_symbols(cx: float = 32.0, cy: float = 32.0, size: float = 28.0, stroke: float = 2.1) -> str:
    """Mathematically centered Sony PlayStation four-symbol motif
    (triangle / circle / cross / square) in a tight 2x2 grid centered at (cx, cy)."""
    q = size * 0.25
    r = size * 0.145
    x1, x2 = cx - q, cx + q
    y1, y2 = cy - q, cy + q
    return (
        f"<g>"
        f"<path d='M{x1 - r:.2f},{y1 + r * 0.88:.2f} L{x1 + r:.2f},{y1 + r * 0.88:.2f} L{x1:.2f},{y1 - r:.2f} Z' "
        f"fill='none' stroke='#46d482' stroke-width='{stroke:.2f}' stroke-linejoin='round'/>"
        f"<circle cx='{x2:.2f}' cy='{y1:.2f}' r='{r:.2f}' fill='none' stroke='#f06565' stroke-width='{stroke:.2f}'/>"
        f"<path d='M{x1 - r * 0.88:.2f},{y2 - r * 0.88:.2f} L{x1 + r * 0.88:.2f},{y2 + r * 0.88:.2f} "
        f"M{x1 + r * 0.88:.2f},{y2 - r * 0.88:.2f} L{x1 - r * 0.88:.2f},{y2 + r * 0.88:.2f}' "
        f"stroke='#62b2ff' stroke-width='{stroke:.2f}' stroke-linecap='round'/>"
        f"<rect x='{x2 - r * 0.88:.2f}' y='{y2 - r * 0.88:.2f}' width='{r * 1.76:.2f}' height='{r * 1.76:.2f}' "
        f"rx='{max(0.6, r * 0.18):.2f}' fill='none' stroke='#db6ee0' stroke-width='{stroke:.2f}'/>"
        "</g>"
    )


def _icon_duotone(p: Dict[str, str]) -> Tuple[str, str, str]:
    """Return crisp (primary_light, vivid_accent, deep_core) for clean icon readability across all 7 themes."""
    k = resolve_theme_key(p.get("key", "seestation"))
    if k == "oriental":
        return ("#f5f5f5", "#ff1c14", "#080808")
    if k == "seestation":
        return ("#eef7ff", "#4db8ff", "#071429")
    if k == "kreatendo":
        return ("#173454", "#009ce0", "#f4faff")
    if k == "mint":
        return ("#eef7f0", "#7ad66d", "#141f18")
    if k == "timeless":
        return ("#f7f1e3", "#e4c685", "#1a1c21")
    if k == "prestige":
        return ("#1c2736", "#2b7ce0", "#eef2f8")
    return ("#fff6d6", "#ffc83b", "#140f06")


