def build_svg_document(asset_key: str, palette: Optional[Dict[str, str]] = None) -> str:
    """Return a complete, valid multi-layer SVG string for the given UI/UX asset
    rendered in the active theme's aesthetic across all 7 flagship themes."""
    p = palette or C
    defs = _svg_defs_common(p)
    k = resolve_theme_key(p.get("key", "seestation"))
    is_oriental = (k == "oriental")
    is_seestation = (k == "seestation")
    shell = _tab_shell_svg(p)
    pri, acc, core = _icon_duotone(p)

    is_kreatendo = (k == "kreatendo")
    is_mint = (k == "mint")
    is_timeless = (k == "timeless")
    is_prestige = (k == "prestige")

