                f"<path d='M6,51 C19,43 27,57 40,49 C50,43 56,50 60,46' fill='none' stroke='{p['svg_metal_1']}' "
                "stroke-opacity='0.76' stroke-width='1.7' stroke-linecap='round'/>"
