MINI_ICON_KEYS: Set[str] = set(_MINI_ICON_MOTIFS.keys())


def build_mini_icon_svg(kind: str, palette: Optional[Dict[str, str]] = None) -> str:
    """24x24 full-bleed bold duotone vector glyph engineered for instant 50ms
    recognizability at 12px-16px toolbar scale across all 3 East-Asian themes.
    Zero cramped outer box clutter — maximum silhouette clarity and contrast."""
    p = palette or C
    defs = _svg_defs_common(p)
    pri, acc, core = _icon_duotone(p)
    motif_tpl = _MINI_ICON_MOTIFS.get(kind) or _MINI_ICON_MOTIFS["info"]
    motif = motif_tpl.format(pri=pri, acc=acc, core=core)
    return (
        f"<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'>{defs}"
        f"{motif}</svg>"
    )


class VectorAssetEngine:
    """High-DPI 3x-oversampled LRU-cached vector renderer for embedded SVG assets."""

    def __init__(self) -> None:
        self._cache: "collections.OrderedDict[Tuple[str, str, int, int, bool], QPixmap]" = collections.OrderedDict()

    def invalidate_theme(self) -> None:
        self._cache.clear()

    def pixmap_for_theme(
        self, asset_key: str, tkey: str, width: int, height: Optional[int] = None, disabled: bool = False
    ) -> QPixmap:
        w = max(8, int(width))
        h = max(8, int(height if height is not None else w))
        resolved = resolve_theme_key(tkey)
        pal = THEMES.get(resolved, C)
        ckey = (asset_key, pal["key"], w, h, bool(disabled))
        cached = self._cache.get(ckey)
        if cached is not None:
            self._cache.move_to_end(ckey)
            return cached
        scr_dpr = 1.0
        if not low_power_mode():
            try:
                app_i = QApplication.instance()
                if isinstance(app_i, QApplication) and app_i.primaryScreen() is not None:
                    scr_dpr = float(app_i.primaryScreen().devicePixelRatio())
            except Exception:  # noqa: BLE001
                scr_dpr = 1.0
        # Low-end laptop optimization: 100%-DPI screens render cleanly at 1x (75% less icon RAM/CPU);
        # HiDPI displays (>1.05x) still get crisp 2x vector supersampling.
        dpr = 1 if (low_power_mode() or scr_dpr <= 1.05) else min(2, int(math.ceil(scr_dpr)))
        pm = QPixmap(w * dpr, h * dpr)
        pm.fill(Qt.GlobalColor.transparent)
        pm.setDevicePixelRatio(float(dpr))
        if _HAS_QTSVG and QSvgRenderer is not None:
            if asset_key in MINI_ICON_KEYS:
                svg_bytes = build_mini_icon_svg(asset_key, pal).encode("utf-8")
            else:
                svg_bytes = build_svg_document(asset_key, pal).encode("utf-8")
            renderer = QSvgRenderer(QByteArray(svg_bytes))
            painter = QPainter(pm)
            painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
            painter.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)
            if disabled:
                painter.setOpacity(0.36)
            renderer.render(painter, QRectF(0, 0, w, h))
            painter.end()
        else:
            self._fallback_paint(pm, asset_key)
        self._cache[ckey] = pm
        max_entries = 280 if low_power_mode() else 480
        while len(self._cache) > max_entries:
            self._cache.popitem(last=False)
        return pm

    def pixmap(self, asset_key: str, width: int, height: Optional[int] = None) -> QPixmap:
        return self.pixmap_for_theme(asset_key, theme_name(), width, height)

    def icon(self, asset_key: str, size: int = 20) -> QIcon:
        return self.icon_for_theme(asset_key, theme_name(), size)

    def icon_for_theme(self, asset_key: str, tkey: str, size: int = 20) -> QIcon:
        ic = QIcon()
        ic.addPixmap(self.pixmap_for_theme(asset_key, tkey, size, size, disabled=False), QIcon.Mode.Normal)
        ic.addPixmap(self.pixmap_for_theme(asset_key, tkey, size, size, disabled=True), QIcon.Mode.Disabled)
        return ic

    @staticmethod
    def _fallback_paint(pm: QPixmap, asset_key: str) -> None:
        painter = QPainter(pm)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        w, h = pm.width(), pm.height()
        grad = QLinearGradient(0, 0, 0, h)
        grad.setColorAt(0.0, QColor(C["acc_spec"]))
        grad.setColorAt(0.45, QColor(C["acc_hi"]))
        grad.setColorAt(1.0, QColor(C["acc_lo"]))
        painter.setBrush(QBrush(grad))
        painter.setPen(QPen(QColor(C["acc_edge"]), 1.2))
        margin = max(2.0, w * 0.14)
        painter.drawRoundedRect(QRectF(margin, margin, w - 2 * margin, h - 2 * margin), 3, 3)
        painter.end()


