_EAST_ASIAN_FONT_FAMILIES: List[str] = [
    "Segoe UI",
    "Yu Gothic UI",
    "Meiryo UI",
    "Microsoft YaHei UI",
    "Malgun Gothic",
    "PingFang SC",
    "Hiragino Sans",
    "Noto Sans CJK JP",
    "Noto Sans CJK SC",
    "Noto Sans CJK KR",
    "Noto Sans",
    "DejaVu Sans",
]


_FONT_CACHE: Dict[Tuple[float, bool, float], QFont] = {}


def _font(size: float, bold: bool = False, spacing: float = 0.0) -> QFont:
    key = (round(max(6.5, float(size)), 2), bool(bold), round(float(spacing), 2))
    hit = _FONT_CACHE.get(key)
    if hit is not None:
        return hit
    f = QFont()
    f.setFamilies(_EAST_ASIAN_FONT_FAMILIES)
    f.setPointSizeF(key[0])
    f.setBold(key[1])
    f.setStyleStrategy(QFont.StyleStrategy.PreferAntialias)
    if key[2]:
        f.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, key[2])
    if len(_FONT_CACHE) > 256:
        _FONT_CACHE.clear()
    _FONT_CACHE[key] = f
    return f


