def resolve_sound_mode(raw: Any, legacy_enabled: Optional[bool] = None) -> str:
    """Resolve persisted audio mode cleanly with seamless migration from legacy enabled bool."""
    val = str(raw or "").strip().lower()
    if val in (SOUND_MODE_ALL, SOUND_MODE_IMPORTANT, SOUND_MODE_NONE):
        return val
    if val in ("on", "true", "full", "all_sounds"):
        return SOUND_MODE_ALL
    if val in ("notify", "notifications", "important_only", "primary"):
        return SOUND_MODE_IMPORTANT
    if val in ("off", "false", "mute", "muted", "silent"):
        return SOUND_MODE_NONE
    if legacy_enabled is not None:
        return SOUND_MODE_ALL if bool(legacy_enabled) else SOUND_MODE_NONE
    return SOUND_MODE_ALL


# =============================================================================
#  6a. Sound Foundry (v25.0) — Seven Original Theme Sound Schemes
#      100% embedded pure-Python DSP. Every scheme uses its OWN synthesis
#      technique, scale and room so no two themes share a sonic signature:
#        seestation  Crystal Wave    FM glass bells, detuned pads, bubble pops
#        gold        Amber Circuit   resonant filtered pulse, relay ticks, scans
#        oriental    Lacquer & Silk  Karplus-Strong plucked strings, wood, bells
#        kreatendo   Plaza Pop       pitch-bent pops, mallets, glockenspiel
#        mint        Morning Dew     water droplets, breath flute, kalimba
#        timeless    Hollow Stone    felt piano, far horn, wind, stone cavern
#        prestige    Studio Glass    inharmonic FM "tink", marimba, soft tock
#      Cues are rendered once, peak-balanced per event class, cached in RAM and
#      persisted to data/sounds/ so low-end laptops never re-synthesize them.
# =============================================================================
_SF_RATE = 22050
_SF_VERSION = "sf2"
_SF_TWO_PI = 2.0 * math.pi
_SF_NYQUIST_SAFE = _SF_RATE * 0.46

# Partial tables: (frequency ratio, amplitude, decay multiplier)
_P_SINE = ((1.0, 1.0, 1.0),)
_P_SOFT = ((1.0, 1.0, 1.0), (2.0, 0.12, 1.6))
_P_PAD = ((1.0, 1.0, 1.0), (1.004, 0.70, 1.0), (2.0, 0.22, 1.3), (0.5, 0.25, 1.0))
_P_PIANO = ((1.0, 1.0, 1.0), (2.002, 0.42, 1.5), (3.007, 0.22, 2.1), (4.016, 0.11, 2.9), (5.03, 0.05, 3.8))
_P_MARIMBA = ((1.0, 1.0, 1.0), (3.93, 0.28, 3.2), (9.5, 0.07, 6.5))
_P_KALIMBA = ((1.0, 1.0, 1.0), (5.42, 0.16, 4.5), (2.0, 0.07, 2.0))
_P_BOWL = ((1.0, 1.0, 1.0), (2.71, 0.40, 1.2), (5.15, 0.18, 1.8))
_P_TRI = ((1.0, 1.0, 1.0), (3.0, 0.111, 1.2), (5.0, 0.04, 1.5))
_P_FLUTE = ((1.0, 1.0, 1.0), (2.0, 0.16, 1.2), (3.0, 0.05, 1.5))
_P_HORN = ((1.0, 1.0, 1.0), (2.0, 0.34, 1.1), (3.0, 0.20, 1.2), (4.0, 0.08, 1.5))


def _sf_span(buf: List[float], t0: float, dur: float) -> Tuple[int, int]:
    """Clamp a (start, duration) pair to the buffer; returns (first index, sample count)."""
    i0 = max(0, int(t0 * _SF_RATE))
    return i0, min(int(dur * _SF_RATE), len(buf) - i0)


def _sf_tone(
    buf: List[float], freq: float, t0: float, dur: float, gain: float,
    parts: Sequence[Sequence[float]] = _P_SINE, atk: float = 0.004, dec: float = 7.0,
    gl: float = 0.0, bend: float = 0.0, bend_t: float = 0.02, vib: float = 0.0, vib_hz: float = 5.2,
) -> None:
    """Additive voice. `gl` glides N semitones across the note, `bend` is a start
    pitch offset (semitones) that relaxes within `bend_t` seconds, `vib` is vibrato depth."""
    i0, n = _sf_span(buf, t0, dur)
    if n < 8 or freq <= 0.0:
        return
    na = max(1, int(atk * _SF_RATE))
    nr = max(8, min(int(0.010 * _SF_RATE), n // 4))
    rel0 = n - nr
    inv_na, inv_nr = 1.0 / na, 1.0 / nr
    glide_k = 2.0 ** (gl / 12.0 / n) if gl else 1.0
    b0 = (2.0 ** (bend / 12.0) - 1.0) if bend else 0.0
    b_k = math.exp(-1.0 / (max(0.002, bend_t) * _SF_RATE))
    vw = _SF_TWO_PI * vib_hz / _SF_RATE
    top = max(1.0, 2.0 ** (gl / 12.0), 1.0 + b0)
    modulated = bool(gl or bend or vib)
    sin = math.sin
    for part in parts:
        ratio = float(part[0])
        if freq * ratio * top > _SF_NYQUIST_SAFE:
            continue
        a = gain * float(part[1])
        k = math.exp(-dec * (float(part[2]) if len(part) > 2 else 1.0) / _SF_RATE)
        w = _SF_TWO_PI * freq * ratio / _SF_RATE
        ph = 0.0
        if not modulated:
            for i in range(n):
                if i < na:
                    e = a * i * inv_na
                elif i >= rel0:
                    e = a * (n - i) * inv_nr
                else:
                    e = a
                buf[i0 + i] += e * sin(ph)
                ph += w
                a *= k
        else:
            b = b0
            for i in range(n):
                if i < na:
                    e = a * i * inv_na
                elif i >= rel0:
                    e = a * (n - i) * inv_nr
                else:
                    e = a
                buf[i0 + i] += e * sin(ph)
                ph += w * (1.0 + b) * ((1.0 + vib * sin(vw * i)) if vib else 1.0)
                w *= glide_k
                b *= b_k
                a *= k


def _sf_fm(
    buf: List[float], freq: float, t0: float, dur: float, gain: float,
    ratio: float = 2.0, index: float = 1.5, idx_dec: float = 18.0, atk: float = 0.002, dec: float = 8.0,
    gl: float = 0.0, bend: float = 0.0, bend_t: float = 0.02,
) -> None:
    """Two-operator FM voice (bells, glass, metallic glints). The modulation index is
    clamped so sidebands stay below Nyquist, then decays for a natural 'strike'."""
    i0, n = _sf_span(buf, t0, dur)
    if n < 8 or freq <= 0.0:
        return
    index = min(index, max(0.2, (_SF_NYQUIST_SAFE / freq - 1.0) / max(0.5, ratio) - 1.0))
    na = max(1, int(atk * _SF_RATE))
    nr = max(8, min(int(0.010 * _SF_RATE), n // 4))
    rel0 = n - nr
    inv_na, inv_nr = 1.0 / na, 1.0 / nr
    w = _SF_TWO_PI * freq / _SF_RATE
    glide_k = 2.0 ** (gl / 12.0 / n) if gl else 1.0
    b = (2.0 ** (bend / 12.0) - 1.0) if bend else 0.0
    b_k = math.exp(-1.0 / (max(0.002, bend_t) * _SF_RATE))
    a_k = math.exp(-dec / _SF_RATE)
    i_k = math.exp(-idx_dec / _SF_RATE)
    a, idx, phc, phm = gain, index, 0.0, 0.0
    sin = math.sin
    for i in range(n):
        if i < na:
            e = a * i * inv_na
        elif i >= rel0:
            e = a * (n - i) * inv_nr
        else:
            e = a
        buf[i0 + i] += e * sin(phc + idx * sin(phm))
        step = w * (1.0 + b)
        phc += step
        phm += step * ratio
        w *= glide_k
        b *= b_k
        a *= a_k
        idx *= i_k


def _sf_pluck(
    buf: List[float], freq: float, t0: float, dur: float, gain: float,
    bright: float = 0.6, damp: float = 0.997, pick: float = 0.7, seed: int = 7,
) -> None:
    """Karplus-Strong plucked string with fractional-delay tuning (koto / shamisen)."""
    i0, n = _sf_span(buf, t0, dur)
    if n < 8 or freq <= 0.0:
        return
    period = _SF_RATE / freq
    size = int(period)
    if size < 2:
        return
    frac = period - size
    lcg = (seed * 2654435761 + int(freq * 97.0)) & 0xFFFFFFFF
    line: List[float] = []
    prev = 0.0
    for _ in range(size + 1):
        lcg = (lcg * 1664525 + 1013904223) & 0xFFFFFFFF
        prev += pick * (((lcg >> 8) / 8388608.0 - 1.0) - prev)
        line.append(prev)
    mean = sum(line) / len(line)
    line = [v - mean for v in line]
    ln = size + 1
    nr = max(8, min(int(0.012 * _SF_RATE), n // 4))
    rel0 = n - nr
    inv_nr = 1.0 / nr
    p, z = 0, 0.0
    one_minus = 1.0 - frac
    for i in range(n):
        oldest = line[p]
        q = p + 1
        if q == ln:
            q = 0
        z += bright * ((one_minus * line[q] + frac * oldest) * damp - z)
        line[p] = z
        p = q
        buf[i0 + i] += z * gain * ((n - i) * inv_nr if i >= rel0 else 1.0)


def _sf_noise(
    buf: List[float], freq: float, t0: float, dur: float, gain: float,
    q: float = 1.5, gl: float = 0.0, atk: float = 0.002, dec: float = 30.0, mode: str = "bp", seed: int = 3,
) -> None:
    """Filtered noise voice: 'bp' / 'lp' use a state-variable filter (sweepable with
    `gl` semitones), 'hp' is an airy one-pole high-pass for breath, leaves and air."""
    i0, n = _sf_span(buf, t0, dur)
    if n < 8:
        return
    na = max(1, int(atk * _SF_RATE))
    nr = max(8, min(int(0.012 * _SF_RATE), n // 4))
    rel0 = n - nr
    inv_na, inv_nr = 1.0 / na, 1.0 / nr
    a = gain
    a_k = math.exp(-dec / _SF_RATE)
    lcg = (seed * 40503 + int(freq)) & 0xFFFFFFFF
    if mode == "hp":
        coef = math.exp(-_SF_TWO_PI * min(freq, 9000.0) / _SF_RATE)
        lp = 0.0
        for i in range(n):
            lcg = (lcg * 1664525 + 1013904223) & 0xFFFFFFFF
            x = (lcg >> 8) / 8388608.0 - 1.0
            lp = x + coef * (lp - x)
            if i < na:
                e = a * i * inv_na
            elif i >= rel0:
                e = a * (n - i) * inv_nr
            else:
                e = a
            buf[i0 + i] += e * (x - lp)
            a *= a_k
        return
    f = 2.0 * math.sin(math.pi * min(max(40.0, freq), 3400.0) / _SF_RATE)
    f_max = 2.0 * math.sin(math.pi * 3400.0 / _SF_RATE)
    f_k = 2.0 ** (gl / 12.0 / n) if gl else 1.0
    q_damp = 1.0 / max(0.5, q)
    comp = 0.55 + 0.45 * max(0.5, q) if mode == "bp" else 1.0
    low = band = 0.0
    is_bp = mode == "bp"
    for i in range(n):
        lcg = (lcg * 1664525 + 1013904223) & 0xFFFFFFFF
        x = (lcg >> 8) / 8388608.0 - 1.0
        low += f * band
        band += f * (x - low - q_damp * band)
        if i < na:
            e = a * i * inv_na
        elif i >= rel0:
            e = a * (n - i) * inv_nr
        else:
            e = a
        buf[i0 + i] += e * comp * (band if is_bp else low)
        a *= a_k
        if gl:
            f = min(f_max, f * f_k)


def _sf_pulse(
    buf: List[float], freq: float, t0: float, dur: float, gain: float,
    duty: float = 0.5, cut: float = 2000.0, cut_gl: float = 0.0, q: float = 1.2,
    atk: float = 0.002, dec: float = 10.0, gl: float = 0.0,
) -> None:
    """Pulse oscillator through a resonant sweeping low-pass (analog HUD / chip voice)."""
    i0, n = _sf_span(buf, t0, dur)
    if n < 8 or freq <= 0.0:
        return
    na = max(1, int(atk * _SF_RATE))
    nr = max(8, min(int(0.010 * _SF_RATE), n // 4))
    rel0 = n - nr
    inv_na, inv_nr = 1.0 / na, 1.0 / nr
    a = gain
    a_k = math.exp(-dec / _SF_RATE)
    step = freq / _SF_RATE
    step_k = 2.0 ** (gl / 12.0 / n) if gl else 1.0
    f = 2.0 * math.sin(math.pi * min(max(60.0, cut), 3400.0) / _SF_RATE)
    f_max = 2.0 * math.sin(math.pi * 3400.0 / _SF_RATE)
    f_min = 2.0 * math.sin(math.pi * 60.0 / _SF_RATE)
    f_k = 2.0 ** (cut_gl / 12.0 / n) if cut_gl else 1.0
    q_damp = 1.0 / max(0.5, q)
    ph = low = band = 0.0
    for i in range(n):
        x = 1.0 if ph < duty else -1.0
        ph += step
        if ph >= 1.0:
            ph -= 1.0
        low += f * band
        band += f * (x - low - q_damp * band)
        if i < na:
            e = a * i * inv_na
        elif i >= rel0:
            e = a * (n - i) * inv_nr
        else:
            e = a
        buf[i0 + i] += e * low
        a *= a_k
        step *= step_k
        if cut_gl:
            f = max(f_min, min(f_max, f * f_k))


def _sf_echo(buf: List[float], ms: float = 90.0, fb: float = 0.3, lp: float = 0.5) -> None:
    """In-place recirculating echo with a darkening low-pass in the feedback path."""
    d = int(ms * _SF_RATE / 1000.0)
    if d < 1 or d >= len(buf):
        return
    z = 0.0
    for i in range(d, len(buf)):
        z += lp * (buf[i - d] - z)
        buf[i] += z * fb


def _sf_reverb(buf: List[float], mix: float = 0.2, room: float = 0.8, damp: float = 0.35, lite: bool = False) -> None:
    """Compact Schroeder reverb (damped parallel combs -> series all-pass diffusers).
    `lite` halves the work for short UI micro-cues."""
    n = len(buf)
    wet = [0.0] * n
    keep = 1.0 - damp
    for d in ((557, 673) if lite else (557, 613, 673, 743)):
        if d >= n:
            continue
        comb = [0.0] * d
        p, z = 0, 0.0
        for i in range(n):
            y = comb[p]
            z = y * keep + z * damp
            comb[p] = buf[i] + z * room
            wet[i] += y
            p += 1
            if p == d:
                p = 0
    for d in ((139,) if lite else (139, 89)):
        ap = [0.0] * d
        p = 0
        for i in range(n):
            y = ap[p]
            x = wet[i]
            ap[p] = x + y * 0.5
            wet[i] = y - x * 0.5
            p += 1
            if p == d:
                p = 0
    g = mix * (0.5 if lite else 0.25)
    for i in range(n):
        buf[i] += wet[i] * g


_SF_PRIMS: Dict[str, Callable[..., None]] = {
    "tone": _sf_tone, "fm": _sf_fm, "pluck": _sf_pluck, "noise": _sf_noise, "pulse": _sf_pulse,
}

# Per-event-class peak targets keep every scheme balanced without manual mixing.
_SF_QUIET_UI = frozenset(("ui_hover", "ui_menu_hover", "ui_slider", "ui_resize"))


def _sf_peak_target(event: str) -> float:
    if event in _SF_QUIET_UI:
        return 0.34
    if event == "theme":
        return 0.72
    return 0.52 if event.startswith("ui_") else 0.82


