def depth_fx_active(fx: Optional[Dict[str, Any]]) -> bool:
    if not fx:
        return False
    return (
        int(fx.get("dof_strength", 0)) > 0
        or int(fx.get("haze_strength", 0)) > 0
        or int(fx.get("rim_strength", 0)) > 0
        or abs(int(fx.get("fg_pop", 0))) > 0
        or abs(int(fx.get("bg_dim", 0))) > 0
        or abs(int(fx.get("bg_cool", 0))) > 0
        or int(fx.get("bg_desat", 0)) > 0
        or int(fx.get("depth_ca", 0)) > 0
        or int(fx.get("depth_vignette", 0)) > 0
    )


def _hex_to_rgb(hex_col: str, fallback: Tuple[int, int, int] = (72, 120, 184)) -> Tuple[int, int, int]:
    c = QColor(str(hex_col or ""))
    if not c.isValid():
        return fallback
    return (c.red(), c.green(), c.blue())


def _build_turbo_lut() -> Tuple[bytes, bytes, bytes]:
    """Compact 256-entry cinema heatmap RGB LUT (0=deep indigo far -> cyan ->
    emerald -> gold -> 255=crimson-white near) for instant depth inspection."""
    stops = (
        (0.00, (14, 18, 56)),
        (0.22, (26, 98, 196)),
        (0.45, (32, 198, 210)),
        (0.68, (186, 224, 64)),
        (0.86, (252, 140, 36)),
        (1.00, (255, 58, 76)),
    )
    rr, gg, bb = bytearray(256), bytearray(256), bytearray(256)
    for i in range(256):
        t = i / 255.0
        for s0, s1 in zip(stops, stops[1:], strict=False):
            if s0[0] <= t <= s1[0]:
                u = (t - s0[0]) / max(1e-6, s1[0] - s0[0])
                rr[i] = int(round(s0[1][0] + (s1[1][0] - s0[1][0]) * u))
                gg[i] = int(round(s0[1][1] + (s1[1][1] - s0[1][1]) * u))
                bb[i] = int(round(s0[1][2] + (s1[1][2] - s0[1][2]) * u))
                break
    return bytes(rr), bytes(gg), bytes(bb)


_TURBO_LUT_RGB = _build_turbo_lut()


def _depth_norm_l_pil(
    depth_img: QImage, w: int, h: int, invert_polarity: bool = False, auto_norm: bool = True,
):
    """Return a PIL 'L' grayscale depth map resized to (w, h), normalized so
    255 = NEAR foreground and 0 = FAR background."""
    pil_d = _qimg_to_pil(depth_img).convert("L")
    if pil_d.size != (w, h):
        pil_d = pil_d.resize((w, h), _PIL_RESAMPLE_BI)
    if invert_polarity:
        pil_d = _PIL_OPS.invert(pil_d) if _PIL_OPS is not None else pil_d.point(lambda v: 255 - v)
    if auto_norm:
        lo, hi = pil_d.getextrema()
        if hi - lo >= 4 and (lo > 2 or hi < 253):
            span = float(hi - lo)
            lut = [max(0, min(255, int(round((v - lo) * 255.0 / span)))) for v in range(256)]
            pil_d = pil_d.point(lut)
    return pil_d


def _depth_norm_gray_qt(
    depth_img: QImage, w: int, h: int, invert_polarity: bool = False, auto_norm: bool = True,
) -> QImage:
    """Pure-Qt fast grayscale depth map (Format_Grayscale8, 255=NEAR, 0=FAR)."""
    g = depth_img.convertToFormat(QImage.Format.Format_Grayscale8)
    if g.width() != w or g.height() != h:
        g = g.scaled(w, h, Qt.AspectRatioMode.IgnoreAspectRatio, Qt.TransformationMode.SmoothTransformation)
        g = g.convertToFormat(QImage.Format.Format_Grayscale8)
    bpl = g.bytesPerLine()
    ptr = g.constBits()
    ptr.setsize(g.sizeInBytes())
    raw = bytes(memoryview(ptr).cast("B"))
    lo, hi = 255, 0
    if auto_norm:
        # Subsample every 4th row for instantaneous extrema scan
        for y in range(0, h, max(1, h // 64)):
            row = raw[y * bpl : y * bpl + w]
            if row:
                rlo, rhi = min(row), max(row)
                if rlo < lo:
                    lo = rlo
                if rhi > hi:
                    hi = rhi
    need_stretch = auto_norm and (hi - lo >= 4) and (lo > 2 or hi < 253)
    if not invert_polarity and not need_stretch:
        return g
    lut = bytearray(256)
    span = float(max(1, hi - lo))
    for v in range(256):
        val = (255 - v) if invert_polarity else v
        if need_stretch:
            src_v = (255 - val) if invert_polarity else val
            norm = max(0.0, min(1.0, (src_v - lo) / span))
            val = int(round((1.0 - norm if invert_polarity else norm) * 255.0))
        lut[v] = max(0, min(255, val))
    tbl = bytes(lut)
    out = bytearray(len(raw))
    for y in range(h):
        off = y * bpl
        out[off : off + w] = raw[off : off + w].translate(tbl)
    return QImage(bytes(out), w, h, bpl, QImage.Format.Format_Grayscale8).copy()


def sample_depth_at(
    depth_img: Optional[QImage], nx: float, ny: float, invert_polarity: bool = False,
) -> Optional[float]:
    """Sample normalized depth (0.0=far .. 100.0=near) at normalized coords (nx, ny)
    using a 3x3 micro-kernel average so clicks on noisy pixels stay rock-steady."""
    if depth_img is None or depth_img.isNull():
        return None
    w, h = depth_img.width(), depth_img.height()
    cx = max(0, min(w - 1, int(round(nx * (w - 1)))))
    cy = max(0, min(h - 1, int(round(ny * (h - 1)))))
    acc = 0.0
    cnt = 0
    for dy in (-1, 0, 1):
        yy = max(0, min(h - 1, cy + dy))
        for dx in (-1, 0, 1):
            xx = max(0, min(w - 1, cx + dx))
            c = depth_img.pixelColor(xx, yy)
            luma = 0.299 * c.red() + 0.587 * c.green() + 0.114 * c.blue()
            acc += (255.0 - luma) if invert_polarity else luma
            cnt += 1
    return round((acc / max(1, cnt)) * 100.0 / 255.0, 1)


def build_depth_mask_lut(params: Dict[str, Any]) -> bytes:
    """Compute a 256-entry alpha LUT mapping normalized depth d (0=far..255=near)
    to mask opacity (0..255). Supports Far->Opaque, Near->Opaque, Focus Band,
    and Outside Band with adjustable threshold, falloff ramp, curve & max opacity."""
    mode = str(params.get("mode") or "far_opaque")
    thresh = max(0.0, min(1.0, float(params.get("threshold", 50)) / 100.0))
    falloff = max(0.0, min(1.0, float(params.get("falloff", 35)) / 100.0))
    curve = max(-100.0, min(100.0, float(params.get("curve", 0)))) / 100.0
    max_op = max(0.05, min(1.0, float(params.get("max_opacity", 100)) / 100.0))

    lut = bytearray(256)
    ramp = max(0.004, falloff)
    for i in range(256):
        d = i / 255.0  # 0.0 = farthest, 1.0 = nearest
        if mode == "far_opaque":
            # Mask starts at threshold and ramps toward 0 (far)
            if falloff <= 0.004:
                t = 1.0 if d <= thresh else 0.0
            else:
                # Smooth ramp from thresh + ramp*0.5 (0) down to thresh - ramp*0.5 (1)
                lo = thresh - ramp * 0.5
                hi = thresh + ramp * 0.5
                t = max(0.0, min(1.0, (hi - d) / max(1e-5, hi - lo)))
        elif mode == "near_opaque":
            # Mask starts at threshold and ramps toward 1 (near)
            if falloff <= 0.004:
                t = 1.0 if d >= thresh else 0.0
            else:
                lo = thresh - ramp * 0.5
                hi = thresh + ramp * 0.5
                t = max(0.0, min(1.0, (d - lo) / max(1e-5, hi - lo)))
        elif mode == "focus_band":
            dist = abs(d - thresh)
            half_w = max(0.02, ramp * 0.55)
            feather_w = max(0.015, half_w * 0.65)
            if dist <= half_w - feather_w:
                t = 1.0
            elif dist >= half_w + feather_w:
                t = 0.0
            else:
                t = 1.0 - (dist - (half_w - feather_w)) / max(1e-5, 2.0 * feather_w)
        else:  # outside_band
            dist = abs(d - thresh)
            half_w = max(0.02, ramp * 0.55)
            feather_w = max(0.015, half_w * 0.65)
            if dist <= half_w - feather_w:
                t = 0.0
            elif dist >= half_w + feather_w:
                t = 1.0
            else:
                t = (dist - (half_w - feather_w)) / max(1e-5, 2.0 * feather_w)

        # Curve shaping: smoothstep S-curve at 0, steeper (>0) or gentler (<0)
        t = t * t * (3.0 - 2.0 * t)
        if curve > 0.01:
            t = t ** (1.0 + 2.4 * curve)
        elif curve < -0.01:
            t = t ** (1.0 / (1.0 + 2.4 * (-curve)))
        lut[i] = max(0, min(255, int(round(t * max_op * 255.0))))
    return bytes(lut)


def build_depth_mask(
    depth_img: Optional[QImage],
    params: Dict[str, Any],
    target_size: Optional[Tuple[int, int]] = None,
) -> Optional[QImage]:
    """Generate a ready-to-use ARGB32 red editor mask from `depth_img` using the
    adjustable depth mask parameters (threshold, falloff, curve, feather, mode)."""
    if depth_img is None or depth_img.isNull():
        return None
    w, h = target_size if target_size else (depth_img.width(), depth_img.height())
    w, h = max(1, int(w)), max(1, int(h))
    inv = bool(params.get("invert_polarity", False))
    auto_norm = bool(params.get("auto_norm", True))
    feather = max(0.0, min(32.0, float(params.get("feather", 0))))
    lut = build_depth_mask_lut(params)

    if _HAS_PIL and _PILImage is not None:
        pil_d = _depth_norm_l_pil(depth_img, w, h, invert_polarity=inv, auto_norm=auto_norm)
        alpha_l = pil_d.point(list(lut))
        if feather >= 0.6 and _PIL_FILT is not None:
            alpha_l = alpha_l.filter(_PIL_FILT.GaussianBlur(radius=feather))
        red = _PILImage.new("L", (w, h), 255)
        zero = _PILImage.new("L", (w, h), 0)
        rgba = _PILImage.merge("RGBA", (red, zero, zero, alpha_l))
        raw = rgba.tobytes("raw", "BGRA")
        return QImage(raw, w, h, w * 4, QImage.Format.Format_ARGB32).copy()

    # Pure-Qt fallback (C-speed bytes.translate + fast smooth alpha feather)
    g = _depth_norm_gray_qt(depth_img, w, h, invert_polarity=inv, auto_norm=auto_norm)
    bpl = g.bytesPerLine()
    ptr = g.constBits()
    ptr.setsize(g.sizeInBytes())
    src = memoryview(ptr).cast("B")
    buf = bytearray(w * h * 4)
    # ARGB32 little-endian memory order: B=0, G=0, R=255, A=lut[d]
    buf[2::4] = b"\xff" * (w * h)
    for y in range(h):
        a_row = bytes(src[y * bpl : y * bpl + w]).translate(lut)
        buf[y * w * 4 + 3 : (y + 1) * w * 4 : 4] = a_row
    out = QImage(bytes(buf), w, h, w * 4, QImage.Format.Format_ARGB32).copy()
    if feather >= 0.8:
        out = blur_alpha_qimage(out, feather)
    return out


def build_depth_visualization(
    depth_img: Optional[QImage],
    vis_mode: str = "turbo",
    focus_pct: float = 65.0,
    band_pct: float = 24.0,
    invert_polarity: bool = False,
    auto_norm: bool = True,
    max_side: int = 960,
) -> Optional[QImage]:
    """Build a crisp preview visualization overlay (Grayscale, Cinema Heatmap,
    or Focus Plane Highlight) in <3ms via 256-entry LUT translation."""
    if depth_img is None or depth_img.isNull() or vis_mode == "off":
        return None
    w, h = depth_img.width(), depth_img.height()
    if max_side and (w > max_side or h > max_side):
        scale = max_side / float(max(w, h))
        w = max(1, int(round(w * scale)))
        h = max(1, int(round(h * scale)))
    g = _depth_norm_gray_qt(depth_img, w, h, invert_polarity=invert_polarity, auto_norm=auto_norm)
    bpl = g.bytesPerLine()
    ptr = g.constBits()
    ptr.setsize(g.sizeInBytes())
    src = memoryview(ptr).cast("B")

    if vis_mode == "gray":
        return g.convertToFormat(QImage.Format.Format_ARGB32)

    if vis_mode == "focus":
        # Highlight focal plane in luminous cyan/gold, far in cool slate, near in warm coral
        f0 = max(0.0, min(1.0, focus_pct / 100.0))
        hw = max(0.03, min(0.45, band_pct / 200.0))
        lr, lg, lb, la = bytearray(256), bytearray(256), bytearray(256), bytearray(256)
        for i in range(256):
            d = i / 255.0
            dist = abs(d - f0)
            if dist <= hw:
                # Inside sharp focus plane: bright emerald-cyan glow band
                u = 1.0 - dist / max(1e-5, hw)
                lr[i] = int(40 + 180 * u)
                lg[i] = int(215 + 40 * u)
                lb[i] = 255
                la[i] = int(125 + 95 * u)
            elif d < f0:
                # Farther than focus: deep cobalt blue tint
                u = min(1.0, (f0 - d) / max(0.05, f0))
                lr[i], lg[i], lb[i], la[i] = 24, 62, 175, int(65 + 115 * u)
            else:
                # Closer than focus: warm amber-coral tint
                u = min(1.0, (d - f0) / max(0.05, 1.0 - f0))
                lr[i], lg[i], lb[i], la[i] = 245, 130, 56, int(65 + 115 * u)
        br, bg, bb, ba = bytes(lr), bytes(lg), bytes(lb), bytes(la)
        buf = bytearray(w * h * 4)
        for y in range(h):
            row = bytes(src[y * bpl : y * bpl + w])
            off = y * w * 4
            buf[off : off + w * 4 : 4] = row.translate(bb)
            buf[off + 1 : off + w * 4 : 4] = row.translate(bg)
            buf[off + 2 : off + w * 4 : 4] = row.translate(br)
            buf[off + 3 : off + w * 4 : 4] = row.translate(ba)
        return QImage(bytes(buf), w, h, w * 4, QImage.Format.Format_ARGB32).copy()

    # Default: "turbo" high-craft cinema heatmap
    br, bg, bb = _TURBO_LUT_RGB
    buf = bytearray(w * h * 4)
    buf[3::4] = b"\xff" * (w * h)
    for y in range(h):
        row = bytes(src[y * bpl : y * bpl + w])
        off = y * w * 4
        buf[off : off + w * 4 : 4] = row.translate(bb)
        buf[off + 1 : off + w * 4 : 4] = row.translate(bg)
        buf[off + 2 : off + w * 4 : 4] = row.translate(br)
    return QImage(bytes(buf), w, h, w * 4, QImage.Format.Format_ARGB32).copy()


def _depth_vertical_grad_pil(w: int, h: int, bias: float):
    """Cached 1D->2D subtle sky/top atmospheric vertical weight mask (PIL 'L')."""
    strip = _PILImage.new("L", (1, max(1, h)))
    pix = []
    for y in range(h):
        t = 1.0 - (y / float(max(1, h - 1)))  # 1 at top, 0 at bottom
        val = (1.0 - bias) + bias * (0.45 + 0.55 * t)
        pix.append(max(0, min(255, int(round(val * 255.0)))))
    strip.putdata(pix)
    return strip.resize((w, h), _PIL_RESAMPLE_BI)


def _apply_depth_cinematic_pil(pil, depth_img: QImage, fx: Dict[str, Any]):
    """Full C-speed PIL cinematic depth post-processing suite."""
    w, h = pil.size
    inv = bool(fx.get("invert_polarity", False))
    auto_norm = bool(fx.get("auto_norm", True))
    d_l = _depth_norm_l_pil(depth_img, w, h, invert_polarity=inv, auto_norm=auto_norm)
    mwh = float(min(w, h))
    focus = max(0.0, min(1.0, float(fx.get("dof_focus", 68)) / 100.0))

    # 1. Foreground / Background Relighting & Separation (before bokeh so blur inherits light)
    fg_pop = int(fx.get("fg_pop", 0))
    bg_dim = int(fx.get("bg_dim", 0))
    bg_cool = int(fx.get("bg_cool", 0))
    bg_desat = int(fx.get("bg_desat", 0))
    if fg_pop != 0 or bg_dim != 0 or bg_cool != 0 or bg_desat > 0:
        # Smooth foreground/background separation around focus plane
        fg_lut = [
            max(0, min(255, int(round(
                ((max(0.0, min(1.0, ((i / 255.0) - (focus - 0.24)) / 0.44)) ** 1.2) * 255.0)
            ))))
            for i in range(256)
        ]
        bg_lut = [255 - v for v in fg_lut]
        if fg_pop != 0:
            fg_layer = pil
            if fg_pop > 0:
                fg_layer = _PIL_ENH.Contrast(fg_layer).enhance(1.0 + fg_pop / 240.0)
                if _PIL_FILT is not None:
                    fg_layer = fg_layer.filter(_PIL_FILT.UnsharpMask(
                        radius=max(1.5, mwh / 220.0), percent=int(fg_pop * 0.95), threshold=2
                    ))
                lift = 1.0 + fg_pop / 620.0
                fg_layer = fg_layer.point(_edit_lut(lambda v: v * lift) * 3)
            else:
                fg_layer = _PIL_ENH.Contrast(fg_layer).enhance(max(0.55, 1.0 + fg_pop / 180.0))
            pil = _PILImage.composite(fg_layer, pil, d_l.point(fg_lut))
        if bg_dim != 0 or bg_cool != 0 or bg_desat > 0:
            bg_layer = pil
            if bg_dim != 0:
                fac = 2.0 ** (bg_dim / 145.0)
                bg_layer = bg_layer.point(_edit_lut(lambda v: v * fac) * 3)
            if bg_cool != 0:
                t = bg_cool / 100.0
                r_c, g_c, b_c = bg_layer.split()
                r_c = r_c.point(_edit_lut(lambda v: v * (1.0 + 0.26 * t)))
                b_c = b_c.point(_edit_lut(lambda v: v * (1.0 - 0.28 * t)))
                bg_layer = _PILImage.merge("RGB", (r_c, g_c, b_c))
            if bg_desat > 0:
                bg_layer = _PIL_ENH.Color(bg_layer).enhance(max(0.05, 1.0 - bg_desat / 105.0))
            pil = _PILImage.composite(bg_layer, pil, d_l.point(bg_lut))

    # 2. Multi-Plane Optical Depth-of-Field (4-tier bokeh pyramid + highlight bloom)
    dof_str = int(fx.get("dof_strength", 0))
    coc_l = None
    if dof_str > 0 and _PIL_FILT is not None:
        ap = max(0.04, min(0.80, float(fx.get("dof_aperture", 24)) / 100.0)) * 0.5
        fg_mul = max(0.0, min(1.0, float(fx.get("dof_fg_blur", 45)) / 100.0))
        bloom_k = max(0.0, min(1.0, float(fx.get("dof_bokeh_bloom", 25)) / 100.0))
        coc_lut = [0] * 256
        for i in range(256):
            d = i / 255.0
            dist = abs(d - focus)
            if dist <= ap:
                c = 0.0
            else:
                raw_c = min(1.0, (dist - ap) / max(0.10, 0.72 - ap))
                if d > focus:
                    raw_c *= fg_mul
                c = raw_c * raw_c * (3.0 - 2.0 * raw_c)
            coc_lut[i] = max(0, min(255, int(round(c * 255.0))))
        coc_l = d_l.point(coc_lut)
        max_r = max(1.4, (dof_str / 100.0) * max(4.0, mwh / 42.0))
        b1 = pil.filter(_PIL_FILT.GaussianBlur(radius=max(0.8, max_r * 0.28)))
        b2 = pil.filter(_PIL_FILT.GaussianBlur(radius=max(1.4, max_r * 0.62)))
        b3_src = pil
        if bloom_k > 0.02:
            # Creamy cinema bokeh specular highlight boost inside deep out-of-focus layer
            spec = pil.point(_edit_lut(lambda v: max(0.0, (v - 178.0) * 255.0 / 77.0)) * 3)
            spec = spec.filter(_PIL_FILT.GaussianBlur(radius=max(2.0, max_r * 0.85)))
            b3_src = _PILImage.blend(pil, _PIL_CHOPS.screen(pil, spec), min(0.85, bloom_k * 0.80))
        b3 = b3_src.filter(_PIL_FILT.GaussianBlur(radius=max_r))
        # Piecewise smooth crossfade across 3 blur tiers (0..85, 85..170, 170..255)
        m1 = coc_l.point([min(255, int(v * 3.0)) for v in range(256)])
        m2 = coc_l.point([max(0, min(255, int((v - 85) * 3.0))) for v in range(256)])
        m3 = coc_l.point([max(0, min(255, int((v - 170) * 3.0))) for v in range(256)])
        out_dof = _PILImage.composite(b1, pil, m1)
        out_dof = _PILImage.composite(b2, out_dof, m2)
        pil = _PILImage.composite(b3, out_dof, m3)

    # 3. Depth-Modulated Optical Lens Chromatic Fringing (strictly in out-of-focus/far zones)
    ca_amt = int(fx.get("depth_ca", 0))
    if ca_amt > 0:
        px_shift = max(1, int(round((ca_amt / 100.0) * max(2.0, mwh / 210.0))))
        r_c, g_c, b_c = pil.split()
        r_s = _PIL_CHOPS.offset(r_c, px_shift, 0)
        b_s = _PIL_CHOPS.offset(b_c, -px_shift, 0)
        ca_img = _PILImage.merge("RGB", (r_s, g_c, b_s))
        if coc_l is not None:
            ca_mask = coc_l.point(lambda v: int(v * min(0.90, ca_amt / 110.0)))
        else:
            ca_lut = [int(((1.0 - i / 255.0) ** 1.5) * 255.0 * min(0.85, ca_amt / 115.0)) for i in range(256)]
            ca_mask = d_l.point(ca_lut)
        pil = _PILImage.composite(ca_img, pil, ca_mask)

    # 4. Atmospheric Depth Haze / Aerial Perspective (exponential mist curve)
    haze_str = int(fx.get("haze_strength", 0))
    if haze_str > 0:
        h_start = max(0.05, min(0.95, float(fx.get("haze_start", 45)) / 100.0))
        h_k = min(0.94, haze_str / 100.0 * 0.90)
        h_lut = [0] * 256
        for i in range(256):
            d = i / 255.0  # 0=far, 1=near
            if d >= h_start:
                m = 0.0
            else:
                far_t = (h_start - d) / max(0.05, h_start)
                m = (1.0 - math.exp(-2.6 * far_t)) / (1.0 - math.exp(-2.6))
            h_lut[i] = max(0, min(255, int(round(m * h_k * 255.0))))
        h_mask = d_l.point(h_lut)
        sky_bias = max(0.0, min(1.0, float(fx.get("haze_sky", 35)) / 100.0))
        if sky_bias > 0.05:
            vgrad = _depth_vertical_grad_pil(w, h, sky_bias)
            h_mask = _PIL_CHOPS.multiply(h_mask, vgrad)
        h_col = _hex_to_rgb(str(fx.get("haze_color") or "#3b6ea5"))
        fog_solid = _PILImage.new("RGB", (w, h), h_col)
        # Hybrid natural mist + subtle luminous aerial scatter
        fog_screen = _PILImage.blend(fog_solid, _PIL_CHOPS.screen(pil, fog_solid), 0.32)
        pil = _PILImage.composite(fog_screen, pil, h_mask)

    # 5. Directional Silhouette Depth Rim-Light / Backlight Separation
    rim_str = int(fx.get("rim_strength", 0))
    if rim_str > 0:
        rim_w = max(1, min(18, int(round(float(fx.get("rim_width", 5)) * max(0.65, mwh / 720.0)))))
        rim_cut = max(0, min(255, int(round(float(fx.get("rim_cutoff", 48)) * 2.55))))
        rdir = str(fx.get("rim_dir") or "top_left")
        shifts = {
            "top": [(0, rim_w)],
            "left": [(rim_w, 0)],
            "right": [(-rim_w, 0)],
            "top_left": [(rim_w, 0), (0, rim_w)],
            "top_right": [(-rim_w, 0), (0, rim_w)],
            "all": [(rim_w, 0), (-rim_w, 0), (0, rim_w), (0, -rim_w)],
        }.get(rdir, [(rim_w, 0), (0, rim_w)])
        edge = None
        for dx, dy in shifts:
            sh = _PIL_CHOPS.offset(d_l, dx, dy)
            diff = _PIL_CHOPS.subtract(d_l, sh)
            edge = diff if edge is None else _PIL_CHOPS.lighter(edge, diff)
        if edge is not None:
            # Gate rim to foreground depth >= rim_cut and amplify crisp silhouette discontinuity
            fg_gate = d_l.point([255 if v >= rim_cut else max(0, int((v - max(0, rim_cut - 26)) * 255 / 26.0)) for v in range(256)])
            edge = _PIL_CHOPS.multiply(edge, fg_gate)
            edge = edge.point([min(255, int(max(0, v - 10) * 4.4)) for v in range(256)])
            if _PIL_FILT is not None:
                edge = edge.filter(_PIL_FILT.GaussianBlur(radius=max(1.2, rim_w * 0.72)))
            r_col = _hex_to_rgb(str(fx.get("rim_color") or "#ffe3a8"), (255, 227, 168))
            gain = min(1.0, rim_str / 100.0 * 0.92)
            rr = edge.point(lambda v: min(255, int(v * gain * (r_col[0] / 255.0))))
            rg = edge.point(lambda v: min(255, int(v * gain * (r_col[1] / 255.0))))
            rb = edge.point(lambda v: min(255, int(v * gain * (r_col[2] / 255.0))))
            pil = _PIL_CHOPS.screen(pil, _PILImage.merge("RGB", (rr, rg, rb)))

    # 6. Foreground-Preserving Depth Studio Vignette
    dvig = int(fx.get("depth_vignette", 0))
    if dvig > 0:
        vmask = _cached_vignette_mask(w, h)
        # Preserve foreground subjects near edges (attenuate vignette up to 72% on near depth)
        bg_keep = d_l.point([int((1.0 - 0.72 * (i / 255.0)) * 255.0) for i in range(256)])
        d_vmask = _PIL_CHOPS.multiply(vmask, bg_keep)
        v_amt = min(0.90, dvig / 100.0 * 0.85)
        edge_dark = _PILImage.new("RGB", (w, h), (5, 7, 12))
        pil = _PILImage.composite(edge_dark, pil, d_vmask.point(lambda v: int(v * v_amt)))

    return pil


def _qt_fast_blur_rgb(img: QImage, radius: float) -> QImage:
    """Fast pure-Qt smooth blur via downscale-upscale pyramid (zero lag fallback)."""
    r = max(0.5, float(radius))
    w, h = img.width(), img.height()
    if w < 4 or h < 4:
        return img
    factor = max(1.15, min(14.0, 1.0 + r * 0.45))
    sw = max(2, int(round(w / factor)))
    sh = max(2, int(round(h / factor)))
    small = img.scaled(sw, sh, Qt.AspectRatioMode.IgnoreAspectRatio, Qt.TransformationMode.SmoothTransformation)
    return small.scaled(w, h, Qt.AspectRatioMode.IgnoreAspectRatio, Qt.TransformationMode.SmoothTransformation)


def _apply_ca_qt(
    img: QImage,
    cfg: Dict[str, Any],
    depth_img: Optional[QImage] = None,
) -> QImage:
    """Pure-Qt depth-modulated optical chromatic aberration fallback (zero Pillow required).
    Shifts R and B channels horizontally along scanlines and composites via out-of-focus depth mask."""
    if img.isNull():
        return img
    strength = max(0, min(100, int(cfg.get("strength", 0))))
    if strength <= 0:
        return img
    src_img = img.convertToFormat(QImage.Format.Format_RGB32)
    w, h = src_img.width(), src_img.height()
    if w < 4 or h < 4:
        return src_img
    shift = max(1, min(14, int(round((strength / 100.0) * max(2.0, min(w, h) / 210.0)))))
    ca_img = QImage(w, h, QImage.Format.Format_RGB32)
    profile = str(cfg.get("profile") or "rc").lower()
    # Format_RGB32 little-endian memory layout is BGRA (bytes 0=B, 1=G, 2=R, 3=A)
    for y in range(h):
        sp = src_img.constScanLine(y)
        dp = ca_img.scanLine(y)
        sp.setsize(w * 4)
        dp.setsize(w * 4)
        s_buf = bytes(sp)
        d_buf = bytearray(s_buf)
        row_bytes = w * 4
        sh_b = shift * 4
        if profile == "gm":
            # Shift green +shift, red/blue -shift
            for x in range(w):
                xo = x * 4
                xs_p = min(row_bytes - 4, xo + sh_b)
                xs_m = max(0, xo - sh_b)
                d_buf[xo] = s_buf[xs_m]
                d_buf[xo + 1] = s_buf[xs_p + 1]
                d_buf[xo + 2] = s_buf[xs_m + 2]
        else:
            # Default red-cyan: shift red +shift, blue -shift (keep green anchored)
            for x in range(w):
                xo = x * 4
                xs_p = min(row_bytes - 4, xo + sh_b)
                xs_m = max(0, xo - sh_b)
                d_buf[xo] = s_buf[xs_m]
                d_buf[xo + 2] = s_buf[xs_p + 2]
        dp[:] = bytes(d_buf)
    if depth_img is not None and not depth_img.isNull():
        mask = build_depth_mask(
            depth_img,
            {
                "mode": "outside_band",
                "threshold": int(cfg.get("focus", 68)),
                "falloff": max(8, int(cfg.get("focus_band", 24))),
                "curve": 0,
                "max_opacity": min(90, int(round(strength * 0.90))),
                "feather": 3,
                "invert_polarity": bool(cfg.get("invert_polarity", False)),
                "auto_norm": True,
            },
            target_size=(w, h),
        )
        if mask is not None:
            return _composite_masked(src_img, ca_img, mask, False)
    return ca_img


def _apply_depth_cinematic_qt(img: QImage, depth_img: QImage, fx: Dict[str, Any]) -> Tuple[QImage, List[str]]:
    """Pure-Qt fallback for cinematic depth post-processing (works without Pillow)."""
    w, h = img.width(), img.height()
    inv = bool(fx.get("invert_polarity", False))
    auto_norm = bool(fx.get("auto_norm", True))
    out = img.convertToFormat(QImage.Format.Format_RGB32)
    mwh = float(min(w, h))

    # 1. Bokeh DOF via fast downscale-upscale depth-masked blur
    dof_str = int(fx.get("dof_strength", 0))
    if dof_str > 0:
        max_r = max(1.5, (dof_str / 100.0) * max(4.0, mwh / 42.0))
        blurred = _qt_fast_blur_rgb(out, max_r)
        coc_mask = build_depth_mask(
            depth_img,
            {
                "mode": "outside_band",
                "threshold": int(fx.get("dof_focus", 68)),
                "falloff": max(8, int(fx.get("dof_aperture", 24))),
                "curve": 10,
                "max_opacity": 100,
                "feather": 3,
                "invert_polarity": inv,
                "auto_norm": auto_norm,
            },
            target_size=(w, h),
        )
        if coc_mask is not None:
            out = _composite_masked(out, blurred, coc_mask, False)

    # 2. Atmospheric Depth Haze
    haze_str = int(fx.get("haze_strength", 0))
    if haze_str > 0:
        h_mask = build_depth_mask(
            depth_img,
            {
                "mode": "far_opaque",
                "threshold": int(fx.get("haze_start", 45)),
                "falloff": 65,
                "curve": -15,
                "max_opacity": min(92, haze_str),
                "feather": 4,
                "invert_polarity": inv,
                "auto_norm": auto_norm,
            },
            target_size=(w, h),
        )
        if h_mask is not None:
            h_col = QColor(str(fx.get("haze_color") or "#3b6ea5"))
            fog = QImage(w, h, QImage.Format.Format_RGB32)
            fog.fill(h_col if h_col.isValid() else QColor("#3b6ea5"))
            out = _composite_masked(out, fog, h_mask, False)

    # 3. Background dim / cool / desat
    bg_dim = int(fx.get("bg_dim", 0))
    bg_cool = int(fx.get("bg_cool", 0))
    bg_desat = int(fx.get("bg_desat", 0))
    if bg_dim != 0 or bg_cool != 0 or bg_desat > 0:
        bg_mask = build_depth_mask(
            depth_img,
            {
                "mode": "far_opaque",
                "threshold": int(fx.get("dof_focus", 68)),
                "falloff": 45,
                "curve": 0,
                "max_opacity": 100,
                "feather": 4,
                "invert_polarity": inv,
                "auto_norm": auto_norm,
            },
            target_size=(w, h),
        )
        if bg_mask is not None:
            adj_bg = default_edit_adjustments()
            adj_bg["exposure"] = float(bg_dim) * 0.72
            adj_bg["temperature"] = float(bg_cool) * 0.85
            adj_bg["saturation"] = -float(bg_desat) * 0.90
            graded_bg, _ = _apply_edit_qt(out, adj_bg)
            out = _composite_masked(out, graded_bg.convertToFormat(QImage.Format.Format_RGB32), bg_mask, False)

    dca = int(fx.get("depth_ca", 0))
    if dca > 0:
        out = _apply_ca_qt(
            out,
            {
                "mode": "depth",
                "profile": "rc",
                "strength": dca,
                "focus": int(fx.get("dof_focus", 68)),
                "focus_band": max(8, int(fx.get("dof_aperture", 24))),
                "invert_polarity": inv,
            },
            depth_img=depth_img,
        )
    skipped: List[str] = []
    if int(fx.get("rim_strength", 0)) > 0:
        skipped.append("depth_rim")
    return out, skipped


def apply_depth_cinematic_pipeline(
    img: QImage, depth_img: Optional[QImage], fx: Optional[Dict[str, Any]],
) -> Tuple[QImage, List[str]]:
    """Run all active Depth Map cinematic post-processing effects on `img`."""
    if img.isNull() or depth_img is None or depth_img.isNull() or not depth_fx_active(fx):
        return img, []
    try:
        if _HAS_PIL and _PILImage is not None:
            pil = _qimg_to_pil(img).convert("RGB")
            pil = _apply_depth_cinematic_pil(pil, depth_img, fx or {})
            return _pil_to_qimg(pil).convertToFormat(QImage.Format.Format_RGB32), []
        return _apply_depth_cinematic_qt(img, depth_img, fx or {})
    except Exception as exc:  # noqa: BLE001
        STUDIO_LOG.warn("SYS", f"Depth cinematic pipeline fallback: {exc}")
        return img, ["depth_fx"]


# =============================================================================
#  7. Prompt Element Tokenizer (Ctrl+Drag Tag Blocks) & Span Highlighter
# =============================================================================
@dataclass
class PromptElement:
    """One discrete prompt element separated by comma or sentence-ending dot.
    May be a single word, weighted tag, multi-word phrase, or full sentence."""
    index: int
    start: int       # inclusive char index of trimmed content start
    end: int         # exclusive char index of trimmed content end
    text: str        # trimmed element text (without trailing separator)
    sep: str         # trailing delimiter ("," or "." or "")


def parse_prompt_elements(text: str) -> List[PromptElement]:
    """Split a prompt into atomic tag/sentence elements separated by commas (,)
    or sentence-ending periods (.) while keeping decimals (1.5, v1.1), ellipses
    (...), and parenthesized weight syntax ((word:1.8)) completely intact."""
    if not text:
        return []
    n = len(text)
    elements: List[PromptElement] = []
    seg_start = 0
    paren_depth = 0
    brace_depth = 0
    bracket_depth = 0

    def _emit(end_pos: int, sep_char: str) -> None:
        raw_seg = text[seg_start:end_pos]
        lead = len(raw_seg) - len(raw_seg.lstrip(" \t\r\n"))
        trail = len(raw_seg) - len(raw_seg.rstrip(" \t\r\n"))
        t_start = seg_start + lead
        t_end = end_pos - trail
        if t_end > t_start:
            elements.append(
                PromptElement(
                    index=len(elements),
                    start=t_start,
                    end=t_end,
                    text=text[t_start:t_end],
                    sep=sep_char,
                )
            )

    i = 0
    while i < n:
        ch = text[i]
        if ch == "(":
            paren_depth += 1
        elif ch == ")" and paren_depth > 0:
            paren_depth -= 1
        elif ch == "{":
            brace_depth += 1
        elif ch == "}" and brace_depth > 0:
            brace_depth -= 1
        elif ch == "[":
            bracket_depth += 1
        elif ch == "]" and bracket_depth > 0:
            bracket_depth -= 1
        elif paren_depth == 0 and brace_depth == 0 and bracket_depth == 0:
            if ch == ",":
                _emit(i, ",")
                seg_start = i + 1
            elif ch == ".":
                prev_c = text[i - 1] if i > 0 else ""
                next_c = text[i + 1] if i + 1 < n else ""
                # Ignore decimals (1.5, v1.1), ellipses (...), and domain names (foo.com)
                is_ellipsis = prev_c == "." or next_c == "."
                is_decimal_or_token = prev_c.isdigit() and next_c.isdigit()
                is_boundary = (not next_c) or next_c.isspace()
                if is_boundary and not is_ellipsis and not is_decimal_or_token:
                    _emit(i, ".")
                    seg_start = i + 1
        i += 1
    if seg_start < n:
        _emit(n, "")
    return elements


def reorder_prompt_elements(
    text: str,
    selected_indices: Sequence[int],
    target_slot: int,
) -> Tuple[str, List[int], List[Tuple[int, int]]]:
    """Atomically move one or more prompt elements (in their relative order) to
    `target_slot` (0..len(elements)) in the original sequence.

    Returns:
        (new_text, new_selected_indices, moved_char_ranges)
    Preserves comma / sentence-dot separators cleanly with zero double commas
    or orphaned punctuation."""
    elems = parse_prompt_elements(text)
    if not elems or not selected_indices:
        return text, [], []
    valid_set = {idx for idx in selected_indices if 0 <= idx < len(elems)}
    if not valid_set:
        return text, [], []

    selected_ordered = [elems[i] for i in sorted(valid_set)]
    remaining = [e for e in elems if e.index not in valid_set]

    # Count how many remaining elements sit strictly before target_slot
    clamped_slot = max(0, min(len(elems), int(target_slot)))
    insert_at = sum(1 for e in remaining if e.index < clamped_slot)

    reordered = remaining[:insert_at] + selected_ordered + remaining[insert_at:]
    new_sel_indices = list(range(insert_at, insert_at + len(selected_ordered)))

    # Reconstruct cleanly while honoring each element's original comma/dot delimiter
    pieces: List[str] = []
    char_ranges: List[Tuple[int, int]] = []
    cursor = 0
    for pos, el in enumerate(reordered):
        is_last = pos == len(reordered) - 1
        start_c = cursor
        pieces.append(el.text)
        cursor += len(el.text)
        end_c = cursor
        if pos in new_sel_indices:
            char_ranges.append((start_c, end_c))
        if not is_last:
            delim = el.sep if el.sep in (",", ".") else ","
            joiner = f"{delim} "
            pieces.append(joiner)
            cursor += len(joiner)
        else:
            if el.sep == ".":
                pieces.append(".")
                cursor += 1
    return "".join(pieces), new_sel_indices, char_ranges


class SpanBook:
    """Tracks colored text spans inside a prompt editor (inserted Tag Groups AND
    inserted LoRA Trigger Words). Each span retains its folder highlight color
    until any character inside that exact span is modified."""

    def __init__(self) -> None:
        self.spans: List[Dict[str, Any]] = []

    def clear(self) -> None:
        self.spans.clear()

    def add(self, start: int, text: str, color: str, kind: str = "tag") -> None:
        if not text:
            return
        self.spans.append({
            "start": int(start),
            "end": int(start) + len(text),
            "text": text,
            "color": color,
            "kind": kind,
        })

    def snapshot(self) -> List[Dict[str, Any]]:
        return copy.deepcopy(self.spans)

    def restore(self, snap: List[Dict[str, Any]]) -> None:
        self.spans = copy.deepcopy(snap)


def maintain_spans(book: SpanBook, new_text: str) -> None:
    """Keep every untouched span aligned with its exact substring even when text
    before/after it changes or tags are Ctrl-dragged. Drop any span whose inner
    text was altered."""
    if not book.spans:
        return
    kept: List[Dict[str, Any]] = []
    used_intervals: List[Tuple[int, int]] = []
    for sp in book.spans:
        needle = sp.get("text") or ""
        if not needle:
            continue
        old_start = int(sp.get("start", 0))
        # Fast path: exact match at previous offset
        if new_text[old_start : old_start + len(needle)] == needle:
            pos = old_start
        else:
            # Find nearest non-overlapping exact occurrence (survives edits elsewhere & Ctrl-drag!)
            best_pos = -1
            best_dist = 10**9
            search_from = 0
            while True:
                idx = new_text.find(needle, search_from)
                if idx < 0:
                    break
                end_idx = idx + len(needle)
                overlaps = any(not (end_idx <= u0 or idx >= u1) for u0, u1 in used_intervals)
                if not overlaps:
                    dist = abs(idx - old_start)
                    if dist < best_dist:
                        best_dist = dist
                        best_pos = idx
                search_from = idx + 1
            pos = best_pos
        if pos >= 0:
            end_pos = pos + len(needle)
            used_intervals.append((pos, end_pos))
            kept.append({
                "start": pos,
                "end": end_pos,
                "text": needle,
                "color": sp["color"],
                "kind": sp.get("kind", "tag"),
            })
    book.spans = kept


class SpanHighlighter(QSyntaxHighlighter):
    """Highlights untouched Tag Group & LoRA Trigger Word spans inside QPlainTextEdit.

    v3.1: additionally renders the trailing LoRA-trigger GHOST region (the
    un-editable auto-appended trigger words) as dimmed italic "ghost text"."""

    def __init__(self, book: SpanBook, document) -> None:
        super().__init__(document)
        self.book = book
        self._ghost_start: int = -1
        self._ghost_end: int = -1

    def set_ghost_range(self, start: int, end: int) -> None:
        if start == self._ghost_start and end == self._ghost_end:
            return
        self._ghost_start = int(start)
        self._ghost_end = int(end)

    def highlightBlock(self, text: str) -> None:  # noqa: N802
        block_start = self.currentBlock().position()
        block_end = block_start + len(text)
        if self.book.spans:
            for sp in self.book.spans:
                s0, s1 = int(sp["start"]), int(sp["end"])
                if s1 <= block_start or s0 >= block_end:
                    continue
                ov_start = max(s0, block_start) - block_start
                ov_end = min(s1, block_end) - block_start
                if ov_end <= ov_start:
                    continue
                fmt = QTextCharFormat()
                col = QColor(readable_accent_for_theme(str(sp["color"])))
                fmt.setForeground(col)
                bg = QColor(col)
                light = is_light_theme()
                bg.setAlpha((46 if light else 38) if sp.get("kind") == "lora" else (32 if light else 26))
                fmt.setBackground(bg)
                if sp.get("kind") == "lora":
                    fmt.setFontUnderline(True)
                    fmt.setUnderlineColor(QColor(col.red(), col.green(), col.blue(), 165))
                self.setFormat(ov_start, ov_end - ov_start, fmt)
        # Subtle highlight for __wildcard__ tokens (fast single-pass regex, zero lag)
        if "__" in text:
            w_col = QColor(readable_accent_for_theme(C["info"]))
            w_bg = QColor(w_col)
            w_bg.setAlpha(34 if is_light_theme() else 28)
            w_fmt = QTextCharFormat()
            w_fmt.setForeground(w_col)
            w_fmt.setBackground(w_bg)
            w_fmt.setFontWeight(QFont.Weight.DemiBold)
            for m_w in re.finditer(r"__[^\n_][^_\n]{0,64}__", text):
                self.setFormat(m_w.start(), m_w.end() - m_w.start(), w_fmt)
        # Ghost (locked LoRA trigger) zone: greyed-out italic, but readable
        if self._ghost_start >= 0 and self._ghost_end > self._ghost_start:
            g0 = max(self._ghost_start, block_start) - block_start
            g1 = min(self._ghost_end, block_end) - block_start
            if g1 > g0:
                fmt = QTextCharFormat()
                fmt.setForeground(QColor(C["ghost"]))
                fmt.setFontItalic(True)
                self.setFormat(g0, g1 - g0, fmt)


# =============================================================================
#  8. OpenAI-Compatible Streaming LLM & VLM Engine (v13.0 — Live Token Counter,
#     Incremental Prompt Parser & Instant Socket-Closing Cancellation)
# =============================================================================
class LlmError(Exception):
    def __init__(self, message: str, status: Optional[int] = None, raw_snippet: str = ""):
        super().__init__(message)
        self.message = message
        self.status = status
        self.raw_snippet = raw_snippet


class LlmCancelled(LlmError):
    """Raised internally when the user stops an in-flight LLM/VLM request."""
    def __init__(self, message: str = "Stopped by user") -> None:
        super().__init__(message)


class LlmCancelToken:
    """Thread-safe instant cancellation handle for streaming & non-streaming LLM
    requests. Registers the live HTTP response / socket so cancel() aborts blocked
    reads in <50ms instead of waiting for network timeouts."""

    def __init__(self) -> None:
        self._ev = threading.Event()
        self._lock = threading.Lock()
        self._closers: List[Callable[[], None]] = []

    @property
    def cancelled(self) -> bool:
        return self._ev.is_set()

    def is_cancelled(self) -> bool:
        return self._ev.is_set()

    def register_closer(self, fn: Callable[[], None]) -> None:
        already = False
        with self._lock:
            if self._ev.is_set():
                already = True
            else:
                self._closers.append(fn)
        if already:
            try:
                fn()
            except Exception:  # noqa: BLE001
                pass

    def clear_closers(self) -> None:
        with self._lock:
            self._closers.clear()

    def cancel(self) -> None:
        with self._lock:
            self._ev.set()
            closers = list(self._closers)
            self._closers.clear()
        for fn in closers:
            try:
                fn()
            except Exception:  # noqa: BLE001
                pass


_CJK_RANGE_RE = re.compile(r"[\u3000-\u30ff\u3400-\u4dbf\u4e00-\u9fff\uac00-\ud7af\uff00-\uffef]")
_WORD_TOK_RE = re.compile(r"[A-Za-z0-9_]+|[^\sA-Za-z0-9_]")


def estimate_tokens(text: str) -> int:
    """Fast, zero-dependency, CJK-aware BPE-calibrated token estimator.
    Used for live real-time streaming counts before server `usage` arrives and
    for Prompt Editor token readouts."""
    if not text:
        return 0
    cjk_chars = len(_CJK_RANGE_RE.findall(text))
    non_cjk = _CJK_RANGE_RE.sub(" ", text) if cjk_chars else text
    est = float(cjk_chars) * 1.45
    for m in _WORD_TOK_RE.finditer(non_cjk):
        tok = m.group(0)
        ln = len(tok)
        if ln <= 4:
            est += 1.0
        else:
            est += max(1.0, ln / 3.85)
    return max(1, int(round(est))) if text.strip() else 0


def _llm_headers(api_key: str, accept_sse: bool = False) -> Dict[str, str]:
    h = {
        "Content-Type": "application/json",
        "Accept": "text/event-stream, application/json" if accept_sse else "application/json",
        "User-Agent": CLIENT_AGENT,
    }
    if api_key and api_key.strip():
        h["Authorization"] = f"Bearer {api_key.strip()}"
    return h


def _llm_close_handle(obj: Any) -> None:
    """Force-shutdown and close an HTTPConnection, socket, requests.Response, or urllib handle."""
    if obj is None:
        return
    try:
        sock = getattr(obj, "sock", None)
        if sock is not None:
            try:
                sock.shutdown(socket.SHUT_RDWR)
            except Exception:  # noqa: BLE001
                pass
            try:
                sock.close()
            except Exception:  # noqa: BLE001
                pass
    except Exception:  # noqa: BLE001
        pass
    try:
        raw = getattr(obj, "raw", None)
        if raw is not None:
            try:
                fp = getattr(raw, "_fp", None)
                sock2 = getattr(fp, "fp", None)
                raw_sock = getattr(sock2, "raw", None) if sock2 is not None else None
                for cand in (raw_sock, sock2, fp, raw):
                    if cand is not None:
                        if hasattr(cand, "shutdown"):
                            try:
                                cand.shutdown(socket.SHUT_RDWR)
                            except Exception:  # noqa: BLE001
                                pass
                        if hasattr(cand, "close"):
                            try:
                                cand.close()
                            except Exception:  # noqa: BLE001
                                pass
            except Exception:  # noqa: BLE001
                pass
    except Exception:  # noqa: BLE001
        pass
    try:
        obj.close()
    except Exception:  # noqa: BLE001
        pass


def _llm_has_proxy_env(scheme: str) -> bool:
    for key in (f"{scheme}_proxy", f"{scheme.upper()}_PROXY", "all_proxy", "ALL_PROXY"):
        if os.environ.get(key, "").strip():
            return True
    return False


def _llm_open_http(
    method: str,
    url: str,
    headers: Dict[str, str],
    body_bytes: Optional[bytes],
    timeout: float,
    cancel_token: Optional[LlmCancelToken] = None,
) -> Tuple[http.client.HTTPConnection, http.client.HTTPResponse]:
    """Open a socket-tracked http.client request whose underlying socket is immediately
    registered with `cancel_token` and polled in 0.35s slices during response wait so
    clicking STOP aborts even a hung TTFB / slow connect in <350ms."""
    cur_url = url
    for _hop in range(4):
        if cancel_token is not None and cancel_token.cancelled:
            raise LlmCancelled()
        parts = urllib.parse.urlsplit(cur_url)
        scheme = (parts.scheme or "https").lower()
        host = parts.hostname
        if not host:
            raise LlmError(f"Invalid API URL: {cur_url}")
        port = parts.port or (443 if scheme == "https" else 80)
        req_path = parts.path or "/"
        if parts.query:
            req_path += "?" + parts.query

        conn_timeout = min(15.0, max(5.0, float(timeout)))
        if scheme == "https":
            ctx = ssl.create_default_context()
            conn: http.client.HTTPConnection = http.client.HTTPSConnection(host, port, timeout=conn_timeout, context=ctx)
        else:
            conn = http.client.HTTPConnection(host, port, timeout=conn_timeout)

        if cancel_token is not None:
            cancel_token.register_closer(lambda c=conn: _llm_close_handle(c))

        try:
            conn.connect()
            if cancel_token is not None and cancel_token.cancelled:
                _llm_close_handle(conn)
                raise LlmCancelled()
            if conn.sock is not None:
                conn.sock.settimeout(0.35)
            hdrs = dict(headers)
            hdrs.setdefault("Host", f"{host}:{port}" if parts.port else host)
            if body_bytes is not None:
                hdrs["Content-Length"] = str(len(body_bytes))
            conn.request(method, req_path, body=body_bytes, headers=hdrs)

            deadline = time.monotonic() + max(5.0, float(timeout))
            while True:
                if cancel_token is not None and cancel_token.cancelled:
                    _llm_close_handle(conn)
                    raise LlmCancelled()
                try:
                    resp = conn.getresponse()
                    break
                except (socket.timeout, TimeoutError) as exc:
                    if cancel_token is not None and cancel_token.cancelled:
                        _llm_close_handle(conn)
                        raise LlmCancelled() from exc
                    if time.monotonic() >= deadline:
                        _llm_close_handle(conn)
                        raise LlmError(f"Timed out after {int(timeout)}s waiting for response headers") from exc
                    continue

            if resp.status in (301, 302, 303, 307, 308):
                loc = resp.getheader("Location")
                _llm_close_handle(conn)
                if loc:
                    cur_url = urllib.parse.urljoin(cur_url, loc)
                    continue
            return conn, resp
        except LlmCancelled:
            _llm_close_handle(conn)
            raise
        except LlmError:
            _llm_close_handle(conn)
            raise
        except Exception as exc:  # noqa: BLE001
            _llm_close_handle(conn)
            if cancel_token is not None and cancel_token.cancelled:
                raise LlmCancelled() from exc
            raise LlmError(f"Connection error: {exc.__class__.__name__}: {exc}") from exc
    raise LlmError("Too many HTTP redirects")


def _llm_read_response_all(
    resp: http.client.HTTPResponse,
    timeout: float,
    cancel_token: Optional[LlmCancelToken] = None,
) -> bytes:
    """Read an entire HTTP response body in interruptible 0.35s socket chunks."""
    deadline = time.monotonic() + max(5.0, float(timeout))
    chunks: List[bytes] = []
    while True:
        if cancel_token is not None and cancel_token.cancelled:
            raise LlmCancelled()
        try:
            blk = resp.read(16384)
            if not blk:
                break
            chunks.append(blk)
        except (socket.timeout, TimeoutError) as exc:
            if cancel_token is not None and cancel_token.cancelled:
                raise LlmCancelled() from exc
            if time.monotonic() >= deadline:
                raise LlmError(f"Timed out after {int(timeout)}s reading response body") from exc
            continue
    return b"".join(chunks)


def _llm_iter_lines_cancellable(
    resp: http.client.HTTPResponse,
    timeout: float,
    cancel_token: Optional[LlmCancelToken] = None,
):
    """Yield raw lines from a streaming HTTPResponse while checking `cancel_token`
    every 0.35s even when the remote server pauses between reasoning/output tokens."""
    deadline = time.monotonic() + max(10.0, float(timeout))
    buf = bytearray()
    while True:
        if cancel_token is not None and cancel_token.cancelled:
            raise LlmCancelled()
        nl = buf.find(b"\n")
        if nl >= 0:
            line = bytes(buf[:nl + 1])
            del buf[:nl + 1]
            yield line
            continue
        try:
            chunk = resp.read1(4096) if hasattr(resp, "read1") else resp.read(256)
            if not chunk:
                if buf:
                    yield bytes(buf)
                    buf.clear()
                break
            deadline = time.monotonic() + max(10.0, float(timeout))
            buf.extend(chunk)
        except (socket.timeout, TimeoutError) as exc:
            if cancel_token is not None and cancel_token.cancelled:
                raise LlmCancelled() from exc
            if time.monotonic() >= deadline:
                raise LlmError(f"Stream stalled for {int(timeout)}s with no tokens") from exc
            continue


def _llm_request(
    method: str,
    url: str,
    api_key: str,
    body: Optional[Dict[str, Any]] = None,
    timeout: float = 120.0,
    cancel_token: Optional[LlmCancelToken] = None,
) -> Dict[str, Any]:
    if cancel_token is not None and cancel_token.cancelled:
        raise LlmCancelled()
    t0 = time.monotonic()
    headers = _llm_headers(api_key, accept_sse=False)
    STUDIO_LOG.net("LLM", f"{method} {url}")
    status = 0
    raw_text = ""
    scheme = (urllib.parse.urlsplit(url).scheme or "https").lower()
    use_direct_http = not _llm_has_proxy_env(scheme)
    try:
        if use_direct_http:
            body_bytes = json.dumps(body).encode("utf-8") if body is not None else None
            conn, resp = _llm_open_http(method, url, headers, body_bytes, timeout, cancel_token=cancel_token)
            try:
                status = resp.status
                raw_bytes = _llm_read_response_all(resp, timeout, cancel_token=cancel_token)
                raw_text = raw_bytes.decode("utf-8", "replace")
            finally:
                _llm_close_handle(conn)
        elif _HAS_REQUESTS and requests is not None:
            sess = requests.Session()
            if cancel_token is not None:
                cancel_token.register_closer(sess.close)
            try:
                r = sess.request(method, url, headers=headers, json=body, timeout=(15.0, timeout))
                if cancel_token is not None:
                    cancel_token.register_closer(lambda resp=r: _llm_close_handle(resp))
                status = r.status_code
                raw_text = r.text
            finally:
                try:
                    sess.close()
                except Exception:  # noqa: BLE001
                    pass
        else:
            payload = json.dumps(body).encode("utf-8") if body is not None else None
            req = urllib.request.Request(url, data=payload, headers=headers, method=method)
            try:
                resp = urllib.request.urlopen(req, timeout=timeout)
                if cancel_token is not None:
                    cancel_token.register_closer(lambda rp=resp: _llm_close_handle(rp))
                with resp:
                    status = resp.status
                    raw_text = resp.read().decode("utf-8", "replace")
            except urllib.error.HTTPError as exc:
                status = exc.code
                raw_text = exc.read().decode("utf-8", "replace")
    except LlmCancelled:
        raise
    except LlmError:
        raise
    except Exception as exc:  # noqa: BLE001
        if cancel_token is not None and cancel_token.cancelled:
            raise LlmCancelled() from exc
        dt = int((time.monotonic() - t0) * 1000)
        msg = f"Connection error after {dt}ms: {exc.__class__.__name__}: {exc}"
        STUDIO_LOG.error("LLM", msg)
        raise LlmError(msg) from exc

    if cancel_token is not None and cancel_token.cancelled:
        raise LlmCancelled()

    dt = int((time.monotonic() - t0) * 1000)
    try:
        data = json.loads(raw_text) if raw_text.strip() else {}
    except ValueError as exc:
        snippet = raw_text[:280].replace("\n", " ")
        msg = f"HTTP {status} ({dt}ms) returned non-JSON body: {snippet}"
        STUDIO_LOG.error("LLM", msg)
        raise LlmError(msg, status=status, raw_snippet=snippet) from exc

    if status >= 400:
        err_obj = data.get("error") if isinstance(data, dict) else None
        if isinstance(err_obj, dict):
            detail = err_obj.get("message") or str(err_obj)
        elif isinstance(err_obj, str):
            detail = err_obj
        else:
            detail = str(data.get("message") if isinstance(data, dict) else raw_text[:240])
        msg = f"HTTP {status} ({dt}ms): {detail}"
        STUDIO_LOG.error("LLM", msg)
        raise LlmError(msg, status=status, raw_snippet=raw_text[:240])

    STUDIO_LOG.ok("LLM", f"{method} {urllib.parse.urlsplit(url).path} -> HTTP {status} ({dt}ms)")
    return data if isinstance(data, dict) else {"data": data}


def _strip_code_fences(t: str) -> str:
    t = t.strip()
    if t.startswith("```"):
        t = re.sub(r"^```[A-Za-z0-9_-]*\s*", "", t)
        t = re.sub(r"\s*```$", "", t)
    return t.strip()


def _strip_think_blocks(t: str) -> str:
    """Remove completed and trailing unclosed <think>/<thought>/<reasoning> blocks."""
    cleaned = re.sub(
        r"<(?:think|thought|reasoning|\|thought\|)\b[^>]*>.*?</(?:think|thought|reasoning|\|thought\|)\s*>",
        "",
        t or "",
        flags=re.I | re.S,
    )
    cleaned = re.sub(r"<(?:think|thought|reasoning|\|thought\|)\b[^>]*>.*$", "", cleaned, flags=re.I | re.S)
    return cleaned


def llm_single_line_prompt(reply: str) -> str:
    """Collapse a VLM reply into exactly one clean single-line prompt: strips
    reasoning tags, code fences, quotes, XML tags, numbering and line breaks."""
    t = _strip_think_blocks(reply or "")
    t = _strip_code_fences(t)
    t = re.sub(r"</?prompt(?:_\d+)?\b[^>]*>", "", t, flags=re.I)
    t = xml_unescape(t)
    t = re.sub(r"^\s*(?:prompt|caption|output)\s*[:\-]\s*", "", t, flags=re.I)
    t = t.replace("```", "")
    t = t.replace("\u201c", "").replace("\u201d", "")
    t = t.strip().strip('"').strip("'").strip()
    return " ".join(t.split())


def llm_reply_has_blocks(text: str) -> bool:
    return bool(re.search(r"<prompt(?:_\d+)?\b[^>]*>.*?</prompt(?:_\d+)?\s*>", _strip_think_blocks(text or ""), flags=re.I | re.S))


def llm_extract_prompts(text: str) -> List[str]:
    cleaned = _strip_code_fences(_strip_think_blocks(text or ""))
    blocks = re.findall(r"<prompt(?:_\d+)?\b[^>]*>(.*?)</prompt(?:_\d+)?\s*>", cleaned, flags=re.I | re.S)
    if blocks:
        return [" ".join(xml_unescape(b).split()).strip() for b in blocks if b.strip()]
    out: List[str] = []
    for ln in cleaned.splitlines():
        s = re.sub(r"^\s*(?:\d+[\.\)]\s*|[-*]\s*)", "", ln).strip()
        if len(s) >= 8 and not s.startswith("<"):
            out.append(s)
    return out


class StreamingPromptParser:
    """Incremental real-time prompt parser for streamed LLM output (v14.0).
    - Cleanly filters inline <think>, <thought>, <reasoning>, and <|thought|>
      reasoning blocks while counting thinking text separately.
    - Immediately emits each `<prompt>...</prompt>` (or `<prompt_N>`, `<item>`)
      block one by one the instant its closing tag arrives, unescaping XML entities.
    - Never emits conversational intro chatter ("Here are 5 prompts:") as Prompt #1!
    - Also supports incremental JSON string-array streaming (`["p1", "p2"]`) AND
      numbered/line-separated fallback when a model omits XML tags.
    - On `finalize(stopped=...)`, preserves every emitted prompt and cleanly
      salvages any substantial in-progress prompt.
    """

    _OPEN_PROMPT_RE = re.compile(r"<(prompt(?:_[a-z0-9]+)?|item)\b[^>]*>", flags=re.I)
    _OPEN_PAIR_RE = re.compile(r"<(prompt(?:_[a-z0-9]+)?|candidate_[ab]|option_[ab]|[ab]|item)\b[^>]*>", flags=re.I)
    _OPEN_THINK_RE = re.compile(r"<(think|thought|reasoning|\|thought\|)\b[^>]*>", flags=re.I)
    _NUMBERED_PREFIX_RE = re.compile(r"^\s*(?:\d+[\.\)]\s*|[-*\u2022]\s*)")
    _PREAMBLE_RE = re.compile(
        r"^(?:sure|certainly|of course|okay|ok|here (?:are|is)|below (?:are|is)|"
        r"i(?:'ve| have) (?:created|generated|forged|written)|generating|prompts?\s*:)",
        flags=re.I,
    )

    def __init__(self, mode: str = "prompts") -> None:
        self.mode = mode
        self._open_tag_re = self._OPEN_PAIR_RE if mode == "pair" else self._OPEN_PROMPT_RE
        self._in_think: bool = False
        self._think_tag: str = "think"
        self._think_buf: str = ""
        self._visible_buf: str = ""
        self._scan_pos: int = 0
        self._used_xml: bool = False
        self._used_json: bool = False
        self._json_scan_pos: int = 0
        self._fallback_line_pos: int = 0
        self.emitted: List[str] = []
        self.raw_visible: str = ""
        self.raw_thinking: str = ""

    @property
    def in_thinking(self) -> bool:
        return self._in_think

    @property
    def used_xml(self) -> bool:
        return self._used_xml

    def feed_reasoning(self, delta: str) -> None:
        if delta:
            self.raw_thinking += delta

    def feed(self, delta: str) -> Tuple[List[str], str]:
        """Consume a new streamed content chunk.
        Returns `(newly_completed_prompts, live_preview_of_current_prompt)`."""
        if not delta:
            return [], self.current_preview()
        self._think_buf += delta
        self._drain_think_filter()
        if self.mode not in ("prompts", "pair"):
            return [], self.current_preview()
        newly: List[str] = []
        max_items = 2 if self.mode == "pair" else 10000

        # 1. XML tag streaming (<prompt>...</prompt>, <prompt_a>, <prompt_b>, <item>)
        while len(self.emitted) < max_items:
            tail = self._visible_buf[self._scan_pos:]
            m_open = self._open_tag_re.search(tail)
            if m_open is not None:
                self._used_xml = True
                tag_name = re.escape(m_open.group(1))
                abs_start = self._scan_pos + m_open.end()
                m_close = re.search(rf"</{tag_name}\s*>", self._visible_buf[abs_start:], flags=re.I)
                if m_close is None:
                    break
                raw_inner = self._visible_buf[abs_start:abs_start + m_close.start()]
                inner = " ".join(xml_unescape(raw_inner).split()).strip()
                self._scan_pos = abs_start + m_close.end()
                if inner:
                    self.emitted.append(inner)
                    newly.append(inner)
                continue
            break

        # 2. Incremental JSON string-array streaming (e.g. ["prompt 1", "prompt 2"])
        if not self._used_xml:
            stripped_vis = _strip_code_fences(self._visible_buf).lstrip()
            if self._used_json or stripped_vis.startswith("["):
                if not self._used_json:
                    bracket = self._visible_buf.find("[")
                    if bracket >= 0:
                        self._used_json = True
                        self._json_scan_pos = bracket + 1
                if self._used_json:
                    newly.extend(self._drain_json_strings())
                    return newly, self.current_preview()

        # 3. Non-XML line fallback streaming (preamble-safe!)
        if not self._used_xml and not self._used_json and "<prompt" not in self._visible_buf.lower() and "<item" not in self._visible_buf.lower():
            stripped_lead = self._visible_buf.lstrip()
            if not (stripped_lead.startswith("<") and len(stripped_lead) < 20 and "\n" not in stripped_lead):
                while True:
                    nl = self._visible_buf.find("\n", self._fallback_line_pos)
                    if nl < 0:
                        break
                    line_raw = self._visible_buf[self._fallback_line_pos:nl]
                    self._fallback_line_pos = nl + 1
                    cleaned = self._clean_fallback_line(line_raw)
                    if cleaned:
                        self.emitted.append(cleaned)
                        newly.append(cleaned)

        return newly, self.current_preview()

    def _drain_json_strings(self) -> List[str]:
        out: List[str] = []
        buf = self._visible_buf
        i = self._json_scan_pos
        n = len(buf)
        while i < n:
            ch = buf[i]
            if ch in " \t\r\n,":
                i += 1
                continue
            if ch == "]":
                self._json_scan_pos = i + 1
                break
            if ch == '"':
                j = i + 1
                esc = False
                closed = False
                while j < n:
                    c2 = buf[j]
                    if esc:
                        esc = False
                    elif c2 == "\\":
                        esc = True
                    elif c2 == '"':
                        closed = True
                        break
                    j += 1
                if not closed:
                    self._json_scan_pos = i
                    break
                raw_lit = buf[i:j + 1]
                self._json_scan_pos = j + 1
                i = j + 1
                try:
                    val = json.loads(raw_lit)
                except ValueError:
                    val = raw_lit.strip('"')
                if isinstance(val, str):
                    clean = " ".join(val.split()).strip()
                    if len(clean) >= 8:
                        self.emitted.append(clean)
                        out.append(clean)
                continue
            self._used_json = False
            break
        return out

    def _clean_fallback_line(self, line: str) -> str:
        s = line.strip()
        if not s or s.startswith("```"):
            return ""
        low = s.lower()
        if low in ("<prompts>", "</prompts>", "<prompt>", "</prompt>", "<items>", "</items>"):
            return ""
        if s.startswith("<") and s.endswith(">"):
            return ""
        if not self.emitted and (s.endswith(":") or self._PREAMBLE_RE.match(s)):
            if len(s) < 110 and not self._NUMBERED_PREFIX_RE.match(s):
                return ""
        s = self._NUMBERED_PREFIX_RE.sub("", s).strip()
        s = re.sub(r"^(?:prompt\s*#?\d*\s*[:\-]\s*)", "", s, flags=re.I).strip()
        if s.startswith("<") and s.endswith(">"):
            return ""
        if len(s) < 10:
            return ""
        return " ".join(xml_unescape(s).split())

    def _drain_think_filter(self) -> None:
        while self._think_buf:
            if self._in_think:
                close_pat = rf"</{re.escape(self._think_tag)}\s*>"
                m_end = re.search(close_pat, self._think_buf, flags=re.I)
                if m_end is not None:
                    self.raw_thinking += self._think_buf[:m_end.start()]
                    self._think_buf = self._think_buf[m_end.end():]
                    self._in_think = False
                    continue
                keep = min(len(self._think_buf), len(self._think_tag) + 4)
                if len(self._think_buf) > keep:
                    self.raw_thinking += self._think_buf[:-keep]
                    self._think_buf = self._think_buf[-keep:]
                break
            else:
                m_start = self._OPEN_THINK_RE.search(self._think_buf)
                if m_start is not None:
                    vis = self._think_buf[:m_start.start()]
                    if vis:
                        self._visible_buf += vis
                        self.raw_visible += vis
                    self._think_tag = m_start.group(1)
                    self._think_buf = self._think_buf[m_start.end():]
                    self._in_think = True
                    continue
                lt = self._think_buf.rfind("<")
                if lt >= 0 and len(self._think_buf) - lt < 14:
                    tail = self._think_buf[lt:].lower()
                    if any(cand.startswith(tail) for cand in ("<think", "<thought", "<reasoning", "<|thought|")):
                        vis = self._think_buf[:lt]
                        if vis:
                            self._visible_buf += vis
                            self.raw_visible += vis
                        self._think_buf = self._think_buf[lt:]
                        break
                self._visible_buf += self._think_buf
                self.raw_visible += self._think_buf
                self._think_buf = ""
                break

    def current_preview(self) -> str:
        """Return live in-progress text of the prompt currently being streamed."""
        if self.mode == "single":
            return llm_single_line_prompt(self._visible_buf)
        if self.mode == "raw":
            return _strip_code_fences(self._visible_buf).strip()
        if self._used_xml:
            tail = self._visible_buf[self._scan_pos:]
            m_open = self._OPEN_PROMPT_RE.search(tail)
            if m_open is not None:
                partial = tail[m_open.end():]
                cut = partial.rfind("</")
                if cut >= 0 and len(partial) - cut < 14:
                    partial = partial[:cut]
                return " ".join(xml_unescape(partial).split()).strip()
            return ""
        if self._used_json:
            rem = self._visible_buf[self._json_scan_pos:].lstrip(" \t\r\n,")
            if rem.startswith('"'):
                partial = rem[1:].replace('\\"', '"').replace("\\n", " ")
                return " ".join(partial.split()).strip()
            return ""
        rem = self._visible_buf[self._fallback_line_pos:].strip()
        if rem.startswith("```") or (rem.startswith("<") and len(rem) < 20):
            return ""
        if not self.emitted and (rem.endswith(":") or self._PREAMBLE_RE.match(rem)) and len(rem) < 90:
            return ""
        rem = self._NUMBERED_PREFIX_RE.sub("", rem).strip()
        return " ".join(xml_unescape(rem).split())

    def finalize(self, stopped: bool = False) -> List[str]:
        """Flush any trailing buffered text at stream completion or user Stop.
        Returns any final prompt(s) newly emitted on close."""
        if self._think_buf:
            if self._in_think:
                self.raw_thinking += self._think_buf
            else:
                self._visible_buf += self._think_buf
                self.raw_visible += self._think_buf
            self._think_buf = ""

        if self.mode == "single":
            p = llm_single_line_prompt(self._visible_buf)
            if p:
                self.emitted = [p]
                return [p]
            return []
        if self.mode == "raw":
            t = _strip_code_fences(self._visible_buf).strip()
            if t.startswith('"') and t.endswith('"'):
                t = t.strip('"').strip()
            if t:
                self.emitted = [t]
                return [t]
            return []

        newly: List[str] = []
        max_items = 2 if self.mode == "pair" else 10000
        if self._used_xml:
            while len(self.emitted) < max_items:
                tail = self._visible_buf[self._scan_pos:]
                m_open = self._open_tag_re.search(tail)
                if m_open is None:
                    break
                tag_name = re.escape(m_open.group(1))
                abs_start = self._scan_pos + m_open.end()
                m_close = re.search(rf"</{tag_name}\s*>", self._visible_buf[abs_start:], flags=re.I)
                if m_close is None:
                    break
                inner = " ".join(xml_unescape(self._visible_buf[abs_start:abs_start + m_close.start()]).split()).strip()
                self._scan_pos = abs_start + m_close.end()
                if inner:
                    self.emitted.append(inner)
                    newly.append(inner)
            tail2 = self._visible_buf[self._scan_pos:]
            m_open = self._open_tag_re.search(tail2)
            if m_open is not None and len(self.emitted) < max_items:
                rem = re.sub(r"</?(?:prompt(?:_[a-z0-9]+)?|candidate_[ab]|option_[ab]|[ab]|item)\b[^>]*>", "", tail2[m_open.end():], flags=re.I)
                rem = " ".join(xml_unescape(rem).split()).strip()
                if len(rem) >= (18 if stopped else 10):
                    self.emitted.append(rem)
                    newly.append(rem)
        elif self.mode == "pair" and not self.emitted and _strip_code_fences(self._visible_buf).lstrip().startswith("{"):
            # Fallback JSON object parsing: {"prompt_a": "...", "prompt_b": "..."} or {"a": "...", "b": "..."}
            try:
                jdoc = json.loads(_strip_code_fences(self._visible_buf))
                if isinstance(jdoc, dict):
                    for ka in ("prompt_a", "a", "A", "first", "prompt_1", "option_a"):
                        va = jdoc.get(ka)
                        if isinstance(va, str) and va.strip():
                            pa = " ".join(va.split()).strip()
                            self.emitted.append(pa)
                            newly.append(pa)
                            break
                    for kb in ("prompt_b", "b", "B", "second", "prompt_2", "option_b"):
                        vb = jdoc.get(kb)
                        if isinstance(vb, str) and vb.strip():
                            pb = " ".join(vb.split()).strip()
                            self.emitted.append(pb)
                            newly.append(pb)
                            break
            except ValueError:
                pass
        elif self._used_json:
            newly.extend(self._drain_json_strings())
            rem = self._visible_buf[self._json_scan_pos:].lstrip(" \t\r\n,")
            if rem.startswith('"'):
                partial = " ".join(rem[1:].rstrip('"] \r\n').replace('\\"', '"').split()).strip()
                if len(partial) >= (18 if stopped else 10):
                    self.emitted.append(partial)
                    newly.append(partial)
        else:
            rem = self._visible_buf[self._fallback_line_pos:]
            for ln in rem.splitlines():
                cleaned = self._clean_fallback_line(ln)
                if cleaned:
                    self.emitted.append(cleaned)
                    newly.append(cleaned)
        return newly

def llm_list_models(
    base_url: str,
    api_key: str,
    timeout: float = 30.0,
    cancel_token: Optional[LlmCancelToken] = None,
) -> List[str]:
    base = base_url.strip().rstrip("/")
    if not base:
        raise LlmError("API Base URL is empty (e.g. https://api.openai.com/v1 or http://127.0.0.1:1234/v1)")
    doc = _llm_request("GET", f"{base}/models", api_key, timeout=timeout, cancel_token=cancel_token)
    items = doc.get("data") or doc.get("models") or []
    out: List[str] = []
    for it in items:
        if isinstance(it, dict) and it.get("id"):
            out.append(str(it["id"]))
        elif isinstance(it, str) and it.strip():
            out.append(it.strip())
    out.sort(key=str.lower)
    return out



_REASONING_PART_TYPES = frozenset((
    "thinking", "reasoning", "reasoning_text", "reasoning.text", "reasoning.summary", "summary_text",
))


def _reasoning_text(node: Any) -> str:
    """Flatten the reasoning field variants used by OpenAI-compatible servers into text
    (plain string, {"text"|"content"|"thinking"|"summary": ...} objects, or lists of them).
    Encrypted / redacted reasoning blocks carry no readable text and yield ''."""
    if isinstance(node, str):
        return node
    if isinstance(node, list):
        return "".join(_reasoning_text(v) for v in node)
    if isinstance(node, dict):
        for key in ("text", "content", "thinking", "summary"):
            val = node.get(key)
            if isinstance(val, str) and val:
                return val
            if isinstance(val, list):
                return "".join(_reasoning_text(v) for v in val)
    return ""


def _split_message_parts(msg: Dict[str, Any], fallback_text: str = "") -> Tuple[str, str]:
    """Split one chat `delta` / `message` object into (answer text, reasoning text).

    Reasoning is read from `reasoning_content` (DeepSeek, Qwen, GLM, llama.cpp, vLLM),
    `reasoning` (OpenRouter, Ollama /v1, Groq), `thinking` (Ollama native),
    `reasoning_details` (OpenRouter structured blocks) and typed content parts
    (`{"type": "thinking", ...}`), which must never leak into the answer text."""
    raw = msg.get("content")
    content = ""
    part_reasoning = ""
    if isinstance(raw, list):
        for part in raw:
            if isinstance(part, str):
                content += part
            elif isinstance(part, dict):
                ptype = str(part.get("type") or "text")
                if ptype in _REASONING_PART_TYPES:
                    part_reasoning += _reasoning_text(part)
                elif ptype != "redacted_thinking":
                    content += str(part.get("text") or "")
    elif raw is not None:
        content = str(raw)
    else:
        content = fallback_text
    reasoning = ""
    for key in ("reasoning_content", "reasoning", "thinking", "reasoning_details"):
        reasoning = _reasoning_text(msg.get(key))
        if reasoning:
            break
    return content, reasoning + part_reasoning


def _extract_delta_parts(obj: Dict[str, Any]) -> Tuple[str, str, Optional[Dict[str, Any]]]:
    """Extract (content_delta, reasoning_delta, usage_dict) from one SSE JSON frame,
    Ollama NDJSON frame, or non-streaming chat completion payload."""
    usage = obj.get("usage") if isinstance(obj.get("usage"), dict) else None
    if usage is None and isinstance(obj.get("eval_count"), int):
        usage = {
            "completion_tokens": int(obj["eval_count"]),
            "prompt_tokens": int(obj.get("prompt_eval_count") or 0),
        }
    choices = obj.get("choices") or []
    if not choices or not isinstance(choices[0], dict):
        msg = obj.get("message")
        if isinstance(msg, dict):
            content, reasoning = _split_message_parts(msg)
            return content, reasoning, usage
        if isinstance(obj.get("response"), str):
            return str(obj.get("response") or ""), _reasoning_text(obj.get("thinking")), usage
        return "", "", usage
    ch0 = choices[0]
    delta = ch0.get("delta")
    if not isinstance(delta, dict):
        delta = ch0.get("message") if isinstance(ch0.get("message"), dict) else {}
    content, reasoning = _split_message_parts(delta, fallback_text=str(ch0.get("text") or ""))
    return content, reasoning, usage


def _llm_stream_completion(
    base_url: str,
    api_key: str,
    body: Dict[str, Any],
    on_delta: Callable[[str, str, Optional[Dict[str, Any]]], None],
    cancel_token: Optional[LlmCancelToken] = None,
    timeout: float = 240.0,
    stream: bool = True,
) -> Dict[str, Any]:
    """Execute an OpenAI-compatible chat completion with full SSE / NDJSON streaming,
    usage tracking, automatic fallback if `stream_options` is unsupported, and
    true socket-level instant cancellation via `cancel_token`."""
    base = base_url.strip().rstrip("/")
    if not base:
        raise LlmError("API Base URL is empty.")
    url = f"{base}/chat/completions"

    if not stream:
        req_body = dict(body)
        req_body["stream"] = False
        doc = _llm_request("POST", url, api_key, body=req_body, timeout=timeout, cancel_token=cancel_token)
        content, reasoning, usage = _extract_delta_parts(doc)
        if content or reasoning or usage:
            on_delta(content, reasoning, usage)
        return {"usage": usage, "streamed": False}

    def _process_stream_line(raw_line: bytes, state: Dict[str, Any]) -> bool:
        line = raw_line.decode("utf-8", "replace").strip()
        if not line or line.startswith(":"):
            return True
        if line.startswith("data:"):
            state["saw_sse"] = True
            payload_str = line[5:].strip()
            if payload_str == "[DONE]":
                return False
            try:
                frame = json.loads(payload_str)
            except ValueError:
                return True
        elif not state["saw_sse"] and line.startswith("{"):
            try:
                frame = json.loads(line)
            except ValueError:
                return True
        else:
            return True

        if isinstance(frame, dict):
            if isinstance(frame.get("error"), dict):
                emsg = frame["error"].get("message") or str(frame["error"])
                raise LlmError(f"Stream error: {emsg}")
            content, reasoning, usage = _extract_delta_parts(frame)
            if usage:
                state["last_usage"] = usage
            if content or reasoning or usage:
                on_delta(content, reasoning, usage)
            if frame.get("done") is True and "choices" not in frame:
                return False
        return True

    def _run_sse(req_body: Dict[str, Any]) -> Dict[str, Any]:
        if cancel_token is not None and cancel_token.cancelled:
            raise LlmCancelled()
        headers = _llm_headers(api_key, accept_sse=True)
        t0 = time.monotonic()
        STUDIO_LOG.net("LLM", f"POST {url} (stream=true)")
        state: Dict[str, Any] = {"last_usage": None, "saw_sse": False}
        scheme = (urllib.parse.urlsplit(url).scheme or "https").lower()
        use_direct_http = not _llm_has_proxy_env(scheme)

        if use_direct_http:
            body_bytes = json.dumps(req_body).encode("utf-8")
            conn, resp = _llm_open_http("POST", url, headers, body_bytes, timeout, cancel_token=cancel_token)
            try:
                status = resp.status
                ctype = (resp.getheader("Content-Type") or "").lower()
                if status >= 400:
                    raw_err = _llm_read_response_all(resp, 15.0, cancel_token=cancel_token).decode("utf-8", "replace")[:400]
                    detail = raw_err
                    try:
                        ed = json.loads(raw_err)
                        eo = ed.get("error") if isinstance(ed, dict) else None
                        if isinstance(eo, dict):
                            detail = eo.get("message") or str(eo)
                        elif isinstance(eo, str):
                            detail = eo
                    except ValueError:
                        pass
                    raise LlmError(f"HTTP {status}: {detail}", status=status, raw_snippet=raw_err[:240])

                if "application/json" in ctype and "text/event-stream" not in ctype and "ndjson" not in ctype:
                    raw_all = _llm_read_response_all(resp, timeout, cancel_token=cancel_token).decode("utf-8", "replace")
                    try:
                        doc = json.loads(raw_all)
                    except ValueError as exc:
                        raise LlmError(f"Invalid JSON completion body: {raw_all[:200]}", status=status) from exc
                    content, reasoning, usage = _extract_delta_parts(doc)
                    if content or reasoning or usage:
                        on_delta(content, reasoning, usage)
                    dt = int((time.monotonic() - t0) * 1000)
                    STUDIO_LOG.ok("LLM", f"POST /chat/completions (non-SSE fallback) -> HTTP {status} ({dt}ms)")
                    return {"usage": usage, "streamed": False}

                for raw_line in _llm_iter_lines_cancellable(resp, timeout, cancel_token=cancel_token):
                    if cancel_token is not None and cancel_token.cancelled:
                        raise LlmCancelled()
                    if not _process_stream_line(raw_line, state):
                        break
            except LlmCancelled:
                raise
            except LlmError:
                raise
            except Exception as exc:  # noqa: BLE001
                if cancel_token is not None and cancel_token.cancelled:
                    raise LlmCancelled() from exc
                raise LlmError(f"Stream connection error: {exc.__class__.__name__}: {exc}") from exc
            finally:
                _llm_close_handle(conn)
        elif _HAS_REQUESTS and requests is not None:
            sess = requests.Session()
            if cancel_token is not None:
                cancel_token.register_closer(sess.close)
            try:
                r = sess.post(url, headers=headers, json=req_body, timeout=(15.0, timeout), stream=True)
                if cancel_token is not None:
                    cancel_token.register_closer(lambda resp=r: _llm_close_handle(resp))
                status = r.status_code
                ctype = (r.headers.get("Content-Type") or "").lower()
                if status >= 400:
                    raw_err = r.text[:400]
                    detail = raw_err
                    try:
                        ed = json.loads(raw_err)
                        eo = ed.get("error") if isinstance(ed, dict) else None
                        if isinstance(eo, dict):
                            detail = eo.get("message") or str(eo)
                        elif isinstance(eo, str):
                            detail = eo
                    except ValueError:
                        pass
                    raise LlmError(f"HTTP {status}: {detail}", status=status, raw_snippet=raw_err[:240])

                if "application/json" in ctype and "text/event-stream" not in ctype and "ndjson" not in ctype:
                    raw_all = r.text
                    try:
                        doc = json.loads(raw_all)
                    except ValueError as exc:
                        raise LlmError(f"Invalid JSON completion body: {raw_all[:200]}", status=status) from exc
                    content, reasoning, usage = _extract_delta_parts(doc)
                    if content or reasoning or usage:
                        on_delta(content, reasoning, usage)
                    dt = int((time.monotonic() - t0) * 1000)
                    STUDIO_LOG.ok("LLM", f"POST /chat/completions (non-SSE fallback) -> HTTP {status} ({dt}ms)")
                    return {"usage": usage, "streamed": False}

                for raw_line in r.iter_lines(chunk_size=1, decode_unicode=False):
                    if cancel_token is not None and cancel_token.cancelled:
                        raise LlmCancelled()
                    if raw_line and not _process_stream_line(raw_line, state):
                        break
            except LlmCancelled:
                raise
            except LlmError:
                raise
            except Exception as exc:  # noqa: BLE001
                if cancel_token is not None and cancel_token.cancelled:
                    raise LlmCancelled() from exc
                raise LlmError(f"Stream connection error: {exc.__class__.__name__}: {exc}") from exc
            finally:
                try:
                    sess.close()
                except Exception:  # noqa: BLE001
                    pass
        else:
            payload = json.dumps(req_body).encode("utf-8")
            req = urllib.request.Request(url, data=payload, headers=headers, method="POST")
            try:
                resp = urllib.request.urlopen(req, timeout=timeout)
                if cancel_token is not None:
                    cancel_token.register_closer(lambda rp=resp: _llm_close_handle(rp))
                with resp:
                    status = resp.status
                    ctype = (resp.headers.get("Content-Type") or "").lower()
                    if "application/json" in ctype and "text/event-stream" not in ctype and "ndjson" not in ctype:
                        raw_all = resp.read().decode("utf-8", "replace")
                        doc = json.loads(raw_all)
                        content, reasoning, usage = _extract_delta_parts(doc)
                        if content or reasoning or usage:
                            on_delta(content, reasoning, usage)
                        return {"usage": usage, "streamed": False}
                    while True:
                        if cancel_token is not None and cancel_token.cancelled:
                            raise LlmCancelled()
                        raw_line = resp.readline()
                        if not raw_line:
                            break
                        if not _process_stream_line(raw_line, state):
                            break
            except urllib.error.HTTPError as exc:
                raw_err = exc.read().decode("utf-8", "replace")[:400]
                raise LlmError(f"HTTP {exc.code}: {raw_err[:220]}", status=exc.code, raw_snippet=raw_err[:240]) from exc
            except LlmCancelled:
                raise
            except LlmError:
                raise
            except Exception as exc:  # noqa: BLE001
                if cancel_token is not None and cancel_token.cancelled:
                    raise LlmCancelled() from exc
                raise LlmError(f"Stream connection error: {exc.__class__.__name__}: {exc}") from exc

        dt = int((time.monotonic() - t0) * 1000)
        STUDIO_LOG.ok("LLM", f"SSE stream complete ({dt}ms)")
        return {"usage": state["last_usage"], "streamed": True}

    body_with_usage = dict(body)
    body_with_usage["stream"] = True
    body_with_usage["stream_options"] = {"include_usage": True}
    try:
        return _run_sse(body_with_usage)
    except LlmError as exc:
        if exc.status in (400, 422) and "stream_options" in (exc.message + exc.raw_snippet).lower():
            STUDIO_LOG.net("LLM", "Endpoint rejected stream_options — retrying SSE without stream_options")
            body_plain = dict(body)
            body_plain["stream"] = True
            return _run_sse(body_plain)
        raise

def llm_chat(
    base_url: str,
    api_key: str,
    model: str,
    system: str,
    user: str,
    temperature: float = 0.75,
    top_p: float = 0.92,
    timeout: float = 180.0,
    max_tokens: int = 0,
    cancel_token: Optional[LlmCancelToken] = None,
) -> str:
    base = base_url.strip().rstrip("/")
    if not base:
        raise LlmError("API Base URL is empty.")
    if not model.strip():
        raise LlmError("No LLM model selected.")
    messages: List[Dict[str, str]] = []
    if system.strip():
        messages.append({"role": "system", "content": system.strip()})
    messages.append({"role": "user", "content": user.strip()})
    body: Dict[str, Any] = {
        "model": model.strip(),
        "messages": messages,
        "temperature": float(temperature),
        "top_p": float(top_p),
    }
    if int(max_tokens) > 0:
        body["max_tokens"] = int(max_tokens)
    doc = _llm_request("POST", f"{base}/chat/completions", api_key, body=body, timeout=timeout, cancel_token=cancel_token)
    content, _r, _u = _extract_delta_parts(doc)
    content = content.strip()
    if not content:
        STUDIO_LOG.warn("LLM", "Endpoint returned empty assistant content.")
    return content


def llm_vision_chat(
    base_url: str,
    api_key: str,
    model: str,
    system: str,
    instruction: str,
    image_data_urls: Any,
    temperature: float = 0.4,
    top_p: float = 0.9,
    timeout: float = 240.0,
    max_tokens: int = 0,
    cancel_token: Optional[LlmCancelToken] = None,
) -> str:
    base = base_url.strip().rstrip("/")
    if not base:
        raise LlmError("API Base URL is empty.")
    if not model.strip():
        raise LlmError("No VLM model selected.")
    if isinstance(image_data_urls, str):
        image_data_urls = [image_data_urls]
    urls = [u for u in (image_data_urls or []) if isinstance(u, str) and u.strip()]
    if not urls:
        raise LlmError("No image attached for the vision request.")
    messages: List[Dict[str, Any]] = []
    if system.strip():
        messages.append({"role": "system", "content": system.strip()})
    content_parts: List[Dict[str, Any]] = [
        {"type": "text", "text": instruction.strip() or "Caption this image as a text-to-image prompt."}
    ]
    for u in urls:
        content_parts.append({"type": "image_url", "image_url": {"url": u}})
    messages.append({"role": "user", "content": content_parts})
    body: Dict[str, Any] = {
        "model": model.strip(),
        "messages": messages,
        "temperature": float(temperature),
        "top_p": float(top_p),
    }
    if int(max_tokens) > 0:
        body["max_tokens"] = int(max_tokens)
    doc = _llm_request("POST", f"{base}/chat/completions", api_key, body=body, timeout=timeout, cancel_token=cancel_token)
    content, _r, _u = _extract_delta_parts(doc)
    content = content.strip()
    if not content:
        STUDIO_LOG.warn("LLM", "VLM endpoint returned empty assistant content.")
    return content


def image_to_vlm_data_url(path: str, max_side: int = 1152) -> str:
    """Load an image, downscale it to a VLM-friendly size and return a JPEG
    data-URL (base64). Raises LlmError when the file cannot be decoded."""
    img = QImage(path)
    if img.isNull():
        raise LlmError(f"Cannot decode image: {os.path.basename(path)}")
    if img.width() * img.height() > IMAGE_SANITY_MAX_MP:
        raise LlmError("Image is too large to send to a VLM.")
    if img.width() > max_side or img.height() > max_side:
        img = img.scaled(
            max_side, max_side,
            Qt.AspectRatioMode.KeepAspectRatio,
            Qt.TransformationMode.SmoothTransformation,
        )
    if img.hasAlphaChannel():
        flat = QImage(img.size(), QImage.Format.Format_RGB32)
        flat.fill(Qt.GlobalColor.black)
        painter = QPainter(flat)
        painter.drawImage(0, 0, img)
        painter.end()
        img = flat
    else:
        img = img.convertToFormat(QImage.Format.Format_RGB32)
    buf = QBuffer()
    buf.open(QBuffer.OpenModeFlag.WriteOnly)
    if not img.save(buf, "JPEG", 90):
        buf.close()
        raise LlmError("JPEG re-encode of the image failed.")
    b64 = base64.b64encode(bytes(buf.data())).decode("ascii")
    buf.close()
    STUDIO_LOG.net("LLM", f"VLM attachment: {img.width()}x{img.height()} jpeg, {len(b64) // 1024} KiB b64")
    return f"data:image/jpeg;base64,{b64}"



class LlmStreamWorker(QThread):
    """Cancellable streaming LLM / VLM worker thread (v14.0).
    - Counts streamed output tokens & reasoning tokens live (snapping to exact
      server `usage.completion_tokens` / `reasoning_tokens` when provided).
    - Computes TTFT + live generation speed (tok/s) & runs a lightweight 280ms
      heartbeat so elapsed time ticks smoothly during connect/thinking pauses.
    - Batches raw_chunk emissions (~14Hz) to eliminate low-end laptop GUI lag.
    - Emits parsed prompts one-by-one as they complete during streaming.
    - Aborts immediately on `stop()` via `LlmCancelToken` (socket shutdown).
    """

    prompt_parsed = pyqtSignal(str, str)        # (prompt_text, tag)
    preview_changed = pyqtSignal(str, int)      # (partial_text, prompt_index)
    raw_chunk = pyqtSignal(str, bool)           # (delta_text, is_reasoning)
    stats_changed = pyqtSignal(dict)            # live telemetry dict
    completed = pyqtSignal(dict)                # final summary dict
    failed = pyqtSignal(str)                    # error message

    def __init__(
        self,
        *,
        task_kind: str,
        base_url: str,
        api_key: str,
        model: str,
        system: str,
        user_text: str,
        temperature: float,
        top_p: float,
        max_tokens: int = 0,
        reasoning_effort: str = "",
        stream: bool = True,
        image_paths: Optional[List[str]] = None,
        tag: str = "",
        mode_label: str = "",
        timeout: float = 240.0,
        parent: Optional[QObject] = None,
    ) -> None:
        super().__init__(parent)
        self.task_kind = task_kind
        self.base_url = base_url.strip().rstrip("/")
        self.api_key = api_key.strip()
        self.model = model.strip()
        self.system = system
        self.user_text = user_text
        self.temperature = float(temperature)
        self.top_p = float(top_p)
        self.max_tokens = max(0, int(max_tokens))
        self.reasoning_effort = str(reasoning_effort or "").strip().lower()
        self.stream = bool(stream)
        self.image_paths = list(image_paths or [])
        self.tag = tag
        self.mode_label = mode_label
        self.timeout = float(timeout)
        self.cancel_token = LlmCancelToken()

    def stop(self) -> None:
        self.cancel_token.cancel()

    def run(self) -> None:
        t0 = time.monotonic()
        parser_mode = (
            "pair" if self.task_kind == "self_improve"
            else ("prompts" if self.task_kind == "forge" else ("single" if self.task_kind == "describe" else "raw"))
        )
        parser = StreamingPromptParser(mode=parser_mode)
        exact_comp_tokens: Optional[int] = None
        exact_reason_tokens: Optional[int] = None
        exact_prompt_tokens: Optional[int] = None
        first_token_at: Optional[float] = None
        chunk_count = 0
        last_ui_emit = 0.0
        last_preview = ""
        emitted_count = 0
        think_sent = 0  # chars of parser.raw_thinking already forwarded to the Reasoning panel
        cur_phase = "connecting"
        raw_buf_parts: List[Tuple[str, bool]] = []
        raw_lock = threading.Lock()
        hb_stop = threading.Event()

        def _flush_raw_chunks() -> None:
            with raw_lock:
                if not raw_buf_parts:
                    return
                batch = list(raw_buf_parts)
                raw_buf_parts.clear()
            merged_txt = ""
            merged_flag: Optional[bool] = None
            for txt, flag in batch:
                if merged_flag is None:
                    merged_flag = flag
                    merged_txt = txt
                elif flag == merged_flag:
                    merged_txt += txt
                else:
                    if merged_txt:
                        self.raw_chunk.emit(merged_txt, bool(merged_flag))
                    merged_flag = flag
                    merged_txt = txt
            if merged_txt and merged_flag is not None:
                self.raw_chunk.emit(merged_txt, bool(merged_flag))

        def _snapshot(phase: str) -> Dict[str, Any]:
            now_m = time.monotonic()
            dt = max(0.001, now_m - t0)
            est_vis = estimate_tokens(parser.raw_visible) if parser.raw_visible else 0
            est_think = estimate_tokens(parser.raw_thinking) if parser.raw_thinking else 0
            if exact_comp_tokens is not None:
                out_tok = exact_comp_tokens
                exact = True
            else:
                out_tok = max(est_vis + est_think, chunk_count if (est_vis + est_think) == 0 else 0)
                exact = False
            think_tok = exact_reason_tokens if exact_reason_tokens is not None else est_think
            gen_dt = max(0.05, now_m - first_token_at) if first_token_at is not None else dt
            tps = out_tok / gen_dt if out_tok > 0 else 0.0
            ttft = (first_token_at - t0) if first_token_at is not None else None
            return {
                "task_kind": self.task_kind,
                "phase": phase,
                "tokens": out_tok,
                "think_tokens": think_tok,
                "prompt_tokens": exact_prompt_tokens,
                "exact_usage": exact,
                "tps": tps,
                "ttft": ttft,
                "elapsed": dt,
                "prompts": emitted_count,
                "used_xml": parser.used_xml,
                "mode_label": self.mode_label,
                "raw_text": parser.raw_visible,
            }

        def _heartbeat_loop() -> None:
            while not hb_stop.wait(0.28):
                if self.cancel_token.cancelled:
                    break
                if (time.monotonic() - last_ui_emit) >= 0.25:
                    _flush_raw_chunks()
                    self.stats_changed.emit(_snapshot(cur_phase))

        hb_thread = threading.Thread(target=_heartbeat_loop, daemon=True)
        try:
            if not self.base_url:
                raise LlmError("API Base URL is empty (e.g. https://api.openai.com/v1 or http://127.0.0.1:1234/v1)")
            if not self.model:
                raise LlmError("No LLM/VLM model selected.")

            self.stats_changed.emit(_snapshot("connecting"))
            hb_thread.start()

            messages: List[Dict[str, Any]] = []
            if self.system.strip():
                messages.append({"role": "system", "content": self.system.strip()})

            if self.image_paths:
                data_urls: List[str] = []
                for p in self.image_paths:
                    if self.cancel_token.cancelled:
                        raise LlmCancelled()
                    data_urls.append(image_to_vlm_data_url(p))
                parts: List[Dict[str, Any]] = [{"type": "text", "text": self.user_text.strip()}]
                for u in data_urls:
                    parts.append({"type": "image_url", "image_url": {"url": u}})
                messages.append({"role": "user", "content": parts})
            else:
                messages.append({"role": "user", "content": self.user_text.strip()})

            body: Dict[str, Any] = {
                "model": self.model,
                "messages": messages,
                "temperature": self.temperature,
                "top_p": self.top_p,
            }
            if self.max_tokens > 0:
                body["max_tokens"] = self.max_tokens
            if self.reasoning_effort in ("low", "medium", "high"):
                # Optional hint; "Auto" sends nothing so strict servers never see an unknown field.
                body["reasoning_effort"] = self.reasoning_effort

            def _on_delta(content_d: str, reason_d: str, usage: Optional[Dict[str, Any]]) -> None:
                nonlocal exact_comp_tokens, exact_reason_tokens, exact_prompt_tokens
                nonlocal first_token_at, chunk_count, last_ui_emit, last_preview, emitted_count, cur_phase
                nonlocal think_sent

                if (content_d or reason_d) and first_token_at is None:
                    first_token_at = time.monotonic()

                if usage:
                    ct = usage.get("completion_tokens")
                    if isinstance(ct, int) and ct >= 0:
                        exact_comp_tokens = ct
                    pt = usage.get("prompt_tokens")
                    if isinstance(pt, int) and pt >= 0:
                        exact_prompt_tokens = pt
                    details = usage.get("completion_tokens_details")
                    if isinstance(details, dict) and isinstance(details.get("reasoning_tokens"), int):
                        exact_reason_tokens = int(details["reasoning_tokens"])

                if reason_d:
                    parser.feed_reasoning(reason_d)
                    chunk_count += 1
                    think_sent = len(parser.raw_thinking)
                    with raw_lock:
                        raw_buf_parts.append((reason_d, True))

                if content_d:
                    chunk_count += 1
                    with raw_lock:
                        raw_buf_parts.append((content_d, False))
                    newly, preview = parser.feed(content_d)
                    if len(parser.raw_thinking) > think_sent:
                        # Inline <think>...</think> text isolated by the parser joins the Reasoning panel too.
                        inline_think = parser.raw_thinking[think_sent:]
                        think_sent = len(parser.raw_thinking)
                        with raw_lock:
                            raw_buf_parts.append((inline_think, True))
                    for item in newly:
                        emitted_count += 1
                        self.prompt_parsed.emit(item, self.tag)
                    now = time.monotonic()
                    cur_phase = "thinking" if (parser.in_thinking or (reason_d and not content_d)) else "streaming"
                    if newly or (now - last_ui_emit) >= 0.075:
                        last_ui_emit = now
                        _flush_raw_chunks()
                        if preview != last_preview:
                            last_preview = preview
                            self.preview_changed.emit(preview, emitted_count + 1)
                        self.stats_changed.emit(_snapshot(cur_phase))
                elif reason_d:
                    cur_phase = "thinking"
                    now = time.monotonic()
                    if (now - last_ui_emit) >= 0.085:
                        last_ui_emit = now
                        _flush_raw_chunks()
                        self.stats_changed.emit(_snapshot("thinking"))

            stopped = False
            try:
                _llm_stream_completion(
                    self.base_url,
                    self.api_key,
                    body,
                    _on_delta,
                    cancel_token=self.cancel_token,
                    timeout=self.timeout,
                    stream=self.stream,
                )
            except LlmCancelled:
                stopped = True

            hb_stop.set()
            _flush_raw_chunks()

            tail_items = parser.finalize(stopped=stopped)
            for item in tail_items:
                emitted_count += 1
                self.prompt_parsed.emit(item, self.tag)
            self.preview_changed.emit("", emitted_count)

            summary = _snapshot("stopped" if stopped else "done")
            summary["stopped"] = stopped
            summary["all_prompts"] = list(parser.emitted)
            self.stats_changed.emit(summary)
            self.completed.emit(summary)
        except LlmCancelled:
            hb_stop.set()
            _flush_raw_chunks()
            summary = _snapshot("stopped")
            summary["stopped"] = True
            summary["all_prompts"] = list(parser.emitted)
            self.preview_changed.emit("", emitted_count)
            self.stats_changed.emit(summary)
            self.completed.emit(summary)
        except LlmError as exc:
            hb_stop.set()
            _flush_raw_chunks()
            self.preview_changed.emit("", emitted_count)
            self.stats_changed.emit(_snapshot("error"))
            self.failed.emit(exc.message)
        except Exception as exc:  # noqa: BLE001
            hb_stop.set()
            _flush_raw_chunks()
            self.preview_changed.emit("", emitted_count)
            self.stats_changed.emit(_snapshot("error"))
            self.failed.emit(f"{exc.__class__.__name__}: {exc}")
        finally:
            hb_stop.set()
            if hb_thread.is_alive():
                hb_thread.join(timeout=0.4)
            self.cancel_token.clear_closers()

class LlmModelsWorker(QThread):
    """Cancellable background GET /models worker for the LLM tab."""

    loaded = pyqtSignal(list)
    failed = pyqtSignal(str)
    stopped = pyqtSignal()

    def __init__(self, base_url: str, api_key: str, parent: Optional[QObject] = None) -> None:
        super().__init__(parent)
        self.base_url = base_url
        self.api_key = api_key
        self.cancel_token = LlmCancelToken()

    def stop(self) -> None:
        self.cancel_token.cancel()

    def run(self) -> None:
        try:
            models = llm_list_models(self.base_url, self.api_key, timeout=25.0, cancel_token=self.cancel_token)
            if self.cancel_token.cancelled:
                self.stopped.emit()
            else:
                self.loaded.emit(models)
        except LlmCancelled:
            self.stopped.emit()
        except LlmError as exc:
            self.failed.emit(exc.message)
        except Exception as exc:  # noqa: BLE001
            self.failed.emit(f"{exc.__class__.__name__}: {exc}")
        finally:
            self.cancel_token.clear_closers()


# =============================================================================
#  9. Browser Bridge (Local VPN Tunnel for Tampermonkey Userscript)
# =============================================================================
class BridgeError(Exception):
    def __init__(self, message: str, network: bool = False):
        super().__init__(message)
        self.message = message
        self.network = network


class _BridgeRequest:
    __slots__ = (
        "id", "method", "url", "headers", "body", "deadline",
        "done", "status", "resp_headers", "data", "error", "created",
    )

    def __init__(
        self,
        method: str,
        url: str,
        headers: Dict[str, str],
        body: Optional[bytes],
        timeout: float,
    ) -> None:
        self.id = secrets.token_hex(8)
        self.method = method.upper()
        self.url = url
        self.headers = dict(headers or {})
        self.body = body
        self.deadline = time.time() + min(300.0, timeout + 25.0)
        self.done = threading.Event()
        self.status = 0
        self.resp_headers: Dict[str, str] = {}
        self.data = b""
        self.error = ""
        self.created = time.time()

    def payload(self) -> Dict[str, Any]:
        return {
            "id": self.id,
            "method": self.method,
            "url": self.url,
            "headers": self.headers,
            "body_b64": base64.b64encode(self.body).decode("ascii") if self.body else "",
            "timeout_ms": int(max(1000.0, self.deadline - time.time()) * 1000),
        }


class _BridgeHandler(BaseHTTPRequestHandler):
    server_version = "HSLBridge/4.0"  # tokenless long-poll protocol (v10.2)
    protocol_version = "HTTP/1.1"

    @property
    def bridge(self) -> "BrowserBridge":
        return self.server.bridge  # type: ignore[attr-defined]

    def log_message(self, fmt: str, *args: Any) -> None:
        pass

    def _cors(self) -> None:
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "Content-Type")
        self.send_header("Access-Control-Allow-Private-Network", "true")

    def _send_json(self, code: int, obj: Dict[str, Any], close: bool = False) -> None:
        data = json.dumps(obj).encode("utf-8")
        try:
            self.send_response(code)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(data)))
            if close:
                self.send_header("Connection", "close")
                self.close_connection = True
            self._cors()
            self.end_headers()
            self.wfile.write(data)
        except (BrokenPipeError, ConnectionResetError):
            self.close_connection = True

    def _read_body(self, cap: int) -> Optional[bytes]:
        try:
            n = int(self.headers.get("Content-Length") or 0)
        except ValueError:
            n = 0
        if n <= 0:
            return b""
        if n > cap:
            return None
        return self.rfile.read(n)

    def do_OPTIONS(self) -> None:  # noqa: N802
        self.send_response(204)
        self.send_header("Content-Length", "0")
        self._cors()
        self.end_headers()

    def do_GET(self) -> None:  # noqa: N802
        # v10.1: the bridge is TOKENLESS — the connection itself is the only
        # credential. The listener is bound to 127.0.0.1 exclusively, so any
        # local browser tab that reaches it is trusted outright.
        path = urllib.parse.urlsplit(self.path).path
        if path == "/" or path == "/status":
            # v10.2: the relay answers with plain JSON status only — there is
            # no local bridge page anymore; the userscript lives on
            # stablehorde.net / aihorde.net pages, not on any local page.
            b = self.bridge
            self._send_json(200, {
                "app": f"{APP_NAME} {APP_VERSION}",
                "endpoint": HORDE_URL,
                "tokenless": True,
                "connected": b.is_connected(),
                "served": b.served,
                "client": b.client_label(),
            })
            return
        if path == "/poll":
            self._do_poll()
            return
        self._send_json(404, {"error": "unknown endpoint"})

    def _do_poll(self) -> None:
        b = self.bridge
        q = urllib.parse.parse_qs(urllib.parse.urlsplit(self.path).query)
        try:
            wait = min(30.0, max(1.0, float(q.get("timeout", ["25"])[0])))
        except (ValueError, IndexError):
            wait = BRIDGE_POLL_SECS
        b._poll_started(self.headers.get("User-Agent", ""))
        job: Optional[_BridgeRequest] = None
        try:
            deadline = time.time() + wait
            with b._cond:
                while True:
                    if b._queue:
                        job = b._queue.popleft()
                        break
                    rem = deadline - time.time()
                    if rem <= 0:
                        break
                    b._cond.wait(rem)
            self._send_json(200, {"job": job.payload() if job is not None else None})
        except (BrokenPipeError, ConnectionResetError):
            if job is not None:
                with b._cond:
                    b._queue.appendleft(job)
        finally:
            b._poll_ended()

    def do_POST(self) -> None:  # noqa: N802
        path = urllib.parse.urlsplit(self.path).path
        body = self._read_body(BRIDGE_BODY_CAP)
        if body is None:
            self._send_json(413, {"error": "reply too large"}, close=True)
            return
        if path != "/reply":
            self._send_json(404, {"error": "unknown endpoint"})
            return
        try:
            doc = json.loads(body.decode("utf-8") or "{}")
        except ValueError:
            self._send_json(400, {"error": "bad json"})
            return
        self._send_json(200 if self.bridge._deliver(doc) else 404, {"ok": True})


class BrowserBridge:
    """Local 127.0.0.1 relay that lets a browser tab (Tampermonkey userscript)
    execute every Horde API request inside the browser's network stack, so a
    VPN / proxy browser extension applies to all traffic.

    v10.2: fully TOKENLESS — connection itself is the credential. The server
    binds 127.0.0.1 only; any local tab reaching it is trusted, which removes
    the old token-mismatch deadlock where the app refused to even register a
    polling tab ("waiting for browser tab" forever). The app always ADDRESSES
    https://stablehorde.net/api/v2 — this relay only transports those requests
    through the browser while the VPN tunnel is enabled. The companion
    userscript ships as a separate file (horde_studio_bridge.user.js) and runs
    on stablehorde.net / aihorde.net pages, never on a local page."""

    def __init__(self, port: int) -> None:
        self.port = int(port)
        self._cond = threading.Condition()
        self._queue: "collections.deque[_BridgeRequest]" = collections.deque()
        self._waiters: Dict[str, _BridgeRequest] = {}
        self._active_polls = 0
        self._last_poll = 0.0
        self._last_serve = 0.0
        self._client = ""
        self._served = 0
        self._httpd: Optional[ThreadingHTTPServer] = None
        self._thread: Optional[threading.Thread] = None
        self.running = False
        self.last_error = ""

    def start(self) -> bool:
        if self.running:
            return True
        try:
            httpd = ThreadingHTTPServer(("127.0.0.1", self.port), _BridgeHandler)
        except OSError as exc:
            self.last_error = str(exc)
            STUDIO_LOG.error("BRIDGE", f"Failed to bind 127.0.0.1:{self.port}: {exc}")
            self.running = False
            return False
        httpd.daemon_threads = True
        httpd.bridge = self  # type: ignore[attr-defined]
        self._httpd = httpd
        self.running = True
        self.last_error = ""
        self._thread = threading.Thread(target=httpd.serve_forever, name="bridge-http", daemon=True)
        self._thread.start()
        STUDIO_LOG.ok("BRIDGE", f"Browser VPN bridge listening on 127.0.0.1:{self.port}")
        return True

    def stop(self) -> None:
        self.running = False
        httpd, self._httpd = self._httpd, None
        if httpd is not None:
            try:
                httpd.shutdown()
                httpd.server_close()
            except Exception:  # noqa: BLE001
                pass
        self._thread = None
        with self._cond:
            for job in list(self._waiters.values()):
                job.error = "bridge stopped"
                job.done.set()
            self._waiters.clear()
            self._queue.clear()
            self._cond.notify_all()
        STUDIO_LOG.info("BRIDGE", "Browser VPN bridge stopped")

    def _poll_started(self, label: str) -> None:
        with self._cond:
            self._active_polls += 1
            self._last_poll = time.time()
            if label:
                self._client = label

    def _poll_ended(self) -> None:
        with self._cond:
            self._active_polls = max(0, self._active_polls - 1)

    def _deliver(self, doc: Dict[str, Any]) -> bool:
        rid = str(doc.get("id") or "")
        with self._cond:
            job = self._waiters.pop(rid, None)
            if job is None:
                return False
            err = doc.get("error")
            if err:
                job.error = str(err)
            else:
                try:
                    job.status = int(doc.get("status") or 200)
                except (ValueError, TypeError):
                    job.status = 200
                job.resp_headers = dict(doc.get("headers") or {})
                b64 = doc.get("data_b64") or ""
                try:
                    job.data = base64.b64decode(b64) if b64 else b""
                except ValueError as exc:
                    job.error = f"corrupt base64 reply: {exc}"
                self._served += 1
                self._last_serve = time.time()
            job.done.set()
            return True

    def is_connected(self) -> bool:
        with self._cond:
            now = time.time()
            return (
                self._active_polls > 0
                or (now - self._last_poll) <= BRIDGE_CLIENT_TIMEOUT
                or (now - self._last_serve) <= BRIDGE_SERVE_GRACE
            )

    @property
    def served(self) -> int:
        with self._cond:
            return self._served

    def client_label(self) -> str:
        with self._cond:
            raw = self._client
        for tag in ("Firefox", "Edg/", "Chrome", "Safari", "Brave", "Opera"):
            if tag in raw:
                return "Edge" if tag == "Edg/" else tag
        return raw[:28] if raw else "browser"

    def request(
        self,
        method: str,
        url: str,
        headers: Dict[str, str],
        body: Optional[bytes],
        timeout: float,
    ) -> Tuple[int, Dict[str, str], bytes]:
        if not self.running:
            raise BridgeError("bridge is not running", network=False)
        if not self.is_connected():
            raise BridgeError(
                "browser bridge has no connected tab — install the companion "
                "horde_studio_bridge.user.js in Tampermonkey, then open "
                "https://stablehorde.net/ and keep that tab open (no token needed)",
                network=False,
            )
        job = _BridgeRequest(method, url, headers, body, timeout)
        with self._cond:
            self._waiters[job.id] = job
            self._queue.append(job)
            self._cond.notify()
        if not job.done.wait(max(5.0, timeout + 15.0)):
            with self._cond:
                self._waiters.pop(job.id, None)
                try:
                    self._queue.remove(job)
                except ValueError:
                    pass
            raise BridgeError(f"browser bridge timed out after {int(timeout)}s", network=True)
        if job.error:
            raise BridgeError(f"browser bridge: {job.error}", network=True)
        return job.status, job.resp_headers, job.data


# =============================================================================
#  10. Local SillyTavern Server (A1111-Compatible /sdapi/v1)
# =============================================================================
class LocalStServer:
    def __init__(
        self,
        port: int,
        state_fn: Callable[[], Dict[str, Any]],
        submit_fn: Callable[[str], Dict[str, Any]],
    ) -> None:
        self.port = int(port)
        self.state_fn = state_fn
        self.submit_fn = submit_fn
        self.running = False
        self.last_error = ""
        self.last_request = ""
        self._httpd: Optional[ThreadingHTTPServer] = None
        self._thread: Optional[threading.Thread] = None
        self._lock = threading.Lock()

    def _note(self, text: str, level: str = "INFO") -> None:
        with self._lock:
            self.last_request = text
        STUDIO_LOG.log("ST", level, text)

    def start(self) -> bool:
        if self.running:
            return True
        try:
            httpd = ThreadingHTTPServer(("127.0.0.1", self.port), _StHandler)
        except OSError as exc:
            self.last_error = str(exc)
            STUDIO_LOG.error("ST", f"Failed to bind SillyTavern port {self.port}: {exc}")
            self.running = False
            return False
        httpd.daemon_threads = True
        httpd.st = self  # type: ignore[attr-defined]
        self._httpd = httpd
        self.running = True
        self.last_error = ""
        self._thread = threading.Thread(target=httpd.serve_forever, name="st-server", daemon=True)
        self._thread.start()
        STUDIO_LOG.ok("ST", f"SillyTavern A1111 server listening on {self.address}")
        return True

    def stop(self) -> None:
        self.running = False
        httpd, self._httpd = self._httpd, None
        if httpd is not None:
            try:
                httpd.shutdown()
                httpd.server_close()
            except Exception:  # noqa: BLE001
                pass
        self._thread = None
        STUDIO_LOG.info("ST", "SillyTavern local server stopped")

    @property
    def address(self) -> str:
        return f"http://127.0.0.1:{self.port}"


class _StHandler(BaseHTTPRequestHandler):
    server_version = "HSLSt/3.0"
    protocol_version = "HTTP/1.1"

    @property
    def st(self) -> LocalStServer:
        return self.server.st  # type: ignore[attr-defined]

    def log_message(self, fmt: str, *args: Any) -> None:
        pass

    def _cors(self) -> None:
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "Content-Type")

    def _send_json(self, code: int, obj: Any, close: bool = False) -> None:
        data = json.dumps(obj).encode("utf-8")
        try:
            self.send_response(code)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(data)))
            if close:
                self.send_header("Connection", "close")
                self.close_connection = True
            self._cors()
            self.end_headers()
            self.wfile.write(data)
        except (BrokenPipeError, ConnectionResetError):
            self.close_connection = True

    def _read_json(self) -> Optional[Dict[str, Any]]:
        try:
            n = int(self.headers.get("Content-Length") or 0)
        except ValueError:
            n = 0
        if n <= 0:
            return {}
        if n > ST_BODY_CAP:
            return None
        try:
            return json.loads(self.rfile.read(n).decode("utf-8") or "{}")
        except ValueError:
            return {}

    def do_OPTIONS(self) -> None:  # noqa: N802
        self.send_response(204)
        self.send_header("Content-Length", "0")
        self._cors()
        self.end_headers()

    def do_GET(self) -> None:  # noqa: N802
        path = urllib.parse.urlsplit(self.path).path
        try:
            state = self.st.state_fn() or {}
        except Exception:  # noqa: BLE001
            state = {}
        if path in ("/", ""):
            self._send_json(200, {"app": f"{APP_NAME} {APP_VERSION}", "status": "ok"})
        elif path == "/sdapi/v1/options":
            self._send_json(200, {
                "sd_model_checkpoint": state.get("model_label", ""),
                "sd_vae": "Automatic",
                "CLIP_stop_at_last_layers": 1,
                "forge_additional_modules": [],
                "forge_preset": "none",
            })
        elif path == "/sdapi/v1/sd-models":
            models = [
                {
                    "name": name,
                    "title": label,
                    "model_name": name,
                    "hash": "00000000",
                    "sha256": "0" * 64,
                    "filename": f"{name}.safetensors",
                    "config": None,
                }
                for name, label in state.get("models", [])
            ]
            self._send_json(200, models)
        elif path == "/sdapi/v1/samplers":
            self._send_json(200, [{"name": s, "aliases": [], "options": {}} for s in state.get("samplers", [])])
        elif path == "/sdapi/v1/schedulers":
            self._send_json(200, [{"name": s, "label": s.title()} for s in SCHEDULERS])
        elif path == "/sdapi/v1/upscalers":
            self._send_json(200, [{"name": lbl} for lbl, _n, _f in UPSCALERS] + [{"name": "Lanczos"}])
        elif path == "/sdapi/v1/latent-upscale-modes":
            self._send_json(200, [{"name": "Latent"}])
        elif path == "/sdapi/v1/progress":
            self._send_json(200, {
                "progress": 0,
                "eta_relative": 0.0,
                "state": {"skipped": False, "interrupted": False, "batch_index": 0},
                "current_image": None,
                "textinfo": None,
            })
        elif path.startswith("/sdapi/"):
            self._send_json(200, [])
        else:
            self._send_json(404, {"error": "unknown endpoint"})

    def do_POST(self) -> None:  # noqa: N802
        path = urllib.parse.urlsplit(self.path).path
        doc = self._read_json()
        if doc is None:
            self._send_json(413, {"error": "payload too large"}, close=True)
            return
        if path == "/sdapi/v1/png-info":
            self._send_json(200, {"info": "", "items": {}})
            return
        if path not in ("/sdapi/v1/txt2img", "/sdapi/v1/img2img"):
            self._send_json(404, {"error": "unknown endpoint"})
            return
        prompt = " ".join(str(doc.get("prompt") or "").split())
        if not prompt:
            self._send_json(400, {"error": "empty prompt"})
            return
        st = self.st
        st._note(f"Incoming request: {elide(prompt, 72)}")
        try:
            res = st.submit_fn(prompt)
        except Exception as exc:  # noqa: BLE001
            st._note(f"Submission error: {exc}", "ERROR")
            self._send_json(500, {"error": f"{exc.__class__.__name__}: {exc}"})
            return
        if not isinstance(res, dict) or not res.get("ok"):
            err = (res or {}).get("error") if isinstance(res, dict) else "generation failed"
            st._note(f"Generation failed: {err}", "ERROR")
            self._send_json(502, {"error": str(err or "generation failed")})
            return
        path_img = str(res.get("path") or "")
        try:
            with open(path_img, "rb") as fh:
                data = fh.read()
        except OSError as exc:
            st._note(f"Image read failed: {exc}", "ERROR")
            self._send_json(502, {"error": f"cannot read generated file: {exc}"})
            return
        meta = res.get("meta") or {}
        b64 = base64.b64encode(data).decode("ascii")
        info = json.dumps({
            "prompt": prompt,
            "seed": meta.get("seed"),
            "width": meta.get("width"),
            "height": meta.get("height"),
            "steps": meta.get("steps"),
            "sampler_name": meta.get("sampler"),
            "cfg_scale": meta.get("cfg"),
            "model": meta.get("model"),
        })
        params = {
            "prompt": prompt,
            "steps": meta.get("steps"),
            "width": meta.get("width"),
            "height": meta.get("height"),
            "cfg_scale": meta.get("cfg"),
            "sampler_name": meta.get("sampler"),
        }
        st._note(f"Delivered {os.path.basename(path_img)}", "OK")
        self._send_json(200, {"images": [b64], "parameters": params, "info": info})

# =============================================================================
#  11. Resilient AI Horde REST Client (requests / urllib / BrowserBridge)
# =============================================================================
# =============================================================================
#  11. AI Horde REST Client (Thread-Local Sessions & Outage Classification)
# =============================================================================
TRANSIENT_HTTP_STATUS = frozenset({408, 425, 429, 500, 502, 503, 504, 520, 521, 522, 523, 524, 525, 526})


class HordeError(Exception):
    def __init__(
        self,
        message: str,
        rc: Optional[str] = None,
        status: Optional[int] = None,
        retry_after: Optional[float] = None,
    ) -> None:
        super().__init__(message)
        self.message = message
        self.rc = rc
        self.status = status
        self.retry_after = retry_after


def is_valid_image_bytes(data: Any) -> bool:
    """Verify magic header bytes so captive-portal HTML or CDN JSON error pages
    are never mistakenly saved as corrupt PNG/WebP images."""
    if not isinstance(data, (bytes, bytearray)) or len(data) < 64:
        return False
    head = bytes(data[:16])
    if head.startswith(b"\x89PNG\r\n\x1a\n"):
        return True
    if head.startswith(b"\xff\xd8\xff"):
        return True
    if head.startswith(b"RIFF") and head[8:12] == b"WEBP":
        return True
    if head.startswith((b"GIF87a", b"GIF89a")):
        return True
    if head.startswith(b"BM"):
        return True
    if len(head) >= 12 and head[4:8] == b"ftyp":
        return True
    return False


def is_transient_horde_error(exc: Exception) -> bool:
    """True when an error indicates a recoverable connectivity drop, bridge disconnect,
    CDN hiccup, captive portal HTML page, rate limit, or temporary 5xx server outage."""
    if isinstance(exc, HordeError):
        if exc.rc in ("Network", "InvalidImage"):
            return True
        if exc.status in TRANSIENT_HTTP_STATUS:
            return True
        msg = (exc.message or "").lower()
        for tok in (
            "network error", "connection", "timed out", "timeout", "name resolution",
            "failed to resolve", "getaddrinfo", "unreachable", "reset by peer",
            "broken pipe", "eof occurred", "ssl", "proxy", "no connected browser",
            "bridge", "temporarily unavailable", "bad gateway", "service unavailable",
            "non-image payload", "empty or truncated",
        ):
            if tok in msg:
                return True
        return False
    return isinstance(exc, (OSError, TimeoutError, urllib.error.URLError))


class HordeAPI:
    """Thread-safe AI Horde client using per-thread requests.Session pools so parallel
    queue workers never race or close another thread's active socket."""

    def __init__(self, base_url: str = HORDE_URL, api_key: str = ANON_KEY, client_agent: str = CLIENT_AGENT) -> None:
        self.base_url = base_url.rstrip("/")
        self.api_key = api_key or ANON_KEY
        self.client_agent = client_agent
        self.bridge: Optional[BrowserBridge] = None
        self._tls = threading.local()

    @property
    def transport(self) -> str:
        if self._bridge_active():
            return "browser-bridge"
        return "requests" if (_HAS_REQUESTS and requests is not None) else "urllib"

    def _bridge_active(self) -> bool:
        return self.bridge is not None and self.bridge.running

    def _make_session(self):
        if not _HAS_REQUESTS or requests is None:
            return None
        session = requests.Session()
        try:
            from requests.adapters import HTTPAdapter
            # v13: Zero hidden urllib3 retries (which ignore cancel_check and stall
            # shutdown/cancel during outages). All retries are managed explicitly
            # with interruptible cancel/wake handling in HordeAPI.call().
            adapter = HTTPAdapter(max_retries=0, pool_connections=4, pool_maxsize=8)
            session.mount("https://", adapter)
            session.mount("http://", adapter)
        except Exception:  # noqa: BLE001
            pass
        return session

    def _get_session(self):
        if not _HAS_REQUESTS or requests is None:
            return None
        sess = getattr(self._tls, "session", None)
        if sess is None:
            sess = self._make_session()
            self._tls.session = sess
        return sess

    def _reset_session(self) -> None:
        sess = getattr(self._tls, "session", None)
        if sess is not None:
            try:
                sess.close()
            except Exception:  # noqa: BLE001
                pass
            self._tls.session = None

    def _headers(self, auth: bool) -> Dict[str, str]:
        h = {"Client-Agent": self.client_agent, "Accept": "application/json"}
        if auth:
            h["apikey"] = self.api_key or ANON_KEY
        return h

    def call(
        self,
        method: str,
        path: str,
        body: Optional[Dict[str, Any]] = None,
        params: Optional[Dict[str, Any]] = None,
        timeout: float = 30,
        auth: bool = True,
        net_attempts: int = 3,
        cancel_check: Optional[Callable[[], bool]] = None,
    ) -> Any:
        url = path if path.startswith("http") else self.base_url + path
        if params:
            url += ("&" if "?" in url else "?") + urllib.parse.urlencode(params)
        short_path = urllib.parse.urlsplit(url).path
        last: Optional[HordeError] = None
        for attempt in range(1, max(1, net_attempts) + 1):
            if cancel_check and cancel_check():
                raise HordeError("Cancelled", rc="Cancelled")
            t0 = time.monotonic()
            try:
                return self._call_once(method, url, body, timeout, auth)
            except HordeError as exc:
                dt = int((time.monotonic() - t0) * 1000)
                if not is_transient_horde_error(exc) or exc.status == 429 or attempt >= net_attempts:
                    if exc.rc != "Network":
                        STUDIO_LOG.error(
                            "HORDE",
                            f"{method} {short_path} failed ({dt}ms, HTTP {exc.status or '-'}, rc={exc.rc or '-'}): "
                            f"{exc.message[:220]}",
                        )
                    raise
                last = exc
                self._reset_session()
                STUDIO_LOG.net(
                    "HORDE",
                    f"Retry {attempt}/{net_attempts} on {method} {short_path} ({dt}ms): {exc.message[:140]}",
                )
                wait_s = min(6.0, 1.2 * attempt)
                if cancel_check:
                    if not _interruptible_sleep(wait_s, cancel_check):
                        raise HordeError("Cancelled", rc="Cancelled") from exc
                else:
                    time.sleep(wait_s)
        raise last or HordeError("Network error", rc="Network")

    def _call_once(
        self,
        method: str,
        url: str,
        body: Optional[Dict[str, Any]],
        timeout: float,
        auth: bool,
    ) -> Any:
        if self._bridge_active():
            return self._bridge_call(method, url, body, timeout, auth)
        headers = self._headers(auth)
        if body is not None:
            headers["Content-Type"] = "application/json"
        sess = self._get_session()
        if sess is not None and requests is not None:
            try:
                r = sess.request(method, url, json=body, headers=headers, timeout=(min(10.0, float(timeout)), float(timeout)))
            except requests.RequestException as exc:  # type: ignore[attr-defined]
                raise HordeError(f"Network error: {exc.__class__.__name__}: {exc}", rc="Network") from exc
            status = r.status_code
            try:
                data = r.json()
            except ValueError:
                data = {"message": r.text[:300]}
            retry_after = r.headers.get("Retry-After")
        else:
            payload = json.dumps(body).encode("utf-8") if body is not None else None
            req = urllib.request.Request(url, data=payload, headers=headers, method=method)
            try:
                with urllib.request.urlopen(req, timeout=timeout) as resp:
                    status = resp.status
                    raw = resp.read()
                    retry_after = resp.headers.get("Retry-After")
            except urllib.error.HTTPError as exc:
                status = exc.code
                raw = exc.read()
                retry_after = exc.headers.get("Retry-After")
            except (urllib.error.URLError, OSError, ValueError) as exc:
                raise HordeError(f"Network error: {exc}", rc="Network") from exc
            try:
                data = json.loads(raw.decode("utf-8")) if raw else {}
            except ValueError:
                data = {"message": raw[:300].decode("utf-8", "replace")}
        return self._finish_response(status, data, retry_after)

    def _bridge_call(
        self,
        method: str,
        url: str,
        body: Optional[Dict[str, Any]],
        timeout: float,
        auth: bool,
    ) -> Any:
        assert self.bridge is not None
        headers = self._headers(auth)
        payload: Optional[bytes] = None
        if body is not None:
            payload = json.dumps(body).encode("utf-8")
            headers["Content-Type"] = "application/json"
        try:
            status, _hdrs, raw = self.bridge.request(method, url, headers, payload, timeout)
        except BridgeError as exc:
            raise HordeError(exc.message, rc="Network" if exc.network else None) from exc
        try:
            data = json.loads(raw.decode("utf-8")) if raw else {}
        except ValueError:
            data = {"message": raw[:300].decode("utf-8", "replace")}
        return self._finish_response(status, data, None)

    @staticmethod
    def _finish_response(status: int, data: Any, retry_after: Optional[str]) -> Any:
        if status < 400:
            return data
        msg = data.get("message") if isinstance(data, dict) else str(data)
        errs = data.get("errors") if isinstance(data, dict) else None
        if isinstance(errs, dict) and errs:
            msg = f"{msg} ({'; '.join(f'{k}: {v}' for k, v in errs.items())})"
        rc = data.get("rc") if isinstance(data, dict) else None
        try:
            ra = float(retry_after) if retry_after else None
        except ValueError:
            ra = None
        raise HordeError(msg or f"HTTP {status}", rc=rc, status=status, retry_after=ra)

    # Generation endpoints
    def submit(self, payload: Dict[str, Any], cancel_check: Optional[Callable[[], bool]] = None) -> Dict[str, Any]:
        params = payload.get("params")
        if isinstance(params, dict) and "seed" in params and not isinstance(params["seed"], str):
            payload = dict(payload, params=dict(params, seed=str(params["seed"])))
        return self.call("POST", "/generate/async", body=payload, timeout=60, net_attempts=2, cancel_check=cancel_check)

    def check(self, rid: str, cancel_check: Optional[Callable[[], bool]] = None) -> Dict[str, Any]:
        return self.call("GET", f"/generate/check/{rid}", timeout=20, auth=False, net_attempts=2, cancel_check=cancel_check)

    def status(self, rid: str, cancel_check: Optional[Callable[[], bool]] = None) -> Dict[str, Any]:
        return self.call("GET", f"/generate/status/{rid}", timeout=60, auth=False, net_attempts=2, cancel_check=cancel_check)

    def cancel(self, rid: str) -> Dict[str, Any]:
        return self.call("DELETE", f"/generate/status/{rid}", timeout=25, auth=False, net_attempts=1)

    # Alchemy interrogation endpoints
    def interrogate_submit(self, payload: Dict[str, Any], cancel_check: Optional[Callable[[], bool]] = None) -> Dict[str, Any]:
        return self.call("POST", "/interrogate/async", body=payload, timeout=45, net_attempts=2, cancel_check=cancel_check)

    def interrogate_status(self, rid: str, cancel_check: Optional[Callable[[], bool]] = None) -> Dict[str, Any]:
        return self.call("GET", f"/interrogate/status/{rid}", timeout=30, auth=False, net_attempts=2, cancel_check=cancel_check)

    def interrogate_cancel(self, rid: str) -> Dict[str, Any]:
        return self.call("DELETE", f"/interrogate/status/{rid}", timeout=25, auth=False, net_attempts=1)

    # Cluster info endpoints
    def models(self) -> List[Dict[str, Any]]:
        return self.call("GET", "/status/models", params={"type": "image"}, timeout=30, auth=False)

    def heartbeat(self, timeout: float = 12.0) -> Dict[str, Any]:
        return self.call("GET", "/status/heartbeat", timeout=timeout, auth=False, net_attempts=1)

    def find_user(self) -> Dict[str, Any]:
        return self.call("GET", "/find_user", timeout=20)

    def sampler_constraints(self) -> Dict[str, Any]:
        return self.call("GET", "/status/sampler_constraints", timeout=30, auth=False)

    _DL_RETRY_STATUS = frozenset({404, 408, 425, 429, 500, 502, 503, 504})

    def download(
        self,
        url: str,
        timeout: float = 90,
        cancel_check: Optional[Callable[[], bool]] = None,
        wake_event: Optional[threading.Event] = None,
    ) -> bytes:
        """Fetch one image with interruptible backoff and transient-outage persistence."""
        delays = (1.5, 3.0, 5.0, 8.0, 12.0, 16.0, 22.0)
        last: Optional[HordeError] = None
        for attempt in range(1, len(delays) + 1):
            if cancel_check and cancel_check():
                raise HordeError("Cancelled", rc="Cancelled")
            try:
                return self._download_once(url, timeout)
            except HordeError as exc:
                retryable = is_transient_horde_error(exc) or (exc.status or 0) in self._DL_RETRY_STATUS
                if not retryable or attempt >= len(delays):
                    raise
                last = exc
                self._reset_session()
                STUDIO_LOG.net(
                    "HORDE",
                    f"Download retry {attempt}/{len(delays)} (HTTP {exc.status or '-'}) "
                    f"in {delays[attempt - 1]:.0f}s: {exc.message[:120]}",
                )
                if not _interruptible_sleep(delays[attempt - 1], cancel_check or (lambda: False), wake_event=wake_event):
                    raise HordeError("Cancelled", rc="Cancelled") from exc
        raise last or HordeError("Download failed", rc="Network")

    def _download_once(self, url: str, timeout: float) -> bytes:
        if self._bridge_active():
            assert self.bridge is not None
            try:
                status, _hdrs, raw = self.bridge.request(
                    "GET", url, {"User-Agent": self.client_agent, "Accept": "*/*"}, None, timeout
                )
            except BridgeError as exc:
                raise HordeError(f"Download failed: {exc.message}", rc="Network" if exc.network else None) from exc
            if status >= 400:
                raise HordeError(f"Download failed: HTTP {status}", status=status)
            return raw
        sess = self._get_session()
        if sess is not None and requests is not None:
            try:
                r = sess.get(url, timeout=(min(12.0, float(timeout)), float(timeout)))
            except requests.RequestException as exc:  # type: ignore[attr-defined]
                raise HordeError(f"Download failed: {exc}", rc="Network") from exc
            if r.status_code >= 400:
                raise HordeError(f"Download failed: HTTP {r.status_code}", status=r.status_code)
            return r.content
        req = urllib.request.Request(url, headers={"User-Agent": self.client_agent})
        try:
            with urllib.request.urlopen(req, timeout=timeout) as resp:
                return resp.read()
        except urllib.error.HTTPError as exc:
            raise HordeError(f"Download failed: HTTP {exc.code}", status=exc.code) from exc
        except (urllib.error.URLError, OSError) as exc:
            raise HordeError(f"Download failed: {exc}", rc="Network") from exc

    def civitai_lookup(self, ident: str, is_version: bool) -> Dict[str, Any]:
        url = (CIVITAI_VERSION_URL if is_version else CIVITAI_MODEL_URL).format(id=ident)
        data = self.call("GET", url, timeout=25, auth=False)
        out: Dict[str, Any] = {"name": "", "trained_words": [], "base": "", "type": ""}
        if is_version:
            out["name"] = f"{data.get('model', {}).get('name', '')} / {data.get('name', '')}".strip(" /")
            out["trained_words"] = data.get("trainedWords") or []
            out["base"] = data.get("baseModel", "")
            out["type"] = data.get("model", {}).get("type", "")
        else:
            out["name"] = data.get("name", "")
            out["type"] = data.get("type", "")
            vers = data.get("modelVersions") or []
            if vers:
                out["trained_words"] = vers[0].get("trainedWords") or []
                out["base"] = vers[0].get("baseModel", "")
        return out


# =============================================================================
#  12. Image Storage (outputs/, outputs/temp/ ring of 10, data/tiles/)
# =============================================================================
class ImageStore:
    def __init__(self, temp_dir: str, output_dir: str, capacity: int = TEMP_CAPACITY) -> None:
        self.temp_dir = temp_dir
        self.output_dir = output_dir
        self.capacity = capacity
        self._lock = threading.Lock()
        for d in (temp_dir, output_dir):
            try:
                os.makedirs(d, exist_ok=True)
            except OSError:
                pass
        self.orphans_cleaned = self.cleanup_orphan_metadata()

    def cleanup_orphan_metadata(self) -> int:
        removed = 0
        for d in (self.temp_dir, self.output_dir):
            try:
                names = os.listdir(d)
            except OSError:
                continue
            stems = {
                os.path.splitext(n)[0].lower()
                for n in names
                if n.lower().endswith((".png", ".webp", ".jpg", ".jpeg"))
            }
            for n in names:
                if n.lower().endswith(".json") and os.path.splitext(n)[0].lower() not in stems:
                    try:
                        os.remove(os.path.join(d, n))
                        removed += 1
                    except OSError:
                        pass
        return removed

    def _slot(self, i: int) -> str:
        return os.path.join(self.temp_dir, f"hsl_{i:02d}")

    def reserve(self) -> str:
        with self._lock:
            oldest, oldest_t = None, None
            for i in range(self.capacity):
                base = self._slot(i)
                existing = [base + ext for ext in (".png", ".webp") if os.path.exists(base + ext)]
                if not existing:
                    return base
                t = max(os.path.getmtime(p) for p in existing)
                if oldest_t is None or t < oldest_t:
                    oldest, oldest_t = base, t
            base = oldest or self._slot(0)
            # v4: depth-map attachments follow their source slot out of the ring
            for cand in (
                base + ".png", base + ".webp", base + ".json",
                base + DEPTH_POSTFIX + ".png", base + DEPTH_POSTFIX + ".json",
            ):
                try:
                    os.remove(cand)
                except OSError:
                    pass
            return base

    def save_temp(self, data: bytes, meta: Dict[str, Any]) -> str:
        base = self.reserve()
        return write_image_with_metadata(data, base + ".png", meta)

    def save_direct(self, data: bytes, meta: Dict[str, Any]) -> str:
        ensure_dirs()
        dest = self.output_name(meta, ".png")
        return write_image_with_metadata(data, dest, meta)

    def save_tile(self, data: bytes, meta: Dict[str, Any]) -> str:
        ensure_dirs()
        dest = meta.get("tile_target") or os.path.join(
            TILES_DIR, f"tile_{int(time.time() * 1000) % 100000}.png"
        )
        return write_image_with_metadata(data, dest, meta)

    @staticmethod
    def clean_group_tiles(gid: int) -> int:
        prefix = f"g{int(gid)}_"
        removed = 0
        try:
            for n in os.listdir(TILES_DIR):
                if n.startswith(prefix):
                    try:
                        os.remove(os.path.join(TILES_DIR, n))
                        removed += 1
                    except OSError:
                        pass
        except OSError:
            pass
        return removed

    def list_recent(self, include_output: bool = False) -> List[str]:
        dirs = [self.temp_dir] + ([self.output_dir] if include_output else [])
        files: List[str] = []
        for d in dirs:
            try:
                files += [
                    os.path.join(d, f)
                    for f in os.listdir(d)
                    if os.path.isfile(os.path.join(d, f))
                    and f.lower().endswith((".png", ".webp"))
                    and not is_depth_image_path(f)
                ]
            except OSError:
                continue
        files.sort(key=lambda p: os.path.getmtime(p), reverse=True)
        return files[: self.capacity]

    def output_name(self, meta: Dict[str, Any], ext: str) -> str:
        model = model_short(str(meta.get("model", ""))) or ("UPS" if meta.get("tile_upscale") else "IMG")
        seed = re.sub(r"[^A-Za-z0-9_-]", "", str(meta.get("seed", "")))[:16] or "noseed"
        stamp = time.strftime("%Y%m%d_%H%M%S", time.localtime(meta.get("saved_at") or time.time()))
        name = f"{stamp}_{model}_{seed}{ext}"
        dest = os.path.join(self.output_dir, name)
        idx = 2
        while os.path.exists(dest):
            dest = os.path.join(self.output_dir, f"{stamp}_{model}_{seed}_{idx}{ext}")
            idx += 1
        return dest

    def save_to_output(self, src: str, dest: Optional[str] = None) -> str:
        ensure_dirs()
        meta = read_image_metadata(src)
        ext = os.path.splitext(src)[1].lower() or ".png"
        target = dest or self.output_name(meta, ext)
        shutil.copy2(src, target)
        src_sidecar = os.path.splitext(src)[0] + ".json"
        if os.path.isfile(src_sidecar):
            shutil.copy2(src_sidecar, os.path.splitext(target)[0] + ".json")
        elif meta:
            write_text(os.path.splitext(target)[0] + ".json", json.dumps(meta, indent=2, ensure_ascii=False))
        # v4: a saved image carries its depth-map attachment along
        src_depth = depth_path_for(src)
        if os.path.isfile(src_depth):
            try:
                shutil.copy2(src_depth, depth_path_for(target))
                src_depth_json = os.path.splitext(src_depth)[0] + ".json"
                if os.path.isfile(src_depth_json):
                    shutil.copy2(src_depth_json, os.path.splitext(depth_path_for(target))[0] + ".json")
            except OSError:
                pass
        return target

    def delete_file(self, path: str) -> bool:
        ok = False
        depth = depth_path_for(path)
        for cand in (path, os.path.splitext(path)[0] + ".json", depth, os.path.splitext(depth)[0] + ".json"):
            if os.path.isfile(cand):
                try:
                    os.remove(cand)
                    ok = True
                except OSError:
                    pass
        return ok

# =============================================================================
#  13. Resilient Jobs, Outage-Proof Workers, Alchemy & Tile Upscale Geometry
# =============================================================================
@dataclass
class Job:
    local_id: int
    payload: Dict[str, Any]
    meta: Dict[str, Any]
    kind: str = KIND_GEN
    group_id: Optional[int] = None
    state: str = STATE_QUEUED
    horde_id: str = ""
    wait_time: Optional[float] = None
    wait_initial: Optional[float] = None
    queue_position: Optional[int] = None
    finished: int = 0
    processing: int = 0
    waiting: int = 0
    restarted: int = 0
    is_possible: bool = True
    kudos: float = 0.0
    message: str = ""
    results: List[str] = field(default_factory=list)
    created_at: float = field(default_factory=time.time)
    started_at: Optional[float] = None
    ended_at: Optional[float] = None
    retry_after: float = 0.0
    outage_attempts: int = 0
    outage_resubmits: int = 0
    resumed_from_journal: bool = False
    watchdog_recoveries: int = 0
    journal_scratch_path: str = ""
    # Group summary fields (KIND_GROUP)
    group_title: str = ""
    group_detail: str = ""
    group_progress: float = 0.0

    @property
    def active(self) -> bool:
        return self.state in ACTIVE_STATES

    @property
    def terminal(self) -> bool:
        return self.state in (STATE_DONE, STATE_FAILED, STATE_CANCELLED)

    def n_total(self) -> int:
        return int((self.payload.get("params") or {}).get("n", 1))

    def progress_fraction(self) -> float:
        if self.kind == KIND_GROUP:
            return max(0.0, min(1.0, self.group_progress))
        if self.state == STATE_DONE:
            return 1.0
        if self.state == STATE_RECONNECTING:
            if self.horde_id:
                return max(0.18, min(0.85, 0.25 + 0.55 * (self.finished / max(1, self.n_total()))))
            return 0.08
        if self.state in (STATE_QUEUED, STATE_SUBMITTING):
            return 0.06 if self.state == STATE_SUBMITTING else 0.0
        if self.state == STATE_FETCHING:
            return 0.94
        n = max(1, self.n_total())
        if self.finished > 0:
            return min(0.92, 0.15 + 0.77 * (self.finished / n))
        if self.wait_initial and self.wait_time is not None and self.wait_initial > 0:
            return max(0.08, min(0.88, 1.0 - (self.wait_time / max(1.0, self.wait_initial))))
        return 0.35 if self.state == STATE_PROCESSING else 0.14

    def title_line(self) -> str:
        if self.kind == KIND_GROUP:
            return self.group_title or f"Tile Upscale #{self.group_id}"
        if self.kind == KIND_ALCH:
            form = str(self.meta.get("alchemy_form") or "upscale")
            return f"Base Upscale ({UPSCALER_BY_NAME.get(form, form)})"
        if self.kind == KIND_TILE_I2I:
            r, c = self.meta.get("tile_row", "?"), self.meta.get("tile_col", "?")
            return f"Tile r{r}c{c} \u2022 {model_short(str(self.meta.get('model', '')))}"
        if self.kind == KIND_DEPTH:
            return f"Depth Map \u2022 {elide(os.path.basename(str(self.meta.get('depth_source') or '?')), 54)}"
        return elide(str(self.meta.get("prompt") or "(empty)"), 68)

    def status_line(self) -> str:
        if self.kind == KIND_GROUP:
            return self.group_detail or self.state.upper()
        if self.state == STATE_QUEUED:
            if self.retry_after > time.time():
                rem = max(1, int(self.retry_after - time.time()))
                return self.message or f"Backoff — retrying in {rem}s"
            return self.message or "Queued locally — standing by"
        if self.state == STATE_SUBMITTING:
            return self.message or ("Submitting to AI Horde\u2026" if not self.horde_id else "Resuming request on AI Horde\u2026")
        if self.state == STATE_RECONNECTING:
            return self.message or "Connection lost — holding task & auto-reconnecting\u2026"
        if self.state == STATE_WAITING:
            pos = f"pos #{self.queue_position}" if self.queue_position is not None else "in queue"
            eta = f"ETA {fmt_secs(self.wait_time)}" if self.wait_time is not None else "estimating ETA"
            extra = f" \u2022 {self.message}" if self.message else (" \u2022 no workers yet" if not self.is_possible else "")
            return f"Waiting ({pos}) \u2022 {eta}{extra}"
        if self.state == STATE_PROCESSING:
            n = max(1, self.n_total())
            eta = f" \u2022 ETA {fmt_secs(self.wait_time)}" if self.wait_time is not None else ""
            return f"Generating {self.finished}/{n} ({self.processing} active){eta}"
        if self.state == STATE_FETCHING:
            return self.message or "Downloading finished image(s)\u2026"
        if self.state == STATE_DONE:
            n = len(self.results)
            return f"Complete \u2022 {n} image{'s' if n != 1 else ''}"
        if self.state == STATE_FAILED:
            return f"Error: {self.message or 'Request failed'}  (double-click for details)"
        if self.state == STATE_CANCELLED:
            return "Cancelled"
        return self.state

    def cleanup_journal_scratch(self) -> None:
        p = self.journal_scratch_path
        if p and os.path.isfile(p):
            try:
                os.remove(p)
            except OSError:
                pass
            self.journal_scratch_path = ""

    def to_journal_dict(self) -> Optional[Dict[str, Any]]:
        """Serialize unfinished non-group jobs for crash/restart recovery.
        Even large inline img2img source_image blobs are spilled safely into
        data/scratch/ so NO queued job is ever dropped on restart."""
        if self.kind == KIND_GROUP or self.terminal:
            return None
        payload_copy = copy.deepcopy(self.payload)
        inline_src = payload_copy.get("source_image")
        if not payload_copy.get("source_image_path") and isinstance(inline_src, str) and len(inline_src) > 120_000:
            try:
                os.makedirs(SCRATCH_DIR, exist_ok=True)
                sp = self.journal_scratch_path or os.path.join(
                    SCRATCH_DIR, f"journal_src_{self.local_id}_{int(self.created_at)}.bin"
                )
                if not os.path.isfile(sp):
                    with open(sp, "wb") as fh:
                        fh.write(base64.b64decode(inline_src))
                self.journal_scratch_path = sp
                payload_copy.pop("source_image", None)
                payload_copy["source_image_path"] = sp
            except Exception:  # noqa: BLE001
                return None
        return {
            "local_id": self.local_id,
            "kind": self.kind,
            "group_id": self.group_id,
            "payload": payload_copy,
            "meta": self.meta,
            "horde_id": self.horde_id,
            "kudos": self.kudos,
            "created_at": self.created_at,
            "outage_resubmits": self.outage_resubmits,
            "journal_scratch_path": self.journal_scratch_path,
        }

    @classmethod
    def from_journal_dict(cls, doc: Dict[str, Any], local_id: int) -> Optional["Job"]:
        if not isinstance(doc, dict) or not isinstance(doc.get("payload"), dict):
            return None
        kind = str(doc.get("kind") or KIND_GEN)
        if kind not in (KIND_GEN, KIND_DEPTH, KIND_ALCH, KIND_TILE_I2I):
            return None
        src_p = doc["payload"].get("source_image_path")
        if src_p and not os.path.isfile(str(src_p)):
            return None
        hid = str(doc.get("horde_id") or "")
        return cls(
            local_id=local_id,
            payload=copy.deepcopy(doc["payload"]),
            meta=copy.deepcopy(doc.get("meta") or {}),
            kind=kind,
            group_id=None if kind == KIND_GEN else doc.get("group_id"),
            state=STATE_QUEUED,
            horde_id=hid,
            kudos=float(doc.get("kudos") or 0.0),
            created_at=float(doc.get("created_at") or time.time()),
            outage_resubmits=int(doc.get("outage_resubmits") or 0),
            resumed_from_journal=bool(hid),
            journal_scratch_path=str(doc.get("journal_scratch_path") or ""),
        )


def _interruptible_sleep(
    secs: float,
    flag: Callable[[], bool],
    step: float = 0.2,
    wake_event: Optional[threading.Event] = None,
) -> bool:
    """Sleep up to `secs`, aborting immediately on `flag()` (returns False) or waking
    early when `wake_event` is set (returns True so caller retries immediately!)."""
    end = time.monotonic() + max(0.0, secs)
    while time.monotonic() < end:
        if flag():
            return False
        if wake_event is not None and wake_event.is_set():
            return True
        rem = max(0.02, end - time.monotonic())
        if wake_event is not None:
            if wake_event.wait(min(step, rem)):
                return not flag()
        else:
            time.sleep(min(step, rem))
    return not flag()


class JobWorker(QThread):
    """Outage-proof AI Horde generation worker (v13.0).
    Strict Settlement Invariant: every started worker is GUARANTEED to emit
    EXACTLY ONE outcome (`completed`, `failed`, or clean app-shutdown suspend) —
    never silently dropped, never double-failed, surviving intermittent outages
    across submit, poll, status fetch, and CDN image download."""

    progress = pyqtSignal(int, dict)
    completed = pyqtSignal(int, list, str)
    failed = pyqtSignal(int, str, float)
    network_state = pyqtSignal(bool, str)

    def __init__(
        self,
        api: HordeAPI,
        store: ImageStore,
        job: Job,
        poll_interval: float,
        save_direct: bool,
        wake_event: Optional[threading.Event] = None,
        parent: Optional[QObject] = None,
    ) -> None:
        super().__init__(parent)
        self.api = api
        self.store = store
        self.job = job
        self.poll_interval = max(1.5, float(poll_interval))
        self.save_direct = bool(save_direct)
        self._cancel = threading.Event()
        self._suspend = threading.Event()
        self._wake = wake_event
        self.settled: bool = False

    def request_cancel(self) -> None:
        """Explicit user cancellation (will cancel the remote AI Horde request)."""
        self._cancel.set()

    def request_suspend(self) -> None:
        """Clean app-shutdown pause (exits thread WITHOUT cancelling remote AI Horde
        request so it stays alive and resumes seamlessly from queue_journal.json)."""
        self._suspend.set()

    def _stop_requested(self) -> bool:
        return self._cancel.is_set() or self._suspend.is_set()

    def _emit_completed(self, paths: List[str], final_state: str) -> None:
        if not self.settled:
            self.settled = True
            self.completed.emit(self.job.local_id, paths, final_state)

    def _emit_failed(self, msg: str, retry_after: float = 0.0) -> None:
        if not self.settled:
            self.settled = True
            self.failed.emit(self.job.local_id, msg, retry_after)

    def _sleep(self, secs: float, allow_wake: bool = True) -> bool:
        return _interruptible_sleep(secs, self._stop_requested, wake_event=(self._wake if allow_wake else None))

    def _wait_outage(self, jid: int, outage_start: float, attempt: int, stage_label: str, reason: str) -> bool:
        """Hold job calmly in STATE_RECONNECTING with capped exponential backoff until
        connectivity returns or RECONNECT_MAX_PATIENCE_SECS expires.
        Laptop sleep/hibernate clock jumps automatically grant a fresh probe window."""
        now_m = time.monotonic()
        last_m = getattr(self, "_last_outage_tick", now_m)
        self._last_outage_tick = now_m
        if (now_m - last_m) > OUTAGE_SLEEP_JUMP_SECS:
            self._outage_sleep_bonus = getattr(self, "_outage_sleep_bonus", 0.0) + (now_m - last_m)
            STUDIO_LOG.info("HORDE", f"#{jid} detected system sleep/wake — granting fresh reconnect window")
        effective_elapsed = max(0.0, (now_m - outage_start) - getattr(self, "_outage_sleep_bonus", 0.0))
        if effective_elapsed >= RECONNECT_MAX_PATIENCE_SECS and attempt >= 6:
            self._emit_failed(
                f"Internet remained unreachable for {int(effective_elapsed // 60)}m during {stage_label} ({reason[:110]}) — click Retry when online",
                0.0,
            )
            return False
        delay = min(20.0, 3.0 + 2.0 * min(attempt, 8))
        short_err = elide(reason, 64)
        self.network_state.emit(False, short_err)
        self.progress.emit(jid, {
            "state": STATE_RECONNECTING,
            "outage_attempts": attempt,
            "message": f"Offline ({stage_label}) — retry #{attempt} in {int(delay)}s · {short_err}",
        })
        if attempt in (1, 3, 6) or attempt % 10 == 0:
            STUDIO_LOG.warn("HORDE", f"#{jid} offline during {stage_label} (retry #{attempt}, holding safely): {reason[:140]}")
        if not self._sleep(delay, allow_wake=True):
            return False
        return True

    def run(self) -> None:
        try:
            self._run_inner()
        except Exception as exc:  # noqa: BLE001
            if not self._suspend.is_set():
                STUDIO_LOG.error("HORDE", f"#{self.job.local_id} unexpected worker error: {exc.__class__.__name__}: {exc}")
                self._emit_failed(f"Unexpected worker error: {exc.__class__.__name__}: {exc}", 0.0)
        finally:
            self.api._reset_session()
            if not self.settled and not self._suspend.is_set():
                if self._cancel.is_set():
                    self._emit_completed([], STATE_CANCELLED)
                else:
                    self._emit_failed("Worker terminated unexpectedly before completing task", 0.0)

    def _run_inner(self) -> None:
        job = self.job
        jid = job.local_id
        self.progress.emit(jid, {"state": STATE_SUBMITTING, "started_at": job.started_at or time.time(), "message": ""})

        try:
            payload = self._materialize_payload(job.payload)
        except HordeError as exc:
            self._emit_failed(exc.message, 0.0)
            return
        except Exception as exc:  # noqa: BLE001
            self._emit_failed(f"{exc.__class__.__name__}: {exc}", 0.0)
            return

        resubmit_count = int(job.outage_resubmits)
        fault_retries = 0
        rid = str(job.horde_id or "")
        allow_404_resubmit = bool(job.resumed_from_journal)
        self._outage_sleep_bonus = 0.0
        self._last_outage_tick = time.monotonic()

        while True:
            if self._suspend.is_set():
                self.settled = True
                return
            if self._cancel.is_set():
                if rid:
                    self._do_cancel(rid)
                else:
                    self._emit_completed([], STATE_CANCELLED)
                return

            # ---- Phase 1: Submit (skipped if resuming a persisted horde_id!) ----
            if not rid:
                outage_start: Optional[float] = None
                outage_attempt = 0
                while not rid:
                    if self._suspend.is_set():
                        self.settled = True
                        return
                    if self._cancel.is_set():
                        self._emit_completed([], STATE_CANCELLED)
                        return
                    try:
                        sub = self.api.submit(payload, cancel_check=self._stop_requested)
                        if outage_start is not None:
                            self.network_state.emit(True, "Connected")
                            STUDIO_LOG.ok("HORDE", f"#{jid} reconnected and submitted cleanly")
                    except HordeError as exc:
                        if self._suspend.is_set():
                            self.settled = True
                            return
                        if exc.rc == "Cancelled" or self._cancel.is_set():
                            self._emit_completed([], STATE_CANCELLED)
                            return
                        if exc.status == 429:
                            cool = max(6.0, float(exc.retry_after or 15.0))
                            self.progress.emit(jid, {
                                "state": STATE_RECONNECTING,
                                "message": f"Rate-limited — retrying submit in {int(cool)}s",
                            })
                            STUDIO_LOG.net("HORDE", f"#{jid} submit rate-limited, cooling {cool:.0f}s")
                            if not self._sleep(cool, allow_wake=False):
                                if self._cancel.is_set():
                                    self._emit_completed([], STATE_CANCELLED)
                                else:
                                    self.settled = True
                                return
                            continue
                        if is_transient_horde_error(exc):
                            if outage_start is None:
                                outage_start = time.monotonic()
                            outage_attempt += 1
                            if not self._wait_outage(jid, outage_start, outage_attempt, "submit", exc.message):
                                if self._cancel.is_set():
                                    self._emit_completed([], STATE_CANCELLED)
                                elif self._suspend.is_set():
                                    self.settled = True
                                return
                            continue
                        self._emit_failed(exc.message, 0.0)
                        return
                    except Exception as exc:  # noqa: BLE001
                        self._emit_failed(f"{exc.__class__.__name__}: {exc}", 0.0)
                        return

                    rid = str(sub.get("id") or "")
                    if not rid:
                        self._emit_failed("AI Horde returned no request id", 0.0)
                        return
                    kudos = float(sub.get("kudos") or 0.0)
                    STUDIO_LOG.info("HORDE", f"Job #{jid} submitted -> {rid[:10]} ({kudos:.0f} kudos)")
                    self.progress.emit(jid, {
                        "horde_id": rid,
                        "kudos": kudos,
                        "state": STATE_WAITING,
                        "message": "",
                        "outage_attempts": 0,
                        "resumed_from_journal": False,
                    })
            else:
                STUDIO_LOG.info("HORDE", f"Job #{jid} resuming existing AI Horde request {rid[:10]}")
                self.progress.emit(jid, {"state": STATE_WAITING, "message": ""})

            # ---- Phase 2: Poll /generate/check/{rid} with full outage resilience ----
            outage_start = None
            outage_attempt = 0
            had_outage = allow_404_resubmit
            impossible_since: Optional[float] = None
            last_progress_at = time.monotonic()
            last_progress_sig: Tuple[Any, ...] = ()
            need_resubmit = False

            while True:
                if self._suspend.is_set():
                    self.settled = True
                    return
                if self._cancel.is_set():
                    self._do_cancel(rid)
                    return
                try:
                    chk = self.api.check(rid, cancel_check=self._stop_requested)
                    if outage_start is not None:
                        self.network_state.emit(True, "Connected")
                        STUDIO_LOG.ok("HORDE", f"#{jid} connection restored — resumed polling {rid[:10]}")
                        outage_start = None
                        outage_attempt = 0
                except HordeError as exc:
                    if self._suspend.is_set():
                        self.settled = True
                        return
                    if exc.rc == "Cancelled" or self._cancel.is_set():
                        self._do_cancel(rid)
                        return
                    if exc.status == 404:
                        if had_outage and resubmit_count < MAX_OUTAGE_RESUBMITS:
                            resubmit_count += 1
                            STUDIO_LOG.warn(
                                "HORDE",
                                f"#{jid} request {rid[:10]} expired after outage/resume — auto-resubmitting ({resubmit_count}/{MAX_OUTAGE_RESUBMITS})",
                            )
                            rid = ""
                            allow_404_resubmit = False
                            self.progress.emit(jid, {
                                "horde_id": "",
                                "outage_resubmits": resubmit_count,
                                "state": STATE_SUBMITTING,
                                "message": f"Re-submitting expired request ({resubmit_count}/{MAX_OUTAGE_RESUBMITS})\u2026",
                            })
                            need_resubmit = True
                            break
                        self._emit_failed("Request expired or not found on AI Horde (HTTP 404)", 0.0)
                        return
                    if exc.status == 429:
                        cool = max(5.0, float(exc.retry_after or 8.0))
                        STUDIO_LOG.net("HORDE", f"#{jid} check rate-limited, cooling {cool:.0f}s")
                        if not self._sleep(cool, allow_wake=False):
                            if self._cancel.is_set():
                                self._do_cancel(rid)
                            else:
                                self.settled = True
                            return
                        continue
                    if is_transient_horde_error(exc):
                        had_outage = True
                        if outage_start is None:
                            outage_start = time.monotonic()
                        outage_attempt += 1
                        if not self._wait_outage(jid, outage_start, outage_attempt, "queue poll", exc.message):
                            if self._cancel.is_set():
                                self._do_cancel(rid)
                            elif self._suspend.is_set():
                                self.settled = True
                            return
                        continue
                    self._emit_failed(f"Poll error: {exc.message}", 0.0)
                    return
                except Exception as exc:  # noqa: BLE001
                    self._emit_failed(f"Poll error: {exc.__class__.__name__}: {exc}", 0.0)
                    return

                if chk.get("faulted"):
                    if fault_retries < FAULT_AUTO_RETRIES:
                        fault_retries += 1
                        STUDIO_LOG.warn("HORDE", f"#{jid} worker faulted — auto-resubmitting once ({fault_retries}/{FAULT_AUTO_RETRIES})")
                        rid = ""
                        allow_404_resubmit = False
                        self.progress.emit(jid, {
                            "horde_id": "",
                            "state": STATE_SUBMITTING,
                            "message": f"Remote worker faulted — auto-retrying ({fault_retries}/{FAULT_AUTO_RETRIES})\u2026",
                        })
                        need_resubmit = True
                        break
                    self._emit_failed("AI Horde worker faulted this request (auto-retry also faulted)", 0.0)
                    return

                is_possible = bool(chk.get("is_possible", True))
                processing = int(chk.get("processing") or 0)
                finished = int(chk.get("finished") or 0)
                prog_sig = (finished, processing, chk.get("queue_position"), chk.get("wait_time"), chk.get("restarted"))
                if prog_sig != last_progress_sig or outage_start is not None:
                    last_progress_sig = prog_sig
                    last_progress_at = time.monotonic()
                elif not chk.get("done") and (time.monotonic() - last_progress_at) >= STALL_WATCHDOG_SECS:
                    try:
                        self.api.cancel(rid)
                    except HordeError:
                        pass
                    self._emit_failed(
                        f"AI Horde request stalled with zero progress for {int(STALL_WATCHDOG_SECS // 60)}m — click Retry to resubmit",
                        0.0,
                    )
                    return
                imp_msg = ""
                if not is_possible and processing == 0 and finished == 0 and not chk.get("done"):
                    if impossible_since is None:
                        impossible_since = time.monotonic()
                        STUDIO_LOG.warn("HORDE", f"#{jid} currently has no matching AI Horde workers (is_possible=False)")
                    imp_rem = int(max(0.0, IMPOSSIBLE_GRACE_SECS - (time.monotonic() - impossible_since)))
                    imp_msg = f"no matching workers ({imp_rem}s grace)"
                    if (time.monotonic() - impossible_since) >= IMPOSSIBLE_GRACE_SECS:
                        try:
                            self.api.cancel(rid)
                        except HordeError:
                            pass
                        self._emit_failed(
                            "No online AI Horde workers match this model/LoRA/resolution combination (is_possible=False)",
                            0.0,
                        )
                        return
                else:
                    impossible_since = None

                fields: Dict[str, Any] = {
                    "wait_time": chk.get("wait_time"),
                    "queue_position": chk.get("queue_position"),
                    "finished": finished,
                    "processing": processing,
                    "waiting": int(chk.get("waiting") or 0),
                    "restarted": int(chk.get("restarted") or 0),
                    "is_possible": is_possible,
                    "kudos": chk.get("kudos", job.kudos),
                    "message": imp_msg,
                    "outage_attempts": 0,
                }
                if job.wait_initial is None and chk.get("wait_time"):
                    fields["wait_initial"] = chk.get("wait_time")
                if chk.get("done"):
                    fields["state"] = STATE_FETCHING
                    fields["message"] = ""
                    self.progress.emit(jid, fields)
                    break
                fields["state"] = STATE_PROCESSING if (processing or finished) else STATE_WAITING
                self.progress.emit(jid, fields)
                if not self._sleep(self.poll_interval, allow_wake=False):
                    if self._cancel.is_set():
                        self._do_cancel(rid)
                    else:
                        self.settled = True
                    return

            if need_resubmit:
                continue

            # ---- Phase 3: Fetch /generate/status/{rid} & Download with outage recovery ----
            fetch_deadline = time.monotonic() + 300.0
            outage_start = None
            outage_attempt = 0
            empty_tries = 0
            final: Optional[Dict[str, Any]] = None

            while True:
                if self._suspend.is_set():
                    self.settled = True
                    return
                if self._cancel.is_set():
                    self._do_cancel(rid)
                    return
                try:
                    cand = self.api.status(rid, cancel_check=self._stop_requested)
                    if outage_start is not None:
                        self.network_state.emit(True, "Connected")
                        STUDIO_LOG.ok("HORDE", f"#{jid} connection restored — fetching final result {rid[:10]}")
                        outage_start = None
                        outage_attempt = 0
                        fetch_deadline = max(fetch_deadline, time.monotonic() + 180.0)
                    if cand.get("generations"):
                        final = cand
                        break
                    empty_tries += 1
                    if time.monotonic() >= fetch_deadline:
                        break
                    delay = min(20.0, 2.0 + 2.0 * empty_tries)
                    self.progress.emit(jid, {
                        "state": STATE_FETCHING,
                        "message": f"Waiting for worker image upload ({empty_tries})\u2026",
                    })
                    if not self._sleep(delay, allow_wake=False):
                        if self._cancel.is_set():
                            self._do_cancel(rid)
                        else:
                            self.settled = True
                        return
                except HordeError as exc:
                    if self._suspend.is_set():
                        self.settled = True
                        return
                    if exc.rc == "Cancelled" or self._cancel.is_set():
                        self._do_cancel(rid)
                        return
                    if exc.status == 404:
                        if had_outage and resubmit_count < MAX_OUTAGE_RESUBMITS:
                            resubmit_count += 1
                            rid = ""
                            allow_404_resubmit = False
                            self.progress.emit(jid, {
                                "horde_id": "",
                                "outage_resubmits": resubmit_count,
                                "state": STATE_SUBMITTING,
                                "message": f"Result expired during outage — re-submitting ({resubmit_count}/{MAX_OUTAGE_RESUBMITS})\u2026",
                            })
                            need_resubmit = True
                            break
                        self._emit_failed("Generated result expired on AI Horde before download (HTTP 404)", 0.0)
                        return
                    if exc.status == 429:
                        cool = max(5.0, float(exc.retry_after or 8.0))
                        if not self._sleep(cool, allow_wake=False):
                            if self._cancel.is_set():
                                self._do_cancel(rid)
                            else:
                                self.settled = True
                            return
                        continue
                    if is_transient_horde_error(exc):
                        had_outage = True
                        if outage_start is None:
                            outage_start = time.monotonic()
                        outage_attempt += 1
                        if not self._wait_outage(jid, outage_start, outage_attempt, "result fetch", exc.message):
                            if self._cancel.is_set():
                                self._do_cancel(rid)
                            elif self._suspend.is_set():
                                self.settled = True
                            return
                        continue
                    self._emit_failed(f"Status fetch error: {exc.message}", 0.0)
                    return
                except Exception as exc:  # noqa: BLE001
                    self._emit_failed(f"Status fetch error: {exc.__class__.__name__}: {exc}", 0.0)
                    return

            if need_resubmit:
                continue

            if final is None or not final.get("generations"):
                self._emit_failed("AI Horde finished the request, but no image generations became available", 0.0)
                return

            paths, censored, black, dl_outage, disk_err = self._store_generations(final, rid)
            if self.settled:
                return
            if self._suspend.is_set():
                self.settled = True
                return
            if self._cancel.is_set():
                self._emit_completed(paths, STATE_CANCELLED)
                return
            if not paths:
                if dl_outage and resubmit_count < MAX_OUTAGE_RESUBMITS:
                    resubmit_count += 1
                    rid = ""
                    allow_404_resubmit = False
                    STUDIO_LOG.warn("HORDE", f"#{jid} image download lost during outage — auto-resubmitting ({resubmit_count}/{MAX_OUTAGE_RESUBMITS})")
                    self.progress.emit(jid, {
                        "horde_id": "",
                        "outage_resubmits": resubmit_count,
                        "state": STATE_SUBMITTING,
                        "message": f"Download lost during outage — re-submitting ({resubmit_count}/{MAX_OUTAGE_RESUBMITS})\u2026",
                    })
                    continue
                if disk_err:
                    self._emit_failed(f"Failed saving generated image to disk: {disk_err}", 0.0)
                    return
                if job.kind == KIND_TILE_I2I and (censored or black):
                    self._emit_failed(TILE_CENSORED_MSG, 0.0)
                    return
                self._emit_failed(
                    "AI Horde returned no usable images (censored, blank, or download failed)",
                    0.0,
                )
                return
            n_expected = max(1, int((job.payload.get("params") or {}).get("n") or 1))
            if len(paths) < n_expected:
                note = f"Delivered {len(paths)}/{n_expected} image(s) (remaining lost to CDN/filter)"
                self.progress.emit(jid, {"message": note})
                STUDIO_LOG.warn("HORDE", f"Job #{jid} partial delivery: {note}")
            else:
                STUDIO_LOG.ok("HORDE", f"Job #{jid} complete ({len(paths)} image(s))")
            self._emit_completed(paths, STATE_DONE)
            return

    def _do_cancel(self, rid: str) -> None:
        jid = self.job.local_id
        paths: List[str] = []
        try:
            res = self.api.cancel(rid)
            paths, _c, _b, _o, _de = self._store_generations(res, rid, allow_outage_wait=False)
            STUDIO_LOG.info("HORDE", f"Job #{jid} cancelled on AI Horde")
        except HordeError as exc:
            if exc.status in (400, 404) or "already" in str(exc.message).lower():
                try:
                    res = self.api.status(rid)
                    paths, _c, _b, _o, _de = self._store_generations(res, rid, allow_outage_wait=False)
                    STUDIO_LOG.info("HORDE", f"Job #{jid} finished before cancel — results kept")
                except HordeError as exc2:
                    STUDIO_LOG.warn("HORDE", f"Job #{jid} cancel error: {exc2.message}")
            else:
                STUDIO_LOG.warn("HORDE", f"Job #{jid} cancel error: {exc.message}")
        except Exception as exc:  # noqa: BLE001
            STUDIO_LOG.warn("HORDE", f"Job #{jid} cancel cleanup error: {exc}")
        self._emit_completed(paths, STATE_CANCELLED)

    def _materialize_payload(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        out = dict(payload)
        src_path = out.pop("source_image_path", None)
        rect = out.pop("source_rect", None)
        mask_path = out.pop("source_mask_path", None)
        if src_path:
            try:
                with open(src_path, "rb") as fh:
                    data = fh.read()
                if rect:
                    img = QImage.fromData(QByteArray(data))
                    if img.isNull():
                        raise HordeError(f"Cannot decode source image: {src_path}")
                    x, y, w, h = rect
                    crop = img.copy(int(x), int(y), int(w), int(h))
                    data = image_to_png_bytes(crop)
                out["source_image"] = base64.b64encode(data).decode("ascii")
            except OSError as exc:
                raise HordeError(f"Cannot read source image: {exc}") from exc
        if mask_path:
            try:
                with open(mask_path, "rb") as fh:
                    out["source_mask"] = base64.b64encode(fh.read()).decode("ascii")
            except OSError as exc:
                raise HordeError(f"Cannot read mask image: {exc}") from exc
        return out

    def _store_generations(
        self,
        result: Dict[str, Any],
        rid: str,
        allow_outage_wait: bool = True,
    ) -> Tuple[List[str], int, int, bool, str]:
        job = self.job
        is_tile = job.kind == KIND_TILE_I2I
        paths: List[str] = []
        censored = 0
        black = 0
        had_dl_outage = False
        last_disk_err = ""
        gens = list(result.get("generations") or [])
        pending = list(enumerate(gens))
        outage_start: Optional[float] = None
        outage_attempt = 0
        non_outage_passes = 0

        while pending:
            deferred: List[Tuple[int, Dict[str, Any]]] = []
            saw_outage_this_pass = False
            for idx, gen in pending:
                if self._stop_requested():
                    return paths, censored, black, had_dl_outage, last_disk_err
                img_ref = gen.get("img") or ""
                if not img_ref:
                    continue
                data: Optional[bytes] = None
                try:
                    data = (
                        self.api.download(
                            img_ref,
                            cancel_check=self._stop_requested,
                            wake_event=self._wake,
                        )
                        if img_ref.startswith("http")
                        else base64.b64decode(img_ref)
                    )
                    if not data or len(data) < 64:
                        raise HordeError("Downloaded image payload was empty or truncated", rc="Network")
                    if not is_valid_image_bytes(data):
                        raise HordeError("CDN returned non-image payload (HTML/error page or corrupt bytes)", rc="InvalidImage")
                    if outage_start is not None:
                        self.network_state.emit(True, "Connected")
                        outage_start = None
                        outage_attempt = 0
                except (HordeError, ValueError) as exc:
                    if isinstance(exc, HordeError) and exc.rc == "Cancelled":
                        return paths, censored, black, had_dl_outage, last_disk_err
                    if allow_outage_wait and (is_transient_horde_error(exc) or (isinstance(exc, HordeError) and exc.status in (404, 408, 429, 500, 502, 503, 504))):
                        had_dl_outage = True
                        saw_outage_this_pass = True
                        if outage_start is None:
                            outage_start = time.monotonic()
                        outage_attempt += 1
                        deferred.append((idx, gen))
                        STUDIO_LOG.net("HORDE", f"#{job.local_id} image {idx + 1} deferred (outage attempt #{outage_attempt}): {exc}")
                    elif allow_outage_wait and non_outage_passes < 3:
                        deferred.append((idx, gen))
                        STUDIO_LOG.net("HORDE", f"#{job.local_id} image {idx + 1} retry pass {non_outage_passes + 1}/3: {exc}")
                    else:
                        STUDIO_LOG.error("HORDE", f"#{job.local_id} image {idx + 1} download failed: {exc}")
                    continue

                notes: List[str] = []
                was_censored = bool(gen.get("censored"))
                for md in gen.get("gen_metadata") or []:
                    if md.get("type") == "censorship":
                        notes.append("censored: " + str(md.get("value")))
                        was_censored = True
                    elif md.get("type") == "lora":
                        notes.append(f"lora {md.get('ref', '')}: {md.get('value')}")
                if is_tile and was_censored:
                    censored += 1
                    STUDIO_LOG.warn("Upscale", f"Tile r{job.meta.get('tile_row')}c{job.meta.get('tile_col')} censored — skipped")
                    continue
                if is_tile and is_black_placeholder_frame(data):
                    black += 1
                    STUDIO_LOG.warn("Upscale", f"Tile r{job.meta.get('tile_row')}c{job.meta.get('tile_col')} black placeholder — skipped")
                    continue
                meta = dict(job.meta)
                meta.update({
                    "seed": gen.get("seed"),
                    "horde_request_id": result.get("id") or job.horde_id or rid,
                    "generation_id": gen.get("id"),
                    "worker_name": gen.get("worker_name"),
                    "worker_id": gen.get("worker_id"),
                    "model": gen.get("model") or job.meta.get("model"),
                    "kudos": result.get("kudos", job.kudos),
                    "censored": was_censored,
                    "notes": notes,
                    "saved_at": time.time(),
                    "shared": result.get("shared"),
                    "app": f"{APP_NAME} {APP_VERSION}",
                    "index": idx,
                })
                try:
                    if is_tile:
                        path = self.store.save_tile(data, meta)
                    elif self.save_direct:
                        path = self.store.save_direct(data, meta)
                    else:
                        path = self.store.save_temp(data, meta)
                    paths.append(path)
                except OSError as exc:
                    last_disk_err = str(exc)
                    STUDIO_LOG.error("SYS", f"#{job.local_id} disk write failed: {exc}")

            if not deferred or not allow_outage_wait or self._stop_requested():
                break
            pending = deferred
            if saw_outage_this_pass and outage_start is not None:
                if not self._wait_outage(job.local_id, outage_start, max(1, outage_attempt), "image download", "CDN unreachable"):
                    break
                # Refresh /generate/status/{rid} after reconnect in case R2 signed URL rotated
                try:
                    fresh = self.api.status(rid, cancel_check=self._stop_requested)
                    fresh_gens = list(fresh.get("generations") or [])
                    if fresh_gens:
                        pending = [(i, fresh_gens[i]) for i, _g in pending if i < len(fresh_gens)]
                except HordeError as exc:
                    if exc.status == 404:
                        break
            else:
                non_outage_passes += 1
                if non_outage_passes >= 3:
                    break
                if not self._sleep(4.0 * non_outage_passes, allow_wake=True):
                    break
        return paths, censored, black, had_dl_outage, last_disk_err


class TaskThread(QThread):
    done = pyqtSignal(object)
    error = pyqtSignal(str)

    def __init__(self, fn: Callable[[], Any], parent: Optional[QObject] = None) -> None:
        super().__init__(parent)
        self.fn = fn

    def run(self) -> None:
        try:
            self.done.emit(self.fn())
        except (HordeError, LlmError) as exc:
            self.error.emit(exc.message)
        except Exception as exc:  # noqa: BLE001
            self.error.emit(f"{exc.__class__.__name__}: {exc}")


class _LogBridge(QObject):
    logged = pyqtSignal(object)


class _StSubmitBridge(QObject):
    requested = pyqtSignal(str, object, dict)


def poll_interrogation(
    api: HordeAPI,
    rid: str,
    form_name: str,
    is_cancelled: Callable[[], bool],
    poll_interval: float = 2.5,
    timeout: float = 420.0,
    wake_event: Optional[threading.Event] = None,
    on_reconnecting: Optional[Callable[[int, str], None]] = None,
    on_reconnected: Optional[Callable[[], None]] = None,
    cancel_remote_on_stop: Optional[Callable[[], bool]] = None,
) -> Optional[Dict[str, Any]]:
    """Outage-resilient Alchemy interrogation poller (survives temporary internet drops)."""
    deadline = time.monotonic() + timeout
    outage_start: Optional[float] = None
    outage_attempt = 0
    while True:
        if is_cancelled():
            if cancel_remote_on_stop is None or cancel_remote_on_stop():
                try:
                    api.interrogate_cancel(rid)
                except HordeError:
                    pass
            return None
        try:
            res = api.interrogate_status(rid, cancel_check=is_cancelled)
            if outage_start is not None:
                if on_reconnected:
                    on_reconnected()
                deadline = max(deadline, time.monotonic() + 180.0)
                outage_start = None
                outage_attempt = 0
        except HordeError as exc:
            if exc.rc == "Cancelled" or is_cancelled():
                return None
            if exc.status == 404:
                raise HordeError("Alchemy interrogation expired on AI Horde (HTTP 404)", status=404) from exc
            if exc.status == 429:
                cool = max(5.0, float(exc.retry_after or 8.0))
                if not _interruptible_sleep(cool, is_cancelled):
                    return None
                continue
            if is_transient_horde_error(exc):
                if outage_start is None:
                    outage_start = time.monotonic()
                outage_attempt += 1
                if (time.monotonic() - outage_start) >= RECONNECT_MAX_PATIENCE_SECS:
                    raise HordeError(f"Offline timeout while waiting for Alchemy {form_name}", rc="Network") from exc
                if on_reconnecting:
                    on_reconnecting(outage_attempt, exc.message)
                delay = min(18.0, 3.0 + 2.0 * min(outage_attempt, 7))
                if not _interruptible_sleep(delay, is_cancelled, wake_event=wake_event):
                    return None
                continue
            raise
        state = str(res.get("state") or "").lower()
        if state == "done":
            return res
        if state in ("faulted", "cancelled"):
            raise HordeError(f"Alchemy {form_name} {state}")
        if time.monotonic() >= deadline:
            raise HordeError(f"Alchemy {form_name} timed out")
        if not _interruptible_sleep(poll_interval, is_cancelled):
            return None


def alchemy_fetch_result(
    api: HordeAPI,
    res: Dict[str, Any],
    form_name: str,
    cancel_check: Optional[Callable[[], bool]] = None,
    wake_event: Optional[threading.Event] = None,
) -> Any:
    for item in res.get("forms") or []:
        if item.get("form") == form_name or len(res.get("forms") or []) == 1:
            r = item.get("result")
            if isinstance(r, dict):
                if form_name in r:
                    return r[form_name]
                if "url" in r:
                    return api.download(str(r["url"]), cancel_check=cancel_check, wake_event=wake_event)
                if "result" in r:
                    return r["result"]
                return r
            if isinstance(r, str):
                if r.startswith("http"):
                    return api.download(r, cancel_check=cancel_check, wake_event=wake_event)
                return r
    return None


class AlchemyJobWorker(QThread):
    progress = pyqtSignal(int, dict)
    completed = pyqtSignal(int, list, str)
    failed = pyqtSignal(int, str, float)
    network_state = pyqtSignal(bool, str)

    def __init__(
        self,
        api: HordeAPI,
        store: ImageStore,
        job: Job,
        poll_interval: float,
        wake_event: Optional[threading.Event] = None,
        parent: Optional[QObject] = None,
    ) -> None:
        super().__init__(parent)
        self.api = api
        self.store = store
        self.job = job
        self.poll_interval = max(1.5, float(poll_interval))
        self._cancel = threading.Event()
        self._suspend = threading.Event()
        self._wake = wake_event
        self.settled: bool = False

    def request_cancel(self) -> None:
        self._cancel.set()

    def request_suspend(self) -> None:
        self._suspend.set()

    def _stop_requested(self) -> bool:
        return self._cancel.is_set() or self._suspend.is_set()

    def _emit_completed(self, paths: List[str], st: str) -> None:
        if not self.settled:
            self.settled = True
            self.completed.emit(self.job.local_id, paths, st)

    def _emit_failed(self, msg: str) -> None:
        if not self.settled:
            self.settled = True
            self.failed.emit(self.job.local_id, msg, 0.0)

    def run(self) -> None:
        try:
            self._run_inner()
        except Exception as exc:  # noqa: BLE001
            if not self._suspend.is_set():
                self._emit_failed(f"Alchemy upscale error: {exc.__class__.__name__}: {exc}")
        finally:
            self.api._reset_session()
            if not self.settled and not self._suspend.is_set():
                if self._cancel.is_set():
                    self._emit_completed([], STATE_CANCELLED)
                else:
                    self._emit_failed("Upscale worker terminated unexpectedly")

    def _run_inner(self) -> None:
        job = self.job
        jid = job.local_id
        form_name = str(job.meta.get("alchemy_form") or DEFAULT_UPSCALER)
        src_path = str(job.payload.get("source_image_path") or "")
        target_w = int(job.meta.get("target_w") or 0)
        target_h = int(job.meta.get("target_h") or 0)
        target_path = str(job.meta.get("tile_target") or "")
        self.progress.emit(jid, {"state": STATE_SUBMITTING, "started_at": job.started_at or time.time(), "message": ""})

        if form_name == LANCZOS_UPSCALER:
            try:
                img = QImage(src_path)
                if img.isNull():
                    raise RuntimeError(f"Cannot load source image: {src_path}")
                out_img = hq_resize(img, target_w, target_h) if (target_w and target_h) else img
                data = image_to_png_bytes(out_img)
                meta = dict(job.meta, width=out_img.width(), height=out_img.height(), tile_target=target_path)
                path = self.store.save_tile(data, meta)
                STUDIO_LOG.ok("Upscale", f"Local Lanczos base ready ({out_img.width()}x{out_img.height()})")
                self._emit_completed([path], STATE_DONE)
            except Exception as exc:  # noqa: BLE001
                self._emit_failed(f"Lanczos resize failed: {exc}")
            return

        try:
            with open(src_path, "rb") as fh:
                b64 = base64.b64encode(fh.read()).decode("ascii")
        except OSError as exc:
            self._emit_failed(f"Cannot read upscale source: {exc}")
            return

        rid = str(job.horde_id or "")
        resubmit_count = int(job.outage_resubmits)
        had_outage = bool(job.resumed_from_journal)

        while True:
            if self._suspend.is_set():
                self.settled = True
                return
            if self._cancel.is_set():
                self._emit_completed([], STATE_CANCELLED)
                return

            outage_start: Optional[float] = None
            outage_attempt = 0
            while not rid:
                if self._suspend.is_set():
                    self.settled = True
                    return
                if self._cancel.is_set():
                    self._emit_completed([], STATE_CANCELLED)
                    return
                try:
                    sub = self.api.interrogate_submit(
                        {"source_image": b64, "forms": [{"name": form_name}]},
                        cancel_check=self._stop_requested,
                    )
                    if outage_start is not None:
                        self.network_state.emit(True, "Connected")
                    rid = str(sub.get("id") or "")
                    if not rid:
                        self._emit_failed("Alchemy returned no request id")
                        return
                except HordeError as exc:
                    if self._suspend.is_set():
                        self.settled = True
                        return
                    if exc.rc == "Cancelled" or self._cancel.is_set():
                        self._emit_completed([], STATE_CANCELLED)
                        return
                    if exc.status == 429:
                        cool = max(6.0, float(exc.retry_after or 12.0))
                        self.progress.emit(jid, {"state": STATE_RECONNECTING, "message": f"Rate-limited — retrying upscale in {int(cool)}s"})
                        if not _interruptible_sleep(cool, self._stop_requested):
                            if self._cancel.is_set():
                                self._emit_completed([], STATE_CANCELLED)
                            else:
                                self.settled = True
                            return
                        continue
                    if is_transient_horde_error(exc):
                        had_outage = True
                        if outage_start is None:
                            outage_start = time.monotonic()
                        outage_attempt += 1
                        if (time.monotonic() - outage_start) >= RECONNECT_MAX_PATIENCE_SECS:
                            self._emit_failed(f"Offline timeout submitting upscale: {exc.message}")
                            return
                        delay = min(18.0, 3.0 + 2.0 * min(outage_attempt, 7))
                        self.network_state.emit(False, exc.message[:60])
                        self.progress.emit(jid, {
                            "state": STATE_RECONNECTING,
                            "outage_attempts": outage_attempt,
                            "message": f"Offline (upscale submit) — retry #{outage_attempt} in {int(delay)}s",
                        })
                        if not _interruptible_sleep(delay, self._stop_requested, wake_event=self._wake):
                            if self._cancel.is_set():
                                self._emit_completed([], STATE_CANCELLED)
                            else:
                                self.settled = True
                            return
                        continue
                    self._emit_failed(exc.message)
                    return

            self.progress.emit(jid, {"horde_id": rid, "state": STATE_PROCESSING, "message": "", "resumed_from_journal": False})
            try:
                res = poll_interrogation(
                    self.api,
                    rid,
                    form_name,
                    self._stop_requested,
                    self.poll_interval,
                    420.0,
                    wake_event=self._wake,
                    on_reconnecting=lambda att, msg: (
                        self.network_state.emit(False, msg[:60]),
                        self.progress.emit(jid, {"state": STATE_RECONNECTING, "outage_attempts": att, "message": f"Offline (upscale poll #{att}) — holding safely"}),
                    ),
                    on_reconnected=lambda: (
                        self.network_state.emit(True, "Connected"),
                        self.progress.emit(jid, {"state": STATE_PROCESSING, "message": ""}),
                    ),
                    cancel_remote_on_stop=lambda: self._cancel.is_set(),
                )
                if res is None:
                    if self._suspend.is_set():
                        self.settled = True
                    else:
                        self._emit_completed([], STATE_CANCELLED)
                    return
                self.progress.emit(jid, {"state": STATE_FETCHING, "message": "Downloading upscaled base\u2026"})
                raw = alchemy_fetch_result(self.api, res, form_name, cancel_check=self._stop_requested, wake_event=self._wake)
                if isinstance(raw, str):
                    raw = base64.b64decode(raw)
                if not isinstance(raw, (bytes, bytearray)) or not raw:
                    self._emit_failed(f"Alchemy {form_name} returned empty image")
                    return
                img = QImage.fromData(QByteArray(bytes(raw)))
                if img.isNull():
                    self._emit_failed(f"Alchemy {form_name} returned undecodable image")
                    return
                if target_w and target_h and (img.width() != target_w or img.height() != target_h):
                    img = hq_resize(img, target_w, target_h)
                out_bytes = image_to_png_bytes(img)
                meta = dict(job.meta, width=img.width(), height=img.height(), tile_target=target_path)
                path = self.store.save_tile(out_bytes, meta)
                STUDIO_LOG.ok("Upscale", f"Alchemy base ready ({img.width()}x{img.height()})")
                self._emit_completed([path], STATE_DONE)
                return
            except HordeError as exc:
                if self._suspend.is_set():
                    self.settled = True
                    return
                if exc.rc == "Cancelled" or self._cancel.is_set():
                    self._emit_completed([], STATE_CANCELLED)
                    return
                if is_transient_horde_error(exc):
                    had_outage = True
                    self.network_state.emit(False, elide(exc.message, 64))
                    self.progress.emit(jid, {"state": STATE_RECONNECTING, "message": f"Offline during upscale download — retrying… ({elide(exc.message, 48)})"})
                    if not _interruptible_sleep(8.0, self._stop_requested, wake_event=self._wake):
                        if self._cancel.is_set():
                            self._emit_completed([], STATE_CANCELLED)
                        else:
                            self.settled = True
                        return
                    continue
                if exc.status == 404 and (had_outage or resubmit_count < MAX_OUTAGE_RESUBMITS):
                    if resubmit_count < MAX_OUTAGE_RESUBMITS:
                        resubmit_count += 1
                        rid = ""
                        self.progress.emit(jid, {"horde_id": "", "outage_resubmits": resubmit_count, "state": STATE_SUBMITTING, "message": f"Re-submitting upscale ({resubmit_count}/{MAX_OUTAGE_RESUBMITS})\u2026"})
                        continue
                self._emit_failed(exc.message)
                return


class AestheticWorker(QThread):
    scored = pyqtSignal(str, float)

    def __init__(self, api: HordeAPI, path: str, parent: Optional[QObject] = None) -> None:
        super().__init__(parent)
        self.api = api
        self.path = path
        self._cancel = threading.Event()

    def request_cancel(self) -> None:
        self._cancel.set()

    def run(self) -> None:
        try:
            with open(self.path, "rb") as fh:
                b64 = base64.b64encode(fh.read()).decode("ascii")
            sub = self.api.interrogate_submit({"source_image": b64, "forms": [{"name": "aesthetics"}]}, cancel_check=self._cancel.is_set)
            rid = str(sub.get("id") or "")
            if not rid:
                return
            res = poll_interrogation(self.api, rid, "aesthetics", self._cancel.is_set, 2.5, 180.0)
            if not res:
                return
            val = alchemy_fetch_result(self.api, res, "aesthetics", cancel_check=self._cancel.is_set)
            score: Optional[float] = None
            if isinstance(val, (int, float)):
                score = float(val)
            elif isinstance(val, dict):
                for k in ("score", "aesthetic", "aesthetics"):
                    if isinstance(val.get(k), (int, float)):
                        score = float(val[k])
                        break
            if score is not None:
                self.scored.emit(self.path, score)
        except Exception as exc:  # noqa: BLE001
            STUDIO_LOG.warn("HORDE", f"Aesthetic scoring failed for {os.path.basename(self.path)}: {exc}")


class DepthMapWorker(QThread):
    """Outage-resilient Depth Anything V2 annotation worker (v13.0)."""

    progress = pyqtSignal(int, dict)
    completed = pyqtSignal(int, list, str)
    failed = pyqtSignal(int, str, float)
    network_state = pyqtSignal(bool, str)

    def __init__(
        self,
        api: HordeAPI,
        job: Job,
        poll_interval: float,
        wake_event: Optional[threading.Event] = None,
        parent: Optional[QObject] = None,
    ) -> None:
        super().__init__(parent)
        self.api = api
        self.job = job
        self.poll_interval = max(1.5, float(poll_interval))
        self._cancel = threading.Event()
        self._suspend = threading.Event()
        self._wake = wake_event
        self.settled: bool = False

    def request_cancel(self) -> None:
        self._cancel.set()

    def request_suspend(self) -> None:
        self._suspend.set()

    def _stop_requested(self) -> bool:
        return self._cancel.is_set() or self._suspend.is_set()

    def _emit_completed(self, paths: List[str], st: str) -> None:
        if not self.settled:
            self.settled = True
            self.completed.emit(self.job.local_id, paths, st)

    def _emit_failed(self, msg: str) -> None:
        if not self.settled:
            self.settled = True
            self.failed.emit(self.job.local_id, msg, 0.0)

    def run(self) -> None:
        try:
            self._run_inner()
        except Exception as exc:  # noqa: BLE001
            if not self._suspend.is_set():
                self._emit_failed(f"Depth map error: {exc.__class__.__name__}: {exc}")
        finally:
            self.api._reset_session()
            if not self.settled and not self._suspend.is_set():
                if self._cancel.is_set():
                    self._emit_completed([], STATE_CANCELLED)
                else:
                    self._emit_failed("Depth worker terminated unexpectedly")

    def _run_inner(self) -> None:
        job = self.job
        jid = job.local_id
        src_path = str(job.payload.get("source_image_path") or "")
        target_path = str(job.meta.get("depth_target") or depth_path_for(src_path))
        self.progress.emit(jid, {"state": STATE_SUBMITTING, "started_at": job.started_at or time.time(), "message": ""})
        try:
            with open(src_path, "rb") as fh:
                b64 = base64.b64encode(fh.read()).decode("ascii")
        except OSError as exc:
            self._emit_failed(f"Cannot read depth source: {exc}")
            return

        rid = str(job.horde_id or "")
        resubmit_count = int(job.outage_resubmits)
        had_outage = bool(job.resumed_from_journal)
        payload = {
            "source_image": b64,
            "forms": [{"name": DEPTH_FORM, "payload": {"control_type": DEPTH_CONTROL_TYPE}}],
        }

        while True:
            if self._suspend.is_set():
                self.settled = True
                return
            if self._cancel.is_set():
                self._emit_completed([], STATE_CANCELLED)
                return

            outage_start: Optional[float] = None
            outage_attempt = 0
            while not rid:
                if self._suspend.is_set():
                    self.settled = True
                    return
                if self._cancel.is_set():
                    self._emit_completed([], STATE_CANCELLED)
                    return
                try:
                    sub = self.api.interrogate_submit(payload, cancel_check=self._stop_requested)
                    if outage_start is not None:
                        self.network_state.emit(True, "Connected")
                    rid = str(sub.get("id") or "")
                    if not rid:
                        self._emit_failed("Alchemy depth returned no request id")
                        return
                except HordeError as exc:
                    if self._suspend.is_set():
                        self.settled = True
                        return
                    if exc.rc == "Cancelled" or self._cancel.is_set():
                        self._emit_completed([], STATE_CANCELLED)
                        return
                    if exc.status == 429:
                        cool = max(6.0, float(exc.retry_after or 12.0))
                        self.progress.emit(jid, {"state": STATE_RECONNECTING, "message": f"Rate-limited — retrying depth in {int(cool)}s"})
                        if not _interruptible_sleep(cool, self._stop_requested):
                            if self._cancel.is_set():
                                self._emit_completed([], STATE_CANCELLED)
                            else:
                                self.settled = True
                            return
                        continue
                    if is_transient_horde_error(exc):
                        had_outage = True
                        if outage_start is None:
                            outage_start = time.monotonic()
                        outage_attempt += 1
                        if (time.monotonic() - outage_start) >= RECONNECT_MAX_PATIENCE_SECS:
                            self._emit_failed(f"Offline timeout submitting depth map: {exc.message}")
                            return
                        delay = min(18.0, 3.0 + 2.0 * min(outage_attempt, 7))
                        self.network_state.emit(False, exc.message[:60])
                        self.progress.emit(jid, {
                            "state": STATE_RECONNECTING,
                            "outage_attempts": outage_attempt,
                            "message": f"Offline (depth submit) — retry #{outage_attempt} in {int(delay)}s",
                        })
                        if not _interruptible_sleep(delay, self._stop_requested, wake_event=self._wake):
                            if self._cancel.is_set():
                                self._emit_completed([], STATE_CANCELLED)
                            else:
                                self.settled = True
                            return
                        continue
                    self._emit_failed(exc.message)
                    return

            self.progress.emit(jid, {"horde_id": rid, "state": STATE_PROCESSING, "message": "", "resumed_from_journal": False})
            try:
                res = poll_interrogation(
                    self.api,
                    rid,
                    DEPTH_FORM,
                    self._stop_requested,
                    self.poll_interval,
                    420.0,
                    wake_event=self._wake,
                    on_reconnecting=lambda att, msg: (
                        self.network_state.emit(False, msg[:60]),
                        self.progress.emit(jid, {"state": STATE_RECONNECTING, "outage_attempts": att, "message": f"Offline (depth poll #{att}) — holding safely"}),
                    ),
                    on_reconnected=lambda: (
                        self.network_state.emit(True, "Connected"),
                        self.progress.emit(jid, {"state": STATE_PROCESSING, "message": ""}),
                    ),
                    cancel_remote_on_stop=lambda: self._cancel.is_set(),
                )
                if res is None:
                    if self._suspend.is_set():
                        self.settled = True
                    else:
                        self._emit_completed([], STATE_CANCELLED)
                    return
                self.progress.emit(jid, {"state": STATE_FETCHING, "message": "Downloading depth map\u2026"})
                raw = alchemy_fetch_result(self.api, res, DEPTH_FORM, cancel_check=self._stop_requested, wake_event=self._wake)
                if isinstance(raw, dict):
                    raw = raw.get(DEPTH_CONTROL_TYPE) or raw.get("url") or raw.get("result") or ""
                if isinstance(raw, str):
                    if raw.startswith("http"):
                        raw = self.api.download(raw, cancel_check=self._stop_requested, wake_event=self._wake)
                    else:
                        raw = base64.b64decode(raw)
                if not isinstance(raw, (bytes, bytearray)) or not raw:
                    self._emit_failed("Alchemy depth_anything_v2 returned empty map")
                    return
                img = QImage.fromData(QByteArray(bytes(raw)))
                if img.isNull():
                    self._emit_failed("Alchemy depth_anything_v2 returned undecodable image")
                    return
                meta = {
                    "depth_map": True,
                    "control_type": DEPTH_CONTROL_TYPE,
                    "depth_source": src_path,
                    "width": img.width(),
                    "height": img.height(),
                    "saved_at": time.time(),
                    "app": f"{APP_NAME} {APP_VERSION}",
                }
                write_image_with_metadata(image_to_png_bytes(img), target_path, meta)
                STUDIO_LOG.ok("HORDE", f"Depth map saved -> {os.path.basename(target_path)}")
                self._emit_completed([target_path], STATE_DONE)
                return
            except HordeError as exc:
                if self._suspend.is_set():
                    self.settled = True
                    return
                if exc.rc == "Cancelled" or self._cancel.is_set():
                    self._emit_completed([], STATE_CANCELLED)
                    return
                if is_transient_horde_error(exc):
                    had_outage = True
                    self.network_state.emit(False, elide(exc.message, 64))
                    self.progress.emit(jid, {"state": STATE_RECONNECTING, "message": f"Offline during depth download — retrying… ({elide(exc.message, 48)})"})
                    if not _interruptible_sleep(8.0, self._stop_requested, wake_event=self._wake):
                        if self._cancel.is_set():
                            self._emit_completed([], STATE_CANCELLED)
                        else:
                            self.settled = True
                        return
                    continue
                if exc.status == 404 and (had_outage or resubmit_count < MAX_OUTAGE_RESUBMITS):
                    if resubmit_count < MAX_OUTAGE_RESUBMITS:
                        resubmit_count += 1
                        rid = ""
                        self.progress.emit(jid, {"horde_id": "", "outage_resubmits": resubmit_count, "state": STATE_SUBMITTING, "message": f"Re-submitting depth ({resubmit_count}/{MAX_OUTAGE_RESUBMITS})\u2026"})
                        continue
                self._emit_failed(exc.message)
                return


def snap64(v: float, lo: int = 64, hi: int = 3072) -> int:
    s = int(round(v / 64.0)) * 64
    return max(lo, min(hi, s))


def snap64_up(v: float, lo: int = 64, hi: int = 3072) -> int:
    """Ceil to the next multiple of 64 (never exceeds `hi`)."""
    s = int(math.ceil(v / 64.0)) * 64
    return max(lo, min(hi, s))


def snap64_nearest(v: float, lo: int = 64, hi: int = 3072) -> int:
    """Round to the NEAREST multiple of 64 (up or down, whichever is closer)
    and clamp into [lo, hi] - the AI Horde dimension requirement."""
    s = int(round(v / 64.0)) * 64
    return max(lo, min(hi, s))


def fit_pair_under_mp(w: float, h: float, max_mp: int = MEGAPIXEL_BUDGET) -> Tuple[int, int]:
    """Scale a W x H pair to fit under the megapixel budget while keeping the
    aspect ratio, snapping both dimensions to the nearest multiple of 64. If
    nearest-rounding still exceeds the budget, step the larger dimension down
    by 64 until it fits."""
    px = float(w) * float(h)
    if px <= 0:
        return (64, 64)
    if px > max_mp:
        s = math.sqrt(max_mp / px)
        w, h = w * s, h * s
    ow, oh = snap64_nearest(w), snap64_nearest(h)
    while ow * oh > max_mp and (ow > 64 or oh > 64):
        if ow >= oh and ow > 64:
            ow -= 64
        elif oh > 64:
            oh -= 64
        else:
            break
    return (ow, oh)


def plan_tile_grid(
    src_w: int,
    src_h: int,
    scale: float,
    overlap: int,
    max_mp: int = MEGAPIXEL_BUDGET,
) -> Dict[str, Any]:
    """Plan the A1111-style tiled upscale as a grid of UNIFORM SQUARE tiles.

    Design goals (v3.1 remaster):
      * Every tile that goes through img2img is a large S×S square (SDXL-optimal,
        aspect 1:1) — except an axis that fits inside a single tile, which then
        spans the full extent of that axis.
      * Tiles are evenly distributed across the image: the first tile starts at 0,
        the last tile ends exactly at the image edge, and every neighbour pair
        shares the SAME overlap. No tiny/narrow corner or edge remainder tiles —
        every request is a full-size square.
      * Each tile is 64px-aligned and stays within `max_mp` (the 1 MP AI Horde
        budget), so the worker never resizes the source and never rejects it.

    Algorithm:
      1. S_max = largest 64-multiple with S_max² <= max_mp (1024 for 1 MP).
      2. cols/rows = minimal tile counts whose S_max tiles (with `overlap`
         between neighbours) still cover the output canvas.
      3. S = smallest 64-multiple that covers BOTH axes with those counts →
         all tiles are exactly S×S (single-tile axes use the full extent).
      4. Tile origins are evenly spaced with a uniform step so the grid has no
         remainder slivers at the right/bottom edges.
    """
    out_w = max(128, snap64(src_w * scale, 128, 8192))
    out_h = max(128, snap64(src_h * scale, 128, 8192))
    ov = max(0, snap64(overlap, 0, 512))
    ov = min(ov, max(0, min(out_w, out_h) // 4))

    # Largest square tile the AI Horde megapixel budget allows (64-aligned).
    s_max = max(64, int(math.sqrt(max(1, max_mp))))
    s_max = (s_max // 64) * 64

    def _cells(total: int, tile: int) -> int:
        """Minimal tile count covering `total` with `tile`-sized steps + overlap."""
        if total <= tile:
            return 1
        if ov <= 0:
            return int(math.ceil(total / tile))
        return int(math.ceil((total - ov) / float(tile - ov)))

    def _need(total: int, n: int) -> int:
        """Smallest 64-aligned per-tile span covering `total` with n tiles."""
        if n <= 1:
            return total
        return snap64_up((total + (n - 1) * ov) / float(n), 64, s_max)

    cols = _cells(out_w, s_max)
    rows = _cells(out_h, s_max)
    # Uniform square tile size: the smallest S that covers both axes (S <= s_max
    # by construction because s_max is 64-aligned and _need never exceeds it).
    s = max(_need(out_w, cols), _need(out_h, rows))
    s = max(64, min(s, s_max))

    tile_w = s if cols > 1 else out_w   # single-column: full width
    tile_h = s if rows > 1 else out_h   # single-row: full height

    def _origins(total: int, n: int, tile_len: int) -> List[int]:
        if n <= 1:
            return [0]
        # Evenly space n tiles; first at 0, last ends exactly at `total`.
        step = (total - tile_len) / float(n - 1)
        return [int(round(i * step)) for i in range(n)]

    xs = _origins(out_w, cols, tile_w)
    ys = _origins(out_h, rows, tile_h)

    # Uniform neighbour overlap per axis (feathered seam width source)
    ov_x = (tile_w - (xs[1] - xs[0])) if cols > 1 else 0
    ov_y = (tile_h - (ys[1] - ys[0])) if rows > 1 else 0

    tiles: List[Dict[str, Any]] = []
    tid = 0
    for r, y0 in enumerate(ys):
        for c, x0 in enumerate(xs):
            edge_l = ov_x if c > 0 else 0
            edge_r = ov_x if c < cols - 1 else 0
            edge_t = ov_y if r > 0 else 0
            edge_b = ov_y if r < rows - 1 else 0
            tiles.append({
                "idx": tid,
                "row": r,
                "col": c,
                "x": x0,
                "y": y0,
                "w": tile_w,
                "h": tile_h,
                "send_w": tile_w,
                "send_h": tile_h,
                "edge_l": edge_l,
                "edge_t": edge_t,
                "edge_r": edge_r,
                "edge_b": edge_b,
                "state": TILE_PLANNED,
                "path": "",
                "error": "",
                "job_id": None,
            })
            tid += 1
    return {
        "src_w": src_w,
        "src_h": src_h,
        "out_w": out_w,
        "out_h": out_h,
        "cols": cols,
        "rows": rows,
        "tile": s,
        "overlap": ov,
        "tiles": tiles,
    }


def _feathered_tile(tile_img: QImage, e_l: int, e_t: int, e_r: int, e_b: int) -> QImage:
    """Apply smooth linear alpha feather ramps along shared overlap edges.

    v3 optimization: only the actual feather bands are processed (edge-restricted
    alpha), instead of the v2 full-image scan — several times faster per tile
    while producing bit-identical results."""
    img = tile_img.convertToFormat(QImage.Format.Format_ARGB32)
    w, h = img.width(), img.height()
    if w <= 0 or h <= 0:
        return img
    fl = max(0, min(w // 2, e_l * 2))
    fr = max(0, min(w // 2, e_r * 2))
    ft = max(0, min(h // 2, e_t * 2))
    fb = max(0, min(h // 2, e_b * 2))
    if fl == 0 and fr == 0 and ft == 0 and fb == 0:
        return img

    # Horizontal ramp only where a left/right feather exists
    ax: Optional[List[float]] = None
    if fl or fr:
        ax = [1.0] * w
        for x in range(fl):
            ax[x] = min(ax[x], (x + 0.5) / fl)
        for x in range(fr):
            ax[w - 1 - x] = min(ax[w - 1 - x], (x + 0.5) / fr)
    # Vertical ramp only where a top/bottom feather exists
    ay: Optional[List[float]] = None
    if ft or fb:
        ay = [1.0] * h
        for y in range(ft):
            ay[y] = min(ay[y], (y + 0.5) / ft)
        for y in range(fb):
            ay[h - 1 - y] = min(ay[h - 1 - y], (y + 0.5) / fb)

    for y in range(h):
        wy = ay[y] if ay is not None else 1.0
        if wy >= 0.9999 and ax is None:
            continue  # fully opaque row with no horizontal feather
        if wy >= 0.9999:
            # Row keeps full vertical opacity: only touch horizontal bands
            zones: List[Tuple[int, int]] = []
            if fl:
                zones.append((0, fl))
            if fr:
                zones.append((w - fr, w))
            if ax is not None:
                for x0, x1 in zones:
                    for x in range(x0, x1):
                        alpha = ax[x]
                        if alpha < 0.9999:
                            col = img.pixelColor(x, y)
                            col.setAlpha(int(round(col.alpha() * alpha)))
                            img.setPixelColor(x, y, col)
        else:
            # Vertical ramp active: process the full row
            for x in range(w):
                alpha = wy * (ax[x] if ax is not None else 1.0)
                if alpha < 0.9999:
                    col = img.pixelColor(x, y)
                    col.setAlpha(int(round(col.alpha() * alpha)))
                    img.setPixelColor(x, y, col)
    return img


def merge_tiles(
    tiles: List[Dict[str, Any]],
    out_w: int,
    out_h: int,
    base_path: Optional[str] = None,
) -> QImage:
    """Composite finished refined tiles with feathered seams over the upscaled base."""
    canvas = QImage(out_w, out_h, QImage.Format.Format_ARGB32)
    canvas.fill(QColor(0, 0, 0, 255))
    painter = QPainter(canvas)
    painter.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)
    if base_path and os.path.isfile(base_path):
        base = QImage(base_path)
        if not base.isNull():
            if base.width() != out_w or base.height() != out_h:
                base = hq_resize(base, out_w, out_h)
            painter.drawImage(0, 0, base)
    for t in tiles:
        if t.get("state") != TILE_DONE or not t.get("path") or not os.path.isfile(t["path"]):
            continue
        timg = QImage(t["path"])
        if timg.isNull():
            continue
        tw, th = int(t["w"]), int(t["h"])
        if timg.width() != tw or timg.height() != th:
            timg = hq_resize(timg, tw, th)
        feathered = _feathered_tile(
            timg, int(t["edge_l"]), int(t["edge_t"]), int(t["edge_r"]), int(t["edge_b"])
        )
        painter.drawImage(int(t["x"]), int(t["y"]), feathered)
    painter.end()
    return canvas

# =============================================================================
#  14. Queue Manager (Parallel Slot Scheduler + Pinned Upscale Groups)
# =============================================================================
# =============================================================================
#  14. Crash-Safe Queue Journal, Network Probe & Anti-Zombie QueueManager
# =============================================================================
class QueueJournal:
    """Crash-safe atomic JSON journal (data/queue_journal.json + .bak mirror)
    with fsync durability so unfinished queued/in-flight tasks survive sudden
    disconnects, restarts, or power cuts without loss."""

    def __init__(self, path: str = QUEUE_JOURNAL_FILE) -> None:
        self.path = path
        self.bak_path = path + ".bak"
        self._lock = threading.Lock()

    def save(self, jobs: Sequence[Job]) -> None:
        entries: List[Dict[str, Any]] = []
        for j in jobs:
            d = j.to_journal_dict()
            if d is not None:
                entries.append(d)
        with self._lock:
            try:
                os.makedirs(os.path.dirname(self.path), exist_ok=True)
                if not entries:
                    for p in (self.path, self.bak_path):
                        if os.path.isfile(p):
                            try:
                                os.remove(p)
                            except OSError:
                                pass
                    return
                tmp = f"{self.path}.tmp.{os.getpid()}"
                payload = {"version": QUEUE_JOURNAL_VERSION, "saved_at": time.time(), "jobs": entries}
                with open(tmp, "w", encoding="utf-8") as fh:
                    json.dump(payload, fh, indent=2, ensure_ascii=False)
                    fh.flush()
                    try:
                        os.fsync(fh.fileno())
                    except OSError:
                        pass
                if os.path.isfile(self.path):
                    try:
                        shutil.copy2(self.path, self.bak_path)
                    except OSError:
                        pass
                os.replace(tmp, self.path)
            except OSError as exc:
                STUDIO_LOG.warn("SYS", f"Queue journal save skipped: {exc}")

    def load(self) -> List[Dict[str, Any]]:
        with self._lock:
            for candidate in (self.path, self.bak_path):
                if not os.path.isfile(candidate):
                    continue
                try:
                    with open(candidate, "r", encoding="utf-8") as fh:
                        doc = json.load(fh)
                    items = doc.get("jobs") if isinstance(doc, dict) else []
                    if isinstance(items, list):
                        if candidate == self.bak_path:
                            STUDIO_LOG.warn("SYS", "Recovered queue journal from backup copy (.bak)")
                        return [it for it in items if isinstance(it, dict)]
                except (OSError, ValueError):
                    continue
            return []


class _ConnectivityProbeWorker(QThread):
    """Lightweight single-shot heartbeat check run ONLY when connectivity is marked
    offline and queued/active tasks are waiting to resume (zero idle traffic!)."""

    probed = pyqtSignal(bool, str)

    def __init__(self, api: HordeAPI, parent: Optional[QObject] = None) -> None:
        super().__init__(parent)
        self.api = api

    def run(self) -> None:
        try:
            self.api.heartbeat(timeout=8.0)
            self.probed.emit(True, "AI Horde reachable")
        except Exception as exc:  # noqa: BLE001
            self.probed.emit(False, str(exc)[:100])


class QueueManager(QAbstractListModel):
    image_ready = pyqtSignal(str, dict)
    job_finished = pyqtSignal(object)
    summary_changed = pyqtSignal()
    network_online_changed = pyqtSignal(bool, str)

    def __init__(self, api: HordeAPI, store: ImageStore, parent: Optional[QObject] = None) -> None:
        super().__init__(parent)
        self.api = api
        self.store = store
        self.journal = QueueJournal()
        self.jobs: List[Job] = []
        self._workers: Dict[int, QThread] = {}
        self._purged: Dict[int, Job] = {}
        self._next_id = 1
        self.max_parallel = 2
        self.poll_interval = 2.5
        self.save_direct = False
        self.paused = False
        self.network_online = True
        self.network_reason = ""
        self._net_epoch: int = 0
        self._last_online_ts: float = 0.0
        self._wake_event = threading.Event()
        self._probe_worker: Optional[_ConnectivityProbeWorker] = None

        # Zero-idle timers: ONLY run while unfinished jobs exist!
        self._retry_timer = QTimer(self)
        self._retry_timer.setInterval(1500)
        self._retry_timer.timeout.connect(self._tick_watchdog)

        self._probe_timer = QTimer(self)
        self._probe_timer.setInterval(6500)
        self._probe_timer.timeout.connect(self._run_connectivity_probe)

        self._journal_timer = QTimer(self)
        self._journal_timer.setSingleShot(True)
        self._journal_timer.setInterval(450)
        self._journal_timer.timeout.connect(self._flush_journal)

    def _schedule_journal(self) -> None:
        if not self._journal_timer.isActive():
            self._journal_timer.start()

    def _flush_journal(self) -> None:
        self.journal.save(self.jobs)

    def restore_from_journal(self) -> int:
        """Restore any unfinished jobs persisted before last close/crash."""
        docs = self.journal.load()
        if not docs:
            return 0
        restored = 0
        for doc in docs:
            job = Job.from_journal_dict(doc, self._next_id)
            if job is None:
                continue
            self._next_id += 1
            row = self._insert_index_for(job.kind)
            self.beginInsertRows(QModelIndex(), row, row)
            self.jobs.insert(row, job)
            self.endInsertRows()
            restored += 1
        if restored:
            STUDIO_LOG.info("HORDE", f"Restored {restored} unfinished task(s) from crash-safe queue journal")
            self.summary_changed.emit()
            self._sync_timers()
            self._schedule()
        return restored

    def _has_live_jobs(self) -> bool:
        return any(j.kind != KIND_GROUP and not j.terminal for j in self.jobs)

    def _sync_timers(self) -> None:
        live = self._has_live_jobs()
        if live and not self._retry_timer.isActive():
            self._retry_timer.start()
        elif not live and self._retry_timer.isActive():
            self._retry_timer.stop()
        need_probe = live and not self.network_online
        if need_probe and not self._probe_timer.isActive():
            self._probe_timer.start()
        elif not need_probe and self._probe_timer.isActive():
            self._probe_timer.stop()

    def _set_network_online(self, online: bool, reason: str = "") -> None:
        now_m = time.monotonic()
        if not online and self.network_online and (now_m - self._last_online_ts) < 2.0:
            return
        was = self.network_online
        self.network_online = bool(online)
        self.network_reason = "" if online else (reason or "Connection lost")
        if online:
            self._net_epoch += 1
            self._last_online_ts = now_m
            epoch_snap = self._net_epoch
            self._wake_event.set()
            QTimer.singleShot(850, lambda ep=epoch_snap: self._clear_wake_if_epoch(ep))
            now = time.time()
            for j in self.jobs:
                if j.state == STATE_QUEUED and j.retry_after > now:
                    j.retry_after = 0.0
        if online != was:
            if online:
                STUDIO_LOG.ok("HORDE", "Internet connectivity restored — resuming queued/reconnecting tasks")
            else:
                STUDIO_LOG.warn("HORDE", f"Internet connection lost — holding tasks safely ({self.network_reason})")
            self.network_online_changed.emit(self.network_online, self.network_reason)
            self.summary_changed.emit()
        self._sync_timers()
        if online:
            self._schedule()

    def _clear_wake_if_epoch(self, ep: int) -> None:
        if self._net_epoch == ep:
            self._wake_event.clear()

    def retry_network_now(self) -> None:
        """User clicked 'Retry Now' on Offline Banner — immediately probe & wake workers."""
        self._net_epoch += 1
        epoch_snap = self._net_epoch
        self._wake_event.set()
        QTimer.singleShot(850, lambda ep=epoch_snap: self._clear_wake_if_epoch(ep))
        for j in self.jobs:
            if j.state == STATE_QUEUED and j.retry_after > 0:
                j.retry_after = 0.0
        self._run_connectivity_probe()
        self._schedule()

    def _run_connectivity_probe(self) -> None:
        if self._probe_worker is not None and self._probe_worker.isRunning():
            return
        w = _ConnectivityProbeWorker(self.api, self)
        w.probed.connect(self._on_probe_result)
        w.finished.connect(lambda wk=w: self._cleanup_probe(wk))
        self._probe_worker = w
        w.start()

    def _on_probe_result(self, ok: bool, detail: str) -> None:
        if ok:
            self._set_network_online(True, detail)

    def _cleanup_probe(self, wk: _ConnectivityProbeWorker) -> None:
        if self._probe_worker is wk:
            self._probe_worker = None
        wk.deleteLater()

    def _tick_watchdog(self) -> None:
        """Periodic scheduler pump & race-safe orphan sweep (runs ONLY while live jobs exist).
        Never races against queued completed/failed signals: finished workers are
        audited deterministically in `_cleanup_worker` after signal delivery."""
        for job in list(self.jobs):
            if job.kind == KIND_GROUP:
                continue
            if job.active and job.local_id not in self._workers:
                # Truly orphaned (no worker registered at all)
                if job.watchdog_recoveries < MAX_WATCHDOG_RECOVERIES:
                    job.watchdog_recoveries += 1
                    STUDIO_LOG.warn("HORDE", f"Watchdog recovered unowned job #{job.local_id} ({job.watchdog_recoveries}/{MAX_WATCHDOG_RECOVERIES})")
                    job.state = STATE_QUEUED
                    job.retry_after = 0.0
                    job.message = "Recovered by queue watchdog — resuming\u2026"
                    self._emit_row(self._row_of(job.local_id))
                else:
                    job.state = STATE_FAILED
                    job.ended_at = time.time()
                    job.message = "Worker terminated repeatedly without completing task"
                    self._emit_row(self._row_of(job.local_id))
                    self.job_finished.emit(job)
        self._schedule()
        self._sync_timers()

    def rowCount(self, parent: Optional[QModelIndex] = None) -> int:  # noqa: N802
        return 0 if (parent is not None and parent.isValid()) else len(self.jobs)

    def data(self, index: QModelIndex, role: int = Qt.ItemDataRole.DisplayRole) -> Any:
        if not index.isValid() or not (0 <= index.row() < len(self.jobs)):
            return None
        job = self.jobs[index.row()]
        if role == Qt.ItemDataRole.UserRole:
            return job
        if role == Qt.ItemDataRole.DisplayRole:
            return job.title_line()
        return None

    def _row_of(self, local_id: int) -> int:
        for i, j in enumerate(self.jobs):
            if j.local_id == local_id:
                return i
        return -1

    def _emit_row(self, row: int) -> None:
        if 0 <= row < len(self.jobs):
            ix = self.index(row, 0)
            self.dataChanged.emit(ix, ix)

    def _insert_index_for(self, kind: str) -> int:
        if kind == KIND_GROUP:
            idx = 0
            while idx < len(self.jobs) and self.jobs[idx].kind == KIND_GROUP:
                idx += 1
            return idx
        return len(self.jobs)

    def enqueue(
        self,
        payload: Dict[str, Any],
        meta: Dict[str, Any],
        kind: str = KIND_GEN,
        group_id: Optional[int] = None,
    ) -> Job:
        job = Job(
            local_id=self._next_id,
            payload=copy.deepcopy(payload),
            meta=copy.deepcopy(meta),
            kind=kind,
            group_id=group_id,
        )
        self._next_id += 1
        row = self._insert_index_for(kind)
        self.beginInsertRows(QModelIndex(), row, row)
        self.jobs.insert(row, job)
        self.endInsertRows()
        self._flush_journal()
        self._sync_timers()
        self.summary_changed.emit()
        self._schedule()
        return job

    def add_group(self, gid: int, title: str, detail: str) -> Job:
        job = Job(
            local_id=self._next_id,
            payload={},
            meta={"tile_group": gid},
            kind=KIND_GROUP,
            group_id=gid,
            state=STATE_PROCESSING,
            group_title=title,
            group_detail=detail,
            group_progress=0.02,
        )
        self._next_id += 1
        row = self._insert_index_for(KIND_GROUP)
        self.beginInsertRows(QModelIndex(), row, row)
        self.jobs.insert(row, job)
        self.endInsertRows()
        self.summary_changed.emit()
        return job

    def update_group(
        self,
        gid: int,
        state: Optional[str] = None,
        detail: Optional[str] = None,
        progress: Optional[float] = None,
        results: Optional[List[str]] = None,
    ) -> None:
        for row, job in enumerate(self.jobs):
            if job.kind == KIND_GROUP and job.group_id == gid:
                if state is not None:
                    job.state = state
                if detail is not None:
                    job.group_detail = detail
                if progress is not None:
                    job.group_progress = progress
                if results is not None:
                    job.results = list(results)
                self._emit_row(row)
                self.summary_changed.emit()
                return

    def set_paused(self, paused: bool) -> None:
        self.paused = bool(paused)
        self.summary_changed.emit()
        if not self.paused:
            self._schedule()

    def cancel(self, job: Job) -> None:
        row = self._row_of(job.local_id)
        if row < 0:
            return
        if job.kind == KIND_GROUP and job.group_id is not None:
            for child in list(self.jobs):
                if child.group_id == job.group_id and child.kind != KIND_GROUP and not child.terminal:
                    self.cancel(child)
            job.state = STATE_CANCELLED
            job.group_detail = "Cancelled"
            job.ended_at = time.time()
            self._remove_row(job)
            self._schedule_journal()
            self._sync_timers()
            self.summary_changed.emit()
            return
        worker = self._workers.get(job.local_id)
        if worker is not None and hasattr(worker, "request_cancel"):
            worker.request_cancel()  # type: ignore[attr-defined]
            job.state = STATE_CANCELLED
            job.ended_at = time.time()
            self._purged[job.local_id] = job
            self._remove_row(job)
        elif job.state == STATE_QUEUED:
            job.state = STATE_CANCELLED
            job.ended_at = time.time()
            self._remove_row(job)
            self.job_finished.emit(job)
        else:
            return
        self._schedule_journal()
        self._sync_timers()
        self.summary_changed.emit()

    def _remove_row(self, job: Job) -> None:
        row = self._row_of(job.local_id)
        if row >= 0:
            self.beginRemoveRows(QModelIndex(), row, row)
            self.jobs.pop(row)
            self.endRemoveRows()

    def cancel_all(self) -> None:
        for job in list(self.jobs):
            if not job.terminal:
                self.cancel(job)

    def retry(self, job: Job) -> Optional[Job]:
        if job.kind == KIND_GROUP:
            return None
        if job.state == STATE_FAILED:
            job.state = STATE_QUEUED
            job.message = ""
            job.horde_id = ""
            job.retry_after = 0.0
            job.wait_time = None
            job.wait_initial = None
            job.queue_position = None
            job.finished = 0
            job.outage_attempts = 0
            job.outage_resubmits = 0
            job.started_at = None
            job.ended_at = None
            row = self._row_of(job.local_id)
            self._emit_row(row)
            self._flush_journal()
            self._sync_timers()
            self.summary_changed.emit()
            self._schedule()
            return job
        return self.enqueue(job.payload, job.meta, kind=job.kind, group_id=job.group_id)

    def remove(self, job: Job) -> None:
        if job.active:
            self.cancel(job)
        if job.kind == KIND_GROUP and job.group_id is not None:
            children = [j for j in self.jobs if j.group_id == job.group_id and j.kind != KIND_GROUP]
            for ch in children:
                self.remove(ch)
        self._remove_row(job)
        self._schedule_journal()
        self._sync_timers()
        self.summary_changed.emit()

    def move(self, job: Job, delta: int) -> None:
        row = self._row_of(job.local_id)
        if row < 0 or job.kind == KIND_GROUP:
            return
        target = row + delta
        if not (0 <= target < len(self.jobs)) or self.jobs[target].kind == KIND_GROUP:
            return
        self.beginResetModel()
        self.jobs[row], self.jobs[target] = self.jobs[target], self.jobs[row]
        self.endResetModel()
        self._schedule_journal()

    def clear_finished(self) -> None:
        keep = [j for j in self.jobs if not (j.terminal and j.kind != KIND_GROUP)]
        if len(keep) == len(self.jobs):
            return
        self.beginResetModel()
        self.jobs = keep
        self.endResetModel()
        self._sync_timers()
        self.summary_changed.emit()

    def counts(self) -> Dict[str, int]:
        c = {"queued": 0, "active": 0, "waiting": 0, "reconnecting": 0, "done": 0, "failed": 0, "upscales": 0}
        for j in self.jobs:
            if j.kind == KIND_GROUP:
                if j.active:
                    c["upscales"] += 1
                continue
            if j.state == STATE_QUEUED:
                c["queued"] += 1
            elif j.state == STATE_RECONNECTING:
                c["active"] += 1
                c["reconnecting"] += 1
            elif j.state == STATE_WAITING:
                c["active"] += 1
                c["waiting"] += 1
            elif j.active:
                c["active"] += 1
            elif j.state == STATE_DONE:
                c["done"] += 1
            elif j.state == STATE_FAILED:
                c["failed"] += 1
        return c

    def primary_live_job(self) -> Optional[Job]:
        """Return the highest-priority active/waiting/reconnecting job for live Viewer HUD."""
        for st in (STATE_RECONNECTING, STATE_PROCESSING, STATE_FETCHING, STATE_WAITING, STATE_SUBMITTING, STATE_QUEUED):
            for j in self.jobs:
                if j.kind != KIND_GROUP and j.state == st:
                    return j
        return None

    def eta(self) -> Optional[float]:
        waits = [float(j.wait_time) for j in self.jobs if j.active and j.wait_time is not None]
        return max(waits) if waits else None

    def overall_progress(self) -> float:
        live = [j for j in self.jobs if j.kind != KIND_GROUP and not j.terminal]
        if not live:
            return 0.0
        return sum(j.progress_fraction() for j in live) / len(live)

    def _schedule(self) -> None:
        if self.paused:
            return
        if not self.network_online:
            # Hold queued tasks safely while offline; _ConnectivityProbeWorker will
            # wake everything cleanly the instant connectivity returns.
            changed = False
            for row, j in enumerate(self.jobs):
                if j.kind != KIND_GROUP and j.state == STATE_QUEUED:
                    want = "Offline — queued task held safely, waiting for internet…"
                    if j.message != want:
                        j.message = want
                        self._emit_row(row)
                        changed = True
            if changed:
                self.summary_changed.emit()
            return
        now = time.time()
        while len(self._workers) < max(1, int(self.max_parallel)):
            cand = next(
                (j for j in self.jobs if j.kind != KIND_GROUP and j.state == STATE_QUEUED and j.retry_after <= now),
                None,
            )
            if cand is None:
                break
            cand.message = ""
            self._launch(cand)

    def _launch(self, job: Job) -> None:
        if job.kind == KIND_ALCH:
            worker: QThread = AlchemyJobWorker(self.api, self.store, job, self.poll_interval, self._wake_event, self)
        elif job.kind == KIND_DEPTH:
            worker = DepthMapWorker(self.api, job, self.poll_interval, self._wake_event, self)
        else:
            worker = JobWorker(self.api, self.store, job, self.poll_interval, self.save_direct, self._wake_event, self)
        worker.progress.connect(self._on_progress)  # type: ignore[attr-defined]
        worker.completed.connect(self._on_completed)  # type: ignore[attr-defined]
        worker.failed.connect(self._on_failed)  # type: ignore[attr-defined]
        if hasattr(worker, "network_state"):
            worker.network_state.connect(self._set_network_online)  # type: ignore[attr-defined]
        worker.finished.connect(lambda jid=job.local_id, w=worker: self._cleanup_worker(jid, w))
        self._workers[job.local_id] = worker
        job.state = STATE_SUBMITTING
        self._emit_row(self._row_of(job.local_id))
        self._schedule_journal()
        self._sync_timers()
        self.summary_changed.emit()
        worker.start()

    def _on_progress(self, jid: int, fields: Dict[str, Any]) -> None:
        row = self._row_of(jid)
        if row < 0:
            return
        job = self.jobs[row]
        hid_changed = "horde_id" in fields and fields.get("horde_id") != job.horde_id
        for k, v in fields.items():
            if hasattr(job, k):
                setattr(job, k, v)
        self._emit_row(row)
        if hid_changed:
            self._flush_journal()
        self.summary_changed.emit()

    def _on_completed(self, jid: int, paths: List[str], final_state: str) -> None:
        job: Optional[Job] = None
        row = self._row_of(jid)
        if row >= 0:
            job = self.jobs[row]
            job.state = final_state
            job.results = list(paths)
            job.ended_at = time.time()
            self._emit_row(row)
        else:
            job = self._purged.pop(jid, None)
            if job is None:
                return
            job.state = final_state
            job.results = list(paths)
            job.ended_at = time.time()
        self._schedule_journal()
        self._sync_timers()
        for p in paths:
            self.image_ready.emit(p, job.meta)
        self.job_finished.emit(job)
        self.summary_changed.emit()

    def _on_failed(self, jid: int, msg: str, retry_after: float) -> None:
        row = self._row_of(jid)
        if row < 0:
            purged = self._purged.pop(jid, None)
            if purged is not None:
                STUDIO_LOG.net("HORDE", f"Job #{jid} (cancelled) ended: {msg[:120]}")
            return
        job = self.jobs[row]
        if retry_after > 0:
            job.state = STATE_QUEUED
            job.retry_after = time.time() + retry_after
            job.message = f"Rate-limited, retrying in {int(retry_after)}s: {msg}"
            STUDIO_LOG.warn("HORDE", f"Job #{jid} backoff {int(retry_after)}s: {msg}")
        else:
            job.state = STATE_FAILED
            job.message = msg
            job.ended_at = time.time()
            STUDIO_LOG.error("HORDE", f"Job #{jid} failed: {msg}")
            self.job_finished.emit(job)
        self._schedule_journal()
        self._sync_timers()
        self._emit_row(row)
        self.summary_changed.emit()

    def _cleanup_worker(self, jid: int, worker: QThread) -> None:
        if self._workers.get(jid) is worker:
            self._workers.pop(jid, None)
        # Qt guarantees `finished` runs AFTER queued `completed`/`failed` signals
        # from the same worker thread. If the job is somehow still active here,
        # recover or fail it cleanly with zero race condition!
        row = self._row_of(jid)
        if row >= 0:
            job = self.jobs[row]
            if job.terminal:
                job.cleanup_journal_scratch()
            elif job.active and not getattr(worker, "settled", False):
                if job.watchdog_recoveries < MAX_WATCHDOG_RECOVERIES:
                    job.watchdog_recoveries += 1
                    job.state = STATE_QUEUED
                    job.retry_after = time.time() + 1.5
                    job.message = f"Recovered from unexpected worker exit — resuming ({job.watchdog_recoveries}/{MAX_WATCHDOG_RECOVERIES})"
                    STUDIO_LOG.warn("HORDE", f"Recovered unsettled job #{jid} on worker exit")
                    self._emit_row(row)
                else:
                    job.state = STATE_FAILED
                    job.ended_at = time.time()
                    job.message = "Worker exited unexpectedly without producing an image or error"
                    STUDIO_LOG.error("HORDE", f"Job #{jid} failed after repeated unsettled worker exits")
                    self._emit_row(row)
                    self.job_finished.emit(job)
                self._schedule_journal()
        worker.deleteLater()
        self._purged.pop(jid, None)
        self._sync_timers()
        self._schedule()

    def shutdown(self) -> None:
        # Persist unfinished jobs BEFORE suspending workers so they recover cleanly next run
        self._journal_timer.stop()
        self._flush_journal()
        self._retry_timer.stop()
        self._probe_timer.stop()
        self._wake_event.set()
        if self._probe_worker is not None and self._probe_worker.isRunning():
            self._probe_worker.wait(500)
        # v13 FIX: call request_suspend() (NOT request_cancel()!) so remote AI Horde
        # requests stay alive on the cluster and resume seamlessly from queue_journal.json!
        for w in list(self._workers.values()):
            if hasattr(w, "request_suspend"):
                w.request_suspend()  # type: ignore[attr-defined]
            elif hasattr(w, "request_cancel"):
                w.request_cancel()  # type: ignore[attr-defined]
            w.wait(1200)


# =============================================================================
#  15. High-Craft East-Asian Custom Widgets & Delegates (v10.0 Remaster)
# =============================================================================
def _zero_arg_slot(slot: Callable[..., Any]) -> Callable[..., Any]:
    """Guard against Qt's ``clicked(bool)`` pitfall.

    PyQt passes the button's ``checked`` flag to any slot that can take a positional
    argument. For closures written as ``lambda key=key: use(key)`` that flag silently
    replaces the captured value (``use(False)``). Lambdas whose parameters are all
    defaulted are therefore invoked without arguments; the ``_checked=False``
    placeholder idiom and every non-lambda callable are connected unchanged."""
    if getattr(slot, "__name__", "") != "<lambda>":
        return slot
    code = getattr(slot, "__code__", None)
    defaults = getattr(slot, "__defaults__", None) or ()
    if code is None or code.co_argcount == 0 or len(defaults) < code.co_argcount:
        return slot
    if defaults[0] is False or defaults[0] is None:
        return slot
    return lambda _checked=False, _slot=slot: _slot()


def make_button(
    text: str,
    slot: Optional[Callable[[], Any]] = None,
    small: bool = False,
    accent: bool = False,
    tip: str = "",
    icon_key: str = "",
    icon_size: int = 14,
    compress: bool = False,
    checkable: bool = False,
    checked: bool = False,
) -> QPushButton:
    b = QPushButton(text)
    if accent:
        b.setObjectName("Accent")
    elif small:
        b.setObjectName("Small")
    if checkable:
        b.setCheckable(True)
        if checked:
            b.setChecked(True)
    b.setCursor(Qt.CursorShape.PointingHandCursor)
    if compress:
        b.setMinimumWidth(0)
        b.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Fixed)
    if tip:
        b.setToolTip(tip)
    if icon_key:
        b.setIcon(VECTOR_ASSETS.icon(icon_key, icon_size))
        b.setIconSize(QSize(icon_size, icon_size))
    if slot is not None:
        b.clicked.connect(_zero_arg_slot(slot))
    return b


def _relayout_item_view(view: QAbstractItemView) -> None:
    """PyQt6-safe item view relayout (replaces non-public doItemsLayout)."""
    view.scheduleDelayedItemsLayout()
    vp = view.viewport()
    if vp is not None:
        vp.update()


def _bind_shortcut(
    seq: Any,
    parent: QWidget,
    slot: Callable[[], Any],
    context: Optional[Qt.ShortcutContext] = None,
) -> QShortcut:
    """Create and connect a QShortcut cleanly across all PyQt6 versions."""
    sc = QShortcut(seq if isinstance(seq, QKeySequence) else QKeySequence(seq), parent)
    if context is not None:
        sc.setContext(context)
    sc.activated.connect(slot)
    return sc


def make_label(text: str, name: str = "") -> QLabel:
    lb = QLabel(text)
    if name:
        lb.setObjectName(name)
    return lb


class ElideLabel(QLabel):
    def __init__(self, text: str = "", parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self._full = text
        self.setSizePolicy(QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Preferred)
        super().setText(text)

    def sizeHint(self) -> QSize:  # noqa: N802
        fm = QFontMetrics(self.font())
        m = self.contentsMargins()
        w = fm.horizontalAdvance(self._full) + m.left() + m.right() + 12
        h = fm.height() + m.top() + m.bottom() + 4
        return QSize(max(16, w), max(16, h))

    def minimumSizeHint(self) -> QSize:  # noqa: N802
        fm = QFontMetrics(self.font())
        return QSize(12, fm.height() + 2)

    def setText(self, text: str) -> None:  # noqa: N802
        self._full = text or ""
        self.updateGeometry()
        self._apply_elide()

    def full_text(self) -> str:
        return self._full

    def resizeEvent(self, event) -> None:  # noqa: N802
        super().resizeEvent(event)
        self._apply_elide()

    def _apply_elide(self) -> None:
        fm = QFontMetrics(self.font())
        m = self.contentsMargins()
        w = self.width()
        if w <= 2:
            super().setText(self._full)
            return
        avail = max(16, w - m.left() - m.right() - 4)
        super().setText(fm.elidedText(self._full, Qt.TextElideMode.ElideRight, avail))


class _ResettableSlider(QSlider):
    """Pro photography slider: double-clicking resets cleanly to default_value."""

    def __init__(
        self,
        orientation: Any = Qt.Orientation.Horizontal,
        default_value: int = 0,
        parent: Optional[QWidget] = None,
    ) -> None:
        if isinstance(orientation, int) and not isinstance(orientation, Qt.Orientation):
            default_value = int(orientation)
            orientation = Qt.Orientation.Horizontal
        super().__init__(orientation, parent)
        self._default_value = int(default_value)

    def mouseDoubleClickEvent(self, event) -> None:  # noqa: N802
        if event.button() == Qt.MouseButton.LeftButton:
            self.setValue(self._default_value)
            event.accept()
            return
        super().mouseDoubleClickEvent(event)


class BevelDeck(QFrame):
    """Sculpted, LRU-pixmap-cached command deck with unmistakable architecture across all 7 themes:
    - SeeStation: Sony PS4 sapphire OLED glass + XMB dual silk wave + cyan lightbar
    - Sarif Gold: Deus Ex: HR chamfered carbon plate + isometric facets + gold HUD brackets
    - Oriental Spirit: Kuro-Urushi neutral jet-black altar + vermilion Torii lintels + kintsugi gold hairline
    - Kreatendo: Nintendo Wii / Wii U / DS / 3DS LIGHT porcelain dome + Aqua/Mint rail + 4-dot ABXY strip
    - Mint Serenity: Linux Mint Cinnamon evergreen-charcoal bevel + botanical leaf vein + Mint-Leaf horizon
    """

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.setObjectName("Deck")

    def paintEvent(self, event) -> None:  # noqa: N802
        w, h = max(1, self.width()), max(1, self.height())
        key = resolve_theme_key(C.get("key", "seestation"))
        lp = low_power_mode()
        ck = (key, w, h, lp)
        pm = _BEVEL_DECK_CACHE.get(ck)
        if pm is not None:
            _BEVEL_DECK_CACHE.move_to_end(ck)
        else:
            pm = QPixmap(w, h)
            pm.fill(Qt.GlobalColor.transparent)
            p = QPainter(pm)
            p.setRenderHint(QPainter.RenderHint.Antialiasing, not lp)
            r = QRectF(0.5, 0.5, max(1.0, w - 1.0), max(1.0, h - 1.0))
            grad = QLinearGradient(r.left(), r.top(), r.left(), r.bottom())
            grad.setColorAt(0.0, QColor(C["deck_hi"]))
            grad.setColorAt(0.46, QColor(C["deck_mid"]))
            grad.setColorAt(1.0, QColor(C["deck_lo"]))
            frame_path = _theme_frame_path(r, key, rad_see=9.0, ch_gold=8.0)
            p.setBrush(QBrush(grad))
            p.setPen(QPen(QColor(C["line_hi"] if key in ("seestation", "kreatendo", "mint", "timeless", "prestige") else C["line"]), 1.05))
            p.drawPath(frame_path)

            p.save()
            p.setClipPath(frame_path)
            if key == "seestation":
                if not lp:
                    for dy, amp, al, lw in ((24.0, 14.0, 52, 1.7), (34.0, 10.0, 28, 1.1)):
                        wave = QPainterPath()
                        wave.moveTo(r.left() - 6, r.top() + dy)
                        wave.cubicTo(
                            r.left() + r.width() * 0.30, r.top() + dy - amp,
                            r.left() + r.width() * 0.68, r.top() + dy + amp,
                            r.right() + 6, r.top() + dy - amp * 0.4,
                        )
                        wc = QColor(C["acc_hi"]); wc.setAlpha(al)
                        p.setPen(QPen(wc, lw))
                        p.setBrush(Qt.BrushStyle.NoBrush)
                        p.drawPath(wave)
                rail = QLinearGradient(r.left(), r.top(), r.right(), r.top())
                a0 = QColor(C["acc_hi"]); a0.setAlpha(0)
                rail.setColorAt(0.0, a0)
                rail.setColorAt(0.22, QColor(C["acc_mid"]))
                rail.setColorAt(0.50, QColor(C["acc_spec"]))
                rail.setColorAt(0.78, QColor(C["acc_mid"]))
                rail.setColorAt(1.0, a0)
                p.setPen(QPen(QBrush(rail), 2.1))
                p.drawLine(QPointF(r.left() + 8, r.top() + 1.5), QPointF(r.right() - 8, r.top() + 1.5))
            elif key == "oriental":
                p.setPen(QPen(QColor(C["acc_hi"]), 2.2))
                p.drawLine(QPointF(r.left() + 1, r.top() + 1.2), QPointF(r.right() - 1, r.top() + 1.2))
                p.setPen(QPen(QColor(214, 168, 84, 72), 0.9))
                p.drawLine(QPointF(r.left() + 14, r.top() + 4.8), QPointF(r.right() - 14, r.top() + 4.8))
                if not lp:
                    slash = QLinearGradient(r.right() - 70, r.top(), r.right() - 18, r.bottom())
                    slash.setColorAt(0.0, QColor(245, 16, 10, 0))
                    slash.setColorAt(0.5, QColor(245, 16, 10, 36))
                    slash.setColorAt(1.0, QColor(245, 16, 10, 0))
                    p.setPen(QPen(QBrush(slash), 1.5))
                    p.drawLine(QPointF(r.right() - 62, r.top()), QPointF(r.right() - 22, r.bottom()))
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QBrush(QColor(C["acc_hi"])))
                p.drawPolygon(QPolygonF([QPointF(r.left() + 1, r.top() + 1), QPointF(r.left() + 13, r.top() + 1), QPointF(r.left() + 1, r.top() + 13)]))
                p.setBrush(QBrush(QColor(C["acc_mid"])))
                p.drawPolygon(QPolygonF([QPointF(r.right() - 1, r.bottom() - 1), QPointF(r.right() - 11, r.bottom() - 1), QPointF(r.right() - 1, r.bottom() - 11)]))
            elif key == "kreatendo":
                if not lp:
                    gloss = QLinearGradient(r.left(), r.top(), r.left(), r.top() + 26.0)
                    gloss.setColorAt(0.0, QColor(255, 255, 255, 220))
                    gloss.setColorAt(1.0, QColor(255, 255, 255, 0))
                    p.setPen(Qt.PenStyle.NoPen)
                    p.setBrush(gloss)
                    p.drawRect(QRectF(r.left(), r.top(), r.width(), 26.0))
                rail = QLinearGradient(r.left(), r.top(), r.right(), r.top())
                rail.setColorAt(0.0, QColor(0, 156, 224, 0))
                rail.setColorAt(0.18, QColor("#009ce0"))
                rail.setColorAt(0.50, QColor("#2ec6ff"))
                rail.setColorAt(0.78, QColor("#19b87a"))
                rail.setColorAt(1.0, QColor(25, 184, 122, 0))
                p.setPen(QPen(QBrush(rail), 2.4))
                p.drawLine(QPointF(r.left() + 10, r.top() + 1.5), QPointF(r.right() - 10, r.top() + 1.5))
                p.setPen(Qt.PenStyle.NoPen)
                for idx_d, dcol in enumerate(("#009ce0", "#e63b4b", "#f5a800", "#19b87a")):
                    p.setBrush(QColor(dcol))
                    p.drawEllipse(QPointF(r.right() - 28.0 + idx_d * 6.2, r.top() + 6.5), 1.9, 1.9)
            elif key == "mint":
                if not lp:
                    arc = QPainterPath()
                    arc.moveTo(r.left() - 4, r.top() + 28)
                    arc.cubicTo(
                        r.left() + r.width() * 0.36, r.top() + 9,
                        r.left() + r.width() * 0.72, r.top() + 24,
                        r.right() + 4, r.top() + 11,
                    )
                    p.setBrush(Qt.BrushStyle.NoBrush)
                    p.setPen(QPen(QColor(135, 207, 62, 38), 1.5))
                    p.drawPath(arc)
                rail = QLinearGradient(r.left(), r.top(), r.right(), r.top())
                rail.setColorAt(0.0, QColor(135, 207, 62, 0))
                rail.setColorAt(0.22, QColor("#87cf3e"))
                rail.setColorAt(0.52, QColor("#e6ffda"))
                rail.setColorAt(0.78, QColor("#4ec7b8"))
                rail.setColorAt(1.0, QColor(78, 199, 184, 0))
                p.setPen(QPen(QBrush(rail), 2.0))
                p.drawLine(QPointF(r.left() + 8, r.top() + 1.5), QPointF(r.right() - 8, r.top() + 1.5))
            elif key == "timeless":
                if not lp:
                    beam = QLinearGradient(r.left(), r.top(), r.left() + r.width() * 0.55, r.bottom())
                    beam.setColorAt(0.0, QColor(248, 229, 182, 30))
                    beam.setColorAt(0.55, QColor(220, 190, 134, 12))
                    beam.setColorAt(1.0, QColor(145, 193, 182, 0))
                    p.setPen(Qt.PenStyle.NoPen)
                    p.setBrush(beam)
                    p.drawPolygon(QPolygonF([
                        QPointF(r.left(), r.top()),
                        QPointF(r.left() + r.width() * 0.42, r.top()),
                        QPointF(r.left() + r.width() * 0.62, r.bottom()),
                        QPointF(r.left() + r.width() * 0.14, r.bottom()),
                    ]))
                    p.setBrush(Qt.BrushStyle.NoBrush)
                    p.setPen(QPen(QColor(145, 193, 182, 40), 0.9))
                    p.drawArc(QRectF(r.right() - 48.0, r.top() - 20.0, 56.0, 56.0), 180 * 16, 100 * 16)
                rail = QLinearGradient(r.left(), r.top(), r.right(), r.top())
                rail.setColorAt(0.0, QColor(228, 198, 133, 0))
                rail.setColorAt(0.22, QColor("#e4c685"))
                rail.setColorAt(0.52, QColor("#fcf2d7"))
                rail.setColorAt(0.78, QColor("#91c1b6"))
                rail.setColorAt(1.0, QColor(145, 193, 182, 0))
                p.setPen(QPen(QBrush(rail), 1.9))
                p.drawLine(QPointF(r.left() + 8, r.top() + 1.5), QPointF(r.right() - 8, r.top() + 1.5))
            elif key == "prestige":
                if not lp:
                    gloss = QLinearGradient(r.left(), r.top(), r.left(), r.top() + 28.0)
                    gloss.setColorAt(0.0, QColor(255, 255, 255, 172))
                    gloss.setColorAt(1.0, QColor(255, 255, 255, 0))
                    p.setPen(Qt.PenStyle.NoPen)
                    p.setBrush(gloss)
                    p.drawRect(QRectF(r.left(), r.top(), r.width(), 28.0))
                    # Classic late-2000s OS X subtle brushed-aluminum horizontal hairlines
                    p.setPen(QPen(QColor(255, 255, 255, 26), 1.0))
                    for py in range(int(r.top()) + 6, int(r.bottom()) - 4, 5):
                        p.drawLine(int(r.left()) + 6, py, int(r.right()) - 6, py)
                    # Signature miniature glass aqua status jewels on top-right hardware bezel
                    if r.width() >= 180:
                        for j_i, j_col in enumerate(("#e56761", "#e6b44c", "#50b868")):
                            jx = r.right() - 28.0 + j_i * 7.5
                            jy = r.top() + 6.5
                            p.setPen(QPen(QColor(110, 122, 140, 145), 0.7))
                            p.setBrush(QColor(j_col))
                            p.drawEllipse(QPointF(jx, jy), 2.15, 2.15)
                            p.setPen(Qt.PenStyle.NoPen)
                            p.setBrush(QColor(255, 255, 255, 165))
                            p.drawEllipse(QPointF(jx - 0.55, jy - 0.65), 0.75, 0.75)
                p.setPen(QPen(QColor(255, 255, 255, 222), 1.0))
                p.drawLine(QPointF(r.left() + 8, r.top() + 1.0), QPointF(r.right() - 8, r.top() + 1.0))
                rail = QLinearGradient(r.left(), r.top(), r.right(), r.top())
                rail.setColorAt(0.0, QColor(43, 124, 224, 0))
                rail.setColorAt(0.22, QColor("#2b7ce0"))
                rail.setColorAt(0.50, QColor("#82c2fc"))
                rail.setColorAt(0.78, QColor("#2b7ce0"))
                rail.setColorAt(1.0, QColor(43, 124, 224, 0))
                p.setPen(QPen(QBrush(rail), 2.0))
                p.drawLine(QPointF(r.left() + 10, r.top() + 2.4), QPointF(r.right() - 10, r.top() + 2.4))
            else:
                if not lp:
                    p.setPen(Qt.PenStyle.NoPen)
                    step = 24.0
                    for ci in range(0, int(r.width() // step) + 2):
                        if (ci * 5 + 1) % 3 == 0:
                            tx = r.left() + ci * step
                            p.setBrush(QColor(247, 194, 62, 14))
                            p.drawPolygon(QPolygonF([QPointF(tx, r.top()), QPointF(tx + step, r.top()), QPointF(tx + step * 0.5, r.top() + 20)]))
                p.setPen(QPen(QColor(C["acc_mid"]), 1.8))
                p.drawLine(QPointF(r.left() + 8, r.top() + 1.3), QPointF(r.right() - 8, r.top() + 1.3))
                p.setPen(QPen(QColor(C["acc_spec"]), 1.5))
                ch = 8.0
                p.drawLine(QPointF(r.left() + 1.5, r.top() + ch + 9), QPointF(r.left() + 1.5, r.top() + ch))
                p.drawLine(QPointF(r.left() + 1.5, r.top() + ch), QPointF(r.left() + ch, r.top() + 1.5))
                p.drawLine(QPointF(r.right() - 1.5, r.top() + ch + 9), QPointF(r.right() - 1.5, r.top() + ch))
                p.drawLine(QPointF(r.right() - 1.5, r.top() + ch), QPointF(r.right() - ch, r.top() + 1.5))
                p.drawLine(QPointF(r.right() - 1.5, r.bottom() - ch - 9), QPointF(r.right() - 1.5, r.bottom() - ch))
                p.drawLine(QPointF(r.right() - 1.5, r.bottom() - ch), QPointF(r.right() - ch, r.bottom() - 1.5))
            p.restore()
            p.setPen(QPen(QColor(C["sunken_bot"]), 1.0))
            p.drawLine(QPointF(r.left() + 6, r.bottom() - 1.5), QPointF(r.right() - 6, r.bottom() - 1.5))
            p.end()
            _BEVEL_DECK_CACHE[ck] = pm
            cap_dk = 4 if lp else _BEVEL_DECK_MAX
            while len(_BEVEL_DECK_CACHE) > cap_dk:
                _BEVEL_DECK_CACHE.popitem(last=False)
        out = QPainter(self)
        out.drawPixmap(0, 0, pm)
        out.end()


class SectionHeader(QWidget):
    """Crisp technical section header with distinctive per-theme emblem & rule across all 7 themes."""

    def __init__(self, title: str, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.setMinimumHeight(23)
        self._lay = QHBoxLayout(self)
        self._lay.setContentsMargins(0, 1, 2, 1)
        self._lay.setSpacing(5)
        self.title_label = ElideLabel("")
        self.title_label.setObjectName("Kicker")
        self.title_label.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Preferred)
        self.title_label.setFont(_font(9.0 * ui_scale(), True, 0.4))
        self.title_label.setText(title)
        self._lay.addSpacing(13)
        self._lay.addWidget(self.title_label, 1)

    def apply_scale(self, scale: float) -> None:
        s = max(SCALE_MIN, min(SCALE_MAX, float(scale)))
        self.title_label.setFont(_font(9.0 * s, True, 0.4))
        self.setMinimumHeight(max(20, int(round(23 * s))))
        self.update()

    def minimumSizeHint(self) -> QSize:  # noqa: N802
        return QSize(24, self.minimumHeight())

    def set_title(self, title: str) -> None:
        self.title_label.setText(title)

    def add_right(self, w: QWidget) -> None:
        self._lay.addWidget(w)

    def paintEvent(self, event) -> None:  # noqa: N802
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        cy = self.height() / 2.0
        key = resolve_theme_key(C.get("key", "seestation"))
        if key == "seestation":
            halo = QColor(C["hdr_dot"]); halo.setAlpha(72)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QBrush(halo))
            p.drawEllipse(QRectF(0.4, cy - 5.0, 10.0, 10.0))
            p.setBrush(QBrush(QColor(C["hdr_dot"])))
            p.drawEllipse(QRectF(2.2, cy - 3.2, 6.4, 6.4))
            p.setBrush(QColor(255, 255, 255, 190))
            p.drawEllipse(QRectF(3.6, cy - 2.2, 2.2, 2.2))
            rule = QLinearGradient(12.0, cy, self.width(), cy)
            rule.setColorAt(0.0, QColor(C["acc_hi"]))
            rule.setColorAt(0.55, QColor(C["hdr_line"]))
            fade = QColor(C["hdr_line"]); fade.setAlpha(0)
            rule.setColorAt(1.0, fade)
            p.setPen(QPen(QBrush(rule), 1.3))
            p.drawLine(QPointF(12.0, self.height() - 1.2), QPointF(self.width(), self.height() - 1.2))
        elif key == "oriental":
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QBrush(QColor(C["hdr_dot"])))
            p.drawPolygon(QPolygonF([
                QPointF(3.8, cy - 4.8), QPointF(9.2, cy - 4.8),
                QPointF(5.4, cy + 4.8), QPointF(0.0, cy + 4.8),
            ]))
            # Kintsugi gold micro-filigree highlight
            p.setPen(QPen(QColor(216, 169, 76, 185), 0.95))
            p.drawLine(QPointF(9.8, cy - 4.2), QPointF(6.8, cy + 4.2))
            p.setPen(QPen(QColor(C["acc_hi"]), 1.35))
            p.drawLine(QPointF(0.0, self.height() - 2.0), QPointF(self.width(), self.height() - 2.0))
            p.setPen(QPen(QColor(216, 169, 76, 115), 0.85))
            p.drawLine(QPointF(10.0, self.height() - 0.5), QPointF(self.width() - 6.0, self.height() - 0.5))
            p.setPen(QPen(QColor(C["acc_hi"]), 1.6))
            p.drawLine(QPointF(self.width() - 1.5, self.height() - 6.5), QPointF(self.width() - 1.5, self.height() - 1.5))
        elif key == "kreatendo":
            # Wii / 3DS glossy Aqua pill + Miiverse Mint pip + colorful Aqua->Mint->Gold->Coral rule
            p.setPen(QPen(QColor("#0073b8"), 0.9))
            p.setBrush(QColor("#009ce0"))
            p.drawRoundedRect(QRectF(1.0, cy - 4.2, 8.2, 8.2), 4.1, 4.1)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(255, 255, 255, 225))
            p.drawEllipse(QRectF(2.6, cy - 3.0, 2.4, 2.4))
            p.setBrush(QColor("#14b87a"))
            p.drawEllipse(QPointF(10.3, cy + 2.8), 1.5, 1.5)
            rule = QLinearGradient(12.0, cy, self.width(), cy)
            rule.setColorAt(0.0, QColor("#009ce0"))
            rule.setColorAt(0.38, QColor("#14b87a"))
            rule.setColorAt(0.68, QColor("#f5a800"))
            rule.setColorAt(0.88, QColor("#e63e4f"))
            rule.setColorAt(1.0, QColor(230, 62, 79, 0))
            p.setPen(QPen(QBrush(rule), 1.85))
            p.drawLine(QPointF(12.0, self.height() - 1.4), QPointF(self.width(), self.height() - 1.4))
        elif key == "mint":
            # Linux Mint Cinnamon leaf bud with central vein + Mint-Leaf to Alpine-Teal hairline
            leaf = QPainterPath()
            leaf.moveTo(1.2, cy + 4.1)
            leaf.quadTo(1.2, cy - 4.1, 9.8, cy - 4.1)
            leaf.quadTo(9.8, cy + 4.1, 1.2, cy + 4.1)
            p.setBrush(QColor(C["acc_hi"]))
            p.setPen(QPen(QColor(C["acc_spec"]), 0.75))
            p.drawPath(leaf)
            p.setPen(QPen(QColor("#0e2613"), 0.85))
            p.drawLine(QPointF(2.4, cy + 2.9), QPointF(8.3, cy - 2.9))
            rule = QLinearGradient(12.0, cy, self.width(), cy)
            rule.setColorAt(0.0, QColor(C["acc_hi"]))
            rule.setColorAt(0.52, QColor(C["info"]))
            rule.setColorAt(1.0, QColor(78, 199, 184, 0))
            p.setPen(QPen(QBrush(rule), 1.45))
            p.drawLine(QPointF(12.0, self.height() - 1.2), QPointF(self.width(), self.height() - 1.2))
        elif key == "timeless":
            # Timeless Feel: serene sunlit-ochre sanctuary diamond crest + celadon-mist fading hairline
            p.setBrush(QColor(C["acc_hi"]))
            p.setPen(QPen(QColor(C["acc_spec"]), 0.75))
            crest = QPolygonF([
                QPointF(5.2, cy - 4.4), QPointF(9.0, cy),
                QPointF(5.2, cy + 4.4), QPointF(1.4, cy),
            ])
            p.drawPolygon(crest)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(C["info"]))
            p.drawEllipse(QPointF(5.2, cy), 1.45, 1.45)
            rule = QLinearGradient(12.0, cy, self.width(), cy)
            rule.setColorAt(0.0, QColor(C["acc_hi"]))
            rule.setColorAt(0.54, QColor(C["info"]))
            rule.setColorAt(1.0, QColor(145, 193, 182, 0))
            p.setPen(QPen(QBrush(rule), 1.35))
            p.drawLine(QPointF(12.0, self.height() - 1.2), QPointF(self.width(), self.height() - 1.2))
        elif key == "prestige":
            # Prestige: glossy Aqua sapphire jewel pip + classic OS X twin engraved aluminum rule
            orb = QRadialGradient(4.6, cy - 1.4, 5.0)
            orb.setColorAt(0.0, QColor("#d9eeff"))
            orb.setColorAt(0.45, QColor("#4a98ef"))
            orb.setColorAt(1.0, QColor("#1856ad"))
            p.setBrush(orb)
            p.setPen(QPen(QColor("#144994"), 0.8))
            p.drawEllipse(QRectF(1.6, cy - 3.6, 7.2, 7.2))
            p.setPen(QPen(QColor("#929db0"), 1.0))
            p.drawLine(QPointF(12.0, self.height() - 2.0), QPointF(self.width() - 2.0, self.height() - 2.0))
            p.setPen(QPen(QColor(255, 255, 255, 200), 1.0))
            p.drawLine(QPointF(12.0, self.height() - 1.0), QPointF(self.width() - 2.0, self.height() - 1.0))
        else:
            poly = QPolygonF([
                QPointF(5.2, cy - 4.5), QPointF(9.6, cy),
                QPointF(5.2, cy + 4.5), QPointF(0.8, cy),
            ])
            p.setBrush(QBrush(QColor(C["hdr_dot"])))
            p.setPen(QPen(QColor(C["acc_spec"]), 0.9))
            p.drawPolygon(poly)
            p.setPen(QPen(QColor(C["acc_mid"]), 1.15))
            p.drawLine(QPointF(0.0, self.height() - 1.2), QPointF(self.width() - 6.0, self.height() - 1.2))
            p.setPen(QPen(QColor(C["acc_hi"]), 1.4))
            p.drawLine(QPointF(self.width() - 6.0, self.height() - 1.2), QPointF(self.width() - 1.2, self.height() - 5.2))
        p.end()


class CollapsibleSection(QWidget):
    toggled = pyqtSignal(bool)

    def __init__(self, title: str, body: QWidget, expanded: bool = False, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self._expanded = bool(expanded)
        self.body = body
        lay = QVBoxLayout(self)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(3)
        self.header = SectionHeader(title)
        self.header.setCursor(Qt.CursorShape.PointingHandCursor)
        self.header.setToolTip("Click header to expand / collapse this section")
        self.header.installEventFilter(self)
        self.toggle_btn = QToolButton()
        self.toggle_btn.setObjectName("Small")
        self.toggle_btn.setCheckable(True)
        self.toggle_btn.setChecked(self._expanded)
        self.toggle_btn.setFixedWidth(26)
        self.toggle_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        self.toggle_btn.setToolTip("Expand / collapse this section")
        self.toggle_btn.toggled.connect(self.set_expanded)
        self.header.add_right(self.toggle_btn)
        lay.addWidget(self.header)
        lay.addWidget(self.body)
        self._sync_ui()

    def eventFilter(self, obj: QObject, event: QEvent) -> bool:  # noqa: N802
        if obj is self.header and event.type() == QEvent.Type.MouseButtonRelease:
            if isinstance(event, QMouseEvent) and event.button() == Qt.MouseButton.LeftButton:
                child = self.header.childAt(event.position().toPoint())
                if not isinstance(child, QAbstractButton):
                    self.set_expanded(not self._expanded)
                    return True
        return super().eventFilter(obj, event)

    def is_expanded(self) -> bool:
        return self._expanded

    def set_expanded(self, on: bool) -> None:
        on = bool(on)
        if self._expanded == on and self.body.isVisible() == on:
            return
        self._expanded = on
        if self.toggle_btn.isChecked() != on:
            self.toggle_btn.blockSignals(True)
            self.toggle_btn.setChecked(on)
            self.toggle_btn.blockSignals(False)
        self._sync_ui()
        self.toggled.emit(on)

    def _sync_ui(self) -> None:
        self.body.setVisible(self._expanded)
        self.toggle_btn.setText("\u25BE" if self._expanded else "\u25B8")


class FolderChipButton(QAbstractButton):
    """Glossy bevelled folder chip button carrying its signature folder color stripe."""

    def __init__(
        self,
        label: str,
        color: str,
        icon_key: str = "",
        parent: Optional[QWidget] = None,
    ) -> None:
        super().__init__(parent)
        self.setText(label)
        self.folder_color = color
        self.icon_key = icon_key
        self.setCheckable(True)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setMinimumHeight(max(22, int(round(24 * ui_scale()))))
        self.setSizePolicy(QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Fixed)

    def sizeHint(self) -> QSize:  # noqa: N802
        s = ui_scale()
        fm = QFontMetrics(_font(8.1 * s, True))
        ico = int(round(14 * s)) if self.icon_key else 0
        w = fm.horizontalAdvance(self.text()) + (ico + 16 if self.icon_key else 15)
        h = max(21, int(round(24 * s)))
        return QSize(max(38, w), h)

    def minimumSizeHint(self) -> QSize:  # noqa: N802
        sh = self.sizeHint()
        return QSize(min(sh.width(), 44), sh.height())

    def paintEvent(self, event) -> None:  # noqa: N802
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        r = QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5)
        checked = self.isChecked()
        hovered = self.underMouse()
        grad = QLinearGradient(r.left(), r.top(), r.left(), r.bottom())
        if checked:
            grad.setColorAt(0.0, QColor(C["tab_on_hi"]))
            grad.setColorAt(1.0, QColor(C["tab_on_lo"]))
        elif hovered:
            grad.setColorAt(0.0, QColor(C["btn_hov_hi"]))
            grad.setColorAt(1.0, QColor(C["btn_hov_lo"]))
        else:
            grad.setColorAt(0.0, QColor(C["btn_hi"]))
            grad.setColorAt(1.0, QColor(C["btn_lo"]))
        tkey = resolve_theme_key(C.get("key", "seestation"))
        frame = _theme_frame_path(r, tkey, rad_see=6.5, ch_gold=3.5)
        p.setBrush(QBrush(grad))
        p.setPen(QPen(QColor(self.folder_color if checked else C["line_hi"]), 1.25 if checked else 0.9))
        p.drawPath(frame)
        p.save()
        p.setClipPath(frame)
        p.setBrush(QBrush(QColor(self.folder_color)))
        p.setPen(Qt.PenStyle.NoPen)
        if tkey == "seestation":
            bar_h = 2.4 if checked else 1.5
            p.drawRoundedRect(QRectF(r.left() + 6.0, r.bottom() - bar_h - 0.8, max(4.0, r.width() - 12.0), bar_h), 1.2, 1.2)
        elif tkey == "mint":
            bar_h = 2.5 if checked else 1.6
            mg = QLinearGradient(r.left() + 6.0, 0, r.right() - 6.0, 0)
            mg.setColorAt(0.0, QColor(self.folder_color))
            mg.setColorAt(0.65, QColor("#87cf3e"))
            mg.setColorAt(1.0, QColor("#4ec7b8"))
            p.setBrush(mg)
            p.drawRoundedRect(QRectF(r.left() + 6.0, r.bottom() - bar_h - 0.8, max(4.0, r.width() - 12.0), bar_h), 1.25, 1.25)
        elif tkey == "kreatendo":
            bar_h = 2.6 if checked else 1.6
            p.drawRoundedRect(QRectF(r.left() + 8.0, r.bottom() - bar_h - 0.8, max(4.0, r.width() - 16.0), bar_h), 1.3, 1.3)
            p.setBrush(QColor(255, 255, 255, 22))
            p.drawRect(QRectF(r.left(), r.top(), r.width(), r.height() * 0.44))
        elif tkey == "timeless":
            bar_h = 2.4 if checked else 1.5
            tg = QLinearGradient(r.left() + 5.0, 0, r.right() - 5.0, 0)
            tg.setColorAt(0.0, QColor(self.folder_color))
            tg.setColorAt(0.65, QColor("#e4c685"))
            tg.setColorAt(1.0, QColor("#91c1b6"))
            p.setBrush(tg)
            p.drawRoundedRect(QRectF(r.left() + 5.0, r.bottom() - bar_h - 0.8, max(4.0, r.width() - 10.0), bar_h), 1.2, 1.2)
            p.setBrush(QColor(252, 242, 215, 16))
            p.drawRect(QRectF(r.left(), r.top(), r.width(), r.height() * 0.38))
        elif tkey == "prestige":
            bar_h = 2.5 if checked else 1.6
            p.setBrush(QColor(255, 255, 255, 105 if not checked else 58))
            p.drawRect(QRectF(r.left(), r.top(), r.width(), r.height() * 0.45))
            p.setBrush(QColor(readable_accent_for_theme(self.folder_color, "prestige") if not checked else "#2b7ce0"))
            p.drawRoundedRect(QRectF(r.left() + 6.0, r.bottom() - bar_h - 0.8, max(4.0, r.width() - 12.0), bar_h), 1.2, 1.2)
        elif tkey == "oriental":
            p.drawRect(QRectF(r.left() + 0.5, r.top() + 0.5, 3.2 if checked else 2.0, r.height() - 1.0))
            if checked:
                p.drawPolygon(QPolygonF([QPointF(r.right(), r.top()), QPointF(r.right() - 6.0, r.top()), QPointF(r.right(), r.top() + 6.0)]))
        else:
            p.drawRect(QRectF(r.left() + 3.0, r.top() + 0.8, max(4.0, r.width() - 6.0), 2.5 if checked else 1.7))
        p.restore()
        s = ui_scale()
        tx = int(r.left() + (6 if tkey == "oriental" else 5))
        if self.icon_key:
            isz = max(12, min(18, int(round(13.5 * s))))
            pm = VECTOR_ASSETS.pixmap(self.icon_key, isz, isz)
            p.drawPixmap(tx, int((self.height() - isz) / 2), pm)
            tx += isz + 4
        p.setFont(_font(8.1 * s, True))
        p.setPen(QColor(C["text_hi"] if checked else C["text"]))
        text_rect = QRect(tx, 1, max(10, int(r.right()) - tx - 3), self.height() - 2)
        elided = QFontMetrics(p.font()).elidedText(self.text(), Qt.TextElideMode.ElideRight, text_rect.width())
        p.drawText(
            text_rect,
            Qt.AlignmentFlag.AlignCenter if not self.icon_key else (Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft),
            elided,
        )
        p.end()


class _HScrollWheelFilter(QObject):
    """Converts vertical wheel events into horizontal scrolling when attached."""

    def __init__(self, scroll: QScrollArea, parent: Optional[QObject] = None) -> None:
        super().__init__(parent or scroll)
        self._scroll = scroll

    def eventFilter(self, obj, event) -> bool:  # noqa: N802
        if event.type() == QEvent.Type.Wheel:
            dy = event.angleDelta().y()
            if dy:
                sb = self._scroll.horizontalScrollBar()
                sb.setValue(sb.value() - int(dy * 1.2))
                return True
        return super().eventFilter(obj, event)


class ThinProgressBar(QProgressBar):
    """6px illuminated lacquer channel showing overall queue progress."""

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.setFixedHeight(6)
        self.setTextVisible(False)
        self.setRange(0, 100)
        self.setValue(0)

    def sizeHint(self) -> QSize:  # noqa: N802
        return QSize(56, 6)

    def minimumSizeHint(self) -> QSize:  # noqa: N802
        return QSize(28, 6)


class Toast(QWidget):
    """Single glossy toast card in the corner notification stack."""

    clicked = pyqtSignal(object)

    def __init__(
        self,
        text: str,
        kind: str = "ok",
        payload: Any = None,
        parent: Optional[QWidget] = None,
    ) -> None:
        super().__init__(parent)
        self._text = text
        self._kind = kind
        self._payload = payload
        self._alpha = 1.0
        self._fading = False
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, False)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        s = ui_scale()
        self.setFont(_font(9.0 * s, True))
        fm = QFontMetrics(self.font())
        self._w = max(160, min(340, fm.horizontalAdvance(text) + 56))
        self._h = max(30, int(round(34 * s)))
        self.setFixedSize(self._w, self._h)

    def fade_out(self) -> None:
        self._fading = True

    @property
    def fading(self) -> bool:
        return self._fading

    @property
    def alpha(self) -> float:
        return self._alpha

    def set_alpha(self, a: float) -> None:
        self._alpha = max(0.0, min(1.0, a))
        self.setVisible(self._alpha > 0.02)
        self.update()

    def mousePressEvent(self, event) -> None:  # noqa: N802
        if event.button() == Qt.MouseButton.LeftButton:
            self.fade_out()
            self.clicked.emit(self._payload)
            event.accept()
            return
        super().mousePressEvent(event)

    def paintEvent(self, event) -> None:  # noqa: N802
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        p.setOpacity(self._alpha)
        r = QRectF(self.rect()).adjusted(1.0, 1.0, -1.0, -1.0)
        tkey = resolve_theme_key(C.get("key", "seestation"))
        frame = _theme_frame_path(r, tkey, rad_see=8.0, ch_gold=6.0)
        grad = QLinearGradient(r.left(), r.top(), r.left(), r.bottom())
        if tkey == "kreatendo":
            grad.setColorAt(0.0, QColor("#ffffff"))
            grad.setColorAt(1.0, QColor("#e3f3fe"))
        elif tkey == "prestige":
            grad.setColorAt(0.0, QColor("#f2f5fa"))
            grad.setColorAt(0.50, QColor("#e2e7f0"))
            grad.setColorAt(1.0, QColor("#cfd7e4"))
        else:
            grad.setColorAt(0.0, QColor(C["btn_hov_hi"]))
            grad.setColorAt(1.0, QColor(C["btn_lo"]))
        p.setBrush(QBrush(grad))
        p.setPen(QPen(QColor("#009ce0" if tkey == "kreatendo" else ("#2b7ce0" if tkey == "prestige" else (C["acc_hi"] if tkey == "seestation" else C["acc_mid"]))), 1.5 if tkey in ("kreatendo", "prestige") else 1.25))
        p.drawPath(frame)
        kind_col = {"ok": C["ok"], "err": C["err"], "warn": C["warn"], "info": C["info"]}.get(self._kind, C["info"])
        p.save()
        p.setClipPath(frame)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QBrush(QColor(kind_col)))
        if tkey == "seestation":
            p.drawRoundedRect(QRectF(r.left() + 3, r.top() + 5, 3.2, r.height() - 10), 1.6, 1.6)
        elif tkey == "mint":
            tg = QLinearGradient(0, r.top() + 4, 0, r.bottom() - 4)
            tg.setColorAt(0.0, QColor("#87cf3e"))
            tg.setColorAt(1.0, QColor("#4ec7b8"))
            p.setBrush(tg)
            p.drawRoundedRect(QRectF(r.left() + 3, r.top() + 4, 3.5, r.height() - 8), 1.75, 1.75)
        elif tkey == "kreatendo":
            p.drawRoundedRect(QRectF(r.left() + 3, r.top() + 5, 3.8, r.height() - 10), 1.9, 1.9)
            p.setBrush(QColor("#2ce0b5"))
            p.drawRoundedRect(QRectF(r.right() - 6.5, r.top() + 7, 2.8, r.height() - 14), 1.4, 1.4)
        elif tkey == "oriental":
            p.drawRect(QRectF(r.left(), r.top(), 4.0, r.height()))
            p.drawPolygon(QPolygonF([QPointF(r.right(), r.top()), QPointF(r.right() - 10, r.top()), QPointF(r.right(), r.top() + 10)]))
        else:
            p.drawRect(QRectF(r.left() + 2, r.top() + 6, 3.5, r.height() - 12))
        spec = QLinearGradient(r.left(), r.top(), r.left(), r.bottom())
        glass = QColor(C["svg_glass"]); glass.setAlpha(28 if tkey == "seestation" else 18)
        spec.setColorAt(0.0, glass)
        glass2 = QColor(C["svg_glass"]); glass2.setAlpha(0)
        spec.setColorAt(1.0, glass2)
        p.setBrush(QBrush(spec))
        p.drawRect(QRectF(r.left() + 1, r.top() + 1, r.width() - 2, r.height() * 0.46))
        p.restore()
        icon_key = {"ok": "check", "err": "cross", "warn": "warning", "info": "info"}.get(self._kind, "info")
        p.drawPixmap(10, int((self._h - 16) / 2), VECTOR_ASSETS.pixmap(icon_key, 16, 16))
        p.setFont(_font(9.0 * ui_scale(), True))
        p.setPen(QColor(C["text_hi"]))
        text_r = QRectF(r.left() + 32, r.top(), r.width() - 36, r.height())
        p.drawText(text_r, Qt.AlignmentFlag.AlignVCenter, QFontMetrics(p.font()).elidedText(
            self._text, Qt.TextElideMode.ElideRight, int(text_r.width())))
        p.end()


class ToastOverlay(QObject):
    """Zero-overhead corner toast stack manager (max 3 visible, auto-fade, truly clickable).
    Parents toasts directly onto `host` so clicks reach Toast.clicked cleanly without a
    full-window mouse-blocking overlay, and repositions ONLY on add/dismiss/resize."""

    def __init__(self, host: QWidget) -> None:
        super().__init__(host)
        self._host = host
        self._toasts: List[Toast] = []
        self._births: Dict[int, float] = {}
        self._timer = QTimer(self)
        self._timer.setInterval(72)
        self._timer.timeout.connect(self._tick)
        host.installEventFilter(self)

    def eventFilter(self, obj: QObject, event: QEvent) -> bool:  # noqa: N802
        if obj is self._host and event.type() == QEvent.Type.Resize and self._toasts:
            self._reposition()
        return False

    def notify(self, text: str, kind: str = "ok", payload: Any = None, on_click: Optional[Callable[[Any], None]] = None) -> None:
        while len(self._toasts) >= 3:
            old = self._toasts.pop(0)
            self._births.pop(id(old), None)
            old.hide()
            old.deleteLater()
        toast = Toast(text, kind, payload, self._host)
        if on_click is not None:
            toast.clicked.connect(on_click)
        else:
            toast.clicked.connect(lambda _p: None)
        self._toasts.append(toast)
        self._births[id(toast)] = time.monotonic()
        toast.show()
        toast.raise_()
        self._reposition()
        if not self._timer.isActive():
            self._timer.start()

    def _reposition(self) -> None:
        host = self._host
        if host is None:
            return
        max_w = max(140, host.width() - 20)
        y = host.height() - 10
        for toast in reversed(self._toasts):
            tw = min(max(140, toast.width()), max_w)
            if tw != toast.width():
                toast.setFixedWidth(tw)
            y -= toast.height() + 6
            tx = max(8, host.width() - toast.width() - 10)
            toast.move(tx, max(8, y))
            toast.raise_()

    def _tick(self) -> None:
        now = time.monotonic()
        alive: List[Toast] = []
        removed = False
        for toast in self._toasts:
            tid_t = id(toast)
            if tid_t not in self._births:
                self._births[tid_t] = now
            age = now - self._births[tid_t]
            if age > 3.6 and not toast.fading:
                toast.fade_out()
            if toast.fading:
                toast.set_alpha(toast.alpha - 0.14)
            if toast.alpha > 0.02:
                alive.append(toast)
            else:
                self._births.pop(tid_t, None)
                toast.hide()
                toast.deleteLater()
                removed = True
        self._toasts = alive
        if not self._toasts:
            self._timer.stop()
        elif removed:
            self._reposition()


# =============================================================================
#  16. Corporate East-Asian GENERATE Ignition Button (v10.0 Zero-Glitch Engine)
#      - Single monotonic animation driver (~30 FPS ONLY during transitions;
#        strictly 0% CPU when idle, hidden, minimized, or unfocused).
#      - Smooth cubic ease-in-out beveled specular shimmer with sinusoidal
#        edge fade-in/out and 1.8s hover cooldown (eliminates rapid-repeat bug).
#      - Fully distinct Sony/SCE SeeStation, Sarif Gold, and Oriental Spirit
#        (pure neutral black + exact pure red) craftsmanship.
# =============================================================================
class IgnitionGenerateButton(QPushButton):
    """Flagship East-Asian 'ENGAGE / SORTIE' style Generate CTA button."""

    _SHEEN_DURATION = 0.88      # seconds for one smooth specular glide
    _IDLE_CADENCE_MS = 10500    # low-CPU calm ambient shimmer cadence when active
    _HOVER_COOLDOWN = 2.00      # minimum seconds between hover sheen triggers
    _GLOW_DURATION = 0.20       # smooth hover corona fade time

    def __init__(self, text: str = "GENERATE", parent: Optional[QWidget] = None) -> None:
        super().__init__(text, parent)
        self._ui_scale: float = 1.0
        self._compact_mode: bool = False
        self._sub_text: str = "KREA 2  \u2022  \u00d71  \u2022  1024\u00d71024"
        self._active_badge: str = ""
        self._in_flight: int = 0

        # Smooth monotonic animation state (single driver timer, ZERO timer leaks!)
        self._hovered: bool = False
        self._hover_glow: float = 0.0
        self._glow_start_val: float = 0.0
        self._glow_target: float = 0.0
        self._glow_t0: float = 0.0
        self._glow_animating: bool = False

        self._sheen_active: bool = False
        self._sheen_t0: float = 0.0
        self._sheen_progress: float = -1.0   # 0.0..1.0 while sweeping, <0 at rest
        self._last_sheen_trigger: float = 0.0

        self.setMinimumHeight(46)
        self.setMaximumHeight(52)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
        self.setCursor(Qt.CursorShape.PointingHandCursor)

        # Single lightweight frame driver: ONLY runs while sheen or hover glow is moving
        self._anim_timer = QTimer(self)
        self._anim_timer.setInterval(40)  # ~25 FPS capped for low-end laptops, zero CPU when stopped
        self._anim_timer.timeout.connect(self._tick_animation)

        # Single calm idle ambient shimmer timer
        self._idle_timer = QTimer(self)
        self._idle_timer.setInterval(self._IDLE_CADENCE_MS)
        self._idle_timer.timeout.connect(self._on_idle_cadence)
        if not low_power_mode():
            self._idle_timer.start()

    def sync_low_power(self) -> None:
        if low_power_mode():
            self._idle_timer.stop()
            self._sheen_active = False
            self._sheen_progress = -1.0
        elif self.isVisible() and not self._idle_timer.isActive():
            self._idle_timer.start()

    def hideEvent(self, event) -> None:  # noqa: N802
        self._anim_timer.stop()
        self._idle_timer.stop()
        self._sheen_active = False
        self._sheen_progress = -1.0
        self._glow_animating = False
        super().hideEvent(event)

    def showEvent(self, event) -> None:  # noqa: N802
        super().showEvent(event)
        if not low_power_mode() and not self._idle_timer.isActive():
            self._idle_timer.start()

    def apply_metrics(self, scale: float, compact: bool = False) -> None:
        """Update button height & font metrics cleanly WITHOUT touching live state or timers."""
        self._ui_scale = max(SCALE_MIN, min(SCALE_MAX, float(scale)))
        self._compact_mode = bool(compact)
        base_h = 36 if self._compact_mode else 46
        h = max(33, min(70, int(round(base_h * self._ui_scale))))
        if self.minimumHeight() != h or self.maximumHeight() != h:
            self.setMinimumHeight(h)
            self.setMaximumHeight(h)
        self.update()

    def stop_animations(self) -> None:
        """Stop all timers immediately (called on hide/shutdown)."""
        self._anim_timer.stop()
        self._idle_timer.stop()
        self._sheen_active = False
        self._sheen_progress = -1.0
        self._glow_animating = False

    def set_sub_info(self, sub_text: str, active_badge: str = "") -> None:
        if sub_text != self._sub_text or active_badge != self._active_badge:
            self._sub_text = sub_text
            self._active_badge = active_badge
            self.update()

    def set_in_flight(self, count: int) -> None:
        count = max(0, int(count))
        if count != self._in_flight:
            self._in_flight = count
            self.update()

    def _can_animate(self) -> bool:
        if not self.isVisible() or not self.isEnabled():
            return False
        win = self.window()
        if win is not None and (win.isMinimized() or not win.isActiveWindow()):
            return False
        return True

    def _on_idle_cadence(self) -> None:
        if self._sheen_active or self.isDown() or not self._can_animate():
            return
        now = time.monotonic()
        if now - self._last_sheen_trigger < self._HOVER_COOLDOWN:
            return
        self._start_sheen(now)

    def _start_sheen(self, now: Optional[float] = None) -> None:
        ts = time.monotonic() if now is None else now
        self._sheen_active = True
        self._sheen_t0 = ts
        self._sheen_progress = 0.0
        self._last_sheen_trigger = ts
        if not self._anim_timer.isActive():
            self._anim_timer.start()

    def _start_glow(self, target: float) -> None:
        self._glow_start_val = self._hover_glow
        self._glow_target = max(0.0, min(1.0, float(target)))
        self._glow_t0 = time.monotonic()
        self._glow_animating = abs(self._glow_target - self._glow_start_val) > 0.005
        if self._glow_animating and not self._anim_timer.isActive():
            self._anim_timer.start()

    def _tick_animation(self) -> None:
        if not self.isVisible():
            self._sheen_active = False
            self._sheen_progress = -1.0
            self._glow_animating = False
            self._anim_timer.stop()
            return
        now = time.monotonic()
        still_running = False

        if self._sheen_active:
            u = (now - self._sheen_t0) / self._SHEEN_DURATION
            if u >= 1.0:
                self._sheen_active = False
                self._sheen_progress = -1.0
            else:
                # Smoothstep cubic ease-in-out: serene acceleration & deceleration
                self._sheen_progress = max(0.0, min(1.0, u))
                still_running = True

        if self._glow_animating:
            g_u = (now - self._glow_t0) / self._GLOW_DURATION
            if g_u >= 1.0:
                self._hover_glow = self._glow_target
                self._glow_animating = False
            else:
                eased = 1.0 - (1.0 - g_u) * (1.0 - g_u)
                self._hover_glow = self._glow_start_val + (self._glow_target - self._glow_start_val) * eased
                still_running = True

        self.update()
        if not still_running:
            self._anim_timer.stop()

    # Low-power-aware showEvent / hideEvent are defined once above.

    def enterEvent(self, event) -> None:  # noqa: N802
        self._hovered = True
        self._start_glow(1.0)
        now = time.monotonic()
        if not self._sheen_active and (now - self._last_sheen_trigger) >= self._HOVER_COOLDOWN and self._can_animate():
            self._start_sheen(now)
        super().enterEvent(event)

    def leaveEvent(self, event) -> None:  # noqa: N802
        self._hovered = False
        self._start_glow(0.0)
        super().leaveEvent(event)

    def mousePressEvent(self, event) -> None:  # noqa: N802
        self.update()
        super().mousePressEvent(event)

    def mouseReleaseEvent(self, event) -> None:  # noqa: N802
        self.update()
        super().mouseReleaseEvent(event)

    def paintEvent(self, event) -> None:  # noqa: N802
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)

        pressed = self.isDown()
        enabled = self.isEnabled()
        r = QRectF(self.rect()).adjusted(1.5, 1.5, -1.5, -1.5)
        if pressed:
            r.translate(0.0, 1.0)

        tkey = resolve_theme_key(C.get("key", "seestation"))
        bezel_path = QPainterPath()
        if tkey == "seestation":
            ch = 8.5
            bezel_path.addRoundedRect(r, 8.5, 8.5)
        elif tkey == "kreatendo":
            ch = 11.5
            bezel_path.addRoundedRect(r, 11.5, 11.5)
        elif tkey == "mint":
            ch = 7.5
            bezel_path.addRoundedRect(r, 7.5, 7.5)
        elif tkey == "timeless":
            ch = 6.5
            bezel_path.addRoundedRect(r, 6.5, 6.5)
        elif tkey == "prestige":
            ch = 9.5
            bezel_path.addRoundedRect(r, 9.5, 9.5)
        elif tkey == "oriental":
            ch = 0.0
            bezel_path.addRect(r)
        else:
            ch = 7.0
            bezel_path = _chamfer_path(r, ch)

        # 1. Restrained hover corona glow (zero jitter, smooth ease-out)
        if enabled and self._hover_glow > 0.02 and not pressed:
            glow_outer = QColor(C["acc_glow"])
            glow_outer.setAlpha(int(36 * self._hover_glow))
            p.setPen(QPen(glow_outer, 4.4))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPath(bezel_path)
            glow_inner = QColor(C["acc_glow"])
            glow_inner.setAlpha(int(84 * self._hover_glow))
            p.setPen(QPen(glow_inner, 1.8))
            p.drawPath(bezel_path)

        # 2. Multi-stop luminous lacquer body fill
        grad = QLinearGradient(r.left(), r.top(), r.left(), r.bottom())
        if not enabled:
            grad.setColorAt(0.0, QColor(C["btn_mid"]))
            grad.setColorAt(1.0, QColor(C["btn_lo"]))
        elif pressed:
            grad.setColorAt(0.0, QColor(C["acc_deep"]))
            grad.setColorAt(0.45, QColor(C["acc_lo"]))
            grad.setColorAt(1.0, QColor(C["acc_mid"]))
        elif self._hover_glow > 0.05:
            # Smoothly blend hover brightness
            grad.setColorAt(0.0, QColor(C["acc_hov_hi"]))
            grad.setColorAt(0.44, QColor(C["acc_hov_mid"]))
            grad.setColorAt(0.54, QColor(C["acc_mid"]))
            grad.setColorAt(1.0, QColor(C["acc_lo"]))
        else:
            grad.setColorAt(0.0, QColor(C["acc_hi"]))
            grad.setColorAt(0.46, QColor(C["acc_mid"]))
            grad.setColorAt(0.54, QColor(C["acc_lo"]))
            grad.setColorAt(1.0, QColor(C["acc_deep"]))

        border_col = QColor(C["acc_edge"] if (self._hovered and enabled) else C["acc_edge_lo"])
        p.setBrush(QBrush(grad))
        p.setPen(QPen(border_col, 1.35))
        p.drawPath(bezel_path)

        # Clip internal specular, watermark, and sheen layers strictly inside bezel
        p.save()
        p.setClipPath(bezel_path)

        # 3. Sculpted upper lacquer glass reflection band
        if not pressed and enabled:
            spec_rect = QRectF(r.left() + 1.0, r.top() + 1.0, r.width() - 2.0, r.height() * 0.45)
            sg = QLinearGradient(spec_rect.left(), spec_rect.top(), spec_rect.left(), spec_rect.bottom())
            sg.setColorAt(0.0, QColor(255, 255, 255, int(92 + 34 * self._hover_glow)))
            sg.setColorAt(0.68, QColor(255, 255, 255, 18))
            sg.setColorAt(1.0, QColor(255, 255, 255, 0))
            p.setBrush(QBrush(sg))
            p.setPen(Qt.PenStyle.NoPen)
            p.drawRect(spec_rect)

        # 4. Subtle lower ambient bounce light
        bounce_rect = QRectF(r.left(), r.bottom() - 9.0, r.width(), 9.0)
        bg = QLinearGradient(0, bounce_rect.top(), 0, bounce_rect.bottom())
        bcol0 = QColor(C["acc_spec"]); bcol0.setAlpha(0)
        bcol1 = QColor(C["acc_spec"]); bcol1.setAlpha(int(48 + 38 * self._hover_glow))
        bg.setColorAt(0.0, bcol0)
        bg.setColorAt(1.0, bcol1)
        p.setBrush(QBrush(bg))
        p.setPen(Qt.PenStyle.NoPen)
        p.drawRect(bounce_rect)

        # 5. Theme-specific architectural craftsmanship inside plate
        if tkey == "seestation":
            wpath = QPainterPath()
            wpath.moveTo(r.left() - 6, r.bottom() - 7)
            wpath.cubicTo(
                r.left() + r.width() * 0.34, r.top() + 10,
                r.left() + r.width() * 0.68, r.bottom() - 4,
                r.right() + 6, r.top() + 13,
            )
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.setPen(QPen(QColor(220, 245, 255, int(34 + 22 * self._hover_glow)), 1.5))
            p.drawPath(wpath)
        elif tkey == "oriental":
            # Oriental Spirit: crisp pure jet-black lacquer left/right torii pillar edges
            # & warm-neutral ivory-red specular accents (G >= B, ZERO purple/pink cast!)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(0, 0, 0, 210))
            p.drawRect(QRectF(r.left(), r.top(), 4.0, r.height()))
            p.drawRect(QRectF(r.right() - 4.0, r.top(), 4.0, r.height()))
            p.setBrush(QColor(255, 232, 224, int(52 + 30 * self._hover_glow)))
            p.drawPolygon(QPolygonF([QPointF(r.left() + 4, r.top()), QPointF(r.left() + 16, r.top()), QPointF(r.left() + 4, r.top() + 12)]))
            p.drawPolygon(QPolygonF([QPointF(r.right() - 4, r.bottom()), QPointF(r.right() - 16, r.bottom()), QPointF(r.right() - 4, r.bottom() - 12)]))
            p.setPen(QPen(QColor(255, 220, 212, 34), 1.0))
            p.drawLine(QPointF(r.right() - 42, r.top()), QPointF(r.right() - 22, r.bottom()))
        elif tkey == "kreatendo":
            # Nintendo Wii / Wii U glossy curved channel dome arc
            dome = QPainterPath()
            dome.moveTo(r.left() - 4, r.top() + r.height() * 0.56)
            dome.quadTo(r.center().x(), r.top() + r.height() * 0.24, r.right() + 4, r.top() + r.height() * 0.54)
            dome.lineTo(r.right() + 4, r.top())
            dome.lineTo(r.left() - 4, r.top())
            dome.closeSubpath()
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(232, 251, 255, int(30 + 22 * self._hover_glow)))
            p.drawPath(dome)
        elif tkey == "mint":
            # Linux Mint subtle botanical vein satin sheen (clean, no gold cross-hatch!)
            vein = QPainterPath()
            vein.moveTo(r.left() + 8, r.bottom() - 5)
            vein.quadTo(r.center().x(), r.top() + 9, r.right() - 10, r.top() + 11)
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.setPen(QPen(QColor(232, 255, 236, int(36 + 24 * self._hover_glow)), 1.35))
            p.drawPath(vein)
        elif tkey == "timeless":
            # Timeless Feel: soft skylight ray wash + refined concentric geometric hairline arcs
            ray = QLinearGradient(r.left(), r.top(), r.left() + r.width() * 0.65, r.bottom())
            ray.setColorAt(0.0, QColor(255, 246, 222, int(42 + 24 * self._hover_glow)))
            ray.setColorAt(1.0, QColor(255, 246, 222, 0))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(ray)
            p.drawPolygon(QPolygonF([
                QPointF(r.left() + 6, r.top()),
                QPointF(r.left() + r.width() * 0.45, r.top()),
                QPointF(r.left() + r.width() * 0.28, r.bottom()),
                QPointF(r.left() - 6, r.bottom()),
            ]))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.setPen(QPen(QColor(255, 245, 218, int(44 + 26 * self._hover_glow)), 1.0))
            p.drawEllipse(QPointF(r.right() - 18.0, r.center().y()), r.height() * 0.52, r.height() * 0.52)
            p.setPen(QPen(QColor(145, 193, 182, int(54 + 28 * self._hover_glow)), 0.9))
            p.drawEllipse(QPointF(r.right() - 18.0, r.center().y()), r.height() * 0.34, r.height() * 0.34)
        elif tkey == "prestige":
            # Prestige: iconic late-2000s OS X / iOS curved Aqua liquid-glass meniscus dome
            dome = QPainterPath()
            dome.moveTo(r.left() - 4, r.top() + r.height() * 0.50)
            dome.quadTo(r.center().x(), r.top() + r.height() * 0.36, r.right() + 4, r.top() + r.height() * 0.50)
            dome.lineTo(r.right() + 4, r.top())
            dome.lineTo(r.left() - 4, r.top())
            dome.closeSubpath()
            mg = QLinearGradient(r.left(), r.top(), r.left(), r.top() + r.height() * 0.52)
            mg.setColorAt(0.0, QColor(255, 255, 255, int(138 + 30 * self._hover_glow)))
            mg.setColorAt(1.0, QColor(255, 255, 255, 26))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(mg)
            p.drawPath(dome)
        else:
            # Sarif Gold: subtle isometric chamfer micro-facets
            p.setPen(QPen(QColor(255, 242, 180, 26), 0.7))
            step_g = 18.0
            gx = r.left()
            while gx < r.right() + r.height():
                p.drawLine(QPointF(gx, r.top()), QPointF(gx - r.height() * 0.55, r.bottom()))
                gx += step_g

        # 6. Harmonious Monotonic Dual-Layer Specular Sheen (eased position + sinusoidal alpha!)
        if enabled and not pressed and 0.0 <= self._sheen_progress <= 1.0:
            u = self._sheen_progress
            eased = u * u * (3.0 - 2.0 * u)
            env = math.sin(math.pi * u)  # 0 at both ends -> smooth fade-in & fade-out
            span_w = r.width() + 90.0
            sx = r.left() - 45.0 + span_w * eased
            slant = r.height() * 0.42
            # Wide soft ambient glide
            wide_half = 30.0
            sh_wide = QLinearGradient(sx - wide_half, r.top(), sx + wide_half, r.top())
            a_wide = int(68 * env)
            sh_wide.setColorAt(0.0, QColor(255, 255, 255, 0))
            sh_wide.setColorAt(0.5, QColor(255, 255, 255, a_wide))
            sh_wide.setColorAt(1.0, QColor(255, 255, 255, 0))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QBrush(sh_wide))
            p.drawPolygon(QPolygonF([
                QPointF(sx - wide_half + slant * 0.5, r.top()),
                QPointF(sx + wide_half + slant * 0.5, r.top()),
                QPointF(sx + wide_half - slant * 0.5, r.bottom()),
                QPointF(sx - wide_half - slant * 0.5, r.bottom()),
            ]))
            # Crisp narrow specular blade edge
            thin_half = 8.0
            sh_thin = QLinearGradient(sx - thin_half, r.top(), sx + thin_half, r.top())
            a_thin = int(96 * env)
            sh_thin.setColorAt(0.0, QColor(255, 255, 255, 0))
            sh_thin.setColorAt(0.5, QColor(255, 255, 255, a_thin))
            sh_thin.setColorAt(1.0, QColor(255, 255, 255, 0))
            p.setBrush(QBrush(sh_thin))
            p.drawPolygon(QPolygonF([
                QPointF(sx - thin_half + slant * 0.5, r.top()),
                QPointF(sx + thin_half + slant * 0.5, r.top()),
                QPointF(sx + thin_half - slant * 0.5, r.bottom()),
                QPointF(sx - thin_half - slant * 0.5, r.bottom()),
            ]))

        # 7. Top catch-light hairline
        p.setPen(QPen(QColor(255, 255, 255, int(112 + 54 * self._hover_glow)), 1.0))
        p.drawLine(QPointF(r.left() + max(2.0, ch), r.top() + 1.2), QPointF(r.right() - max(2.0, ch), r.top() + 1.2))
        p.restore()

        # 8. Signature outer trim accents across all 7 themes
        if tkey == "seestation":
            p.setPen(QPen(QColor(C["acc_spec"]), 1.5))
            uw = min(52.0, r.width() * 0.22)
            p.drawLine(QPointF(r.left() + 10, r.bottom() - 3.2), QPointF(r.left() + 10 + uw, r.bottom() - 3.2))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor("#b8ebff"))
            p.drawEllipse(QPointF(r.left() + 15 + uw, r.bottom() - 3.2), 1.6, 1.6)
        elif tkey == "kreatendo":
            # Nintendo Wii/Wii U Aqua + Mint rail & colorful ABXY micro-dots
            p.setPen(QPen(QColor("#b8f3ff"), 1.7))
            uw = min(58.0, r.width() * 0.26)
            p.drawLine(QPointF(r.left() + 12, r.bottom() - 3.0), QPointF(r.left() + 12 + uw, r.bottom() - 3.0))
            p.setPen(QPen(QColor("#2ce0b5"), 1.7))
            p.drawLine(QPointF(r.right() - 12 - uw * 0.55, r.bottom() - 3.0), QPointF(r.right() - 12, r.bottom() - 3.0))
            p.setPen(Qt.PenStyle.NoPen)
            for idx_c, col_hex in enumerate(("#ffffff", "#5ef2b6", "#ffe066", "#ff8a96")):
                p.setBrush(QColor(col_hex))
                p.drawEllipse(QPointF(r.left() + 18 + uw + idx_c * 5.2, r.bottom() - 3.0), 1.5, 1.5)
        elif tkey == "mint":
            # Linux Mint leaf-green to alpine-teal organic bottom glow + dewdrop pip
            mg = QLinearGradient(r.left() + 10, 0, r.left() + 74, 0)
            mg.setColorAt(0.0, QColor("#e8ffe0"))
            mg.setColorAt(1.0, QColor("#4ec7b8"))
            p.setPen(QPen(QBrush(mg), 1.7))
            uw = min(64.0, r.width() * 0.28)
            p.drawLine(QPointF(r.left() + 10, r.bottom() - 3.0), QPointF(r.left() + 10 + uw, r.bottom() - 3.0))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor("#92f2dd"))
            p.drawEllipse(QPointF(r.left() + 16 + uw, r.bottom() - 3.0), 1.6, 1.6)
        elif tkey == "timeless":
            # Timeless Feel: warm ivory-ochre to celadon-mist bottom hairline + subtle diamond pip
            tg = QLinearGradient(r.left() + 10, 0, r.left() + 82, 0)
            tg.setColorAt(0.0, QColor("#fcf2d7"))
            tg.setColorAt(1.0, QColor("#91c1b6"))
            p.setPen(QPen(QBrush(tg), 1.6))
            uw = min(66.0, r.width() * 0.28)
            p.drawLine(QPointF(r.left() + 10, r.bottom() - 3.0), QPointF(r.left() + 10 + uw, r.bottom() - 3.0))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor("#fcf2d7"))
            dx_p, dy_p = r.left() + 16 + uw, r.bottom() - 3.0
            p.drawPolygon(QPolygonF([
                QPointF(dx_p, dy_p - 2.1), QPointF(dx_p + 2.1, dy_p),
                QPointF(dx_p, dy_p + 2.1), QPointF(dx_p - 2.1, dy_p),
            ]))
        elif tkey == "prestige":
            # Prestige: crisp frosted-white inner bevel + Aqua lower glass reflection
            ag = QLinearGradient(r.left() + 14, 0, r.right() - 14, 0)
            ag.setColorAt(0.0, QColor(186, 224, 255, 0))
            ag.setColorAt(0.5, QColor(204, 234, 255, 220))
            ag.setColorAt(1.0, QColor(186, 224, 255, 0))
            p.setPen(QPen(QBrush(ag), 1.6))
            p.drawLine(QPointF(r.left() + 14, r.bottom() - 2.6), QPointF(r.right() - 14, r.bottom() - 2.6))
        elif tkey == "oriental":
            p.setPen(QPen(QColor(C["acc_spec"]), 1.3))
            p.drawLine(QPointF(r.left() + 4.5, r.top() + 1.2), QPointF(r.right() - 4.5, r.top() + 1.2))
            # Whisper-fine Kintsugi gold inner torii edge accents
            p.setPen(QPen(QColor(218, 172, 82, 170), 0.95))
            p.drawLine(QPointF(r.left() + 4.5, r.top() + 3.0), QPointF(r.left() + 4.5, r.bottom() - 3.0))
            p.drawLine(QPointF(r.right() - 4.5, r.top() + 3.0), QPointF(r.right() - 4.5, r.bottom() - 3.0))
        else:
            p.setPen(QPen(QColor(C["acc_spec"]), 1.5))
            p.drawLine(QPointF(r.left() + 2, r.top() + ch + 5), QPointF(r.left() + 2, r.top() + ch))
            p.drawLine(QPointF(r.left() + 2, r.top() + ch), QPointF(r.left() + ch, r.top() + 2))
            p.drawLine(QPointF(r.right() - 2, r.bottom() - ch - 5), QPointF(r.right() - 2, r.bottom() - ch))
            p.drawLine(QPointF(r.right() - 2, r.bottom() - ch), QPointF(r.right() - ch, r.bottom() - 2))
            p.setPen(QPen(QColor(255, 232, 140, 155), 1.0))
            p.drawLine(QPointF(r.right() - ch - 12, r.top() + 2.2), QPointF(r.right() - ch - 2, r.top() + 2.2))

        # 9. Ignition Vector Emblem (switches to live animated vector asset when jobs are in flight!)
        bh = max(34.0, r.height())
        icon_sz = max(20, min(30, int(round(bh * 0.56))))
        if self._in_flight > 0:
            pm = ANIM_ASSETS.pixmap("anim_waiting", ANIM_CLOCK.frame, icon_sz, tkey)
        else:
            pm = VECTOR_ASSETS.pixmap("generate_core", icon_sz, icon_sz)
        icon_x = int(r.left() + (11 if tkey == "oriental" else 9))
        icon_y = int(r.center().y() - icon_sz / 2)
        p.drawPixmap(icon_x, icon_y, pm)

        txt_left = icon_x + icon_sz + 8
        badge_w = 0
        if self._in_flight > 0:
            badge_txt = f"{self._in_flight} LIVE" if r.width() < 280 else f"{self._in_flight} ACTIVE"
            p.setFont(_font(7.2 * self._ui_scale, True, 0.5))
            fm_b = QFontMetrics(p.font())
            badge_w = fm_b.horizontalAdvance(badge_txt) + 14
            bx = int(r.right() - badge_w - (9 if tkey == "oriental" else 7))
            by = int(r.center().y() - 8)
            badge_r = QRectF(bx, by, badge_w, 16)
            p.setBrush(QColor(0, 0, 0, 195))
            p.setPen(QPen(QColor(C["acc_spec"]), 1.0))
            p.drawPath(_theme_frame_path(badge_r, tkey, rad_see=4.5, ch_gold=3.0))
            p.setPen(QColor(C["acc_spec"]))
            p.drawText(badge_r, Qt.AlignmentFlag.AlignCenter, badge_txt)
        elif r.width() >= 250:
            hint_txt = "CTRL+\u21B5"
            p.setFont(_font(max(6.2, 6.7 * self._ui_scale), True, 0.35))
            fm_h = QFontMetrics(p.font())
            badge_w = fm_h.horizontalAdvance(hint_txt) + 10
            badge_h = max(14, min(18, fm_h.height() + 3))
            bx = int(r.right() - badge_w - (9 if tkey == "oriental" else 7))
            by = int(r.center().y() - badge_h / 2.0)
            badge_r = QRectF(bx, by, badge_w, badge_h)
            if tkey in ("kreatendo", "prestige"):
                p.setBrush(QColor(246, 250, 255, 222))
                p.setPen(QPen(QColor("#1a5eb8" if tkey == "prestige" else "#0073b8"), 1.0))
                p.drawPath(_theme_frame_path(badge_r, tkey, rad_see=6.0, ch_gold=2.5))
                p.setPen(QColor("#144994" if tkey == "prestige" else "#00558f"))
            else:
                p.setBrush(QColor(0, 0, 0, 160 if tkey in ("gold", "mint") else 112))
                p.setPen(QPen(QColor(C["acc_spec"] if tkey in ("gold", "mint") else "#ffffff"), 0.85))
                p.drawPath(_theme_frame_path(badge_r, tkey, rad_see=4.0, ch_gold=2.5))
                p.setPen(QColor(C["acc_spec"] if tkey in ("gold", "mint") else "#ffffff"))
            p.drawText(badge_r, Qt.AlignmentFlag.AlignCenter, hint_txt)

        right_pad = 9 + (badge_w + 6 if badge_w > 0 else 0)
        txt_w = max(24, int(r.right() - txt_left - right_pad))

        # Exact font-metrics vertical layout so Title + Subtext NEVER collide or clip at any height/scale
        avail_h = max(24.0, r.height() - 5.0)
        title_pt = max(8.6, min(13.2, (9.8 if self._compact_mode else 11.2) * self._ui_scale))
        sub_pt = max(6.4, min(9.2, (6.9 if self._compact_mode else 7.4) * self._ui_scale))
        title_font = _font(title_pt, True, 1.4)
        sub_font = _font(sub_pt, True, 0.35)
        fm_t = QFontMetrics(title_font)
        fm_s = QFontMetrics(sub_font)
        need_h = fm_t.height() + fm_s.height()
        if need_h > avail_h:
            shrink = max(0.76, avail_h / max(1.0, float(need_h)))
            title_font = _font(max(8.0, title_pt * shrink), True, 1.1)
            sub_font = _font(max(6.0, sub_pt * shrink), True, 0.2)
            fm_t = QFontMetrics(title_font)
            fm_s = QFontMetrics(sub_font)
        th = fm_t.height()
        sh = fm_s.height()
        gap = 1 if (th + sh + 1 <= avail_h) else -1
        block_h = th + gap + sh
        top_y = int(round(r.center().y() - block_h / 2.0))
        title_rect = QRect(txt_left, top_y, txt_w, th)
        sub_rect = QRect(txt_left, top_y + th + gap, txt_w, sh)

        p.setFont(title_font)
        if tkey in ("oriental", "kreatendo", "prestige"):
            shadow_col = QColor(0, 0, 0, 165 if tkey == "prestige" else 175)
        elif tkey == "seestation":
            shadow_col = QColor(3, 10, 22, 165)
        elif tkey == "mint":
            shadow_col = QColor(227, 255, 237, 90)
        else:
            shadow_col = QColor(255, 246, 200, 95)
        title_el = fm_t.elidedText(self.text().upper(), Qt.TextElideMode.ElideRight, title_rect.width())
        p.setPen(shadow_col)
        p.drawText(title_rect.translated(0, 1), Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter, title_el)
        p.setPen(QColor(C["acc_text"] if enabled else C["dim"]))
        p.drawText(title_rect, Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter, title_el)

        p.setFont(sub_font)
        sub_col = QColor(C["acc_text"] if enabled else C["dim"])
        sub_col.setAlpha(225)
        p.setPen(sub_col)
        sub_txt = self._active_badge if self._active_badge else self._sub_text
        sub_el = fm_s.elidedText(sub_txt, Qt.TextElideMode.ElideRight, sub_rect.width())
        p.drawText(sub_rect, Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter, sub_el)
        p.end()


# =============================================================================
#  17. Unique Prompt Editor: Ctrl+Hold Tag Block Selection & Drag-and-Drop
# =============================================================================
class TagFlowPromptEdit(QPlainTextEdit):
    """Enhanced prompt / negative editor with Ctrl+Hold Tag-Element Drag-and-Drop:
    - Hold Ctrl to work with comma- and sentence-period-separated elements as
      discrete tactile blocks (single words, weighted tags, or full sentences).
    - Ctrl+Click toggles/selects individual tags; Ctrl+Shift+Click selects a
      range; dragging inside a normal text selection lifts all intersecting tags.
    - Dragging renders a floating translucent ghost badge and snaps a glowing
      insertion beacon between elements. Drop reorders atomically in one undo step.
    - Also accepts drag-and-drop from Tags tab and LoRA trigger chips, and offers
      a pro right-click tag context menu.
    - v3.1 GHOST ZONE: the trailing LoRA trigger words live in a read-only,
      greyed-out "ghost" tail of the document. They are rendered dim/italic,
      cannot be edited, selected, deleted or dragged, and are excluded from
      toPlainText() — the app appends them to the real payload automatically.
    """

    tags_reordered = pyqtSignal()
    save_as_tag_group_requested = pyqtSignal(str)
    external_drop_received = pyqtSignal(str, str, str)  # text, color, kind
    ghost_changed = pyqtSignal(str)                    # current ghost text

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.setMouseTracking(True)
        self.viewport().setMouseTracking(True)
        self.setAcceptDrops(True)
        self.setWordWrapMode(QTextOption.WrapMode.WrapAtWordBoundaryOrAnywhere)
        self._ctrl_mode = False
        self._elements: List[PromptElement] = []
        self._hover_idx: int = -1
        self._selected_indices: Set[int] = set()
        self._anchor_idx: int = -1
        self._dragging = False
        self._press_pos: Optional[QPoint] = None
        self._drag_pos: Optional[QPoint] = None
        self._drag_indices: List[int] = []
        self._drop_slot: int = -1
        self._flash_ranges: List[Tuple[int, int]] = []
        self._pending_toggle_idx: int = -1
        # ---- LoRA trigger ghost zone (read-only tail of the document) ----
        self._ghost_text: str = ""
        self._ghost_start: int = 0          # document position where the ghost begins
        self._ghost_updating: bool = False  # re-entrancy guard
        self._flash_timer = QTimer(self)
        self._flash_timer.setSingleShot(True)
        self._flash_timer.setInterval(480)
        self._flash_timer.timeout.connect(self._clear_flash)
        self.textChanged.connect(self._on_text_mutated)

    # ---- Ghost zone public API ---------------------------------------------
    def _full_text(self) -> str:
        """Raw document text INCLUDING the ghost zone."""
        return QPlainTextEdit.toPlainText(self)

    def _ghost_part(self) -> str:
        """Exact document tail occupied by the ghost (separator + text)."""
        if not self._ghost_text:
            return ""
        editable = self._full_text()[: self._ghost_start] if self._ghost_start >= 0 else ""
        sep = "\n" if editable else ""
        return sep + self._ghost_text

    def ghost_range(self) -> Tuple[int, int]:
        """(start, end) document positions of the ghost zone (end==start when none)."""
        if not self._ghost_text:
            return (self._ghost_start, self._ghost_start)
        part = self._ghost_part()
        return (self._ghost_start, self._ghost_start + len(part))

    def editable_end(self) -> int:
        """First document position owned by the ghost (== end of editable text)."""
        return self._ghost_start if self._ghost_text else len(self._full_text())

    def editable_text(self) -> str:
        return self._full_text()[: self.editable_end()]

    def user_text(self) -> str:
        """Compatibility alias for editable_text() (excludes read-only ghost text)."""
        return self.editable_text()

    def set_ghost(self, text: str) -> None:
        """Replace the read-only ghost tail (LoRA triggers) without touching the
        editable part, the caret or the span book."""
        new_ghost = " ".join(str(text or "").split())
        if new_ghost == self._ghost_text:
            return
        self._ghost_text = new_ghost
        self._apply_ghost()

    def _apply_ghost(self) -> None:
        self._ghost_updating = True
        try:
            editable = self._full_text()[: self._ghost_start] if (self._ghost_text and self._ghost_start >= 0) else self._full_text()
            if not self._ghost_text:
                editable = self._full_text()
            sep = "\n" if (editable and self._ghost_text) else ""
            full = editable + sep + self._ghost_text
            cur = self.textCursor()
            keep = min(cur.position(), len(editable))
            keep_anchor = min(cur.anchor(), len(editable))
            tc = QTextCursor(self.document())
            tc.beginEditBlock()
            tc.select(QTextCursor.SelectionType.Document)
            tc.insertText(full)
            tc.endEditBlock()
            if cur.hasSelection() and keep_anchor != keep:
                cur.setPosition(keep_anchor)
                cur.setPosition(keep, QTextCursor.MoveMode.KeepAnchor)
            else:
                cur.setPosition(keep)
            self.setTextCursor(cur)
            # ghost_start points at the START of the separator so the editable
            # value never contains the trailing newline.
            self._ghost_start = len(editable)
        finally:
            self._ghost_updating = False
        self.ghost_changed.emit(self._ghost_text)
        self.viewport().update()

    def set_editable_text(self, text: str) -> None:
        """Replace ONLY the editable part; the ghost tail is preserved."""
        self._ghost_updating = True
        try:
            cur = self.textCursor()
            keep = min(cur.position(), len(text))
            sep = "\n" if (text and self._ghost_text) else ""
            full = text + sep + self._ghost_text
            tc = QTextCursor(self.document())
            tc.beginEditBlock()
            tc.select(QTextCursor.SelectionType.Document)
            tc.insertText(full)
            tc.endEditBlock()
            cur.setPosition(keep)
            self.setTextCursor(cur)
            self._ghost_start = len(text)
        finally:
            self._ghost_updating = False
        self.ghost_changed.emit(self._ghost_text)

    # ---- Qt overrides: the ghost tail is invisible to callers & untouchable --
    def toPlainText(self) -> str:  # noqa: N802 - Python-side override
        """Editable text only — the ghost tail is NEVER part of the prompt value."""
        if self._ghost_text:
            return self._full_text()[: self._ghost_start]
        return self._full_text()

    def setPlainText(self, text: str) -> None:  # noqa: N802
        self.set_editable_text(text)

    def clear(self) -> None:  # noqa: N802
        self.set_editable_text("")

    def selectAll(self) -> None:  # noqa: N802
        tc = self.textCursor()
        tc.setPosition(0)
        tc.setPosition(self.editable_end(), QTextCursor.MoveMode.KeepAnchor)
        self.setTextCursor(tc)

    def insertFromMimeData(self, source) -> None:  # noqa: N802
        self._clamp_cursor()
        super().insertFromMimeData(source)

    def _clamp_cursor(self) -> None:
        """Keep the caret & selection out of the ghost zone."""
        if not self._ghost_text:
            return
        limit = self.editable_end()
        tc = self.textCursor()
        changed = False
        if tc.position() > limit or tc.anchor() > limit:
            changed = True
            if tc.hasSelection():
                a0 = min(tc.anchor(), tc.position())
                a1 = max(tc.anchor(), tc.position())
                n0 = min(a0, limit)
                n1 = min(a1, limit)
                if n1 > n0:
                    tc.setPosition(n0)
                    tc.setPosition(n1, QTextCursor.MoveMode.KeepAnchor)
                else:
                    tc.setPosition(limit)
            else:
                tc.setPosition(limit)
        if changed:
            self.setTextCursor(tc)

    def _on_text_mutated(self) -> None:
        # Ghost-zone integrity: typing at the editable/ghost boundary legitimately
        # shifts the ghost; real damage (should be impossible through the guarded
        # UI paths) triggers a full tail rebuild.
        if self._ghost_text and not self._ghost_updating:
            full = self._full_text()
            gt = self._ghost_text
            if full.endswith(gt):
                new_start = len(full) - len(gt)
                if new_start > 0 and full[new_start - 1] == "\n":
                    new_start -= 1
                self._ghost_start = max(0, new_start)
            else:
                self._ghost_updating = True
                try:
                    editable = full[: self._ghost_start]
                    sep = "\n" if editable else ""
                    tc = QTextCursor(self.document())
                    tc.beginEditBlock()
                    tc.select(QTextCursor.SelectionType.Document)
                    tc.insertText(editable + sep + gt)
                    tc.endEditBlock()
                    self._ghost_start = len(editable)
                finally:
                    self._ghost_updating = False
                self.ghost_changed.emit(gt)
        self._elements = parse_prompt_elements(self.toPlainText())
        if not self._dragging:
            self._selected_indices = {i for i in self._selected_indices if 0 <= i < len(self._elements)}
            if self._hover_idx >= len(self._elements):
                self._hover_idx = -1

    def _clear_flash(self) -> None:
        self._flash_ranges = []
        self.viewport().update()

    def _is_ctrl_held(self) -> bool:
        return bool(QApplication.keyboardModifiers() & Qt.KeyboardModifier.ControlModifier)

    def _sync_ctrl_mode(self, active: bool) -> None:
        if active == self._ctrl_mode:
            return
        self._ctrl_mode = active
        if active:
            self._elements = parse_prompt_elements(self.toPlainText())
            self._promote_text_selection_to_tags()
            self.viewport().setCursor(Qt.CursorShape.OpenHandCursor)
        else:
            if not self._dragging:
                self._hover_idx = -1
                self._drop_slot = -1
                self.viewport().setCursor(Qt.CursorShape.IBeamCursor)
        self.viewport().update()

    def _promote_text_selection_to_tags(self) -> None:
        """If the user highlighted a range of text covering one or more tags
        before pressing Ctrl, automatically select all intersecting tag blocks."""
        tc = self.textCursor()
        if not tc.hasSelection():
            return
        s0, s1 = tc.selectionStart(), tc.selectionEnd()
        found = {el.index for el in self._elements if not (el.end <= s0 or el.start >= s1)}
        if found:
            self._selected_indices = found
            self._anchor_idx = min(found)

    def _element_at_pos(self, pos: QPoint) -> int:
        if not self._elements:
            return -1
        cur = self.cursorForPosition(pos)
        cpos = cur.position()
        for el in self._elements:
            if el.start <= cpos <= el.end:
                return el.index
        # Soft tolerance: within 2 chars of an element boundary (e.g. clicking on comma/space)
        best_i, best_d = -1, 4
        for el in self._elements:
            d = min(abs(cpos - el.start), abs(cpos - el.end))
            if d < best_d:
                best_d = d
                best_i = el.index
        return best_i

    def _slot_at_pos(self, pos: QPoint) -> int:
        if not self._elements:
            return 0
        cur = self.cursorForPosition(pos)
        cpos = cur.position()
        for el in self._elements:
            mid = (el.start + el.end) / 2.0
            if cpos < mid:
                return el.index
        return len(self._elements)

    def _rects_for_range(self, start: int, end: int) -> List[QRect]:
        """Compute visual viewport rectangles for a character span (handles wrapping)."""
        doc_len = len(self._full_text())
        if start >= end or start < 0 or end > doc_len:
            return []
        rects: List[QRect] = []
        tc = self.textCursor()
        cur_p = start
        while cur_p < end:
            tc.setPosition(cur_p)
            r0 = self.cursorRect(tc)
            # Walk to end of current visual line or end of span
            line_end = cur_p + 1
            last_r = r0
            while line_end <= end:
                tc.setPosition(line_end)
                rn = self.cursorRect(tc)
                if abs(rn.top() - r0.top()) > 4:
                    break
                last_r = rn
                line_end += 1
            x1 = min(r0.left(), last_r.left())
            x2 = max(r0.right(), last_r.right())
            if x2 - x1 < 4:
                x2 = x1 + 6
            rects.append(QRect(x1 - 2, r0.top() - 1, (x2 - x1) + 4, r0.height() + 2))
            cur_p = line_end
            if line_end <= start:
                break
        return rects

    def adjust_tag_weight(self, delta: float) -> bool:
        """East-Asia SD/Anima power-user shortcut (Ctrl+Up / Ctrl+Down):
        nudge emphasis weight of the selected text or tag under caret."""
        tc = self.textCursor()
        limit = self.editable_end()
        if tc.hasSelection():
            s0 = min(tc.selectionStart(), tc.selectionEnd(), limit)
            s1 = min(max(tc.selectionStart(), tc.selectionEnd()), limit)
        else:
            self._elements = parse_prompt_elements(self.toPlainText())
            cpos = min(tc.position(), limit)
            el = next((e for e in self._elements if e.start <= cpos <= e.end), None)
            if el is None:
                return False
            s0, s1 = el.start, min(el.end, limit)
        if s1 <= s0:
            return False
        raw = self.toPlainText()[s0:s1].strip()
        if not raw:
            return False
        m = re.match(r"^\((.+):([0-9]+(?:\.[0-9]+)?)\)$", raw)
        if m:
            inner = m.group(1).strip()
            w = float(m.group(2)) + float(delta)
        else:
            inner = raw
            w = 1.0 + float(delta)
        w = max(0.10, min(2.50, round(w, 2)))
        new_tok = inner if abs(w - 1.0) < 0.005 else f"({inner}:{w:.2f}".rstrip("0").rstrip(".") + ")"
        tc.beginEditBlock()
        tc.setPosition(s0)
        tc.setPosition(s1, QTextCursor.MoveMode.KeepAnchor)
        tc.insertText(new_tok)
        tc.setPosition(s0)
        tc.setPosition(s0 + len(new_tok), QTextCursor.MoveMode.KeepAnchor)
        tc.endEditBlock()
        self.setTextCursor(tc)
        self._flash_ranges = [(s0, s0 + len(new_tok))]
        self._flash_timer.start()
        self.viewport().update()
        return True

    # ---- Keyboard events ----------------------------------------------------
    def keyPressEvent(self, event: QKeyEvent) -> None:  # noqa: N802
        if (event.modifiers() & Qt.KeyboardModifier.ControlModifier) and event.key() in (
            Qt.Key.Key_Up,
            Qt.Key.Key_Down,
        ):
            step = 0.05 if (event.modifiers() & Qt.KeyboardModifier.ShiftModifier) else 0.10
            if self.adjust_tag_weight(step if event.key() == Qt.Key.Key_Up else -step):
                event.accept()
                return
        if event.key() == Qt.Key.Key_Control:
            self._sync_ctrl_mode(True)
        elif event.key() == Qt.Key.Key_Escape and (self._dragging or self._selected_indices):
            self._cancel_drag()
            self._selected_indices.clear()
            self.viewport().update()
            event.accept()
            return
        elif self._ghost_text and event.key() in (
            Qt.Key.Key_Delete, Qt.Key.Key_Backspace,
            Qt.Key.Key_Return, Qt.Key.Key_Enter,
        ) and not self._ctrl_mode:
            # Swallow edits that would eat the locked ghost tail:
            #  - Delete/Backspace with a selection reaching into the ghost
            #  - newline typed while the caret sits inside the ghost
            tc = self.textCursor()
            limit = self.editable_end()
            if tc.hasSelection() and max(tc.anchor(), tc.position()) > limit:
                event.accept()
                return
            if tc.position() > limit and not tc.hasSelection():
                event.accept()
                return
            if event.key() == Qt.Key.Key_Delete and tc.position() == limit and not tc.hasSelection():
                event.accept()
                return
        if event.matches(QKeySequence.StandardKey.SelectAll):
            self.selectAll()
            event.accept()
            return
        self._clamp_cursor()
        super().keyPressEvent(event)
        # A typed character may land exactly at the boundary and is fine; but if
        # some path still moved the caret into the ghost, snap it back.
        if self._ghost_text:
            self._clamp_cursor()

    def keyReleaseEvent(self, event: QKeyEvent) -> None:  # noqa: N802
        if event.key() == Qt.Key.Key_Control and not self._dragging:
            self._sync_ctrl_mode(False)
        super().keyReleaseEvent(event)

    def leaveEvent(self, event) -> None:  # noqa: N802
        if not self._dragging:
            self._hover_idx = -1
            if not self._is_ctrl_held():
                self._sync_ctrl_mode(False)
            self.viewport().update()
        super().leaveEvent(event)

    # ---- Mouse events (Ctrl Tag-Element Selection & Drag-Reorder) -----------
    def mousePressEvent(self, event: QMouseEvent) -> None:  # noqa: N802
        if event.button() == Qt.MouseButton.LeftButton and self._is_ctrl_held():
            self._sync_ctrl_mode(True)
            self._elements = parse_prompt_elements(self.toPlainText())
            self._promote_text_selection_to_tags()
            pos = event.position().toPoint()
            idx = self._element_at_pos(pos)
            if idx >= 0:
                self._press_pos = pos
                self._drag_pos = pos
                if event.modifiers() & Qt.KeyboardModifier.ShiftModifier and self._anchor_idx >= 0:
                    lo, hi = min(self._anchor_idx, idx), max(self._anchor_idx, idx)
                    self._selected_indices.update(range(lo, hi + 1))
                elif idx in self._selected_indices:
                    # Keep multi-selection intact in case the user is initiating a group drag;
                    # if released without dragging, mouseReleaseEvent will toggle it off.
                    self._pending_toggle_idx = idx
                else:
                    self._pending_toggle_idx = -1
                    self._selected_indices.add(idx)
                    self._anchor_idx = idx
                self._drag_indices = sorted(self._selected_indices)
                self.viewport().update()
                event.accept()
                return
            else:
                self._selected_indices.clear()
                self._anchor_idx = -1
                self.viewport().update()
                event.accept()
                return
        # Normal editing clears tag-block selection
        if self._selected_indices and not self._is_ctrl_held():
            self._selected_indices.clear()
            self.viewport().update()
        super().mousePressEvent(event)
        if self._ghost_text and not self._ctrl_mode:
            # Clicks that land inside the ghost zone snap the caret back to the
            # end of the editable text.
            self._clamp_cursor()

    def mouseDoubleClickEvent(self, event) -> None:  # noqa: N802
        super().mouseDoubleClickEvent(event)
        if self._ghost_text:
            self._clamp_cursor()

    def mouseMoveEvent(self, event: QMouseEvent) -> None:  # noqa: N802
        pos = event.position().toPoint()
        ctrl = self._is_ctrl_held()
        if not self._dragging:
            self._sync_ctrl_mode(ctrl)
        if self._press_pos is not None and (event.buttons() & Qt.MouseButton.LeftButton):
            if not self._dragging and (pos - self._press_pos).manhattanLength() >= 6:
                self._dragging = True
                self._pending_toggle_idx = -1
                self.viewport().setCursor(Qt.CursorShape.ClosedHandCursor)
            if self._dragging:
                self._drag_pos = pos
                self._drop_slot = self._slot_at_pos(pos)
                self.viewport().update()
                event.accept()
                return
        if self._ctrl_mode:
            self._elements = parse_prompt_elements(self.toPlainText())
            new_h = self._element_at_pos(pos)
            if new_h != self._hover_idx:
                self._hover_idx = new_h
                self.viewport().update()
            self.viewport().setCursor(
                Qt.CursorShape.OpenHandCursor if new_h >= 0 else Qt.CursorShape.ArrowCursor
            )
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event: QMouseEvent) -> None:  # noqa: N802
        if event.button() == Qt.MouseButton.LeftButton and (self._dragging or self._press_pos is not None):
            was_dragging = self._dragging
            drop_slot = self._drop_slot
            drag_indices = list(self._drag_indices)
            pending_toggle = self._pending_toggle_idx
            self._cancel_drag()
            if was_dragging and drag_indices and drop_slot >= 0:
                self._commit_reorder(drag_indices, drop_slot)
            elif pending_toggle >= 0:
                self._selected_indices.discard(pending_toggle)
            if not self._is_ctrl_held():
                self._sync_ctrl_mode(False)
            self.viewport().update()
            event.accept()
            return
        super().mouseReleaseEvent(event)

    def _cancel_drag(self) -> None:
        self._dragging = False
        self._press_pos = None
        self._drag_pos = None
        self._drag_indices = []
        self._drop_slot = -1
        self._pending_toggle_idx = -1
        self.viewport().setCursor(
            Qt.CursorShape.OpenHandCursor if self._is_ctrl_held() else Qt.CursorShape.IBeamCursor
        )

    def _commit_reorder(self, indices: List[int], target_slot: int) -> None:
        old_text = self.toPlainText()
        new_text, new_sel, ranges = reorder_prompt_elements(old_text, indices, target_slot)
        if new_text == old_text:
            return
        self.set_editable_text(new_text)
        self._elements = parse_prompt_elements(new_text)
        self._selected_indices = set(new_sel)
        self._flash_ranges = ranges
        self._flash_timer.start()
        self.tags_reordered.emit()
        self.viewport().update()

    # ---- External Drag-and-Drop (Tags tab / LoRA triggers) ------------------
    def dragEnterEvent(self, event) -> None:  # noqa: N802
        md = event.mimeData()
        if md.hasFormat("application/x-hsl-snippet") or md.hasText():
            event.acceptProposedAction()
            return
        super().dragEnterEvent(event)

    def dragMoveEvent(self, event) -> None:  # noqa: N802
        md = event.mimeData()
        if md.hasFormat("application/x-hsl-snippet") or md.hasText():
            event.acceptProposedAction()
            return
        super().dragMoveEvent(event)

    def dropEvent(self, event) -> None:  # noqa: N802
        md = event.mimeData()
        if md.hasFormat("application/x-hsl-snippet"):
            try:
                raw = bytes(md.data("application/x-hsl-snippet")).decode("utf-8")
                doc = json.loads(raw)
                txt = str(doc.get("text") or "").strip()
                col = str(doc.get("color") or C["acc_hi"])
                kind = str(doc.get("kind") or "tag")
                if txt:
                    self.external_drop_received.emit(txt, col, kind)
                    event.acceptProposedAction()
                    return
            except Exception:  # noqa: BLE001
                pass
        super().dropEvent(event)

    # ---- Pro Tag Context Menu -----------------------------------------------
    def contextMenuEvent(self, event) -> None:  # noqa: N802
        self._elements = parse_prompt_elements(self.toPlainText())
        self._promote_text_selection_to_tags()
        self._clamp_cursor()  # the standard Cut/Delete actions must never touch the ghost
        pos = event.pos()
        hit = self._element_at_pos(pos)
        menu = self.createStandardContextMenu()
        if hit >= 0 or self._selected_indices:
            target_set = sorted(self._selected_indices) if (self._selected_indices and (hit < 0 or hit in self._selected_indices)) else [hit]
            target_set = [i for i in target_set if 0 <= i < len(self._elements)]
            if target_set:
                label = f"{len(target_set)} tags" if len(target_set) > 1 else f"'{elide(self._elements[target_set[0]].text, 24)}'"
                menu.addSeparator()
                tag_menu = menu.addMenu(f"Tag Element ({label})")
                tag_menu.addAction("Move to Start", lambda: self._commit_reorder(target_set, 0))
                tag_menu.addAction("Move Left", lambda: self._commit_reorder(target_set, max(0, min(target_set) - 1)))
                tag_menu.addAction("Move Right", lambda: self._commit_reorder(target_set, min(len(self._elements), max(target_set) + 2)))
                tag_menu.addAction("Move to End", lambda: self._commit_reorder(target_set, len(self._elements)))
                tag_menu.addSeparator()
                tag_menu.addAction("Weight \u00d71.2  (SDXL/standard)", lambda: self._wrap_weight(target_set, 1.2))
                tag_menu.addAction("Weight \u00d71.8  (Anima strong)", lambda: self._wrap_weight(target_set, 1.8))
                tag_menu.addAction("Unwrap Weight", lambda: self._unwrap_weight(target_set))
                tag_menu.addSeparator()
                tag_menu.addAction("Duplicate Tag(s)", lambda: self._duplicate_tags(target_set))
                tag_menu.addAction("Delete Tag(s)", lambda: self._delete_tags(target_set))
                combined = ", ".join(self._elements[i].text for i in target_set)
                tag_menu.addAction("Save as Tag Group\u2026", lambda: self.save_as_tag_group_requested.emit(combined))
        menu.exec(event.globalPos())

    def _replace_element_texts(self, mapper: Callable[[PromptElement], Optional[str]]) -> None:
        elems = parse_prompt_elements(self.toPlainText())
        pieces: List[str] = []
        out_elems: List[Tuple[str, str]] = []
        for el in elems:
            res = mapper(el)
            if res is not None and res.strip():
                out_elems.append((res.strip(), el.sep))
        for pos, (txt, sep) in enumerate(out_elems):
            pieces.append(txt)
            if pos < len(out_elems) - 1:
                pieces.append(f"{sep if sep in (',', '.') else ','} ")
            elif sep == ".":
                pieces.append(".")
        new_text = "".join(pieces)
        self.set_editable_text(new_text)
        self._selected_indices.clear()
        self.tags_reordered.emit()

    def _wrap_weight(self, indices: List[int], weight: float) -> None:
        iset = set(indices)

        def _fn(el: PromptElement) -> str:
            if el.index not in iset:
                return el.text
            core = re.sub(r"^\((.+):[0-9.]+\)$", r"\1", el.text.strip())
            return f"({core}:{weight:g})"

        self._replace_element_texts(_fn)

    def _unwrap_weight(self, indices: List[int]) -> None:
        iset = set(indices)

        def _fn(el: PromptElement) -> str:
            if el.index not in iset:
                return el.text
            return re.sub(r"^\((.+):[0-9.]+\)$", r"\1", el.text.strip())

        self._replace_element_texts(_fn)

    def _duplicate_tags(self, indices: List[int]) -> None:
        elems = parse_prompt_elements(self.toPlainText())
        iset = set(indices)
        out: List[Tuple[str, str]] = []
        for el in elems:
            out.append((el.text, el.sep))
            if el.index in iset:
                out.append((el.text, el.sep))
        pieces: List[str] = []
        for pos, (txt, sep) in enumerate(out):
            pieces.append(txt)
            if pos < len(out) - 1:
                pieces.append(f"{sep if sep in (',', '.') else ','} ")
            elif sep == ".":
                pieces.append(".")
        self.set_editable_text("".join(pieces))
        self.tags_reordered.emit()

    def _delete_tags(self, indices: List[int]) -> None:
        iset = set(indices)
        self._replace_element_texts(lambda el: None if el.index in iset else el.text)

    # ---- Paint overlays: Tag Pill Frames, Insertion Beacon, Drag Ghost & HUD
    def paintEvent(self, event) -> None:  # noqa: N802
        super().paintEvent(event)
        p = QPainter(self.viewport())
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)

        # Ghost-zone marker: a small dim "LORA TRIGGERS · AUTO" badge drawn in
        # the FREE SPACE below the last document line (never overlaps text; when
        # the editor is completely full the badge simply doesn't draw).
        if self._ghost_text:
            try:
                tc = QTextCursor(self.document())
                tc.movePosition(QTextCursor.MoveOperation.End)
                br = self.cursorRect(tc)
                free_below = self.viewport().height() - br.bottom()
                if free_below >= 18:
                    p.setFont(_font(7.4, True))
                    fm = QFontMetrics(p.font())
                    lbl = "\u25A3 LORA TRIGGERS \u00b7 AUTO"
                    lw = fm.horizontalAdvance(lbl) + 12
                    chip = QRectF(
                        max(2.0, self.viewport().width() - lw - 6),
                        float(br.bottom() + 3),
                        lw,
                        13,
                    )
                    bg = QColor(C["deep"])
                    bg.setAlpha(215)
                    p.setBrush(QBrush(bg))
                    p.setPen(QPen(QColor(C["ghost"]), 0.8))
                    p.drawRoundedRect(chip, 2.0, 2.0)
                    p.setPen(QColor(C["ghost"]))
                    p.drawText(chip, Qt.AlignmentFlag.AlignCenter, lbl)
            except Exception:  # noqa: BLE001 - decoration must never break painting
                pass

        if not (self._ctrl_mode or self._selected_indices or self._dragging or self._flash_ranges):
            p.end()
            return

        # Brief drop confirmation glow
        for s0, s1 in self._flash_ranges:
            col = QColor(C["acc_hi"])
            col.setAlpha(68)
            p.setBrush(QBrush(col))
            p.setPen(QPen(QColor(C["acc_spec"]), 1.2))
            for rc in self._rects_for_range(s0, s1):
                p.drawRoundedRect(QRectF(rc), 3.0, 3.0)

        # Hover & multi-selected tag pill outlines while Ctrl is held or selection active
        if self._ctrl_mode or self._selected_indices:
            sel_order = sorted(self._selected_indices)
            for el in self._elements:
                is_sel = el.index in self._selected_indices
                is_hov = self._ctrl_mode and el.index == self._hover_idx
                if not (is_sel or is_hov):
                    continue
                rects = self._rects_for_range(el.start, el.end)
                bg = QColor(C["tag_sel_bg"] if is_sel else C["tag_hover_bg"])
                bg.setAlpha(115 if is_sel else 85)
                pen_col = QColor(C["tag_sel_border"] if is_sel else C["tag_hover_border"])
                p.setBrush(QBrush(bg))
                p.setPen(QPen(pen_col, 1.4 if is_sel else 1.1))
                for rc in rects:
                    p.drawRoundedRect(QRectF(rc), 3.0, 3.0)
                # Numbered multi-select chip when selecting multiple tags
                if is_sel and len(sel_order) > 1 and rects:
                    ord_num = str(sel_order.index(el.index) + 1)
                    badge = QRectF(rects[0].left() - 2, rects[0].top() - 7, 13, 12)
                    p.setBrush(QBrush(QColor(C["acc_hi"])))
                    p.setPen(Qt.PenStyle.NoPen)
                    p.drawRoundedRect(badge, 2.0, 2.0)
                    p.setFont(_font(7.0, True))
                    p.setPen(QColor(C["acc_text"]))
                    p.drawText(badge, Qt.AlignmentFlag.AlignCenter, ord_num)

        # Live glowing insertion beacon while dragging
        if self._dragging and self._drop_slot >= 0 and self._elements:
            tc = self.textCursor()
            if self._drop_slot < len(self._elements):
                tc.setPosition(self._elements[self._drop_slot].start)
                br = self.cursorRect(tc)
                bx = float(br.left() - 2)
            else:
                tc.setPosition(self._elements[-1].end)
                br = self.cursorRect(tc)
                bx = float(br.right() + 2)
            by0, by1 = float(br.top() - 2), float(br.bottom() + 2)
            beacon = QColor(C["beacon"])
            p.setPen(QPen(beacon, 2.6))
            p.drawLine(QPointF(bx, by0), QPointF(bx, by1))
            p.setBrush(QBrush(beacon))
            p.setPen(Qt.PenStyle.NoPen)
            for cy in (by0, by1):
                p.drawPolygon(QPolygonF([
                    QPointF(bx, cy - 3.5),
                    QPointF(bx + 3.5, cy),
                    QPointF(bx, cy + 3.5),
                    QPointF(bx - 3.5, cy),
                ]))

        # Floating translucent drag ghost badge tracking cursor
        if self._dragging and self._drag_pos is not None and self._drag_indices:
            valid = [self._elements[i].text for i in self._drag_indices if 0 <= i < len(self._elements)]
            if valid:
                lbl = (
                    f"[{len(valid)} TAGS] {elide(', '.join(valid), 30)}"
                    if len(valid) > 1
                    else elide(valid[0], 34)
                )
                p.setFont(_font(8.5, True))
                fm = QFontMetrics(p.font())
                gw = fm.horizontalAdvance(lbl) + 18
                gh = 22
                gx = max(4, min(self.viewport().width() - gw - 4, self._drag_pos.x() + 12))
                gy = max(4, min(self.viewport().height() - gh - 4, self._drag_pos.y() - 26))
                gr = QRectF(gx, gy, gw, gh)
                ggrad = QLinearGradient(gr.left(), gr.top(), gr.left(), gr.bottom())
                ggrad.setColorAt(0.0, QColor(C["acc_hi"]))
                ggrad.setColorAt(1.0, QColor(C["acc_lo"]))
                p.setBrush(QBrush(ggrad))
                p.setPen(QPen(QColor(C["acc_spec"]), 1.2))
                p.drawRoundedRect(gr, 3.0, 3.0)
                p.setPen(QColor(C["acc_text"]))
                p.drawText(gr, Qt.AlignmentFlag.AlignCenter, lbl)

        # Compact bottom-right Ctrl-Tag-Mode status HUD chip
        if self._ctrl_mode:
            hud = (
                f"CTRL TAG MODE \u2022 {len(self._selected_indices)} selected \u2022 Drag to reorder"
                if self._selected_indices
                else "CTRL TAG MODE \u2022 Click=Select \u2022 Drag=Reorder"
            )
            p.setFont(_font(7.6, True))
            fm = QFontMetrics(p.font())
            hw = fm.horizontalAdvance(hud) + 14
            hh = 17
            hr = QRectF(
                max(4, self.viewport().width() - hw - 5),
                max(4, self.viewport().height() - hh - 4),
                hw,
                hh,
            )
            bg = QColor(C["deep"])
            bg.setAlpha(225)
            p.setBrush(QBrush(bg))
            p.setPen(QPen(QColor(C["acc_mid"]), 1.0))
            p.drawRoundedRect(hr, 2.5, 2.5)
            p.setPen(QColor(C["acc_hi"]))
            p.drawText(hr, Qt.AlignmentFlag.AlignCenter, hud)

        p.end()

# =============================================================================
#  17B. Corner-Resizable Prompt Input Container & Live Image Histogram Widget
# =============================================================================
class _CornerResizeGrip(QWidget):
    """Tactile bottom-right corner drag grip for smoothly resizing prompt forms
    (vertical height + optional 2D horizontal left-panel widening). Double-click
    restores the default height."""

    drag_started = pyqtSignal()
    drag_offset = pyqtSignal(int, int)   # total_dx, total_dy from drag start
    drag_delta = pyqtSignal(int, int)    # incremental dx, dy in global pixels
    drag_finished = pyqtSignal()
    reset_requested = pyqtSignal()

    def __init__(self, two_dim: bool = True, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self._two_dim = bool(two_dim)
        self._dragging = False
        self._hovered = False
        self._start_global = QPoint()
        self._last_global = QPoint()
        self.setMouseTracking(True)
        self.apply_scale(ui_scale())
        self.setCursor(
            Qt.CursorShape.SizeFDiagCursor if self._two_dim else Qt.CursorShape.SizeVerCursor
        )
        self.setToolTip(
            "Drag corner to resize prompt box (drag down to enlarge height, "
            "right/left to adjust panel width · double-click to reset height)"
            if self._two_dim
            else "Drag corner vertically to resize prompt box · double-click to reset height"
        )

    def apply_scale(self, scale: float) -> None:
        s = max(SCALE_MIN, min(SCALE_MAX, float(scale)))
        self.setFixedSize(max(24, int(round(26 * s))), max(19, int(round(21 * s))))
        self.update()

    def enterEvent(self, event) -> None:  # noqa: N802
        self._hovered = True
        self.update()
        super().enterEvent(event)

    def leaveEvent(self, event) -> None:  # noqa: N802
        self._hovered = False
        self.update()
        super().leaveEvent(event)

    def mousePressEvent(self, event: QMouseEvent) -> None:  # noqa: N802
        if event.button() == Qt.MouseButton.LeftButton:
            self._dragging = True
            self._start_global = event.globalPosition().toPoint()
            self._last_global = self._start_global
            self.drag_started.emit()
            self.update()
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event: QMouseEvent) -> None:  # noqa: N802
        if self._dragging:
            cur = event.globalPosition().toPoint()
            dx = cur.x() - self._last_global.x()
            dy = cur.y() - self._last_global.y()
            if dx != 0 or dy != 0:
                self._last_global = cur
                self.drag_offset.emit(cur.x() - self._start_global.x(), cur.y() - self._start_global.y())
                self.drag_delta.emit(dx, dy)
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event: QMouseEvent) -> None:  # noqa: N802
        if self._dragging and event.button() == Qt.MouseButton.LeftButton:
            self._dragging = False
            self.update()
            self.drag_finished.emit()
            event.accept()
            return
        super().mouseReleaseEvent(event)

    def mouseDoubleClickEvent(self, event: QMouseEvent) -> None:  # noqa: N802
        if event.button() == Qt.MouseButton.LeftButton:
            self.reset_requested.emit()
            event.accept()
            return
        super().mouseDoubleClickEvent(event)

    def paintEvent(self, event) -> None:  # noqa: N802
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        hot = self._dragging or self._hovered
        w, h = float(self.width()), float(self.height())
        tri = QPolygonF([QPointF(w - 1.0, 2.0), QPointF(w - 1.0, h - 1.0), QPointF(2.0, h - 1.0)])
        glow = QColor(C["acc_hi"])
        glow.setAlpha(86 if self._dragging else (48 if self._hovered else 18))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(glow)
        p.drawPolygon(tri)
        base_col = C["acc_mid"] if (hot and is_light_theme()) else (C["acc_hi"] if hot else C["muted"])
        col = QColor(base_col)
        col.setAlpha(255 if hot else 220)
        p.setPen(QPen(col, 2.0 if hot else 1.65, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
        step = max(3.8, min(5.0, h * 0.23))
        for k_i in (1, 2, 3):
            off = k_i * step + 1.2
            p.drawLine(QPointF(w - off, h - 2.2), QPointF(w - 2.2, h - off))
        p.end()


class ResizablePromptFrame(QFrame):
    """Framed prompt container with a tactile bottom-right corner resize grip (plus
    draggable bottom bar, Fit-to-Content & quick expand buttons) so users can
    effortlessly enlarge long prompts by dragging the corner without breaking 800x600
    scrollability or interfering with Ctrl+Drag tag reordering."""

    height_changed = pyqtSignal(int)
    panel_widen_requested = pyqtSignal(int)
    panel_reset_requested = pyqtSignal()

    def __init__(
        self,
        editor: QPlainTextEdit,
        default_height: int = 124,
        min_height: int = 76,
        max_height: int = 760,
        allow_panel_widen: bool = False,
        footer_hint: str = "drag corner to resize",
        parent: Optional[QWidget] = None,
    ) -> None:
        super().__init__(parent)
        self.setObjectName("ResizablePromptFrame")
        self.editor = editor
        self._default_h = max(min_height, int(default_height))
        self._min_h = max(54, int(min_height))
        self._max_h = max(self._min_h + 60, int(max_height))
        self._allow_widen = bool(allow_panel_widen)
        self._cur_h = self._default_h
        self._drag_base_h = self._default_h
        self._base_hint = footer_hint
        self._bar_dragging = False
        self._bar_start_y = 0

        lay = QVBoxLayout(self)
        lay.setContentsMargins(1, 1, 1, 1)
        lay.setSpacing(0)
        self.editor.setMinimumHeight(0)
        self.editor.setMaximumHeight(16777215)
        self.editor.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        self.editor.installEventFilter(self)
        lay.addWidget(self.editor, 1)

        self._footer_bar = QWidget(self)
        self._footer_bar.setObjectName("PromptResizeFooter")
        self._footer_bar.setCursor(Qt.CursorShape.SizeVerCursor)
        self._footer_bar.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        self._footer_bar.customContextMenuRequested.connect(self._open_size_preset_menu)
        self._footer_bar.installEventFilter(self)
        foot = QHBoxLayout(self._footer_bar)
        foot.setContentsMargins(6, 0, 1, 0)
        foot.setSpacing(3)
        self._hint_lbl = ElideLabel(footer_hint)
        self._hint_lbl.setObjectName("Caption")
        self._hint_lbl.setStyleSheet("font-size: 7.2pt;")
        self._hint_lbl.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        self._fit_btn = QToolButton(self._footer_bar)
        self._fit_btn.setObjectName("Small")
        self._fit_btn.setText("↕")
        self._fit_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        self._fit_btn.setToolTip("Auto-fit prompt box height to show the entire prompt text")
        self._fit_btn.setFixedSize(20, 16)
        self._fit_btn.clicked.connect(self.fit_to_content)
        self._quick_btn = QToolButton(self._footer_bar)
        self._quick_btn.setObjectName("Small")
        self._quick_btn.setText("⤢")
        self._quick_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        self._quick_btn.setToolTip(
            "Toggle expanded / standard prompt box height (right-click footer for exact size presets)"
        )
        self._quick_btn.setFixedSize(20, 16)
        self._quick_btn.clicked.connect(self.toggle_expand_height)
        self._grip = _CornerResizeGrip(two_dim=self._allow_widen, parent=self._footer_bar)
        self._grip.drag_started.connect(self._on_grip_start)
        self._grip.drag_offset.connect(self._on_grip_offset)
        self._grip.drag_delta.connect(self._on_grip_delta)
        self._grip.drag_finished.connect(self._on_grip_finish)
        self._grip.reset_requested.connect(self.reset_size)
        foot.addWidget(self._hint_lbl, 1)
        foot.addWidget(self._fit_btn, 0, Qt.AlignmentFlag.AlignVCenter)
        foot.addWidget(self._quick_btn, 0, Qt.AlignmentFlag.AlignVCenter)
        foot.addWidget(self._grip, 0, Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignBottom)
        lay.addWidget(self._footer_bar)

        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
        self.set_box_height(self._default_h, emit=False)

    def apply_scale(self, scale: float) -> None:
        self._grip.apply_scale(scale)
        s = max(SCALE_MIN, min(SCALE_MAX, float(scale)))
        bw, bh = max(18, int(round(20 * s))), max(15, int(round(17 * s)))
        self._fit_btn.setFixedSize(bw, bh)
        self._quick_btn.setFixedSize(bw, bh)
        self._hint_lbl.setStyleSheet(f"font-size: {max(6.4, round(7.2 * s, 1))}pt;")
        self._grip.update()

    def box_height(self) -> int:
        return int(self._cur_h)

    def set_box_height(self, h: int, emit: bool = False) -> None:
        clamped = max(self._min_h, min(self._max_h, int(h)))
        self._cur_h = clamped
        self.setFixedHeight(clamped)
        self._quick_btn.setText("⤡" if clamped >= self._default_h + 70 else "⤢")
        self.updateGeometry()
        if emit:
            self.height_changed.emit(clamped)

    def fit_to_content(self) -> None:
        """Auto-size height cleanly to fit the full wrapped prompt text without clipping."""
        doc = self.editor.document()
        fm = QFontMetrics(self.editor.font())
        line_h = max(14, fm.lineSpacing())
        vp_w = max(120, self.editor.viewport().width() - 8)
        visual_lines = 0
        blk = doc.begin()
        while blk.isValid():
            lay = blk.layout()
            if lay is not None and lay.lineCount() > 0:
                visual_lines += lay.lineCount()
            else:
                txt = blk.text()
                visual_lines += max(1, (fm.horizontalAdvance(txt) // vp_w) + 1)
            blk = blk.next()
        want_h = max(self._default_h, visual_lines * line_h + self._footer_bar.height() + 26)
        self.set_box_height(min(self._max_h, want_h), emit=True)
        self._ensure_visible_in_scroll()
        SOUNDS.play_ui("ui_resize")

    def toggle_expand_height(self) -> None:
        if self._cur_h >= self._default_h + 70:
            self.set_box_height(self._default_h, emit=True)
        else:
            self.set_box_height(min(self._max_h, max(self._default_h + 170, 300)), emit=True)
        self._ensure_visible_in_scroll()
        SOUNDS.play_ui("ui_resize")

    def reset_height(self) -> None:
        self.set_box_height(self._default_h, emit=True)
        self._hint_lbl.setText(self._base_hint)

    def reset_size(self) -> None:
        self.reset_height()
        if self._allow_widen:
            self.panel_reset_requested.emit()
        SOUNDS.play_ui("ui_resize")

    def _ensure_visible_in_scroll(self) -> None:
        """Keep the bottom resize grip visible inside any enclosing QScrollArea."""
        anc = self.parentWidget()
        while anc is not None:
            if isinstance(anc, QScrollArea):
                anc.ensureWidgetVisible(self._grip, 8, 12)
                return
            anc = anc.parentWidget()

    def _open_size_preset_menu(self, pos: QPoint) -> None:
        m = QMenu(self)
        act_fit = m.addAction("Fit to Prompt Text")
        act_fit.triggered.connect(self.fit_to_content)
        m.addSeparator()
        presets = [
            ("Compact", max(self._min_h, int(self._default_h * 0.78))),
            ("Standard", self._default_h),
            ("Tall (Long Prompt)", min(self._max_h, max(self._default_h + 150, 274))),
            ("Extra Tall (Essay Prompt)", min(self._max_h, max(self._default_h + 300, 440))),
            ("Maximum Studio View", self._max_h),
        ]
        for label, px in presets:
            act = m.addAction(f"{label}  ({px} px)")
            act.triggered.connect(
                lambda _c=False, h_px=px: (self.set_box_height(h_px, emit=True), self._ensure_visible_in_scroll(), SOUNDS.play_ui("ui_resize"))
            )
        if self._allow_widen:
            m.addSeparator()
            act_rst = m.addAction("Reset Box Height & Left Panel Width")
            act_rst.triggered.connect(self.reset_size)
        m.exec(self._footer_bar.mapToGlobal(pos))

    def _update_resize_hint(self) -> None:
        fm = QFontMetrics(self.editor.font())
        approx_lines = max(1, (self._cur_h - self._footer_bar.height() - 10) // max(12, fm.lineSpacing()))
        if self._allow_widen:
            self._hint_lbl.setText(f"{self.width()} \u00d7 {self._cur_h} px  \u00b7  ~{approx_lines} lines")
        else:
            self._hint_lbl.setText(f"{self._cur_h} px  \u00b7  ~{approx_lines} lines")

    def _on_grip_start(self) -> None:
        self._drag_base_h = self._cur_h
        self._update_resize_hint()

    def _on_grip_offset(self, _tot_dx: int, tot_dy: int) -> None:
        self.set_box_height(self._drag_base_h + tot_dy, emit=False)
        self._update_resize_hint()
        if tot_dy > 0:
            self._ensure_visible_in_scroll()

    def _on_grip_delta(self, dx: int, _dy: int) -> None:
        if self._allow_widen and dx != 0:
            self.panel_widen_requested.emit(dx)
            self._update_resize_hint()

    def _on_grip_finish(self) -> None:
        self._hint_lbl.setText(self._base_hint)
        SOUNDS.play_ui("ui_resize")
        self.height_changed.emit(self._cur_h)

    def eventFilter(self, obj, event) -> bool:  # noqa: N802
        et = event.type()
        if obj is self.editor:
            if et == QEvent.Type.FocusIn:
                self.setProperty("focused", True)
                self.style().unpolish(self)
                self.style().polish(self)
            elif et == QEvent.Type.FocusOut:
                self.setProperty("focused", False)
                self.style().unpolish(self)
                self.style().polish(self)
        elif obj is self._footer_bar:
            if et == QEvent.Type.MouseButtonPress and isinstance(event, QMouseEvent):
                if event.button() == Qt.MouseButton.LeftButton:
                    self._bar_dragging = True
                    self._bar_start_y = event.globalPosition().toPoint().y()
                    self._drag_base_h = self._cur_h
                    self._update_resize_hint()
                    event.accept()
                    return True
            elif et == QEvent.Type.MouseMove and self._bar_dragging and isinstance(event, QMouseEvent):
                dy = event.globalPosition().toPoint().y() - self._bar_start_y
                self.set_box_height(self._drag_base_h + dy, emit=False)
                self._update_resize_hint()
                if dy > 0:
                    self._ensure_visible_in_scroll()
                event.accept()
                return True
            elif et == QEvent.Type.MouseButtonRelease and self._bar_dragging and isinstance(event, QMouseEvent):
                if event.button() == Qt.MouseButton.LeftButton:
                    self._bar_dragging = False
                    self._hint_lbl.setText(self._base_hint)
                    SOUNDS.play_ui("ui_resize")
                    self.height_changed.emit(self._cur_h)
                    event.accept()
                    return True
            elif et == QEvent.Type.MouseButtonDblClick and isinstance(event, QMouseEvent):
                if event.button() == Qt.MouseButton.LeftButton:
                    self.reset_height()
                    SOUNDS.play_ui("ui_resize")
                    event.accept()
                    return True
        return super().eventFilter(obj, event)


class EditHistogramWidget(QWidget):
    """Lightweight real-time RGB + Luminance histogram for the Image Editor
    (samples downscaled 64x64 preview for zero latency on low-end laptops)."""

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.setObjectName("HistogramWidget")
        self.setMinimumHeight(46)
        self.setMaximumHeight(58)
        self._bins_r: List[float] = []
        self._bins_g: List[float] = []
        self._bins_b: List[float] = []
        self._bins_l: List[float] = []
        self._stats_txt: str = "No image"

    def update_from_image(self, img: Optional[QImage]) -> None:
        if img is None or img.isNull():
            self._bins_r = self._bins_g = self._bins_b = self._bins_l = []
            self._stats_txt = "No image"
            self.update()
            return
        small = img.scaled(64, 64, Qt.AspectRatioMode.IgnoreAspectRatio, Qt.TransformationMode.FastTransformation)
        rgb = small.convertToFormat(QImage.Format.Format_RGB888)
        w, h, bpl = rgb.width(), rgb.height(), rgb.bytesPerLine()
        ptr = rgb.constBits()
        if ptr is None:
            return
        ptr.setsize(rgb.sizeInBytes())
        data = memoryview(ptr).cast("B")
        nb = 48
        hr = [0] * nb
        hg = [0] * nb
        hb = [0] * nb
        hl = [0] * nb
        clip_lo = 0
        clip_hi = 0
        total = max(1, w * h)
        scale_b = (nb - 1) / 255.0
        for y in range(h):
            off = y * bpl
            row = data[off : off + w * 3]
            for x in range(0, w * 3, 3):
                r, g, b = row[x], row[x + 1], row[x + 2]
                l = (r * 77 + g * 150 + b * 29) >> 8
                hr[int(r * scale_b)] += 1
                hg[int(g * scale_b)] += 1
                hb[int(b * scale_b)] += 1
                hl[int(l * scale_b)] += 1
                if l <= 4:
                    clip_lo += 1
                elif l >= 251:
                    clip_hi += 1
        peak = max(1, max(max(hr), max(hg), max(hb), max(hl)))
        self._bins_r = [v / peak for v in hr]
        self._bins_g = [v / peak for v in hg]
        self._bins_b = [v / peak for v in hb]
        self._bins_l = [v / peak for v in hl]
        self._stats_txt = f"Blk {clip_lo * 100 // total}% · Wht {clip_hi * 100 // total}%"
        self.update()

    def paintEvent(self, event) -> None:  # noqa: N802
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        r = QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5)
        tkey = resolve_theme_key(C.get("key", "seestation"))
        hframe = _theme_frame_path(r, tkey, rad_see=6.0, ch_gold=4.0)
        p.setBrush(QColor(C["deep"]))
        p.setPen(QPen(QColor(C["line"]), 1.0))
        p.drawPath(hframe)
        # Subtle zone guide verticals (25% / 50% / 75%)
        gpen = QPen(QColor(C["line"]), 0.7, Qt.PenStyle.DotLine)
        p.setPen(gpen)
        for frac in (0.25, 0.5, 0.75):
            gx = r.left() + r.width() * frac
            p.drawLine(QPointF(gx, r.top() + 2), QPointF(gx, r.bottom() - 2))
        if self._bins_l:
            n = len(self._bins_l)
            inner = r.adjusted(2.0, 4.0, -2.0, -2.0)
            dx = inner.width() / max(1, n - 1)
            for bins, rgba in (
                (self._bins_r, (235, 76, 76, 78)),
                (self._bins_g, (74, 212, 118, 74)),
                (self._bins_b, (76, 158, 245, 82)),
            ):
                path = QPainterPath()
                path.moveTo(inner.left(), inner.bottom())
                for i, v in enumerate(bins):
                    path.lineTo(inner.left() + i * dx, inner.bottom() - v * inner.height())
                path.lineTo(inner.right(), inner.bottom())
                path.closeSubpath()
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QColor(*rgba))
                p.drawPath(path)
            lpath = QPainterPath()
            for i, v in enumerate(self._bins_l):
                pt = QPointF(inner.left() + i * dx, inner.bottom() - v * inner.height())
                if i == 0:
                    lpath.moveTo(pt)
                else:
                    lpath.lineTo(pt)
            lcol = QColor(C["text_hi"])
            lcol.setAlpha(185)
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.setPen(QPen(lcol, 1.15))
            p.drawPath(lpath)
        p.setFont(_font(max(6.2, 6.8 * ui_scale())))
        p.setPen(QColor(C["muted"]))
        p.drawText(r.adjusted(4, 1, -4, -1), Qt.AlignmentFlag.AlignTop | Qt.AlignmentFlag.AlignRight, self._stats_txt)
        p.end()


# =============================================================================
#  18. Compact Resolution Preset Picker (v25.0 — one 4-column grid for all
#      orientations + explicit "Mix" toggle for a multi-size random draw)
# =============================================================================
class AspectButton(QAbstractButton):
    """Compact glossy aspect tile displaying orientation badge, ratio & WxH px.
    A tick badge marks tiles that belong to the active random mix."""

    tile_clicked = pyqtSignal(str, bool)  # key, shift_held

    def __init__(self, key: str, w: int, h: int, group: str = "square", parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.key = key
        self.w_px = w
        self.h_px = h
        self.group = group
        self._pool_index: int = 0   # >0 while the tile belongs to the active random mix
        self.label_text: str = key
        self.sub_text: str = f"{w}\u00d7{h}"
        self.setCheckable(True)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setMinimumWidth(0)
        self.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Fixed)
        self.setMinimumHeight(max(22, int(round(25 * ui_scale()))))
        orient_lbl = "Square" if group == "square" else ("Landscape" if group == "land" else "Portrait")
        self.setToolTip(
            f"{key} ({orient_lbl})  \u2014  {w} \u00d7 {h} px\n"
            "Click: use this size\n"
            "With Mix on (or Shift+Click): add / remove it from the random mix"
        )

    def set_pool_index(self, idx: int) -> None:
        v = max(0, int(idx))
        if v != self._pool_index:
            self._pool_index = v
            self.update()

    def mousePressEvent(self, event: QMouseEvent) -> None:  # noqa: N802
        if event.button() == Qt.MouseButton.LeftButton:
            shift = bool(event.modifiers() & Qt.KeyboardModifier.ShiftModifier)
            self.tile_clicked.emit(self.key, shift)
            event.accept()
            return
        super().mousePressEvent(event)

    def sizeHint(self) -> QSize:  # noqa: N802
        s = ui_scale()
        return QSize(max(40, int(round(50 * s))), max(22, int(round(25 * s))))

    def paintEvent(self, event) -> None:  # noqa: N802
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        r = QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5)
        checked = self.isChecked()
        hovered = self.underMouse()
        grad = QLinearGradient(r.left(), r.top(), r.left(), r.bottom())
        if checked:
            grad.setColorAt(0.0, QColor(C["acc_hi"]))
            grad.setColorAt(0.52, QColor(C["acc_mid"]))
            grad.setColorAt(1.0, QColor(C["acc_lo"]))
        elif hovered:
            grad.setColorAt(0.0, QColor(C["btn_hov_hi"]))
            grad.setColorAt(1.0, QColor(C["btn_hov_lo"]))
        else:
            grad.setColorAt(0.0, QColor(C["btn_hi"]))
            grad.setColorAt(1.0, QColor(C["btn_lo"]))
        tkey = resolve_theme_key(C.get("key", "seestation"))
        rad = {"seestation": 6.0, "kreatendo": 8.5, "mint": 5.5, "timeless": 5.0, "prestige": 7.0, "oriental": 0.0}.get(tkey, 1.0)
        p.setBrush(QBrush(grad))
        p.setPen(QPen(QColor(C["acc_edge"] if checked else C["line_hi"]), 1.35 if checked else 0.9))
        if tkey == "gold":
            p.drawPath(_chamfer_path(r, 3.5))
        else:
            p.drawRoundedRect(r, rad, rad)
        if checked:
            p.setPen(Qt.PenStyle.NoPen)
            if tkey == "kreatendo":
                kg = QLinearGradient(r.left() + 6, 0, r.right() - 6, 0)
                kg.setColorAt(0.0, QColor("#1aa6e0"))
                kg.setColorAt(0.5, QColor("#d9f2fc"))
                kg.setColorAt(1.0, QColor("#1c9c6b"))
                p.setBrush(kg)
                p.drawRoundedRect(QRectF(r.left() + 6.0, r.bottom() - 3.0, max(4.0, r.width() - 12.0), 2.2), 1.1, 1.1)
            elif tkey == "prestige":
                pg = QLinearGradient(r.left() + 6, 0, r.right() - 6, 0)
                pg.setColorAt(0.0, QColor("#98cdfc"))
                pg.setColorAt(0.5, QColor("#ffffff"))
                pg.setColorAt(1.0, QColor("#98cdfc"))
                p.setBrush(pg)
                p.drawRoundedRect(QRectF(r.left() + 6.0, r.bottom() - 2.8, max(4.0, r.width() - 12.0), 2.0), 1.0, 1.0)
            elif tkey == "seestation":
                p.setBrush(QBrush(QColor(C["acc_spec"])))
                p.drawRoundedRect(QRectF(r.left() + 6.0, r.bottom() - 2.8, max(4.0, r.width() - 12.0), 2.0), 1.0, 1.0)
            elif tkey == "mint":
                ag = QLinearGradient(r.left() + 6, 0, r.right() - 6, 0)
                ag.setColorAt(0.0, QColor("#dcffd8"))
                ag.setColorAt(0.6, QColor("#87cf3e"))
                ag.setColorAt(1.0, QColor("#4ec7b8"))
                p.setBrush(ag)
                p.drawRoundedRect(QRectF(r.left() + 6.0, r.bottom() - 2.9, max(4.0, r.width() - 12.0), 2.2), 1.1, 1.1)
            elif tkey == "timeless":
                tg = QLinearGradient(r.left() + 5.0, 0, r.right() - 5.0, 0)
                tg.setColorAt(0.0, QColor("#fcf2d7"))
                tg.setColorAt(0.6, QColor("#e4c685"))
                tg.setColorAt(1.0, QColor("#91c1b6"))
                p.setBrush(tg)
                p.drawRoundedRect(QRectF(r.left() + 5.0, r.bottom() - 2.8, max(4.0, r.width() - 10.0), 2.1), 1.05, 1.05)
            elif tkey == "oriental":
                p.setBrush(QBrush(QColor(C["acc_spec"])))
                p.drawRect(QRectF(r.left() + 1.0, r.top() + 1.0, 3.0, r.height() - 2.0))
            else:
                p.setBrush(QBrush(QColor(C["acc_spec"])))
                p.drawRect(QRectF(r.left() + 4.0, r.top() + 1.0, max(4.0, r.width() - 8.0), 2.0))
        # Subtle orientation micro-glyph (left side): square / landscape bar / portrait bar
        glyph_col = QColor(C["acc_text"] if checked else C["muted"])
        glyph_col.setAlpha(210 if checked else 145)
        p.setPen(QPen(glyph_col, 1.0))
        p.setBrush(Qt.BrushStyle.NoBrush)
        gx = r.left() + 4.5
        gy = r.top() + r.height() * 0.28
        if self.group == "land":
            p.drawRect(QRectF(gx, gy + 1.0, 6.2, 4.2))
        elif self.group == "port":
            p.drawRect(QRectF(gx + 1.0, gy - 0.5, 4.2, 6.2))
        elif self.group == "mix":
            p.drawRect(QRectF(gx + 2.4, gy - 0.6, 4.2, 4.2))
            p.drawRect(QRectF(gx, gy + 1.8, 4.2, 4.2))
        else:
            p.drawRect(QRectF(gx + 0.6, gy + 0.4, 5.2, 5.2))
        s = ui_scale()
        top_h = r.height() * 0.54
        p.setFont(_font(max(7.1, 8.2 * s), True))
        p.setPen(QColor(C["acc_text"] if checked else C["text_hi"]))
        p.drawText(
            QRectF(r.left() + 9, r.top() + 1, max(12.0, r.width() - 14), top_h),
            Qt.AlignmentFlag.AlignCenter,
            self.label_text,
        )
        p.setFont(_font(max(6.0, 6.7 * s)))
        p.setPen(QColor(C["acc_text"] if checked else C["muted"]))
        dim_txt = self.sub_text
        if self.group != "mix" and QFontMetrics(p.font()).horizontalAdvance(dim_txt) > r.width() - 3:
            dim_txt = f"{self.w_px}\u00b2" if self.w_px == self.h_px else f"{self.w_px}\u00d7\u2026"
        dim_el = QFontMetrics(p.font()).elidedText(dim_txt, Qt.TextElideMode.ElideRight, max(16, int(r.width() - 4)))
        p.drawText(
            QRectF(r.left() + 2, r.top() + top_h - 1, r.width() - 4, r.height() - top_h),
            Qt.AlignmentFlag.AlignCenter,
            dim_el,
        )
        # Random-mix membership badge
        if checked and self._pool_index > 0:
            br = QRectF(r.right() - 12.0, r.top() + 1.5, 10.5, 10.5)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(C["warn"] if not is_light_theme() else "#1c9c6b"))
            p.drawEllipse(br)
            p.setFont(_font(6.0, True))
            p.setPen(QColor("#110a01" if not is_light_theme() else "#f4fff9"))
            p.drawText(br, Qt.AlignmentFlag.AlignCenter, "\u2713")
        p.end()


class AspectPicker(QWidget):
    """Compact resolution preset picker (v25.0).

    All orientations sit in one 4-column grid. The **Mix** toggle turns the grid
    into a multi-select: every enabled size joins a random mix and each generated
    image draws one of them. With Mix off, a click simply switches to that size.
    Shift+Click remains a shortcut that enables Mix on the fly, and the Mix
    button's menu (right-click) fills the mix by orientation in one step."""

    changed = pyqtSignal(str)
    selection_changed = pyqtSignal(list)
    orient_clicked = pyqtSignal(str)

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self._selected_keys: List[str] = ["1:1"]
        self._mix_mode: bool = False
        self._last_land_key: str = "16:9"
        self._last_port_key: str = "9:16"
        self._grid = QGridLayout(self)
        self._grid.setContentsMargins(0, 0, 0, 0)
        self._grid.setHorizontalSpacing(3)
        self._grid.setVerticalSpacing(3)
        self._buttons: Dict[str, AspectButton] = {}

        # Quick orientation / group-pool buttons (docked in Prompt tab mode bar)
        self.orient_land = QToolButton()
        self.orient_land.setObjectName("Small")
        self.orient_land.setText("LAND")
        self.orient_land.setCheckable(True)
        self.orient_land.setMinimumWidth(0)
        self.orient_land.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Fixed)
        self.orient_land.setCursor(Qt.CursorShape.PointingHandCursor)
        self.orient_land.setToolTip(
            "Landscape: switch to the last landscape size (or flip the current ratio).\n"
            "With Mix on (or Shift+Click): add / remove every landscape size."
        )
        self.orient_land.clicked.connect(lambda: self._on_orient_btn("land"))

        self.orient_port = QToolButton()
        self.orient_port.setObjectName("Small")
        self.orient_port.setText("PORT")
        self.orient_port.setCheckable(True)
        self.orient_port.setMinimumWidth(0)
        self.orient_port.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Fixed)
        self.orient_port.setCursor(Qt.CursorShape.PointingHandCursor)
        self.orient_port.setToolTip(
            "Portrait: switch to the last portrait size (or flip the current ratio).\n"
            "With Mix on (or Shift+Click): add / remove every portrait size."
        )
        self.orient_port.clicked.connect(lambda: self._on_orient_btn("port"))

        # One grid, four columns: square + landscape first, then portrait, then the Mix toggle.
        ordered = (
            [a for a in ASPECTS if a["group"] == "square"]
            + [a for a in ASPECTS if a["group"] == "land"]
            + [a for a in ASPECTS if a["group"] == "port"]
        )
        cols = 4
        for idx, a in enumerate(ordered):
            b = AspectButton(a["key"], a["w"], a["h"], group=a["group"])
            b.tile_clicked.connect(self._on_tile_clicked)
            self._buttons[a["key"]] = b
            self._grid.addWidget(b, idx // cols, idx % cols)

        self.pool_btn = AspectButton("__mix__", 0, 0, group="mix")
        self.pool_btn.label_text = "Mix"
        self.pool_btn.sub_text = "off"
        self.pool_btn.tile_clicked.connect(lambda _k, _s: self.set_mix_mode(not self._mix_mode))
        self.pool_btn.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        self.pool_btn.customContextMenuRequested.connect(self._open_mix_menu)
        self._grid.addWidget(self.pool_btn, len(ordered) // cols, len(ordered) % cols)

        # One-line explanation, only visible while the random mix is active.
        self.mix_hint = QLabel("")
        self.mix_hint.setObjectName("Caption")
        self.mix_hint.setWordWrap(True)
        self.mix_hint.setMinimumWidth(0)
        self.mix_hint.setVisible(False)
        self._grid.addWidget(self.mix_hint, len(ordered) // cols + 1, 0, 1, cols)

        self._sync_visuals()

    def _on_orient_btn(self, group: str) -> None:
        shift = bool(QApplication.keyboardModifiers() & Qt.KeyboardModifier.ShiftModifier)
        group_keys = [a["key"] for a in ASPECTS if a["group"] == group]
        if (shift or self._mix_mode) and group_keys:
            self._mix_mode = True
            if set(group_keys).issubset(set(self._selected_keys)) and len(self._selected_keys) > len(group_keys):
                self._selected_keys = [k for k in self._selected_keys if k not in group_keys]
            elif self._selected_keys == group_keys:
                self._selected_keys = [group_keys[0]]
            else:
                self._selected_keys = list(group_keys)
        else:
            cur_k = self._selected_keys[0] if self._selected_keys else "1:1"
            cur_a = ASPECT_BY_KEY.get(cur_k)
            if cur_a and cur_a["group"] != group:
                inv = invert_aspect_key(cur_k) if cur_a["group"] in ("land", "port") else ""
                if inv in ASPECT_BY_KEY and ASPECT_BY_KEY[inv]["group"] == group:
                    target = inv
                else:
                    target = self._last_land_key if group == "land" else self._last_port_key
            else:
                target = self._last_land_key if group == "land" else self._last_port_key
            self._selected_keys = [target if target in ASPECT_BY_KEY else (group_keys[0] if group_keys else "1:1")]
        self._sync_visuals()
        self.orient_clicked.emit(group)
        self.changed.emit(self._selected_keys[0])
        self.selection_changed.emit(list(self._selected_keys))

    def _on_tile_clicked(self, key: str, shift: bool) -> None:
        if key not in self._buttons:
            return
        if shift or self._mix_mode:
            self._mix_mode = True
            if key in self._selected_keys:
                if len(self._selected_keys) > 1:
                    self._selected_keys.remove(key)
            else:
                self._selected_keys.append(key)
        else:
            self._selected_keys = [key]
        self._sync_visuals()
        self.changed.emit(self._selected_keys[0])
        self.selection_changed.emit(list(self._selected_keys))

    def _sync_visuals(self) -> None:
        multi = len(self._selected_keys) > 1
        if multi:
            self._mix_mode = True
        for k, b in self._buttons.items():
            on = k in self._selected_keys
            b.setChecked(on)
            b.set_pool_index((self._selected_keys.index(k) + 1) if (self._mix_mode and on) else 0)
        groups = {ASPECT_BY_KEY[k]["group"] for k in self._selected_keys if k in ASPECT_BY_KEY}
        for k in self._selected_keys:
            a = ASPECT_BY_KEY.get(k)
            if a and a["group"] == "land":
                self._last_land_key = k
            elif a and a["group"] == "port":
                self._last_port_key = k
        for btn, on in ((self.orient_land, "land" in groups), (self.orient_port, "port" in groups),
                        (self.pool_btn, self._mix_mode)):
            btn.blockSignals(True)
            btn.setChecked(on)
            btn.blockSignals(False)
        count = len(self._selected_keys)
        if self._mix_mode:
            names = ", ".join(k for k in self._selected_keys if k in ASPECT_BY_KEY)
            self.pool_btn.sub_text = f"{count} random"
            self.mix_hint.setText(f"Each image draws 1 of {count}: {names}")
            self.pool_btn.setToolTip(
                "Random mix is ON: every ticked size is a candidate and each generated image draws one.\n"
                "Click to switch Mix off (keeps the first size).  Right-click: quick fill."
            )
        else:
            self.pool_btn.sub_text = "off"
            self.pool_btn.setToolTip(
                "Turn on to enable several sizes at once \u2014 each generated image then draws one at random.\n"
                "Right-click: quick fill (all landscape / all portrait / every size)."
            )
        self.pool_btn.update()
        self.mix_hint.setVisible(self._mix_mode)

    def is_mix_mode(self) -> bool:
        return self._mix_mode

    def set_mix_mode(self, on: bool) -> None:
        """Enable / disable the random mix. Disabling keeps only the primary size."""
        on = bool(on)
        if on == self._mix_mode and (on or len(self._selected_keys) <= 1):
            self._sync_visuals()
            return
        self._mix_mode = on
        if not on and len(self._selected_keys) > 1:
            self._selected_keys = [self._selected_keys[0]]
        self._sync_visuals()
        self.changed.emit(self._selected_keys[0])
        self.selection_changed.emit(list(self._selected_keys))

    def _open_mix_menu(self, pos: QPoint) -> None:
        menu = QMenu(self)
        by_group = {g: [a["key"] for a in ASPECTS if a["group"] == g] for g in ("square", "land", "port")}
        fills = (
            ("Every size", by_group["square"] + by_group["land"] + by_group["port"]),
            ("All landscape", by_group["land"]),
            ("All portrait", by_group["port"]),
            ("Square + landscape", by_group["square"] + by_group["land"]),
            ("Square + portrait", by_group["square"] + by_group["port"]),
        )
        for label, keys in fills:
            act = menu.addAction(f"Mix: {label}  ({len(keys)})")
            act.triggered.connect(lambda _c=False, ks=tuple(keys): self.set_selected_keys(ks, emit=True, mix=True))
        menu.addSeparator()
        off = menu.addAction("Mix off \u2014 keep the first size")
        off.setEnabled(self._mix_mode)
        off.triggered.connect(lambda _c=False: self.set_mix_mode(False))
        menu.exec(self.pool_btn.mapToGlobal(pos))

    def collapse_to_single(self) -> None:
        self.set_mix_mode(False)

    def selected_keys(self) -> List[str]:
        return list(self._selected_keys)

    def is_multi(self) -> bool:
        return len(self._selected_keys) > 1

    def pick_random(self) -> Dict[str, Any]:
        pool = [ASPECT_BY_KEY[k] for k in self._selected_keys if k in ASPECT_BY_KEY]
        if not pool:
            return ASPECT_BY_KEY["1:1"]
        return random.choice(pool) if len(pool) > 1 else pool[0]

    def current(self) -> Dict[str, Any]:
        for k in self._selected_keys:
            if k in ASPECT_BY_KEY:
                return ASPECT_BY_KEY[k]
        return ASPECT_BY_KEY["1:1"]

    def set_selected_keys(self, keys: Sequence[str], emit: bool = True, mix: Optional[bool] = None) -> None:
        cleaned: List[str] = []
        for k in keys:
            ks = str(k or "").strip()
            if ks in ASPECT_BY_KEY and ks not in cleaned:
                cleaned.append(ks)
        if not cleaned:
            cleaned = ["1:1"]
        self._selected_keys = cleaned
        self._mix_mode = bool(mix) if mix is not None else len(cleaned) > 1
        self._sync_visuals()
        if emit:
            self.changed.emit(self._selected_keys[0])
            self.selection_changed.emit(list(self._selected_keys))

    def set_current(self, key: str) -> None:
        a = ASPECT_BY_KEY.get(key)
        if a is None:
            return
        self.set_selected_keys([a["key"]], emit=True)

    # Compatibility no-ops (all orientations are now always displayed together)
    def set_group(self, _group: str) -> None:
        return

    def set_portrait(self, _on: bool) -> None:
        return


# =============================================================================
#  19. Zero-Scroll Tab Rails, Wrapping FlowContainer, LoRA Rack & Live Sliders
# =============================================================================
class _IconTabBarStyle(QProxyStyle):
    """Zero-bloat tab metrics for the left icon rail so all 9 icon tabs always
    fit edge-to-edge at any panel width (down to 210px on 800x600 displays)."""

    def pixelMetric(self, metric, option=None, widget=None):  # noqa: N802
        if metric == QStyle.PixelMetric.PM_TabBarTabHSpace:
            return 0
        if metric == QStyle.PixelMetric.PM_TabBarTabVSpace:
            return 2
        if metric == QStyle.PixelMetric.PM_TabBarTabOverlap:
            return 0
        return super().pixelMetric(metric, option, widget)


class _AutoFitIconTabBar(QTabBar):
    """Zero-scroll, auto-distributing icon tab bar with theme-signature active
    bar across all 7 themes PLUS live Queue activity badge & Edit dirty dot."""

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self._avail_w: int = 0
        self._rail_h: int = tab_rail_height(1.0)
        self._queue_badge: int = 0
        self._queue_offline: bool = False
        self._queue_failed: int = 0
        self._llm_streaming: bool = False
        self._lora_count: int = 0
        self._edit_dirty: bool = False
        self.setExpanding(False)
        self.setUsesScrollButtons(False)
        self.setElideMode(Qt.TextElideMode.ElideNone)
        self.setDrawBase(False)

    def set_available_width(self, w: int) -> None:
        w = max(0, int(w))
        if w != self._avail_w:
            self._avail_w = w
            self.updateGeometry()
            self.update()

    def set_rail_height(self, h: int) -> None:
        h = max(24, int(h))
        if h != self._rail_h:
            self._rail_h = h
            self.setFixedHeight(h)
            self.updateGeometry()
            self.update()

    def set_queue_badge(self, count: int, offline: bool = False, failed: int = 0) -> None:
        c = max(0, int(count))
        off = bool(offline)
        fl = max(0, int(failed))
        if c != self._queue_badge or off != self._queue_offline or fl != self._queue_failed:
            self._queue_badge = c
            self._queue_offline = off
            self._queue_failed = fl
            self.update()

    def set_llm_streaming(self, active: bool) -> None:
        v = bool(active)
        if v != self._llm_streaming:
            self._llm_streaming = v
            self.update()

    def set_lora_badge(self, count: int) -> None:
        c = max(0, int(count))
        if c != self._lora_count:
            self._lora_count = c
            self.update()

    def set_edit_dirty(self, dirty: bool) -> None:
        d = bool(dirty)
        if d != self._edit_dirty:
            self._edit_dirty = d
            self.update()

    def tabSizeHint(self, index: int) -> QSize:  # noqa: N802
        n = max(1, self.count())
        avail = self._avail_w if self._avail_w > 0 else max(180, self.width())
        base = max(18, (avail - 2) // n)
        rem = max(0, (avail - 2) - base * n)
        w = base + (1 if index < rem else 0)
        return QSize(w, self._rail_h)

    def minimumTabSizeHint(self, index: int) -> QSize:  # noqa: N802
        return QSize(18, self._rail_h)

    def sizeHint(self) -> QSize:  # noqa: N802
        w = self._avail_w if self._avail_w > 0 else max(210, self.count() * 24)
        return QSize(w, self._rail_h)

    def minimumSizeHint(self) -> QSize:  # noqa: N802
        return QSize(max(162, self.count() * 18), self._rail_h)

    def paintEvent(self, event) -> None:  # noqa: N802
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)
        cur = self.currentIndex()
        tkey = resolve_theme_key(C.get("key", "seestation"))
        base_ico_px = max(12, self.iconSize().width())

        # Draw each tab shape via active QSS/style, then paint its vector icon
        # mathematically dead-center inside tabRect(i) (NEVER left-glued by Fusion!).
        for i in range(self.count()):
            if i == cur:
                continue
            self._paint_single_icon_tab(p, i, False, base_ico_px)
        if 0 <= cur < self.count():
            self._paint_single_icon_tab(p, cur, True, base_ico_px)

        if cur >= 0:
            tr = QRectF(self.tabRect(cur)).adjusted(0.5, 0.5, -0.5, -0.5)
            if tr.width() >= 6 and tr.height() >= 6:
                if tkey == "seestation":
                    aura = QRadialGradient(tr.center().x(), tr.bottom(), tr.width() * 0.72)
                    c0 = QColor(C["acc_hi"]); c0.setAlpha(68)
                    c1 = QColor(C["acc_hi"]); c1.setAlpha(0)
                    aura.setColorAt(0.0, c0)
                    aura.setColorAt(1.0, c1)
                    p.setPen(Qt.PenStyle.NoPen)
                    p.setBrush(aura)
                    p.drawRect(tr)
                    bar = QLinearGradient(tr.left() + 3, 0, tr.right() - 3, 0)
                    bar.setColorAt(0.0, QColor(C["acc_mid"]))
                    bar.setColorAt(0.5, QColor(C["acc_spec"]))
                    bar.setColorAt(1.0, QColor(C["acc_mid"]))
                    p.setBrush(bar)
                    p.drawRoundedRect(QRectF(tr.left() + 3.0, tr.bottom() - 2.6, max(4.0, tr.width() - 6.0), 2.4), 1.2, 1.2)
                elif tkey == "oriental":
                    p.setPen(Qt.PenStyle.NoPen)
                    p.setBrush(QColor(C["acc_hi"]))
                    p.drawRect(QRectF(tr.left(), tr.top(), tr.width(), 2.4))
                    p.drawPolygon(QPolygonF([
                        QPointF(tr.left(), tr.top()),
                        QPointF(tr.left() + 6.5, tr.top()),
                        QPointF(tr.left(), tr.top() + 6.5),
                    ]))
                    p.setBrush(QColor(C["acc_mid"]))
                    p.drawRect(QRectF(tr.left() + 1.0, tr.bottom() - 2.0, max(2.0, tr.width() - 2.0), 1.8))
                elif tkey == "kreatendo":
                    bar = QLinearGradient(tr.left() + 2, 0, tr.right() - 2, 0)
                    bar.setColorAt(0.0, QColor("#009ce0"))
                    bar.setColorAt(0.5, QColor("#2cc4ff"))
                    bar.setColorAt(1.0, QColor("#19b87a"))
                    p.setPen(Qt.PenStyle.NoPen)
                    p.setBrush(bar)
                    p.drawRoundedRect(QRectF(tr.left() + 2.5, tr.bottom() - 3.0, max(4.0, tr.width() - 5.0), 2.8), 1.4, 1.4)
                elif tkey == "mint":
                    bar = QLinearGradient(tr.left() + 3, 0, tr.right() - 3, 0)
                    bar.setColorAt(0.0, QColor(C["acc_mid"]))
                    bar.setColorAt(0.5, QColor("#87cf3e"))
                    bar.setColorAt(1.0, QColor(C["acc_mid"]))
                    p.setPen(Qt.PenStyle.NoPen)
                    p.setBrush(bar)
                    p.drawRoundedRect(QRectF(tr.left() + 3.0, tr.bottom() - 2.6, max(4.0, tr.width() - 6.0), 2.4), 1.2, 1.2)
                elif tkey == "timeless":
                    aura = QRadialGradient(tr.center().x(), tr.top() + 2.0, tr.width() * 0.78)
                    aura.setColorAt(0.0, QColor(238, 209, 148, 58))
                    aura.setColorAt(1.0, QColor(238, 209, 148, 0))
                    p.setPen(Qt.PenStyle.NoPen)
                    p.setBrush(aura)
                    p.drawRect(tr)
                    bar = QLinearGradient(tr.left() + 3, 0, tr.right() - 3, 0)
                    bar.setColorAt(0.0, QColor("#e4c685"))
                    bar.setColorAt(0.55, QColor("#fcf2d7"))
                    bar.setColorAt(1.0, QColor("#91c1b6"))
                    p.setBrush(bar)
                    p.drawRoundedRect(QRectF(tr.left() + 3.0, tr.bottom() - 2.5, max(4.0, tr.width() - 6.0), 2.3), 1.15, 1.15)
                elif tkey == "prestige":
                    bar = QLinearGradient(tr.left() + 3, 0, tr.right() - 3, 0)
                    bar.setColorAt(0.0, QColor("#9cd1ff"))
                    bar.setColorAt(0.5, QColor("#ffffff"))
                    bar.setColorAt(1.0, QColor("#9cd1ff"))
                    p.setPen(Qt.PenStyle.NoPen)
                    p.setBrush(bar)
                    p.drawRoundedRect(QRectF(tr.left() + 3.0, tr.bottom() - 2.6, max(4.0, tr.width() - 6.0), 2.2), 1.1, 1.1)
                else:
                    p.setPen(Qt.PenStyle.NoPen)
                    p.setBrush(QColor(C["acc_spec"]))
                    p.drawRect(QRectF(tr.left() + 2.0, tr.top(), max(4.0, tr.width() - 4.0), 2.2))
                    cx = tr.center().x()
                    p.setBrush(QColor(C["acc_hi"]))
                    p.drawPolygon(QPolygonF([
                        QPointF(cx - 3.5, tr.bottom()),
                        QPointF(cx + 3.5, tr.bottom()),
                        QPointF(cx, tr.bottom() - 3.2),
                    ]))

        # Live Queue active / offline / failed badge on TAB_QUEUE
        if (self._queue_badge > 0 or self._queue_failed > 0) and self.count() > TAB_QUEUE:
            qr = QRectF(self.tabRect(TAB_QUEUE))
            if qr.width() >= 14:
                if self._queue_offline and self._queue_badge > 0:
                    badge_col = QColor(C["warn"])
                    txt_col = QColor("#ffffff" if is_light_theme() else "#120902")
                    lbl = "!"
                elif self._queue_badge > 0:
                    badge_col = QColor(C["acc_mid"] if is_light_theme() else C["acc_hi"])
                    txt_col = QColor(C["acc_text"])
                    lbl = str(min(9, self._queue_badge))
                else:
                    badge_col = QColor(C["err"])
                    txt_col = QColor("#ffffff")
                    lbl = str(min(9, self._queue_failed))
                br = QRectF(qr.right() - 11.5, qr.top() + 1.5, 10.2, 10.2)
                p.setBrush(badge_col)
                p.setPen(QPen(QColor(C["win2"]), 1.0))
                p.drawEllipse(br)
                p.setFont(_font(6.2, True))
                p.setPen(txt_col)
                p.drawText(br, Qt.AlignmentFlag.AlignCenter, lbl)

        # Live LLM streaming pulse dot on TAB_LLM
        if self._llm_streaming and self.count() > TAB_LLM:
            lr = QRectF(self.tabRect(TAB_LLM))
            if lr.width() >= 14:
                p.setBrush(QColor(C["ok"]))
                p.setPen(QPen(QColor(C["win2"]), 1.0))
                p.drawEllipse(QRectF(lr.right() - 9.0, lr.top() + 2.0, 7.2, 7.2))

        # Active LoRA count micro-badge on TAB_LORA
        if self._lora_count > 0 and self.count() > TAB_LORA:
            rr = QRectF(self.tabRect(TAB_LORA))
            if rr.width() >= 14:
                br = QRectF(rr.right() - 10.5, rr.top() + 1.5, 9.2, 9.2)
                p.setBrush(QColor(C["info"]))
                p.setPen(QPen(QColor(C["win2"]), 0.9))
                p.drawEllipse(br)
                p.setFont(_font(5.8, True))
                p.setPen(QColor("#ffffff" if is_light_theme() else "#06131c"))
                p.drawText(br, Qt.AlignmentFlag.AlignCenter, str(min(9, self._lora_count)))

        # Unsaved Edit indicator dot on TAB_EDIT
        if self._edit_dirty and self.count() > TAB_EDIT:
            er = QRectF(self.tabRect(TAB_EDIT))
            if er.width() >= 14:
                p.setBrush(QColor(C["warn"]))
                p.setPen(QPen(QColor(C["win2"]), 1.0))
                p.drawEllipse(QRectF(er.right() - 8.5, er.top() + 2.0, 6.8, 6.8))
        p.end()

    def _paint_single_icon_tab(self, p: QPainter, index: int, selected: bool, base_ico_px: int) -> None:
        opt = QStyleOptionTab()
        self.initStyleOption(opt, index)
        icon = self.tabIcon(index)
        opt.icon = QIcon()
        opt.text = ""
        self.style().drawControl(QStyle.ControlElement.CE_TabBarTabShape, opt, p, self)
        if icon.isNull():
            return
        tr = self.tabRect(index)
        if tr.width() < 8 or tr.height() < 8:
            return
        # Fit icon cleanly inside the tab rectangle with balanced padding and exact mathematical centering
        pad_x = 4 if tr.width() >= 22 else 2
        pad_y = 4 if tr.height() >= 22 else 2
        isz = max(12, min(base_ico_px, tr.width() - pad_x * 2, tr.height() - pad_y * 2))
        cx = tr.left() + (tr.width() - isz) // 2
        cy = tr.top() + (tr.height() - isz) // 2
        mode = QIcon.Mode.Active if selected else (QIcon.Mode.Normal if self.isTabEnabled(index) else QIcon.Mode.Disabled)
        state = QIcon.State.On if selected else QIcon.State.Off
        p.save()
        if not selected and not (opt.state & QStyle.StateFlag.State_MouseOver):
            p.setOpacity(0.84 if not is_light_theme() else 0.88)
        icon.paint(p, QRect(cx, cy, isz, isz), Qt.AlignmentFlag.AlignCenter, mode, state)
        p.restore()




class ModuleContextRibbon(QWidget):
    """Signature 7-theme architectural active-module banner docked beneath the icon rail.
    Splits 'TITLE  ·  context  ·  Ctrl+N' into a luminous title, contextual hint, and
    right-aligned sculpted keycap pill while remaining 100% drop-in compatible with ElideLabel."""

    def __init__(self, text: str = "", parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.setObjectName("TabRibbon")
        self._text: str = text
        self.setMinimumHeight(18)
        self.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Fixed)

    def setText(self, text: str) -> None:  # noqa: N802
        t = str(text or "")
        if t != self._text:
            self._text = t
            self.update()

    def text(self) -> str:
        return self._text

    def sizeHint(self) -> QSize:  # noqa: N802
        return QSize(120, max(19, int(round(22 * ui_scale()))))

    def paintEvent(self, event) -> None:  # noqa: N802
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, not low_power_mode())
        r = QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5)
        tkey = resolve_theme_key(C.get("key", "seestation"))
        s = ui_scale()

        # Background fill + distinctive architectural trim per theme
        bg = QLinearGradient(r.left(), r.top(), r.right(), r.bottom())
        if tkey == "kreatendo":
            bg.setColorAt(0.0, QColor("#ffffff"))
            bg.setColorAt(1.0, QColor("#e3f3fe"))
            p.setBrush(bg)
            p.setPen(QPen(QColor("#8cbce0"), 1.0))
            p.drawRoundedRect(r, 7.0, 7.0)
            # Wii Aqua-to-Mint bottom micro-bar
            bar = QLinearGradient(r.left() + 6, 0, r.right() - 6, 0)
            bar.setColorAt(0.0, QColor("#009ce0"))
            bar.setColorAt(0.55, QColor("#14b87a"))
            bar.setColorAt(1.0, QColor("#f5a600"))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(bar)
            p.drawRoundedRect(QRectF(r.left() + 6, r.bottom() - 2.3, max(8.0, r.width() - 12), 2.0), 1.0, 1.0)
            # Left Wii Aqua capsule pip
            p.setBrush(QColor("#009ce0"))
            p.drawEllipse(QPointF(r.left() + 8.5, r.center().y()), 3.0, 3.0)
            p.setBrush(QColor(255, 255, 255, 210))
            p.drawEllipse(QPointF(r.left() + 7.7, r.center().y() - 0.8), 1.1, 1.1)
        elif tkey == "oriental":
            bg.setColorAt(0.0, QColor("#130404"))
            bg.setColorAt(0.55, QColor("#0b0b0b"))
            bg.setColorAt(1.0, QColor("#050505"))
            p.setBrush(bg)
            p.setPen(QPen(QColor("#2c2c2c"), 1.0))
            p.drawRect(r)
            # Vermilion hanko vertical bar + Kintsugi gold hairline
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor("#ff2218"))
            p.drawRect(QRectF(r.left() + 0.5, r.top() + 0.5, 3.5, r.height() - 1.0))
            p.setPen(QPen(QColor(216, 168, 78, 130), 0.9))
            p.drawLine(QPointF(r.left() + 6, r.bottom() - 0.8), QPointF(r.right() - 4, r.bottom() - 0.8))
        elif tkey == "seestation":
            bg.setColorAt(0.0, QColor("#122645"))
            bg.setColorAt(1.0, QColor("#091529"))
            p.setBrush(bg)
            p.setPen(QPen(QColor("#2c5080"), 1.0))
            p.drawRoundedRect(r, 5.0, 5.0)
            # Sony sapphire pulse orb
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(76, 181, 255, 70))
            p.drawEllipse(QPointF(r.left() + 8.5, r.center().y()), 4.8, 4.8)
            p.setBrush(QColor("#62d2ff"))
            p.drawEllipse(QPointF(r.left() + 8.5, r.center().y()), 2.4, 2.4)
        elif tkey == "mint":
            bg.setColorAt(0.0, QColor("#1e2e24"))
            bg.setColorAt(1.0, QColor("#141e18"))
            p.setBrush(bg)
            p.setPen(QPen(QColor("#34503e"), 1.0))
            p.drawRoundedRect(r, 5.0, 5.0)
            # Linux Mint leaf bud marker
            leaf = QPainterPath()
            cy = r.center().y()
            leaf.moveTo(r.left() + 5.5, cy + 3.2)
            leaf.quadTo(r.left() + 5.5, cy - 3.2, r.left() + 12.0, cy - 3.2)
            leaf.quadTo(r.left() + 12.0, cy + 3.2, r.left() + 5.5, cy + 3.2)
            p.setBrush(QColor("#87cf3e"))
            p.setPen(Qt.PenStyle.NoPen)
            p.drawPath(leaf)
        elif tkey == "timeless":
            bg.setColorAt(0.0, QColor("#33343a"))
            bg.setColorAt(1.0, QColor("#212328"))
            p.setBrush(bg)
            p.setPen(QPen(QColor("#706b5f"), 1.0))
            p.drawRoundedRect(r, 5.0, 5.0)
            bar = QLinearGradient(r.left() + 6, 0, r.right() - 6, 0)
            bar.setColorAt(0.0, QColor("#e4c685"))
            bar.setColorAt(0.65, QColor("#91c1b6"))
            bar.setColorAt(1.0, QColor(145, 193, 182, 0))
            p.setPen(QPen(QBrush(bar), 1.3))
            p.drawLine(QPointF(r.left() + 6, r.bottom() - 1.0), QPointF(r.right() - 6, r.bottom() - 1.0))
            cy = r.center().y()
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor("#e4c685"))
            p.drawPolygon(QPolygonF([
                QPointF(r.left() + 8.5, cy - 3.6), QPointF(r.left() + 12.1, cy),
                QPointF(r.left() + 8.5, cy + 3.6), QPointF(r.left() + 4.9, cy),
            ]))
            p.setBrush(QColor("#91c1b6"))
            p.drawEllipse(QPointF(r.left() + 8.5, cy), 1.3, 1.3)
        elif tkey == "prestige":
            bg.setColorAt(0.0, QColor("#eaeef5"))
            bg.setColorAt(0.50, QColor("#d9dfe9"))
            bg.setColorAt(1.0, QColor("#cad2df"))
            p.setBrush(bg)
            p.setPen(QPen(QColor("#8c97aa"), 1.0))
            p.drawRoundedRect(r, 6.0, 6.0)
            p.setPen(QPen(QColor(255, 255, 255, 195), 1.0))
            p.drawLine(QPointF(r.left() + 5, r.top() + 1.0), QPointF(r.right() - 5, r.top() + 1.0))
            orb = QRadialGradient(r.left() + 8.0, r.center().y() - 0.8, 3.8)
            orb.setColorAt(0.0, QColor("#d9eeff"))
            orb.setColorAt(0.55, QColor("#3b8ee8"))
            orb.setColorAt(1.0, QColor("#1856ad"))
            p.setPen(QPen(QColor("#144994"), 0.7))
            p.setBrush(orb)
            p.drawEllipse(QPointF(r.left() + 8.5, r.center().y()), 3.0, 3.0)
        else:
            # Sarif Gold: chamfered cyber-Renaissance carbon telemetry bar
            bg.setColorAt(0.0, QColor("#211a0d"))
            bg.setColorAt(1.0, QColor("#0e0b05"))
            p.setBrush(bg)
            p.setPen(QPen(QColor("#695224"), 1.0))
            p.drawPath(_chamfer_path(r, 4.0))
            # Amber diamond pip
            cy = r.center().y()
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor("#ffc93c"))
            p.drawPolygon(QPolygonF([
                QPointF(r.left() + 8.5, cy - 3.4),
                QPointF(r.left() + 11.9, cy),
                QPointF(r.left() + 8.5, cy + 3.4),
                QPointF(r.left() + 5.1, cy),
            ]))

        # Parse optional "Ctrl+N" keycap token cleanly from ANY position in ribbon text
        raw_parts = [seg.strip() for seg in self._text.split("\u00b7") if seg.strip()]
        parts: List[str] = []
        shortcut_txt = ""
        for seg in raw_parts:
            m_sc = re.search(r"\b(Ctrl\+\d+)\b", seg)
            if m_sc and not shortcut_txt:
                shortcut_txt = m_sc.group(1)
                cleaned = re.sub(r"\s*\bCtrl\+\d+\b\s*", " ", seg).strip()
                if cleaned:
                    parts.append(cleaned)
            else:
                parts.append(seg)
        title_txt = parts[0] if parts else self._text
        detail_txt = "  \u00b7  ".join(parts[1:]) if len(parts) > 1 else ""

        right_edge = r.right() - 5.0
        if shortcut_txt and r.width() >= 135:
            kfont = _font(max(6.4, 7.0 * s), True)
            kfm = QFontMetrics(kfont)
            kw = kfm.horizontalAdvance(shortcut_txt) + 10.0
            kh = min(r.height() - 5.0, max(13.0, 14.5 * s))
            kr = QRectF(right_edge - kw, r.center().y() - kh / 2.0, kw, kh)
            p.setBrush(QColor("#e8f4fe" if tkey == "kreatendo" else C["deep"]))
            p.setPen(QPen(QColor(C["line_hi"]), 0.9))
            rad_k = 0.0 if tkey == "oriental" else (1.0 if tkey == "gold" else 4.0)
            p.drawRoundedRect(kr, rad_k, rad_k)
            p.setFont(kfont)
            p.setPen(QColor(C["kicker"]))
            p.drawText(kr, Qt.AlignmentFlag.AlignCenter, shortcut_txt)
            right_edge = kr.left() - 6.0

        left_x = r.left() + (10.0 if tkey == "oriental" else 16.0)
        avail_w = max(24.0, right_edge - left_x)
        tfont = _font(max(7.2, 8.1 * s), True, 0.35)
        tfm = QFontMetrics(tfont)
        p.setFont(tfont)
        p.setPen(QColor(C["kicker"] if tkey != "kreatendo" else "#006da8"))
        tw = min(avail_w, float(tfm.horizontalAdvance(title_txt)))
        el_title = tfm.elidedText(title_txt, Qt.TextElideMode.ElideRight, int(avail_w))
        p.drawText(QRectF(left_x, r.top(), avail_w, r.height()), Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft, el_title)

        if detail_txt and avail_w - tw > 28.0:
            dx = left_x + tw + 7.0
            dw = max(12.0, right_edge - dx)
            dfont = _font(max(6.8, 7.5 * s), False)
            dfm = QFontMetrics(dfont)
            el_det = dfm.elidedText(detail_txt, Qt.TextElideMode.ElideRight, int(dw))
            p.setFont(dfont)
            p.setPen(QColor(C["muted"]))
            p.drawText(QRectF(dx, r.top(), dw, r.height()), Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft, el_det)
        p.end()


class StudioTabDeck(QWidget):
    """Optimal v17.0 Workstation Left Tab Deck:
    Stacks the zero-scroll 9-icon rail flush at the top edge (Fitts's Law),
    places the sculpted 5-theme ModuleContextRibbon DIRECTLY beneath the icon rail
    for instantaneous spatial orientation, and hosts each module page inside
    a themed QStackedWidget pane. Exposes a 100% drop-in QTabWidget API."""

    currentChanged = pyqtSignal(int)

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.setObjectName("IconTabs")
        lay = QVBoxLayout(self)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(0)

        self._bar = _AutoFitIconTabBar(self)
        self._bar.setObjectName("IconRailBar")
        self._bar.currentChanged.connect(self._on_bar_changed)
        lay.addWidget(self._bar, 0)

        self.ribbon = ModuleContextRibbon("PROMPT  \u00b7  Ctrl+1")
        self.ribbon.setToolTip("Active module \u2014 switch tabs with Ctrl+1..9 or click the icon rail above")
        lay.addWidget(self.ribbon, 0)

        self._pane = QFrame(self)
        self._pane.setObjectName("StudioTabPane")
        pl = QVBoxLayout(self._pane)
        pl.setContentsMargins(1, 1, 1, 1)
        pl.setSpacing(0)
        self._stack = QStackedWidget(self._pane)
        pl.addWidget(self._stack, 1)
        lay.addWidget(self._pane, 1)

    def _on_bar_changed(self, idx: int) -> None:
        if 0 <= idx < self._stack.count():
            self._stack.setCurrentIndex(idx)
        self.currentChanged.emit(idx)

    def tabBar(self) -> _AutoFitIconTabBar:  # noqa: N802
        return self._bar

    def setTabBar(self, bar: _AutoFitIconTabBar) -> None:  # noqa: N802
        if bar is not self._bar:
            bar.deleteLater()

    def setUsesScrollButtons(self, use: bool) -> None:  # noqa: N802
        self._bar.setUsesScrollButtons(bool(use))

    def setIconSize(self, size: QSize) -> None:  # noqa: N802
        self._bar.setIconSize(size)

    def addTab(self, widget: QWidget, icon: QIcon, label: str = "") -> int:  # noqa: N802
        idx = self._stack.addWidget(widget)
        self._bar.addTab(icon, label)
        if idx == 0:
            self._stack.setCurrentIndex(0)
        return idx

    def count(self) -> int:
        return self._bar.count()

    def currentIndex(self) -> int:  # noqa: N802
        return self._bar.currentIndex()

    def setCurrentIndex(self, index: int) -> None:  # noqa: N802
        if 0 <= index < self._bar.count():
            self._bar.setCurrentIndex(index)
            if self._stack.currentIndex() != index:
                self._stack.setCurrentIndex(index)

    def setTabIcon(self, index: int, icon: QIcon) -> None:  # noqa: N802
        self._bar.setTabIcon(index, icon)

    def setTabToolTip(self, index: int, tip: str) -> None:  # noqa: N802
        self._bar.setTabToolTip(index, tip)

    def widget(self, index: int) -> Optional[QWidget]:
        return self._stack.widget(index)

    def indexOf(self, widget: QWidget) -> int:  # noqa: N802
        return self._stack.indexOf(widget)


class _AutoFitTextTabBar(QTabBar):
    """Zero-scroll equal-distribution labeled tab bar (for LLM sub-tabs, Edit sub-tabs,
    and Right Stage tabs) that mathematically centers [icon + label] inside every tab
    element — never gluing icons to the left side — and fits cleanly at 800x600."""

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.setUsesScrollButtons(False)
        self.setExpanding(True)
        self.setDrawBase(False)
        self.setElideMode(Qt.TextElideMode.ElideRight)

    def minimumSizeHint(self) -> QSize:  # noqa: N802
        return QSize(max(1, self.count()) * 32, max(24, int(round(26 * ui_scale()))))

    def tabSizeHint(self, index: int) -> QSize:  # noqa: N802
        n = max(1, self.count())
        pw = self.parentWidget().width() if self.parentWidget() is not None else self.width()
        avail = max(n * 32, pw - 2)
        base = avail // n
        rem = avail - base * n
        h = max(24, int(round(27 * ui_scale())), super().tabSizeHint(index).height())
        return QSize(max(32, base + (1 if index < rem else 0)), h)

    def paintEvent(self, event) -> None:  # noqa: N802
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)
        cur = self.currentIndex()
        for i in range(self.count()):
            if i == cur:
                continue
            self._paint_centered_tab(p, i, False)
        if 0 <= cur < self.count():
            self._paint_centered_tab(p, cur, True)
        p.end()

    def _paint_centered_tab(self, p: QPainter, index: int, selected: bool) -> None:
        opt = QStyleOptionTab()
        self.initStyleOption(opt, index)
        icon = self.tabIcon(index)
        text = self.tabText(index)
        opt.icon = QIcon()
        opt.text = ""
        self.style().drawControl(QStyle.ControlElement.CE_TabBarTabShape, opt, p, self)

        tr = self.tabRect(index)
        if tr.width() < 8 or tr.height() < 8:
            return
        inner = tr.adjusted(5, 2, -5, -3)
        has_icon = not icon.isNull()
        has_text = bool(text)
        isz = max(12, min(self.iconSize().width() or 14, inner.height() - 2, inner.width() - 2)) if has_icon else 0
        gap = 5 if (has_icon and has_text) else 0

        fnt = self.font()
        fnt.setBold(True)
        p.setFont(fnt)
        fm = QFontMetrics(fnt)

        mode = QIcon.Mode.Active if selected else (QIcon.Mode.Normal if self.isTabEnabled(index) else QIcon.Mode.Disabled)
        state = QIcon.State.On if selected else QIcon.State.Off
        hovered = bool(opt.state & QStyle.StateFlag.State_MouseOver)
        tk_cur = resolve_theme_key(C.get("key", "seestation"))
        if selected and tk_cur == "prestige":
            txt_col = QColor("#ffffff")
        else:
            txt_col = QColor(C["text_hi"] if (selected or hovered) else C["muted"])
        if not self.isTabEnabled(index):
            txt_col = QColor(C["dim"])

        if has_icon and not has_text:
            ix = inner.left() + (inner.width() - isz) // 2
            iy = inner.top() + (inner.height() - isz) // 2
            icon.paint(p, QRect(ix, iy, isz, isz), Qt.AlignmentFlag.AlignCenter, mode, state)
            return

        if has_icon and has_text:
            max_tw = max(0, inner.width() - isz - gap)
            if max_tw < 14:
                # Ultra-narrow: center icon cleanly instead of clipping text
                ix = inner.left() + (inner.width() - isz) // 2
                iy = inner.top() + (inner.height() - isz) // 2
                icon.paint(p, QRect(ix, iy, isz, isz), Qt.AlignmentFlag.AlignCenter, mode, state)
                return
            elided = fm.elidedText(text, Qt.TextElideMode.ElideRight, max_tw)
            tw = min(max_tw, fm.horizontalAdvance(elided))
            group_w = isz + gap + tw
            start_x = inner.left() + max(0, (inner.width() - group_w) // 2)
            iy = inner.top() + (inner.height() - isz) // 2
            if selected and tk_cur == "prestige":
                # Subtle frosted glass halo keeps crisp dark-navy glyph icons vivid on glossy Aqua blue tabs
                p.save()
                p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QColor(255, 255, 255, 212))
                p.drawRoundedRect(QRectF(start_x - 2.0, iy - 1.5, isz + 4.0, isz + 3.0), 4.0, 4.0)
                p.restore()
            icon.paint(p, QRect(start_x, iy, isz, isz), Qt.AlignmentFlag.AlignCenter, mode, state)
            p.setPen(txt_col)
            p.drawText(
                QRect(start_x + isz + gap, inner.top(), tw + 2, inner.height()),
                Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft,
                elided,
            )
            return

        if has_text:
            elided = fm.elidedText(text, Qt.TextElideMode.ElideRight, max(8, inner.width()))
            p.setPen(txt_col)
            p.drawText(inner, Qt.AlignmentFlag.AlignCenter, elided)


class _CompactStackedWidget(QStackedWidget):
    """Zero-bloat QStackedWidget whose size hint tracks ONLY the active page
    with height-for-width support for wrapping FlowLayout bars."""

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Minimum)
        self.currentChanged.connect(lambda _i: self.updateGeometry())

    def minimumSizeHint(self) -> QSize:  # noqa: N802
        cur = self.currentWidget()
        if cur is not None:
            lay = cur.layout()
            if lay is not None and lay.hasHeightForWidth():
                w = max(180, self.width() if self.width() > 60 else 360)
                return QSize(160, max(24, lay.heightForWidth(w)))
            sh = cur.minimumSizeHint()
            return QSize(min(160, sh.width()), max(24, sh.height()))
        return QSize(160, 26)

    def sizeHint(self) -> QSize:  # noqa: N802
        return self.minimumSizeHint()

    def hasHeightForWidth(self) -> bool:  # noqa: N802
        cur = self.currentWidget()
        return bool(cur is not None and cur.layout() is not None and cur.layout().hasHeightForWidth())

    def heightForWidth(self, w: int) -> int:  # noqa: N802
        cur = self.currentWidget()
        if cur is not None and cur.layout() is not None and cur.layout().hasHeightForWidth():
            return max(24, cur.layout().heightForWidth(max(160, w)))
        return self.minimumSizeHint().height()


class FlowLayout(QLayout):
    """Corporate-hardened wrapping FlowLayout (v20.0):
    - Supports separate horizontal (`hgap`) & vertical (`vgap`) gaps plus `spacing`
    - Skips hidden child widgets cleanly (zero ghost gaps!)
    - Two-pass row solver: vertically centers mixed-height items per wrapped row
    - Clamps oversized child widths to container width (never overflows at 800x600!)
    - Immediate widget detach on clear_items() (zero single-frame visual ghosting!)"""

    def __init__(
        self,
        parent: Optional[QWidget] = None,
        margin: int = 0,
        spacing: int = 3,
        hgap: Optional[int] = None,
        vgap: Optional[int] = None,
    ) -> None:
        super().__init__(parent)
        m = max(0, int(margin))
        self.setContentsMargins(m, m, m, m)
        self._hspacing = max(0, int(spacing if hgap is None else hgap))
        self._vspacing = max(0, int(spacing if vgap is None else vgap))
        self._items: List[Any] = []

    def __del__(self) -> None:
        self._items = []

    def set_gaps(self, hgap: Optional[int] = None, vgap: Optional[int] = None) -> None:
        changed = False
        if hgap is not None and int(hgap) != self._hspacing:
            self._hspacing = max(0, int(hgap))
            changed = True
        if vgap is not None and int(vgap) != self._vspacing:
            self._vspacing = max(0, int(vgap))
            changed = True
        if changed:
            self.invalidate()

    def addItem(self, item) -> None:  # noqa: N802
        self._items.append(item)

    def horizontalSpacing(self) -> int:  # noqa: N802
        return self._hspacing

    def verticalSpacing(self) -> int:  # noqa: N802
        return self._vspacing

    def count(self) -> int:  # noqa: N802
        return len(self._items)

    def itemAt(self, i: int):  # noqa: N802
        return self._items[i] if 0 <= i < len(self._items) else None

    def takeAt(self, i: int):  # noqa: N802
        return self._items.pop(i) if 0 <= i < len(self._items) else None

    def expandingDirections(self):  # noqa: N802
        return Qt.Orientation(0)

    def hasHeightForWidth(self) -> bool:  # noqa: N802
        return True

    def heightForWidth(self, w: int) -> int:  # noqa: N802
        return self._do_layout(QRect(0, 0, max(40, w), 0), True)

    def setGeometry(self, rect: QRect) -> None:  # noqa: N802
        super().setGeometry(rect)
        self._do_layout(rect, False)

    def sizeHint(self) -> QSize:  # noqa: N802
        pw = self.parentWidget().width() if self.parentWidget() is not None and self.parentWidget().width() > 60 else 280
        return QSize(self.minimumSize().width(), max(self.minimumSize().height(), self.heightForWidth(pw)))

    def minimumSize(self) -> QSize:  # noqa: N802
        min_h = 0
        for item in self._items:
            wid = item.widget()
            if wid is not None and wid.isHidden():
                continue
            min_h = max(min_h, item.minimumSize().height())
        m = self.contentsMargins()
        return QSize(24 + m.left() + m.right(), min_h + m.top() + m.bottom())

    def _do_layout(self, rect: QRect, test_only: bool) -> int:
        m = self.contentsMargins()
        eff = rect.adjusted(m.left(), m.top(), -m.right(), -m.bottom())
        hs = self._hspacing
        vs = self._vspacing
        max_w = max(24, eff.width())

        # Pass 1: group visible items into wrapped rows with exact per-row heights
        rows: List[Tuple[int, List[Tuple[Any, int, int, int]]]] = []
        cur_row: List[Tuple[Any, int, int, int]] = []
        x = eff.x()
        row_h = 0
        for item in self._items:
            wid = item.widget()
            if wid is not None and wid.isHidden():
                continue
            sh = item.sizeHint()
            ms = item.minimumSize()
            iw = min(max(16, sh.width(), ms.width()), max_w)
            ih = max(16, sh.height(), ms.height())
            if cur_row and (x + iw) > (eff.x() + max_w):
                rows.append((row_h, cur_row))
                cur_row = []
                x = eff.x()
                row_h = 0
            cur_row.append((item, x, iw, ih))
            x += iw + hs
            row_h = max(row_h, ih)
        if cur_row:
            rows.append((row_h, cur_row))

        # Pass 2: place rows and vertically center shorter items cleanly inside each row
        y = eff.y()
        for r_idx, (rh, items) in enumerate(rows):
            if r_idx > 0:
                y += vs
            if not test_only:
                for item, ix, iw, ih in items:
                    iy = y + max(0, (rh - ih) // 2)
                    item.setGeometry(QRect(QPoint(ix, iy), QSize(iw, ih)))
            y += rh
        return max(m.top() + m.bottom(), y - rect.y() + m.bottom())

    def clear_items(self) -> None:
        """Remove and immediately detach every widget in the flow."""
        while self._items:
            item = self.takeAt(0)
            w = item.widget() if item is not None else None
            if w is not None:
                w.hide()
                w.deleteLater()
        self.invalidate()


class FlowContainer(QWidget):
    """Self-sizing wrapping FlowLayout host widget (v20.0) that cleanly expands
    vertically when resized narrower (zero horizontal clipping at 800x600),
    accepts both `spacing` and explicit `hgap`/`vgap` keyword arguments, exposes
    `add_widget()` / `addWidget()` / `clear_items()`, and caches wrapped height
    to eliminate redundant layout cascades during splitter drag."""

    def __init__(
        self,
        margin: int = 0,
        spacing: int = 3,
        parent: Optional[QWidget] = None,
        *,
        hgap: Optional[int] = None,
        vgap: Optional[int] = None,
    ) -> None:
        super().__init__(parent)
        self.setObjectName("Transparent")
        self.flow = FlowLayout(self, margin=margin, spacing=spacing, hgap=hgap, vgap=vgap)
        self._last_flow_w: int = -1
        self._last_flow_h: int = -1
        sp = QSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Preferred)
        sp.setHeightForWidth(True)
        self.setSizePolicy(sp)

    def add_widget(self, widget: QWidget) -> QWidget:
        """Append a child widget into the wrapping flow and trigger a clean relayout."""
        self.flow.addWidget(widget)
        self._last_flow_h = -1
        self.updateGeometry()
        return widget

    def addWidget(self, widget: QWidget) -> None:  # noqa: N802
        self.add_widget(widget)

    def clear_items(self) -> None:
        self.flow.clear_items()
        self._last_flow_h = -1
        self.updateGeometry()

    def set_gaps(self, hgap: Optional[int] = None, vgap: Optional[int] = None) -> None:
        self.flow.set_gaps(hgap=hgap, vgap=vgap)
        self._last_flow_h = -1
        self.updateGeometry()

    def hasHeightForWidth(self) -> bool:  # noqa: N802
        return True

    def heightForWidth(self, w: int) -> int:  # noqa: N802
        return max(0, self.flow.heightForWidth(max(40, w)))

    def sizeHint(self) -> QSize:  # noqa: N802
        w = self.width() if self.width() > 60 else 260
        return QSize(40, max(20, self.flow.heightForWidth(w)))

    def minimumSizeHint(self) -> QSize:  # noqa: N802
        w = self.width() if self.width() > 60 else 220
        return QSize(24, max(18, self.flow.heightForWidth(w)))

    def resizeEvent(self, event) -> None:  # noqa: N802
        super().resizeEvent(event)
        w = max(40, self.width())
        h = self.heightForWidth(w)
        if w != self._last_flow_w and h != self._last_flow_h:
            self._last_flow_w = w
            self._last_flow_h = h
            self.updateGeometry()
        else:
            self._last_flow_w = w
            self._last_flow_h = h


class ThemeSwatchCard(QAbstractButton):
    """Interactive visual theme preview tile (v20.0) rendered in pure QPainter vector graphics:
    displays each flagship theme's authentic surface gradient, frame silhouette, multi-accent
    palette dots, title, and active indicator inside a responsive FlowContainer."""

    def __init__(self, theme_key: str, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.theme_key = resolve_theme_key(theme_key)
        self._hovered = False
        self.setCheckable(True)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setMouseTracking(True)
        pal = THEMES[self.theme_key]
        meta = THEME_META.get(self.theme_key, {})
        self.setToolTip(f"{pal['name']}  —  {meta.get('tagline', pal['hint'])}")
        self.setSizePolicy(QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Fixed)

    def sizeHint(self) -> QSize:  # noqa: N802
        s = ui_scale()
        return QSize(max(98, int(round(108 * s))), max(44, int(round(48 * s))))

    def minimumSizeHint(self) -> QSize:  # noqa: N802
        s = ui_scale()
        return QSize(max(90, int(round(98 * s))), max(40, int(round(44 * s))))

    def enterEvent(self, event) -> None:  # noqa: N802
        self._hovered = True
        self.update()
        super().enterEvent(event)

    def leaveEvent(self, event) -> None:  # noqa: N802
        self._hovered = False
        self.update()
        super().leaveEvent(event)

    def paintEvent(self, event) -> None:  # noqa: N802
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, not low_power_mode())
        r = QRectF(self.rect()).adjusted(1.0, 1.0, -1.0, -1.0)
        tk = self.theme_key
        pal = THEMES[tk]
        meta = THEME_META.get(tk, {})
        active = self.isChecked()
        s = ui_scale()

        frame = _theme_frame_path(r, tk, rad_see=7.0, ch_gold=6.0)
        bg = QLinearGradient(r.left(), r.top(), r.left(), r.bottom())
        bg.setColorAt(0.0, QColor(pal["plate_hi"]))
        bg.setColorAt(1.0, QColor(pal["win2"]))
        p.setBrush(bg)
        border_col = QColor(pal["acc_hi"] if active else (pal["btn_edge_hov"] if self._hovered else pal["line_hi"]))
        p.setPen(QPen(border_col, 2.0 if active else (1.3 if self._hovered else 1.0)))
        p.drawPath(frame)

        # Top theme signature accent bar clipped cleanly inside card silhouette
        p.save()
        p.setClipPath(frame)
        bar = QLinearGradient(r.left(), 0, r.right(), 0)
        if tk == "kreatendo":
            bar.setColorAt(0.0, QColor("#009ce0"))
            bar.setColorAt(0.45, QColor("#16b877"))
            bar.setColorAt(0.75, QColor("#f5a600"))
            bar.setColorAt(1.0, QColor("#e84152"))
        elif tk == "oriental":
            bar.setColorAt(0.0, QColor("#ff1c14"))
            bar.setColorAt(0.72, QColor("#c80000"))
            bar.setColorAt(1.0, QColor("#d8a84e"))
        elif tk == "mint":
            bar.setColorAt(0.0, QColor("#87cf3e"))
            bar.setColorAt(0.65, QColor("#57b347"))
            bar.setColorAt(1.0, QColor("#4ec7b8"))
        elif tk == "timeless":
            bar.setColorAt(0.0, QColor("#b99350"))
            bar.setColorAt(0.45, QColor("#e4c685"))
            bar.setColorAt(0.75, QColor("#fcf2d7"))
            bar.setColorAt(1.0, QColor("#91c1b6"))
        elif tk == "prestige":
            bar.setColorAt(0.0, QColor("#82c2fc"))
            bar.setColorAt(0.50, QColor("#2b7ce0"))
            bar.setColorAt(1.0, QColor("#1856ad"))
        else:
            bar.setColorAt(0.0, QColor(pal["acc_mid"]))
            bar.setColorAt(0.55, QColor(pal["acc_hi"]))
            bar.setColorAt(1.0, QColor(pal["acc_spec"]))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(bar)
        p.drawRect(QRectF(r.left(), r.top(), r.width(), 3.2 if active else 2.2))
        p.restore()

        # Row 1: Title (left) + crisp Active checkmark badge (right) — never collides!
        title = str(meta.get("short") or pal["label"])
        badge = str(meta.get("badge") or "")
        tfont = _font(max(7.2, 8.0 * s), True)
        tfm = QFontMetrics(tfont)
        title_right_pad = 22.0 if active else 8.0
        p.setFont(tfont)
        p.setPen(QColor(pal["text_hi"]))
        p.drawText(
            QRectF(r.left() + 7.0, r.top() + 5.5, max(24.0, r.width() - 7.0 - title_right_pad), 15.0 * s),
            Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter,
            tfm.elidedText(title, Qt.TextElideMode.ElideRight, max(24, int(r.width() - 7.0 - title_right_pad))),
        )
        if active:
            p.setFont(_font(max(6.8, 7.4 * s), True))
            p.setPen(QColor(pal["kicker"] if tk != "kreatendo" else "#0073b8"))
            p.drawText(
                QRectF(r.right() - 21.0, r.top() + 5.0, 16.0, 15.0 * s),
                Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter,
                "\u2713",
            )

        # Row 2: Compact palette gems (left, capped at 4) + non-overlapping badge text (right)
        bfont = _font(max(5.6, 6.2 * s), True)
        bfm = QFontMetrics(bfont)
        tag_txt = "ACTIVE" if active else badge
        tag_w = min(r.width() * 0.56, bfm.horizontalAdvance(tag_txt) + 4.0) if tag_txt else 0.0
        gem_max_x = r.right() - 8.0 - tag_w - 4.0

        swatches = tuple(meta.get("swatches") or (pal["win"], pal["acc_mid"], pal["acc_hi"]))
        sx = r.left() + 7.0
        sy = r.bottom() - 9.5
        for hx in swatches[:4]:
            if sx + 7.0 > gem_max_x:
                break
            p.setBrush(QColor(hx))
            p.setPen(QPen(QColor(pal["plate_edge"] if tk != "kreatendo" else "#8cb4d6"), 0.8))
            if tk in ("oriental", "gold"):
                p.drawRect(QRectF(sx, sy - 3.2, 6.4, 6.4))
            else:
                p.drawEllipse(QRectF(sx, sy - 3.2, 6.6, 6.6))
            sx += 8.6

        if tag_txt:
            p.setFont(bfont)
            p.setPen(QColor((pal["kicker"] if tk != "kreatendo" else "#0073b8") if active else pal["muted"]))
            el_tag = bfm.elidedText(tag_txt, Qt.TextElideMode.ElideRight, max(18, int(r.right() - sx - 6.0)))
            p.drawText(
                QRectF(sx + 2.0, r.bottom() - 16.0, max(16.0, r.right() - sx - 8.0), 13.0),
                Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter,
                el_tag,
            )
        p.end()


class LoraRowDelegate(QStyledItemDelegate):
    """Compact 2-line hardware-strip row per LoRA (v10.0 — fully UI-scaled & narrow-safe)."""

    LAMP_W = 24

    def __init__(self, view: "LoraListView", parent: Optional[QObject] = None) -> None:
        super().__init__(parent or view)
        self._view = view

    def sizeHint(self, option: QStyleOptionViewItem, index: QModelIndex) -> QSize:  # noqa: N802
        h = max(28, int(round(self._view.row_height() * ui_scale())))
        return QSize(160, h)

    def paint(self, painter: QPainter, option: QStyleOptionViewItem, index: QModelIndex) -> None:  # noqa: N802
        entry = self._view.entry_for_uid(str(index.data(Qt.ItemDataRole.UserRole) or ""))
        if not isinstance(entry, dict):
            super().paint(painter, option, index)
            return
        painter.save()
        painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        r = QRectF(option.rect)
        s = ui_scale()
        state = option.state
        selected = bool(state & QStyle.StateFlag.State_Selected)
        hovered = bool(state & QStyle.StateFlag.State_MouseOver)
        tkey = resolve_theme_key(C.get("key", "seestation"))
        card_r = r.adjusted(1.0, 0.5, -1.0, -0.5)
        lframe = _theme_frame_path(card_r, tkey, rad_see=5.5, ch_gold=3.0)
        if selected:
            painter.setBrush(QColor(C["sel_bg"]))
            painter.setPen(QPen(QColor(C["sel_border"]), 1.0))
            painter.drawPath(lframe)
            if tkey == "oriental":
                painter.fillRect(QRectF(card_r.left() + 0.5, card_r.top() + 0.5, 3.2, card_r.height() - 1.0), QColor(C["acc_hi"]))
            elif tkey == "kreatendo":
                painter.setPen(Qt.PenStyle.NoPen)
                painter.setBrush(QColor("#14b87a"))
                painter.drawRoundedRect(QRectF(card_r.right() - 4.0, card_r.top() + 3.0, 2.6, max(4.0, card_r.height() - 6.0)), 1.3, 1.3)
            elif tkey == "mint":
                painter.setPen(Qt.PenStyle.NoPen)
                painter.setBrush(QColor("#87cf3e"))
                painter.drawRoundedRect(QRectF(card_r.right() - 3.6, card_r.top() + 3.0, 2.4, max(4.0, card_r.height() - 6.0)), 1.2, 1.2)
            elif tkey == "timeless":
                painter.setPen(Qt.PenStyle.NoPen)
                tg = QLinearGradient(0, card_r.top() + 3.0, 0, card_r.bottom() - 3.0)
                tg.setColorAt(0.0, QColor("#e4c685"))
                tg.setColorAt(1.0, QColor("#91c1b6"))
                painter.setBrush(tg)
                painter.drawRoundedRect(QRectF(card_r.right() - 3.6, card_r.top() + 3.0, 2.4, max(4.0, card_r.height() - 6.0)), 1.2, 1.2)
            elif tkey == "prestige":
                painter.setPen(Qt.PenStyle.NoPen)
                painter.setBrush(QColor("#2b7ce0"))
                painter.drawRoundedRect(QRectF(card_r.right() - 3.8, card_r.top() + 3.0, 2.6, max(4.0, card_r.height() - 6.0)), 1.3, 1.3)
            elif tkey == "gold":
                painter.fillRect(QRectF(card_r.right() - 3.0, card_r.top() + 2.0, 2.0, max(4.0, card_r.height() - 4.0)), QColor(C["acc_hi"]))
        elif hovered:
            painter.setOpacity(0.62)
            painter.setBrush(QColor(C["tag_hover_bg"]))
            painter.setPen(Qt.PenStyle.NoPen)
            painter.drawPath(lframe)
            painter.setOpacity(1.0)

        enabled = bool(entry.get("enabled", True))
        fcol = QColor(readable_accent_for_theme(lora_folder_color(entry.get("folder", "Improve-Overall"))))
        if not enabled:
            fcol.setAlpha(90)

        # Folder stripe
        painter.fillRect(QRectF(r.left(), r.top() + 2, 3.0, r.height() - 4), fcol)

        # Enable lamp (toggle hit zone)
        lamp_c = r.left() + 14.0
        lamp_y = r.top() + r.height() * 0.5
        if enabled:
            grad = QLinearGradient(lamp_c - 5, lamp_y - 5, lamp_c - 5, lamp_y + 5)
            grad.setColorAt(0.0, QColor(C["acc_spec"]))
            grad.setColorAt(0.5, QColor(C["acc_hi"]))
            grad.setColorAt(1.0, QColor(C["acc_lo"]))
            painter.setBrush(QBrush(grad))
            painter.setPen(QPen(QColor(C["acc_edge"]), 1.0))
            painter.drawEllipse(QPointF(lamp_c, lamp_y), 4.5, 4.5)
            painter.setPen(QPen(QColor(C["acc_text"]), 1.1))
            painter.drawPoint(QPointF(lamp_c, lamp_y))
        else:
            painter.setBrush(Qt.BrushStyle.NoBrush)
            painter.setPen(QPen(QColor(C["dim"]), 1.2))
            painter.drawEllipse(QPointF(lamp_c, lamp_y), 4.1, 4.1)

        # Right-edge weight plate
        m_w = float(entry.get("model", 1.0))
        c_w = float(entry.get("clip", m_w))
        painter.setFont(_font(max(7.2, 8.2 * s), True))
        w_txt = f"{m_w:+.2f}"
        fmw = QFontMetrics(painter.font())
        ww = fmw.horizontalAdvance(w_txt) + 10
        line_h = max(13.0, r.height() * 0.46)
        wr = QRectF(r.right() - ww - 4, r.top() + 3, ww, line_h - 1)
        wbg = QColor(C["acc_deep"]) if enabled else QColor(C["line"])
        painter.setOpacity(0.88 if enabled else 0.5)
        painter.fillRect(wr, wbg)
        painter.setOpacity(1.0)
        painter.setPen(QColor(C["acc_spec"] if enabled else C["muted"]))
        painter.drawText(wr, Qt.AlignmentFlag.AlignCenter, w_txt)

        # Line 1: name (+ #id only if width permits)
        text_x = r.left() + self.LAMP_W
        name_w = max(24.0, r.width() - self.LAMP_W - ww - 10)
        name = str(entry.get("name") or f"LoRA #{entry.get('id', '?')}")
        painter.setFont(_font(max(7.6, 8.8 * s), True))
        painter.setPen(QColor(C["text"] if enabled else C["dim"]))
        fmn = QFontMetrics(painter.font())
        show_id = name_w >= 105
        id_w = 38.0 if show_id else 0.0
        avail_name = max(20, int(name_w - id_w))
        name_el = fmn.elidedText(name, Qt.TextElideMode.ElideRight, avail_name)
        painter.drawText(
            QRectF(text_x, r.top() + 2, avail_name, line_h),
            Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft,
            name_el,
        )
        if show_id:
            id_txt = f"#{entry.get('id', '?')}"
            painter.setFont(_font(max(6.8, 7.4 * s), True))
            painter.setPen(QColor(fcol) if enabled else QColor(C["dim"]))
            painter.drawText(
                QRectF(text_x + avail_name, r.top() + 2, id_w, line_h),
                Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignRight,
                id_txt,
            )

        # Line 2: weights + folder/trigger preview
        painter.setFont(_font(max(6.8, 7.6 * s), False))
        painter.setPen(QColor(C["muted"] if enabled else C["dim"]))
        trig = lora_selected_trigger(entry)
        info = f"M{m_w:+.2f} C{c_w:+.2f}"
        if entry.get("use_slider"):
            info += " \u29bf"
        fmi = QFontMetrics(painter.font())
        info_w = fmi.horizontalAdvance(info) + 6
        sub = QRectF(text_x, r.top() + line_h + 1, max(20.0, r.width() - self.LAMP_W - 6), max(12.0, r.height() - line_h - 3))
        painter.drawText(
            QRectF(sub.left(), sub.top(), min(info_w, sub.width()), sub.height()),
            Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft,
            info,
        )
        tail = ""
        tail_col = QColor(C["dim"])
        if getattr(self._view, "show_folder_names", False):
            tail = str(entry.get("folder") or "")
            tail_col = QColor(fcol)
        elif trig:
            tail = trig
        rem_tail = int(sub.width() - info_w - 2)
        if tail and rem_tail > 18:
            tail_el = fmi.elidedText(tail, Qt.TextElideMode.ElideMiddle, rem_tail)
            painter.setPen(tail_col)
            painter.drawText(
                QRectF(sub.left() + info_w, sub.top(), rem_tail, sub.height()),
                Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft,
                tail_el,
            )
        painter.restore()


class LoraListView(QListWidget):
    """Compact LoRA list: lamp click toggles, double-click edits, Space toggles."""

    toggle_requested = pyqtSignal(str)
    edit_requested = pyqtSignal(str)
    remove_requested = pyqtSignal(str)

    ROW_COMPACT = 36
    ROW_COMFORT = 48

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self._entry_map: Dict[str, Dict[str, Any]] = {}
        self._row_height = self.ROW_COMPACT
        self.show_folder_names: bool = False
        self.setItemDelegate(LoraRowDelegate(self))
        self.setSelectionMode(QAbstractItemView.SelectionMode.ExtendedSelection)
        self.setAlternatingRowColors(True)
        self.setUniformItemSizes(True)
        self.setLayoutMode(QListView.LayoutMode.Batched)
        self.setBatchSize(64)
        self.setVerticalScrollMode(QAbstractItemView.ScrollMode.ScrollPerItem)
        self.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.setMouseTracking(True)

    def set_row_height(self, height: int) -> None:
        self._row_height = max(28, min(64, int(height)))
        self.refresh_scaled_rows()

    def refresh_scaled_rows(self) -> None:
        h = max(28, int(round(self._row_height * ui_scale())))
        for i in range(self.count()):
            it = self.item(i)
            if it is not None:
                it.setSizeHint(QSize(160, h))
        _relayout_item_view(self)

    def row_height(self) -> int:
        return self._row_height

    def set_entries(self, entries: List[Dict[str, Any]]) -> None:
        self._entry_map = {str(e.get("uid") or ""): e for e in entries}

    def entry_for_uid(self, uid: str) -> Optional[Dict[str, Any]]:
        return self._entry_map.get(str(uid or ""))

    def _entry_at(self, pos: QPoint) -> Optional[Dict[str, Any]]:
        it = self.itemAt(pos)
        if it is None:
            return None
        return self.entry_for_uid(str(it.data(Qt.ItemDataRole.UserRole) or ""))

    def _selected_entries(self) -> List[Dict[str, Any]]:
        out: List[Dict[str, Any]] = []
        for it in self.selectedItems():
            e = self.entry_for_uid(str(it.data(Qt.ItemDataRole.UserRole) or ""))
            if e is not None:
                out.append(e)
        return out

    def mousePressEvent(self, event) -> None:  # noqa: N802
        if event.button() == Qt.MouseButton.LeftButton:
            pos = event.position().toPoint()
            entry = self._entry_at(pos)
            if entry is not None and pos.x() <= LoraRowDelegate.LAMP_W:
                entry["enabled"] = not bool(entry.get("enabled", True))
                self.toggle_requested.emit(str(entry.get("uid") or ""))
                self.viewport().update()
                event.accept()
                return
        super().mousePressEvent(event)

    def mouseDoubleClickEvent(self, event) -> None:  # noqa: N802
        entry = self._entry_at(event.position().toPoint())
        if entry is not None:
            self.edit_requested.emit(str(entry.get("uid") or ""))
            event.accept()
            return
        super().mouseDoubleClickEvent(event)

    def keyPressEvent(self, event) -> None:  # noqa: N802
        it = self.currentItem()
        entry = self.entry_for_uid(str(it.data(Qt.ItemDataRole.UserRole) or "")) if it is not None else None
        if isinstance(entry, dict):
            if event.key() == Qt.Key.Key_Space:
                sel = self._selected_entries()
                targets = sel if len(sel) > 1 else [entry]
                any_off = any(not bool(e.get("enabled", True)) for e in targets)
                new_val = True if any_off else False
                for e in targets:
                    e["enabled"] = new_val
                    self.toggle_requested.emit(str(e.get("uid") or ""))
                self.viewport().update()
                event.accept()
                return
            if event.key() in (Qt.Key.Key_Return, Qt.Key.Key_Enter):
                self.edit_requested.emit(str(entry.get("uid") or ""))
                event.accept()
                return
            if event.key() in (Qt.Key.Key_Delete, Qt.Key.Key_Backspace):
                if len(self._selected_entries()) > 1:
                    for e in self._selected_entries():
                        self.remove_requested.emit(str(e.get("uid") or ""))
                else:
                    self.remove_requested.emit(str(entry.get("uid") or ""))
                event.accept()
                return
        super().keyPressEvent(event)


class ActiveLoraSlidersBar(QWidget):
    """Responsive live weight slider rack embedded in the Prompt tab (narrow-safe!)."""

    weight_changed = pyqtSignal(str, float)

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self._lay = QVBoxLayout(self)
        self._lay.setContentsMargins(4, 2, 4, 2)
        self._lay.setSpacing(3)

    def rebuild(self, entries: List[Dict[str, Any]]) -> int:
        while self._lay.count():
            item = self._lay.takeAt(0)
            w = item.widget()
            if w is not None:
                w.hide()
                w.deleteLater()
        active_sliders = [e for e in entries if e.get("enabled") and e.get("use_slider")]
        for e in active_sliders:
            row_w = QWidget()
            row_w.setObjectName("Transparent")
            rl = QHBoxLayout(row_w)
            rl.setContentsMargins(0, 0, 0, 0)
            rl.setSpacing(4)
            fcol = readable_accent_for_theme(lora_folder_color(e.get("folder", "Slider")))
            nm = ElideLabel(str(e.get("name") or f"#{e.get('id')}"))
            nm.setMinimumWidth(52)
            nm.setMaximumWidth(104)
            nm.setStyleSheet(f"color: {fcol}; font-weight: bold;")
            sl = QSlider(Qt.Orientation.Horizontal)
            sl.setMinimumWidth(56)
            s_min = float(e.get("slider_min", -2.0))
            s_max = float(e.get("slider_max", 2.0))
            sl.setRange(int(round(s_min * 20)), int(round(s_max * 20)))
            sl.setValue(int(round(float(e.get("model", 1.0)) * 20)))
            sl.setCursor(Qt.CursorShape.PointingHandCursor)
            vl = make_label(f"{float(e.get('model', 1.0)):+.2f}", "Value")
            vl.setMinimumWidth(34)
            vl.setAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
            uid = str(e["uid"])

            def _on_val(v: int, u: str = uid, lab: QLabel = vl) -> None:
                fw = round(v / 20.0, 2)
                lab.setText(f"{fw:+.2f}")
                self.weight_changed.emit(u, fw)

            sl.valueChanged.connect(_on_val)
            rl.addWidget(nm, 2)
            rl.addWidget(sl, 3)
            rl.addWidget(vl, 0)
            self._lay.addWidget(row_w)
        return len(active_sliders)


# =============================================================================
#  20. Animated Queue Delegate & Tile Upscale Live Previews / Delegate
# =============================================================================
STATE_TINT: Dict[str, str] = {
    STATE_QUEUED: "muted",
    STATE_SUBMITTING: "info",
    STATE_WAITING: "warn",
    STATE_PROCESSING: "acc_hi",
    STATE_FETCHING: "ok",
    STATE_RECONNECTING: "warn",
    STATE_DONE: "ok",
    STATE_FAILED: "err",
    STATE_CANCELLED: "dim",
}

STATE_ANIM_KEY: Dict[str, str] = {
    STATE_QUEUED: "anim_queued",
    STATE_SUBMITTING: "anim_submitting",
    STATE_WAITING: "anim_waiting",
    STATE_PROCESSING: "anim_processing",
    STATE_FETCHING: "anim_fetching",
    STATE_RECONNECTING: "anim_reconnecting",
}


class QueueDelegate(QStyledItemDelegate):
    """Rich animated queue row: live theme-adapted animated vector emblem for
    Waiting / Submitting / Processing / Fetching / Reconnecting / Queued states,
    crisp static badges for Done / Failed, title, live status line, luminous
    animated progress bar & kudos badge — scaled cleanly with ui_scale()."""

    def __init__(self, compact: bool = False, parent: Optional[QObject] = None) -> None:
        super().__init__(parent)
        self.compact = compact

    def sizeHint(self, option: QStyleOptionViewItem, index: QModelIndex) -> QSize:  # noqa: N802
        base_h = 36 if self.compact else 54
        return QSize(max(140, option.rect.width()), max(30, int(round(base_h * ui_scale()))))

    def paint(self, painter: QPainter, option: QStyleOptionViewItem, index: QModelIndex) -> None:  # noqa: N802
        job = index.data(Qt.ItemDataRole.UserRole)
        if not isinstance(job, Job):
            super().paint(painter, option, index)
            return
        painter.save()
        painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        painter.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)
        s = ui_scale()
        r = QRectF(option.rect).adjusted(1.0, 1.0, -1.0, -1.0)
        hovered = bool(option.state & QStyle.StateFlag.State_MouseOver)
        selected = bool(option.state & QStyle.StateFlag.State_Selected)

        grad = QLinearGradient(r.left(), r.top(), r.left(), r.bottom())
        if selected:
            grad.setColorAt(0.0, QColor(C["sel_bg"]))
            grad.setColorAt(1.0, QColor(C["tag_sel_bg"]))
        elif hovered:
            grad.setColorAt(0.0, QColor(C["btn_hov_hi"]))
            grad.setColorAt(1.0, QColor(C["btn_hov_lo"]))
        elif job.state == STATE_RECONNECTING:
            grad.setColorAt(0.0, QColor("#fff1d6" if is_light_theme() else "#2a160a"))
            grad.setColorAt(1.0, QColor(C["plate_lo"]))
        elif job.state == STATE_FAILED:
            grad.setColorAt(0.0, QColor("#ffe4e7" if is_light_theme() else "#290e0e"))
            grad.setColorAt(1.0, QColor(C["plate_lo"]))
        else:
            grad.setColorAt(0.0, QColor(C["plate_hi"]))
            grad.setColorAt(1.0, QColor(C["plate_lo"]))

        tkey = resolve_theme_key(C.get("key", "seestation"))
        qframe = _theme_frame_path(r, tkey, rad_see=6.5, ch_gold=5.0)
        border_col = C["sel_border"] if selected else (
            C["warn"] if job.state == STATE_RECONNECTING else (C["err"] if job.state == STATE_FAILED else C["line"])
        )
        painter.setBrush(QBrush(grad))
        painter.setPen(QPen(QColor(border_col), 1.2 if (selected or job.state in (STATE_RECONNECTING, STATE_FAILED)) else 0.8))
        painter.drawPath(qframe)

        if selected:
            if tkey == "oriental":
                painter.fillRect(QRectF(r.left() + 1.0, r.top() + 1.0, 3.2, r.height() - 2.0), QColor(C["acc_hi"]))
            elif tkey == "kreatendo":
                bar = QLinearGradient(r.left() + 8.0, 0, r.right() - 8.0, 0)
                bar.setColorAt(0.0, QColor("#29c7ff"))
                bar.setColorAt(1.0, QColor("#2ce0b5"))
                painter.fillRect(QRectF(r.left() + 8.0, r.bottom() - 2.2, max(6.0, r.width() - 16.0), 2.0), bar)
            elif tkey in ("seestation", "mint", "timeless", "prestige"):
                painter.fillRect(QRectF(r.left() + 8.0, r.bottom() - 2.2, max(6.0, r.width() - 16.0), 1.8), QColor(C["acc_mid"] if tkey == "prestige" else C["acc_hi"]))
            else:
                painter.fillRect(QRectF(r.left() + 5.0, r.top() + 1.0, max(6.0, r.width() - 10.0), 1.8), QColor(C["acc_spec"]))

        # Animated Vector Status Asset (for Waiting / Submitting / Processing / Fetching / Reconnecting / Queued)
        ic_sz = max(14, min(24, int(round((16 if self.compact else 21) * s))))
        ic_x = int(r.left() + 5)
        ic_y = int(r.top() + (r.height() - 7.0 - ic_sz) / 2.0)
        anim_key = STATE_ANIM_KEY.get(job.state)
        if anim_key is not None:
            if job.kind == KIND_DEPTH and job.state == STATE_PROCESSING:
                anim_key = "anim_depth"
            pm = ANIM_ASSETS.pixmap(anim_key, ANIM_CLOCK.frame, ic_sz, tkey)
            painter.drawPixmap(ic_x, ic_y, pm)
        elif job.state == STATE_DONE:
            painter.drawPixmap(ic_x, ic_y, VECTOR_ASSETS.pixmap("check", ic_sz, ic_sz))
        elif job.state == STATE_FAILED:
            painter.drawPixmap(ic_x, ic_y, VECTOR_ASSETS.pixmap("cross", ic_sz, ic_sz))
        else:
            painter.drawPixmap(ic_x, ic_y, VECTOR_ASSETS.pixmap("warning", ic_sz, ic_sz))

        kudos_w = 0.0
        if job.kudos:
            painter.setFont(_font(max(6.8, 7.4 * s), True))
            k_txt = f"{job.kudos:.0f}k"
            fm_k = QFontMetrics(painter.font())
            kudos_w = fm_k.horizontalAdvance(k_txt) + 10
            kr = QRectF(r.right() - kudos_w - 5, r.top() + 3, kudos_w, max(12.0, 13.0 * s))
            painter.setBrush(QBrush(QColor(C["deep"])))
            painter.setPen(QPen(QColor(C["line"]), 0.8))
            painter.drawRoundedRect(kr, 2.0, 2.0)
            painter.setPen(QColor(C["kicker"]))
            painter.drawText(kr, Qt.AlignmentFlag.AlignCenter, k_txt)

        tx = r.left() + ic_sz + 10
        title_font = _font(max(7.6, 8.8 * s), True)
        painter.setFont(title_font)
        painter.setPen(QColor(C["text_hi"] if not job.terminal else C["muted"]))
        title_w = max(20.0, r.width() - (ic_sz + 16) - (kudos_w + 4 if kudos_w else 0))
        title_h = max(13.0, (15.5 if not self.compact else 14.0) * s)
        title_r = QRectF(tx, r.top() + 3, title_w, title_h)
        painter.drawText(
            title_r,
            Qt.AlignmentFlag.AlignVCenter,
            QFontMetrics(title_font).elidedText(job.title_line(), Qt.TextElideMode.ElideRight, int(title_r.width())),
        )

        if not self.compact:
            painter.setFont(_font(max(7.0, 8.0 * s), job.state in (STATE_FAILED, STATE_RECONNECTING)))
            st_color = (
                C["err"] if job.state == STATE_FAILED else (
                    C["warn"] if job.state == STATE_RECONNECTING else C["muted"]
                )
            )
            painter.setPen(QColor(st_color))
            st_r = QRectF(tx, r.top() + title_h + 3, max(20.0, r.width() - (ic_sz + 14)), max(12.0, 14.5 * s))
            painter.drawText(
                st_r,
                Qt.AlignmentFlag.AlignVCenter,
                QFontMetrics(painter.font()).elidedText(job.status_line(), Qt.TextElideMode.ElideRight, int(st_r.width())),
            )

        prog = job.progress_fraction()
        bar_h = 5.0
        bar_y = r.bottom() - 4.5
        bar_r = QRectF(r.left() + 6, bar_y - bar_h, max(12.0, r.width() - 12), bar_h)
        painter.setBrush(QBrush(QColor(C["deep"])))
        painter.setPen(QPen(QColor(C["sunken_edge"]), 0.8))
        painter.drawRoundedRect(bar_r, 2.0, 2.0)
        if prog > 0.01:
            fill_w = max(4.0, (bar_r.width() - 2) * prog)
            fill_r = QRectF(bar_r.left() + 1, bar_r.top() + 1, fill_w, bar_r.height() - 2)
            pgrad = QLinearGradient(fill_r.left(), fill_r.top(), fill_r.right(), fill_r.top())
            state_col = STATE_TINT.get(job.state, "muted")
            pgrad.setColorAt(0.0, QColor(C["acc_lo"]))
            pgrad.setColorAt(0.65, QColor(C.get(state_col, C["acc_hi"])))
            pgrad.setColorAt(1.0, QColor(C["acc_spec"]))
            painter.setBrush(QBrush(pgrad))
            painter.setPen(Qt.PenStyle.NoPen)
            painter.drawRoundedRect(fill_r, 1.8, 1.8)
            # Subtle travelling shimmer highlight on live/waiting/reconnecting bars
            if job.active and fill_w > 16.0:
                ph = (ANIM_CLOCK.frame / float(max(1, ANIM_CLOCK.frame_count)))
                sx = fill_r.left() + ph * fill_w
                sh = QLinearGradient(sx - 14.0, 0, sx + 14.0, 0)
                sh.setColorAt(0.0, QColor(255, 255, 255, 0))
                sh.setColorAt(0.5, QColor(255, 255, 255, 130))
                sh.setColorAt(1.0, QColor(255, 255, 255, 0))
                painter.setBrush(QBrush(sh))
                painter.drawRoundedRect(fill_r, 1.8, 1.8)
        painter.restore()


class TilePlanPreview(QLabel):
    """Source image with the planned tile grid overlaid (before upscale)."""

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.setMinimumHeight(86)
        self.setMaximumHeight(140)
        self.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.setScaledContents(False)
        self._source: Optional[str] = None
        self._plan: Optional[Dict[str, Any]] = None

    def set_data(self, source: Optional[str], plan: Optional[Dict[str, Any]]) -> None:
        self._source = source
        self._plan = plan
        self._render()

    def _render(self) -> None:
        if not self._source or not os.path.isfile(self._source):
            self.clear()
            self.setText("no source image")
            return
        img = QImage(self._source)
        if img.isNull():
            self.clear()
            self.setText("cannot decode source")
            return
        tw = max(60, self.width() - 8)
        th = max(50, self.height() - 8)
        scale = min(tw / img.width(), th / img.height())
        disp_w, disp_h = int(img.width() * scale), int(img.height() * scale)
        canvas = QImage(max(disp_w, 1), max(disp_h, 1), QImage.Format.Format_ARGB32)
        canvas.fill(QColor(C["deep"]))
        p = QPainter(canvas)
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)
        p.drawImage(QRect(0, 0, disp_w, disp_h), img)
        if self._plan:
            sx = disp_w / max(1, self._plan["out_w"])
            sy = disp_h / max(1, self._plan["out_h"])
            p.setRenderHint(QPainter.RenderHint.Antialiasing, False)
            for t in self._plan["tiles"]:
                rect = QRectF(
                    t["x"] * sx, t["y"] * sy,
                    max(1.0, t["w"] * sx), max(1.0, t["h"] * sy),
                )
                p.setPen(QPen(QColor(C["acc_mid"]), 1.0))
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.drawRect(rect)
                state_col = QColor(TILE_STATE_COLORS.get(t.get("state", TILE_PLANNED), "#928976"))
                p.setBrush(QBrush(state_col))
                p.setPen(Qt.PenStyle.NoPen)
                p.drawRect(QRectF(rect.right() - 4, rect.top() + 1, 3, 3))
        p.end()
        self.setPixmap(QPixmap.fromImage(canvas))

    def resizeEvent(self, event) -> None:  # noqa: N802
        super().resizeEvent(event)
        self._render()


class TileCanvasPreview(QLabel):
    """Live merged-canvas preview: the upscaled base with per-tile state tint."""

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.setMinimumHeight(86)
        self.setMaximumHeight(140)
        self.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self._plan: Optional[Dict[str, Any]] = None
        self._base: Optional[str] = None

    def set_run(self, plan: Optional[Dict[str, Any]], base_path: Optional[str]) -> None:
        self._plan = plan
        self._base = base_path
        self._render()

    def _render(self) -> None:
        if not self._plan:
            self.clear()
            self.setText("no active run")
            return
        out_w, out_h = self._plan["out_w"], self._plan["out_h"]
        tw = max(60, self.width() - 8)
        th = max(50, self.height() - 8)
        scale = min(tw / out_w, th / out_h)
        disp_w, disp_h = int(out_w * scale), int(out_h * scale)
        canvas = QImage(max(disp_w, 1), max(disp_h, 1), QImage.Format.Format_ARGB32)
        canvas.fill(QColor(C["deep"]))
        p = QPainter(canvas)
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)
        if self._base and os.path.isfile(self._base):
            base = QImage(self._base)
            if not base.isNull():
                p.drawImage(QRect(0, 0, disp_w, disp_h), base)
        else:
            p.setPen(QColor(C["dim"]))
            p.setFont(_font(8.5))
            p.drawText(QRect(0, 0, disp_w, disp_h), Qt.AlignmentFlag.AlignCenter, "base upscaling\u2026")
        p.setRenderHint(QPainter.RenderHint.Antialiasing, False)
        sx, sy = disp_w / out_w, disp_h / out_h
        for t in self._plan["tiles"]:
            state = t.get("state", TILE_PLANNED)
            if state != TILE_DONE:
                tint = QColor(TILE_STATE_COLORS.get(state, "#928976"))
                tint.setAlpha(60 if state == TILE_REFINING else 92)
                p.setBrush(QBrush(tint))
                p.setPen(QPen(QColor(C["plate_edge"]), 0.6))
                p.drawRect(QRectF(t["x"] * sx, t["y"] * sy, max(1.0, t["w"] * sx), max(1.0, t["h"] * sy)))
            p.setPen(QPen(QColor(C["line"]), 0.6))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawRect(QRectF(t["x"] * sx, t["y"] * sy, max(1.0, t["w"] * sx), max(1.0, t["h"] * sy)))
        p.end()
        self.setPixmap(QPixmap.fromImage(canvas))

    def resizeEvent(self, event) -> None:  # noqa: N802
        super().resizeEvent(event)
        self._render()


class TileGridDelegate(QStyledItemDelegate):
    """Paints one tile state chip in the tile rack grid."""

    def __init__(self, parent: Optional[QObject] = None) -> None:
        super().__init__(parent)

    def sizeHint(self, option: QStyleOptionViewItem, index: QModelIndex) -> QSize:  # noqa: N802
        return QSize(52, 40)

    def paint(self, painter: QPainter, option: QStyleOptionViewItem, index: QModelIndex) -> None:  # noqa: N802
        t = index.data(Qt.ItemDataRole.UserRole)
        if not isinstance(t, dict):
            super().paint(painter, option, index)
            return
        painter.save()
        painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        r = QRectF(option.rect).adjusted(2.0, 2.0, -2.0, -2.0)
        state = t.get("state", TILE_PLANNED)
        col = QColor(TILE_STATE_COLORS.get(state, "#928976"))
        grad = QLinearGradient(r.left(), r.top(), r.left(), r.bottom())
        grad.setColorAt(0.0, col)
        col2 = QColor(col)
        col2.setAlpha(120)
        grad.setColorAt(1.0, col2)
        painter.setBrush(QBrush(grad))
        painter.setPen(QPen(QColor(C["line"]), 0.8))
        painter.drawRoundedRect(r, 3.0, 3.0)
        # Glass spec
        glass = QColor(C["svg_glass"])
        glass.setAlpha(34)
        painter.setBrush(QBrush(glass))
        painter.setPen(Qt.PenStyle.NoPen)
        painter.drawRect(QRectF(r.left() + 1, r.top() + 1, r.width() - 2, r.height() * 0.42))
        ink = _contrast_ink(col)
        painter.setFont(_font(8.0, True))
        painter.setPen(ink)
        painter.drawText(r.adjusted(0, 1, 0, -11), Qt.AlignmentFlag.AlignCenter, f"r{t.get('row', '?')}c{t.get('col', '?')}")
        painter.setFont(_font(7.2, True))
        sub_ink = QColor(ink)
        sub_ink.setAlpha(220)
        painter.setPen(sub_ink)
        painter.drawText(r.adjusted(0, 11, 0, -1), Qt.AlignmentFlag.AlignCenter, TILE_STATE_SHORT.get(state, "?"))
        painter.restore()

# =============================================================================
#  21. Image Viewer (Zoom, Pan, Drag-Drop & Themed Vector Watermark)
# =============================================================================
class _ViewerCanvas(QWidget):
    def __init__(self, viewer: "ImageViewer") -> None:
        super().__init__(viewer)
        self._viewer = viewer
        self.setAttribute(Qt.WidgetAttribute.WA_OpaquePaintEvent, True)

    def paintEvent(self, event) -> None:  # noqa: N802
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)
        paint_theme_backdrop(p, self.rect())
        pm = self._viewer._pixmap
        live = self._viewer._live_status

        if pm is None or pm.isNull():
            if live is not None:
                # Flagship Animated Waiting / Generating / Reconnecting Centerpiece!
                anim_key = str(live.get("anim_key") or "anim_waiting")
                title = str(live.get("title") or "Waiting in Queue")
                detail = str(live.get("detail") or "")
                prog = float(live.get("progress") or 0.0)
                offline = bool(live.get("offline", False))

                sz = min(104, max(56, min(self.width(), self.height()) // 3))
                card_w = min(self.width() - 28, max(240, 340))
                card_h = sz + 92
                cx = (self.width() - card_w) // 2
                cy = max(12, (self.height() - card_h) // 2)
                card_r = QRectF(cx, cy, card_w, card_h)
                tkey = resolve_theme_key(C.get("key", "seestation"))
                frame = _theme_frame_path(card_r, tkey, rad_see=12.0, ch_gold=9.0)
                bg_c = QColor(C["plate_lo"]); bg_c.setAlpha(212)
                p.setBrush(bg_c)
                p.setPen(QPen(QColor(C["warn"] if offline else C["acc_hi"]), 1.4))
                p.drawPath(frame)

                apm = ANIM_ASSETS.pixmap(anim_key, ANIM_CLOCK.frame, sz, tkey)
                p.drawPixmap(int(card_r.center().x() - sz / 2), int(card_r.top() + 14), apm)

                p.setFont(_font(10.5, True, 0.8))
                p.setPen(QColor(C["warn"] if offline else C["text_hi"]))
                p.drawText(
                    QRectF(card_r.left() + 14, card_r.top() + sz + 20, card_r.width() - 28, 22),
                    Qt.AlignmentFlag.AlignCenter,
                    title,
                )
                p.setFont(_font(8.4))
                p.setPen(QColor(C["muted"]))
                el_det = QFontMetrics(p.font()).elidedText(detail, Qt.TextElideMode.ElideRight, int(card_r.width() - 28))
                p.drawText(
                    QRectF(card_r.left() + 14, card_r.top() + sz + 42, card_r.width() - 28, 18),
                    Qt.AlignmentFlag.AlignCenter,
                    el_det,
                )
                # Animated progress track
                bar_r = QRectF(card_r.left() + 26, card_r.bottom() - 18, card_r.width() - 52, 6.0)
                p.setBrush(QColor(C["deep"]))
                p.setPen(QPen(QColor(C["line"]), 0.8))
                p.drawRoundedRect(bar_r, 3.0, 3.0)
                fw = max(8.0, (bar_r.width() - 2.0) * max(0.05, min(1.0, prog)))
                fr = QRectF(bar_r.left() + 1.0, bar_r.top() + 1.0, fw, bar_r.height() - 2.0)
                pg = QLinearGradient(fr.left(), fr.top(), fr.right(), fr.top())
                pg.setColorAt(0.0, QColor(C["warn"] if offline else C["acc_mid"]))
                pg.setColorAt(1.0, QColor(C["acc_spec"]))
                p.setBrush(QBrush(pg))
                p.setPen(Qt.PenStyle.NoPen)
                p.drawRoundedRect(fr, 2.5, 2.5)
                p.end()
                return

            # Cinematic themed vector centerpiece watermark (idle)
            s_sc = ui_scale()
            sz = min(192, max(76, min(self.width(), self.height()) // 2 - 12))
            wm = VECTOR_ASSETS.pixmap("viewer_watermark", sz, sz)
            wx = (self.width() - sz) // 2
            wy = max(12, (self.height() - sz) // 2 - 22)
            p.drawPixmap(wx, wy, wm)
            p.setFont(_font(max(9.2, min(13.0, 10.6 * s_sc)), True, 0.8))
            p.setPen(QColor(C["text_hi"]))
            p.drawText(
                QRect(12, wy + sz + 4, self.width() - 24, 22),
                Qt.AlignmentFlag.AlignCenter,
                f"{APP_NAME}  v{APP_VERSION}  \u00b7  {C['name']}",
            )
            p.setFont(_font(max(7.6, min(10.4, 8.5 * s_sc))))
            p.setPen(QColor(C["muted"]))
            p.drawText(
                QRect(12, wy + sz + 26, self.width() - 24, 20),
                Qt.AlignmentFlag.AlignCenter,
                "Enter a prompt and press Generate (Ctrl+Enter)  \u00b7  or drop an image here",
            )
            if self.height() >= 260:
                p.setFont(_font(max(7.0, min(9.4, 7.6 * s_sc))))
                p.setPen(QColor(C["dim"]))
                p.drawText(
                    QRect(12, wy + sz + 45, self.width() - 24, 18),
                    Qt.AlignmentFlag.AlignCenter,
                    "Ctrl+K Command Palette  \u00b7  Ctrl+Shift+T Theme  \u00b7  F1 Shortcuts",
                )
            p.end()
            return

        tw = max(1, int(round(pm.width() * self._viewer._scale)))
        th = max(1, int(round(pm.height() * self._viewer._scale)))
        ox = (self.width() - tw) // 2
        oy = (self.height() - th) // 2
        target = QRect(ox, oy, tw, th)
        # Low-end laptop speedup: cache scaled pixmap for active zoom/fit size so hover/HUD repaints are 1:1 blits
        if tw == pm.width() and th == pm.height():
            p.drawPixmap(ox, oy, pm)
        elif tw <= 3840 and th <= 3840:
            sck = (pm.cacheKey(), tw, th, low_power_mode())
            if getattr(self._viewer, "_scaled_cache_key", None) != sck:
                mode = (
                    Qt.TransformationMode.FastTransformation
                    if low_power_mode()
                    else Qt.TransformationMode.SmoothTransformation
                )
                self._viewer._scaled_pm = pm.scaled(tw, th, Qt.AspectRatioMode.IgnoreAspectRatio, mode)
                self._viewer._scaled_cache_key = sck
            spm = getattr(self._viewer, "_scaled_pm", None)
            if spm is not None and not spm.isNull():
                p.drawPixmap(ox, oy, spm)
            else:
                p.drawPixmap(target, pm)
        else:
            p.drawPixmap(target, pm)
        # Crisp subtle frame around artwork
        p.setPen(QPen(QColor(C["line_hi"]), 1.0))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawRect(target.adjusted(0, 0, -1, -1))

        if self._viewer._zoom_rect is not None:
            zr = self._viewer._zoom_rect.normalized()
            zf = QColor(C["acc_hi"]); zf.setAlpha(42)
            p.setBrush(zf)
            p.setPen(QPen(QColor(C["acc_spec"]), 1.4, Qt.PenStyle.DashLine))
            p.drawRect(zr)

        # Unobtrusive live floating HUD pill when tasks are waiting/generating in background
        self._viewer._hud_rect = QRect()
        if live is not None:
            anim_key = str(live.get("anim_key") or "anim_waiting")
            pill_txt = str(live.get("pill") or live.get("title") or "Waiting\u2026")
            offline = bool(live.get("offline", False))
            tkey = resolve_theme_key(C.get("key", "seestation"))
            p.setFont(_font(8.0, True))
            fm = QFontMetrics(p.font())
            tw_txt = min(max(80, self.width() - 72), fm.horizontalAdvance(pill_txt) + 6)
            pw = 28 + tw_txt + 10
            ph = 26
            vp_right = min(self.width(), self._viewer.horizontalScrollBar().value() + self._viewer.viewport().width())
            vp_top = self._viewer.verticalScrollBar().value()
            pr = QRectF(max(8, vp_right - pw - 10), vp_top + 8, pw, ph)
            self._viewer._hud_rect = pr.toRect()
            bg_p = QColor(("#fff3da" if is_light_theme() else "#2e1209") if offline else C["deep"]); bg_p.setAlpha(226)
            p.setBrush(bg_p)
            p.setPen(QPen(QColor(C["warn"] if offline else C["acc_hi"]), 1.25))
            p.drawPath(_theme_frame_path(pr, tkey, rad_see=12.0, ch_gold=5.0))
            apm = ANIM_ASSETS.pixmap(anim_key, ANIM_CLOCK.frame, 18, tkey)
            p.drawPixmap(int(pr.left() + 6), int(pr.top() + 4), apm)
            p.setPen(QColor(C["warn"] if offline else C["text_hi"]))
            p.drawText(
                QRectF(pr.left() + 28, pr.top(), tw_txt, ph),
                Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft,
                fm.elidedText(pill_txt, Qt.TextElideMode.ElideRight, int(tw_txt)),
            )
        p.end()


class ImageViewer(QScrollArea):
    toggled_fit = pyqtSignal(bool)
    zoom_changed = pyqtSignal(float, bool)
    image_dropped = pyqtSignal(str)
    menu_requested = pyqtSignal(QPoint)
    hud_clicked = pyqtSignal()

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.setWidgetResizable(False)
        self.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.setFrameShape(QFrame.Shape.NoFrame)
        self.setAcceptDrops(True)
        self.path: Optional[str] = None
        self.meta: Dict[str, Any] = {}
        self._pixmap: Optional[QPixmap] = None
        self._fit = True
        self._scale = 1.0
        self._panning = False
        self._pan_start = QPoint()
        self._h_start = 0
        self._v_start = 0
        self._zoom_rect: Optional[QRect] = None
        self._live_status: Optional[Dict[str, Any]] = None
        self._hud_rect: QRect = QRect()
        self._canvas = _ViewerCanvas(self)
        self.setWidget(self._canvas)

    def update_hud_only(self) -> None:
        """Low-CPU dirty-rect update for the live status overlay (avoids repainting
        full high-res artwork at 16 FPS on low-end laptops)."""
        if self._pixmap is None or self._pixmap.isNull():
            self._canvas.update()
            return
        if not self._hud_rect.isEmpty():
            self._canvas.update(self._hud_rect.adjusted(-6, -6, 6, 6))
        else:
            self._canvas.update()

    def set_live_status(self, status: Optional[Dict[str, Any]]) -> None:
        """Update the animated Waiting / Generating / Reconnecting overlay HUD."""
        self._live_status = dict(status) if status else None
        self._canvas.update()

    def set_image(self, path: Optional[str]) -> None:
        self.path = path if (path and os.path.isfile(path)) else None
        self.meta = read_image_metadata(self.path) if self.path else {}
        self._pixmap = QPixmap(self.path) if self.path else None
        self._scaled_cache_key = None
        self._scaled_pm = None
        if self._fit:
            self._recompute_fit()
        else:
            self._update_canvas_size()
        self._sync_cursor()
        self._canvas.update()

    def _sync_cursor(self) -> None:
        if self._panning:
            CURSOR_ENGINE.apply_role(self.viewport(), "closed_hand")
        elif self._zoom_rect is not None:
            CURSOR_ENGINE.apply_role(self.viewport(), "zoom_in")
        elif self._pixmap is not None and not self._fit:
            CURSOR_ENGINE.apply_role(self.viewport(), "open_hand")
        else:
            CURSOR_ENGINE.apply_role(self.viewport(), "arrow")

    def set_fit(self, fit: bool) -> None:
        self._fit = bool(fit)
        if self._fit:
            self._recompute_fit()
        else:
            self._scale = 1.0
            self._update_canvas_size()
        self._sync_cursor()
        self.toggled_fit.emit(self._fit)
        self.zoom_changed.emit(self._scale, self._fit)
        self._canvas.update()

    def zoom_by(self, factor: float, anchor: Optional[QPoint] = None) -> None:
        if self._pixmap is None or self._pixmap.isNull():
            return
        old_s = self._scale
        new_s = max(0.08, min(12.0, old_s * factor))
        if abs(new_s - old_s) < 1e-4:
            return
        self._fit = False
        vp = self.viewport()
        if anchor is None:
            anchor = QPoint(vp.width() // 2, vp.height() // 2)
        hbar = self.horizontalScrollBar()
        vbar = self.verticalScrollBar()
        img_x = (hbar.value() + anchor.x()) / max(1e-6, old_s)
        img_y = (vbar.value() + anchor.y()) / max(1e-6, old_s)
        self._scale = new_s
        self._update_canvas_size()
        hbar.setValue(int(round(img_x * new_s - anchor.x())))
        vbar.setValue(int(round(img_y * new_s - anchor.y())))
        self._sync_cursor()
        self.toggled_fit.emit(False)
        self.zoom_changed.emit(self._scale, False)
        self._canvas.update()

    def _recompute_fit(self) -> None:
        vp = self.viewport().size()
        if self._pixmap is None or self._pixmap.isNull() or vp.width() <= 4 or vp.height() <= 4:
            self._scale = 1.0
            self._canvas.resize(max(10, vp.width()), max(10, vp.height()))
            return
        sx = (vp.width() - 8) / max(1, self._pixmap.width())
        sy = (vp.height() - 8) / max(1, self._pixmap.height())
        self._scale = max(0.05, min(sx, sy, 1.0))
        self._canvas.resize(max(10, vp.width()), max(10, vp.height()))
        self.zoom_changed.emit(self._scale, True)

    def _update_canvas_size(self) -> None:
        vp = self.viewport().size()
        if self._pixmap is None or self._pixmap.isNull():
            self._canvas.resize(max(10, vp.width()), max(10, vp.height()))
            return
        tw = max(vp.width(), int(round(self._pixmap.width() * self._scale)))
        th = max(vp.height(), int(round(self._pixmap.height() * self._scale)))
        self._canvas.resize(tw, th)

    def resizeEvent(self, event) -> None:  # noqa: N802
        super().resizeEvent(event)
        if self._fit:
            self._recompute_fit()
        else:
            self._update_canvas_size()
        self._canvas.update()

    def wheelEvent(self, event) -> None:  # noqa: N802
        if event.modifiers() & Qt.KeyboardModifier.ControlModifier:
            delta = event.angleDelta().y()
            if delta:
                self.zoom_by(1.22 if delta > 0 else 1.0 / 1.22, event.position().toPoint())
            event.accept()
            return
        super().wheelEvent(event)

    def mouseDoubleClickEvent(self, event) -> None:  # noqa: N802
        if event.button() == Qt.MouseButton.LeftButton and self._pixmap is not None:
            self.set_fit(not self._fit)
            event.accept()
            return
        super().mouseDoubleClickEvent(event)

    def mousePressEvent(self, event) -> None:  # noqa: N802
        # Clicking the floating live-queue HUD pill jumps directly to the Queue tab
        if event.button() == Qt.MouseButton.LeftButton and not self._hud_rect.isEmpty():
            vp = self.viewport()
            if vp is None:
                return
            cpos = self._canvas.mapFrom(vp, event.position().toPoint())
            if self._hud_rect.contains(cpos):
                self.hud_clicked.emit()
                event.accept()
                return
        if (
            event.button() == Qt.MouseButton.RightButton
            and (event.modifiers() & Qt.KeyboardModifier.ControlModifier)
            and self._pixmap is not None
        ):
            self.set_fit(True)
            event.accept()
            return
        if event.button() == Qt.MouseButton.LeftButton and self._pixmap is not None:
            if event.modifiers() & Qt.KeyboardModifier.ControlModifier:
                self._zoom_rect = QRect(event.position().toPoint(), event.position().toPoint())
                self._sync_cursor()
                event.accept()
                return
            if not self._fit:
                self._panning = True
                self._pan_start = event.position().toPoint()
                self._h_start = self.horizontalScrollBar().value()
                self._v_start = self.verticalScrollBar().value()
                self._sync_cursor()
                event.accept()
                return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event) -> None:  # noqa: N802
        if self._zoom_rect is not None:
            self._zoom_rect = QRect(self._zoom_rect.topLeft(), event.position().toPoint()).normalized()
            self._canvas.update()
            event.accept()
            return
        if self._panning:
            d = event.position().toPoint() - self._pan_start
            self.horizontalScrollBar().setValue(self._h_start - d.x())
            self.verticalScrollBar().setValue(self._v_start - d.y())
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event) -> None:  # noqa: N802
        if event.button() == Qt.MouseButton.LeftButton and self._zoom_rect is not None:
            r = QRect(self._zoom_rect)
            self._zoom_rect = None
            self._sync_cursor()
            self._canvas.update()
            if r.width() >= 14 and r.height() >= 14:
                self._zoom_to_rect(r)
            event.accept()
            return
        if self._panning and event.button() == Qt.MouseButton.LeftButton:
            self._panning = False
            self._sync_cursor()
            event.accept()
            return
        super().mouseReleaseEvent(event)

    def _zoom_to_rect(self, r: QRect) -> None:
        vp = self.viewport().size()
        factor = min(vp.width() / float(r.width()), vp.height() / float(r.height())) * 0.97
        old = self._scale
        new = max(0.05, min(12.0, old * factor))
        if abs(new - old) < 1e-4:
            return
        hbar, vbar = self.horizontalScrollBar(), self.verticalScrollBar()
        cx_doc = (hbar.value() + r.center().x()) / max(1e-6, old)
        cy_doc = (vbar.value() + r.center().y()) / max(1e-6, old)
        self._fit = False
        self._scale = new
        self._update_canvas_size()
        hbar.setValue(int(round(cx_doc * new - vp.width() / 2.0)))
        vbar.setValue(int(round(cy_doc * new - vp.height() / 2.0)))
        self._sync_cursor()
        self.toggled_fit.emit(False)
        self.zoom_changed.emit(new, False)
        self._canvas.update()

    def contextMenuEvent(self, event) -> None:  # noqa: N802
        if self._pixmap is not None and not self._pixmap.isNull():
            self.menu_requested.emit(event.globalPos())
            event.accept()
            return
        super().contextMenuEvent(event)

    def dragEnterEvent(self, event) -> None:  # noqa: N802
        if event.mimeData().hasUrls():
            for u in event.mimeData().urls():
                if u.isLocalFile() and u.toLocalFile().lower().endswith((".png", ".webp", ".jpg", ".jpeg")):
                    event.acceptProposedAction()
                    return
        super().dragEnterEvent(event)

    def dropEvent(self, event) -> None:  # noqa: N802
        if event.mimeData().hasUrls():
            for u in event.mimeData().urls():
                if u.isLocalFile() and u.toLocalFile().lower().endswith((".png", ".webp", ".jpg", ".jpeg")):
                    self.image_dropped.emit(u.toLocalFile())
                    event.acceptProposedAction()
                    return
        super().dropEvent(event)


