class DraggableTagList(QListWidget):
    """Tag Groups list supporting drag-and-drop straight into TagFlowPromptEdit."""

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.setDragEnabled(True)
        self.setDragDropMode(QAbstractItemView.DragDropMode.DragOnly)
        self.setDefaultDropAction(Qt.DropAction.CopyAction)

    def startDrag(self, supportedActions) -> None:  # noqa: N802
        it = self.currentItem()
        if it is None:
            return
        text = str(it.data(Qt.ItemDataRole.UserRole) or "").strip()
        folder = str(it.data(Qt.ItemDataRole.UserRole + 1) or "General")
        if not text:
            return
        mime = QMimeData()
        mime.setText(text)
        payload = json.dumps({"text": text, "color": tag_folder_color(folder), "kind": "tag"}).encode("utf-8")
        mime.setData("application/x-hsl-snippet", QByteArray(payload))
        drag = QDrag(self)
        drag.setMimeData(mime)
        drag.exec(Qt.DropAction.CopyAction)


def clamp_dialog_to_screen(dlg: QDialog, pref_w: int = 560, pref_h: int = 440) -> None:
    """Guarantee any modal dialog fits cleanly inside the available screen geometry
    (including 800x600 displays) so OK/Cancel buttons are NEVER pushed off-screen."""
    scr = dlg.screen() or QGuiApplication.primaryScreen()
    if scr is None:
        dlg.resize(pref_w, pref_h)
        return
    av = scr.availableGeometry()
    w = max(320, min(pref_w, av.width() - 24))
    h = max(260, min(pref_h, av.height() - 36))
    dlg.resize(w, h)
    dlg.move(
        av.left() + max(0, (av.width() - w) // 2),
        av.top() + max(0, (av.height() - h) // 2),
    )


class JobErrorDialog(QDialog):
    """Detailed diagnostic inspector for a failed/reconnecting queue task with
    1-click Retry and Copy Diagnostics."""

    retry_requested = pyqtSignal(int)

    def __init__(self, job: Job, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self._job_id = job.local_id
        self.setWindowTitle(f"Task #{job.local_id} Diagnostics")
        lay = QVBoxLayout(self)
        lay.setContentsMargins(10, 10, 10, 10)
        lay.setSpacing(6)
        hdr = QLabel(f"Task #{job.local_id}  •  {job.state.upper()}")
        hdr.setObjectName("Err" if job.state == STATE_FAILED else "Warn")
        lay.addWidget(hdr)

        ts = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(job.ended_at or job.created_at))
        details = [
            f"Kind: {job.kind}",
            f"State: {job.state}",
            f"Horde Request ID: {job.horde_id or '(not assigned)'}",
            f"Model: {job.meta.get('model') or '(default)'}",
            f"Outage Retries: {job.outage_attempts}  |  Auto-Resubmits: {job.outage_resubmits}",
            f"Timestamp: {ts}",
            "",
            "Error / Status Message:",
            job.message or "(no error detail)",
            "",
            "Prompt:",
            str(job.meta.get("prompt") or ""),
        ]
        self._report = "\n".join(details)
        ed = QPlainTextEdit(self._report)
        ed.setReadOnly(True)
        lay.addWidget(ed, 1)

        row = QHBoxLayout()
        row.setSpacing(6)
        row.addWidget(make_button("Copy Diagnostics", lambda: QApplication.clipboard().setText(self._report), small=True))
        if job.state == STATE_FAILED and job.kind != KIND_GROUP:
            row.addWidget(make_button("Retry Task Now", self._on_retry, accent=True, small=True))
        row.addStretch(1)
        row.addWidget(make_button("Close", self.accept, small=True))
        lay.addLayout(row)
        clamp_dialog_to_screen(self, 520, 380)

    def _on_retry(self) -> None:
        self.retry_requested.emit(self._job_id)
        self.accept()


class ImageInfoDialog(QDialog):
    def __init__(self, path: str, meta: Dict[str, Any], parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
