        # Per-model Negative Prompt (stored separately for Anima & Krea 2)
        neg_wrap = QWidget()
        neg_wrap.setObjectName("Transparent")
        nl = QVBoxLayout(neg_wrap)
        nl.setContentsMargins(0, 0, 0, 0)
        nl.setSpacing(3)
        self.neg_edit = TagFlowPromptEdit()
