    def _on_prompt_panel_widen(self, dx: int) -> None:
        """Smoothly widen or narrow the left control deck when dragging the 2D corner grip
        on the Prompt input frame, while guaranteeing the right Viewer/Gallery never clips
        even at 800x600 screen resolution."""
        if dx == 0 or not hasattr(self, "split"):
            return
        sizes = self.split.sizes()
        if len(sizes) < 2:
            return
        total = sizes[0] + sizes[1]
        if total <= 0:
            return
        min_left = max(212, self.left.minimumWidth() if hasattr(self, "left") else 212)
        min_right = 248 if self.width() <= 840 else 300
        max_left = max(min_left, total - min_right)
        new_left = max(min_left, min(max_left, sizes[0] + int(dx)))
        if new_left != sizes[0]:
            self.split.setSizes([new_left, max(min_right, total - new_left)])
            self._schedule_workspace_resize()
            self._schedule_save()

    def _on_prompt_panel_reset(self) -> None:
        """Restore comfortable balanced split width after double-clicking the 2D corner grip."""
        if not hasattr(self, "split"):
            return
        sizes = self.split.sizes()
        if len(sizes) < 2:
            return
        total = sizes[0] + sizes[1]
        if total <= 0:
            return
        target_left = max(248, min(336, int(total * (0.40 if self.width() <= 840 else 0.34))))
        self.split.setSizes([target_left, max(248, total - target_left)])
        self._schedule_workspace_resize()
        self._schedule_save()

    def _on_llm_concept_changed(self) -> None:
        if hasattr(self, "llm_concept_tok_lbl") and hasattr(self, "llm_user_edit"):
            tok = estimate_tokens(self.llm_user_edit.toPlainText().strip())
            self.llm_concept_tok_lbl.setText(f"{tok} tok")
        self._llm_schedule_save()

    def _llm_prepare_enhance(self) -> None:
        """Load the active Prompt Editor text into Forge with a crisp refinement directive."""
        src = self.prompt_edit.editable_text().strip()
        if not src:
            src = self.llm_user_edit.toPlainText().strip()
        if not src:
            self.toast.notify("Write a prompt or concept first to enhance", "warn")
            self.llm_user_edit.setFocus()
            return
        self.llm_user_edit.setPlainText(
            f"Refine and elevate this prompt with richer lighting, framing, textures, and composition while preserving its core subject:\n{src}"
        )
        self.llm_user_edit.setFocus()
        SOUNDS.play_ui("ui_click")

    def _llm_inject_variation_count(self, n: int) -> None:
        """Set or update a variation count instruction cleanly inside the Forge concept box."""
        cur = self.llm_user_edit.toPlainText().strip()
        cleaned = re.sub(r"(?i)^\s*(?:write|create|generate)\s+\d+\s+distinct\s+variations?\s+of:\s*", "", cur).strip()
        if cleaned:
            self.llm_user_edit.setPlainText(f"Generate {n} distinct variations of: {cleaned}")
        else:
            self.llm_user_edit.setPlainText(f"Generate {n} distinct variations of: ")
        self.llm_user_edit.moveCursor(QTextCursor.MoveOperation.End)
        self.llm_user_edit.setFocus()
        SOUNDS.play_ui("ui_click")

    def _on_llm_subtab_changed(self, _idx: int) -> None:
        self._llm_schedule_save()

    def _open_llm_api_settings(self) -> None:
        """Jump straight to the LLM / VLM API Settings section inside the Settings tab."""
        self.tabs.setCurrentIndex(TAB_HORDE)
        if hasattr(self, "llm_api_settings_section"):
            self.llm_api_settings_section.set_expanded(True)
            if hasattr(self, "settings_scroll"):
                QTimer.singleShot(25, lambda: self.settings_scroll.ensureWidgetVisible(self.llm_api_settings_section, 8, 28))
        if hasattr(self, "llm_url_edit") and not self.llm_url_edit.text().strip():
            self.llm_url_edit.setFocus()
        elif hasattr(self, "llm_model_combo"):
            self.llm_model_combo.setFocus()

    def _sync_llm_api_banner(self) -> None:
        """Keep the compact LLM tab API banner synced with the Settings tab controls."""
        if not hasattr(self, "llm_api_banner_lbl") or not hasattr(self, "llm_url_edit"):
            return
        url = self.llm_url_edit.text().strip()
        model = self.llm_model_combo.currentText().strip() if hasattr(self, "llm_model_combo") else ""
        vmodel = self.llm_vision_model_combo.currentText().strip() if hasattr(self, "llm_vision_model_combo") else ""
        stream = bool(self.llm_stream_cb.isChecked()) if hasattr(self, "llm_stream_cb") else True
        temp = self.llm_temp_spin.value() if hasattr(self, "llm_temp_spin") else 0.75
        if not url or not model:
            self.llm_api_banner_lbl.setText("API not configured — open Settings to set URL & Model")
            self.llm_api_banner_lbl.setStyleSheet(f"color: {C['warn']}; font-weight: bold;")
            self.llm_api_banner_lbl.setToolTip("Configure OpenAI-compatible LLM / VLM endpoint in Settings")
            return
        host = urllib.parse.urlparse(url).netloc or url
        parts = [model]
        if vmodel and vmodel != model:
            parts.append(f"VLM: {vmodel}")
        parts.append(f"T={temp:.2f}")
        parts.append("SSE" if stream else "Batch")
        self.llm_api_banner_lbl.setText(" \u00b7 ".join(parts))
        self.llm_api_banner_lbl.setStyleSheet(f"color: {C['text_hi']}; font-weight: bold;")
        self.llm_api_banner_lbl.setToolTip(
            f"Endpoint: {host}\nModel: {model}\nVision override: {vmodel or '(main model)'}\n"
            f"Temp: {temp:.2f}  |  Mode: {'SSE Stream' if stream else 'Batch'}"
        )

    def _on_si_sys_edited(self) -> None:
        self._update_si_sys_badge()
        self._llm_schedule_save()

    def _si_reset_system_default(self) -> None:
        self.si_sys_edit.blockSignals(True)
        self.si_sys_edit.setPlainText(DEFAULT_SELF_IMPROVING_SYSTEM_PROMPT)
        self.si_sys_edit.blockSignals(False)
        self._update_si_sys_badge()
        self._llm_schedule_save()
        self.toast.notify("Restored default Self-Improving system prompt", "info")

    def _update_si_sys_badge(self) -> None:
        if not hasattr(self, "si_sys_edit"):
            return
        cur = self.si_sys_edit.toPlainText().strip()
        is_def = (not cur) or (cur == DEFAULT_SELF_IMPROVING_SYSTEM_PROMPT.strip())
        if hasattr(self, "si_sys_badge"):
            self.si_sys_badge.setText("DEFAULT" if is_def else "CUSTOM")
            self.si_sys_badge.setStyleSheet(
                f"color: {C['ok']}; border-color: {C['ok']};"
                if is_def
                else f"color: {C['warn']}; border-color: {C['warn']};"
            )
        if hasattr(self, "si_sys_tok_lbl"):
            tok = estimate_tokens(cur or DEFAULT_SELF_IMPROVING_SYSTEM_PROMPT)
            self.si_sys_tok_lbl.setText(f"~{tok} tok base")

    def _vlm_send_result(self, append: bool = False) -> None:
        txt = self.llm_vlm_result_edit.toPlainText().strip() if hasattr(self, "llm_vlm_result_edit") else ""
        if not txt:
            self._flash_summary("No extracted VLM prompt yet.")
            return
        if append:
            cur = self.prompt_edit.editable_text()
            self.prompt_edit.set_editable_text(append_to_prompt(cur, txt))
        else:
            self.prompt_edit.set_editable_text(txt)
        self.tabs.setCurrentIndex(TAB_PROMPT)
        self._on_prompt_changed()
        self._flash_summary("Appended VLM prompt" if append else "Sent VLM prompt to Prompt tab")

    def _vlm_copy_result(self) -> None:
        txt = self.llm_vlm_result_edit.toPlainText().strip() if hasattr(self, "llm_vlm_result_edit") else ""
        if not txt:
            self._flash_summary("No extracted VLM prompt yet.")
            return
        QApplication.clipboard().setText(txt)
        SOUNDS.play_ui("ui_copy")
        self._flash_summary(f"Copied VLM prompt ({len(txt)} chars)")

    def _vlm_queue_result(self) -> None:
        txt = self.llm_vlm_result_edit.toPlainText().strip() if hasattr(self, "llm_vlm_result_edit") else ""
        if not txt:
            self._flash_summary("No extracted VLM prompt yet.")
            return
        self.on_generate(prompt_override=txt)

    # ---- Vision (VLM) handlers ------------------------------------------------
    # ---- Vision (VLM) & Motion handlers --------------------------------------
    def _llm_vision_mode(self) -> str:
        for mode, b in self.llm_vision_mode_btns.items():
            if b.isChecked():
                return mode
        return "natural"

    def _current_llm_vision_task(self) -> str:
        return "motion" if self._llm_vision_task == "motion" else "describe"

    def _llm_vision_mode_clicked(self, btn: QPushButton) -> None:
        for mode, b in self.llm_vision_mode_btns.items():
            if b is btn:
                self._llm_vision_prompts[self._llm_vision_mode_key] = self.llm_vision_sys_edit.toPlainText()
                self._llm_vision_mode_key = mode
                self._load_vision_prompt_ui()
                self._llm_schedule_save()
                return

    def _llm_motion_mode_clicked(self, btn: QPushButton) -> None:
        for mode, b in self.llm_motion_mode_btns.items():
            if b is btn:
                self._llm_motion_prompts[self._llm_motion_mode_key] = self.llm_vision_sys_edit.toPlainText()
                self._llm_motion_mode_key = mode
                self._load_vision_prompt_ui()
                self._llm_schedule_save()
                return

    def _llm_vision_task_clicked(self, btn: QPushButton) -> None:
        new_task = "motion" if btn is self.llm_vision_task_btns.get("motion") else "describe"
        if new_task == self._llm_vision_task:
            return
        self._store_current_vision_prompt()
        self._llm_vision_task = new_task
        if new_task == "motion":
            self._suggest_motion_mode()
        self._load_vision_prompt_ui()
        self._llm_schedule_save()

    def _suggest_motion_mode(self) -> None:
        """Auto-switch the keyframe mode to the best fit for the attachment
        count (1 -> FIRST FRAME, 2+ -> FIRST + LAST) when the user has not
        pinned a deliberate choice."""
        suggested = suggest_motion_mode(len(self._llm_vision_images))
        if suggested != self._llm_motion_mode_key:
            self._llm_motion_prompts[self._llm_motion_mode_key] = self.llm_vision_sys_edit.toPlainText()
            self._llm_motion_mode_key = suggested

    def _store_current_vision_prompt(self) -> None:
        if self._llm_vision_task == "motion":
            self._llm_motion_prompts[self._llm_motion_mode_key] = self.llm_vision_sys_edit.toPlainText()
        else:
            self._llm_vision_prompts[self._llm_vision_mode_key] = self.llm_vision_sys_edit.toPlainText()

    def _load_vision_prompt_ui(self) -> None:
        self.llm_vision_sys_edit.blockSignals(True)
        try:
            if self._llm_vision_task == "motion":
                mode = self._llm_motion_mode_key
                self.llm_vision_task_btns["motion"].setChecked(True)
                self.llm_vision_mode_btns.get(self._llm_vision_mode_key, self.llm_vision_mode_btns["natural"]).setChecked(True)
                self.llm_motion_mode_btns.get(mode, self.llm_motion_mode_btns["i2va"]).setChecked(True)
                self.llm_vision_sys_edit.setPlainText(self._llm_motion_prompts.get(mode, ""))
                self.llm_vision_run_btn.setText("MAKE MOTION PROMPT")
                self.llm_vision_run_btn.setIcon(VECTOR_ASSETS.icon("film", 13))
                self.llm_vision_run_btn.setToolTip(
                    "Forge a structured video prompt (I2VA / FL2VA / References grammar)\n"
                    "with camera language, diegetic sound and non-diegetic music fields."
                )
                self.llm_vision_sys_section.header.set_title(
                    f"Motion System Prompt [{VIDEO_MOTION_LABELS.get(mode, 'FIRST FRAME')}]"
                )
                self._sync_vision_rows_visibility()
                return
            mode = self._llm_vision_mode_key
            self.llm_vision_task_btns["describe"].setChecked(True)
            self.llm_vision_mode_btns.get(mode, self.llm_vision_mode_btns["natural"]).setChecked(True)
            self.llm_motion_mode_btns.get(self._llm_motion_mode_key, self.llm_motion_mode_btns["i2va"]).setChecked(True)
            self.llm_vision_sys_edit.setPlainText(self._llm_vision_prompts.get(mode, ""))
            self.llm_vision_run_btn.setText("EXTRACT PROMPT")
            self.llm_vision_run_btn.setIcon(VECTOR_ASSETS.icon("eye", 13))
            self.llm_vision_run_btn.setToolTip(
                "Caption the attached image(s) into ONE single-line text-to-image prompt "
                "(output grammar follows the selected mode)"
            )
            self.llm_vision_sys_section.header.set_title(
                f"VLM System Prompt [{VISION_MODE_LABELS.get(mode, 'NATURAL')}]"
            )
            self._sync_vision_rows_visibility()
        finally:
            self.llm_vision_sys_edit.blockSignals(False)

    def _sync_vision_rows_visibility(self) -> None:
        """Show the grammar row (DESCRIBE) or the keyframe row (MOTION)."""
        motion = self._llm_vision_task == "motion"
        for _mode, b in self.llm_vision_mode_btns.items():
            b.setVisible(not motion)
        for _mode, b in self.llm_motion_mode_btns.items():
            b.setVisible(motion)

    def _llm_vision_sys_edited(self) -> None:
        self._store_current_vision_prompt()
        self._llm_schedule_save()

    def _llm_vision_reset_default(self) -> None:
        if self._llm_vision_task == "motion":
            self._llm_motion_prompts[self._llm_motion_mode_key] = build_default_motion_prompt(self._llm_motion_mode_key)
        else:
            self._llm_vision_prompts[self._llm_vision_mode_key] = build_default_vision_prompt(self._llm_vision_mode_key)
        self._load_vision_prompt_ui()
        self._llm_schedule_save()
        self.toast.notify("Restored default VLM system prompt", "info")

    # ---- attachments ----------------------------------------------------------
    def _llm_vision_attach(self, path: Optional[str]) -> None:
        if not path or not os.path.isfile(path) or is_depth_image_path(path):
            return
        if len(self._llm_vision_images) >= 4:
            self._flash_summary("Up to 4 VLM images can be attached at once.")
            return
        if path not in self._llm_vision_images:
            self._llm_vision_images.append(path)
        self._llm_vision_refresh_attachments()
        if hasattr(self, "llm_subtabs"):
            self.llm_subtabs.setCurrentIndex(1)
        img = QImage(path)
        dim = f"{img.width()}x{img.height()}" if not img.isNull() else "?"
        self._llm_vision_status_info(
            f"Attached {len(self._llm_vision_images)} image(s) - last: {os.path.basename(path)} ({dim})"
        )

    def _llm_vision_refresh_attachments(self) -> None:
        lst = self.llm_vision_attach_list
        lst.clear()
        n_att = len(self._llm_vision_images)
        lst.setVisible(n_att > 0)
        if hasattr(self, "llm_vision_count_chip"):
            self.llm_vision_count_chip.setText(f"{n_att}/4")
        motion = self._llm_vision_task == "motion"
        mode = self._llm_motion_mode_key
        for i, path in enumerate(self._llm_vision_images):
            reader = QImageReader(path)
            reader.setAutoTransform(True)
            rsz = reader.size()
            if rsz.isValid() and (rsz.width() > 64 or rsz.height() > 56):
                sc = min(64.0 / max(1, rsz.width()), 56.0 / max(1, rsz.height()))
                reader.setScaledSize(QSize(max(1, int(round(rsz.width() * sc))), max(1, int(round(rsz.height() * sc)))))
            qimg = reader.read()
            pm = QPixmap.fromImage(qimg) if not qimg.isNull() else QPixmap()
            it = QListWidgetItem()
            it.setIcon(QIcon(pm) if not pm.isNull() else VECTOR_ASSETS.icon("image", 24))
            it.setData(Qt.ItemDataRole.UserRole, path)
            if motion:
                if mode == "i2va":
                    role = "first frame" if i == 0 else f"reference {i}"
                elif mode == "fl2va":
                    role = "first frame" if i == 0 else ("last frame" if i == 1 else f"reference {i - 1}")
                else:
                    role = f"reference {i + 1}"
            else:
                role = f"image {i + 1}"
            it.setText(role.upper())
            it.setToolTip(f"{os.path.basename(path)}\nrole: {role}")
            lst.addItem(it)
        if self._llm_vision_task == "motion" and not self._loading:
            self._suggest_motion_mode()
            self._load_vision_prompt_ui()
            self._llm_schedule_save()

    def _llm_vision_attach_menu(self, pos: QPoint) -> None:
        it = self.llm_vision_attach_list.itemAt(pos)
        m = QMenu(self)
        if it is not None:
            row = self.llm_vision_attach_list.row(it)
            if row > 0:
                m.addAction("Move Left", lambda: self._llm_vision_move(row, -1))
            if row < len(self._llm_vision_images) - 1:
                m.addAction("Move Right", lambda: self._llm_vision_move(row, 1))
            m.addAction("Remove", lambda: self._llm_vision_remove(row))
        m.addAction("Clear All", self._llm_vision_clear)
        m.exec(self.llm_vision_attach_list.viewport().mapToGlobal(pos))

    def _llm_vision_move(self, row: int, delta: int) -> None:
        tgt = row + delta
        if 0 <= row < len(self._llm_vision_images) and 0 <= tgt < len(self._llm_vision_images):
            self._llm_vision_images[row], self._llm_vision_images[tgt] = (
                self._llm_vision_images[tgt], self._llm_vision_images[row]
            )
            self._llm_vision_refresh_attachments()

    def _llm_vision_remove(self, row: int) -> None:
        if 0 <= row < len(self._llm_vision_images):
            self._llm_vision_images.pop(row)
            self._llm_vision_refresh_attachments()

    def _llm_vision_status_info(self, text: str) -> None:
        """Fold vision source info into the main LLM status line."""
        self.llm_status.setText(text)

    def _llm_vision_from_viewer(self) -> None:
        path = self._current_image()
        if not path:
            self._flash_summary("Open an image in the viewer first.")
            return
        self._llm_vision_attach(path)

    def _llm_vision_open(self) -> None:
        path, _f = QFileDialog.getOpenFileName(
            self, "Select VLM source image", OUTPUT_DIR, "Images (*.png *.webp *.jpg *.jpeg)"
        )
        if path:
            self._llm_vision_attach(path)

    def _llm_vision_paste(self) -> None:
        """Attach an image straight from the system clipboard."""
        img = QApplication.clipboard().image()
        if img.isNull():
            self._flash_summary("Clipboard does not contain an image.")
            return
        ensure_dirs()
        path = os.path.join(SCRATCH_DIR, f"vlm_paste_{time.strftime('%Y%m%d_%H%M%S')}.png")
        if not img.save(path, "PNG"):
            self._flash_summary("Could not save the clipboard image.")
            return
        self._llm_vision_attach(path)
        self._flash_summary(f"Pasted from clipboard \u2192 {os.path.basename(path)}")

    def _llm_vision_clear(self) -> None:
        self._llm_vision_images.clear()
        self._llm_vision_source = None
        self._llm_vision_refresh_attachments()
        self._llm_vision_status_info("No VLM images attached.")

    def _send_image_to_vlm(self, path: Optional[str]) -> None:
        """Attach an image (viewer / gallery / drag-drop) and switch straight to the Vision (VLM) inner tab."""
        if not path or not os.path.isfile(path):
            return
        self._llm_vision_attach(path)
        self.tabs.setCurrentIndex(TAB_LLM)
        if hasattr(self, "llm_subtabs"):
            self.llm_subtabs.setCurrentIndex(1)
        self._flash_summary(f"VLM attached: {os.path.basename(path)} - choose a task & run")

    # ---- extraction --------------------------------------------------------------
    def _llm_vision_extract(self) -> None:
        """Run the active vision task: DESCRIBE (t2i prompt, single line) or
        MOTION (structured video prompt)."""
        if not self._llm_vision_images:
            self.llm_status.setText("Attach at least one image (drop / VIEWER / PASTE) first.")
            return
        self._store_current_vision_prompt()
        model = self.llm_vision_model_combo.currentText().strip() or self.llm_model_combo.currentText().strip()
        base = self.llm_url_edit.text().strip()
        key = self.llm_key_edit.text().strip()
        if not base or not model:
            self.llm_status.setText("Configure LLM / VLM API URL and Model in Settings first.")
            self.toast.notify("Configure LLM / VLM URL & Model in Settings", "warn")
            self._open_llm_api_settings()
            return
        images = list(self._llm_vision_images)
        if self._llm_vision_task == "motion":
            self._llm_motion_extract(base, key, model, images)
        else:
            self._llm_describe_extract(base, key, model, images)

    def _llm_describe_extract(self, base: str, key: str, model: str, images: List[str]) -> None:
        mode = self._llm_vision_mode_key
        system = self._llm_vision_prompts.get(mode) or build_default_vision_prompt(mode)
        n_txt = "image" if len(images) == 1 else f"{len(images)} images"
        note = self.llm_vlm_note_edit.text().strip() if hasattr(self, "llm_vlm_note_edit") else ""
        instruction = (
            "Caption this image as ONE text-to-image prompt following your instructions exactly."
            if len(images) == 1
            else f"Caption the FIRST of the {len(images)} attached images as ONE text-to-image "
                 "prompt following your instructions exactly; use the others only as context."
        )
        if note:
            instruction += f"\nAdditional user focus note: {note}"
        self._start_llm_stream(
            task_kind="describe",
            base_url=base,
            api_key=key,
            model=model,
            system=system,
            user_text=instruction,
            temperature=min(0.5, max(0.0, self.llm_temp_spin.value())),
            top_p=self.llm_topp_spin.value(),
            image_paths=images,
            tag="",
            mode_label=VISION_MODE_LABELS[mode],
            clear_existing=False,
            status_start=f"Streaming vision caption for {n_txt} [{VISION_MODE_LABELS[mode]}]\u2026",
            timeout=240.0,
        )

    def _llm_motion_extract(self, base: str, key: str, model: str, images: List[str]) -> None:
        """Stream-forge a structured video prompt (I2VA / FL2VA / References) from
        attached keyframe(s) + optional user guidance."""
        mode = self._llm_motion_mode_key
        if mode == "fl2va" and len(images) < 2:
            self.llm_status.setText("FIRST + LAST frame mode needs TWO attached images (or switch mode).")
            return
        system = self._llm_motion_prompts.get(mode) or build_default_motion_prompt(mode)
        note = self.llm_vlm_note_edit.text().strip() if hasattr(self, "llm_vlm_note_edit") else ""
        concept = note or self.llm_user_edit.toPlainText().strip()
        if not concept:
            concept = "A short, natural continuation of the attached keyframe(s) - your choice of motion; keep it tasteful and cinematic."
        n_txt = "image" if len(images) == 1 else f"{len(images)} images"
        instruction = (
            f"Active mode: {VIDEO_MOTION_LABELS[mode]}. Attached images: {len(images)}. "
            f"Desired video content from the user:\n{concept}\n\n"
            "Write the final video prompt now, following your instructions exactly."
        )
        self._start_llm_stream(
            task_kind="motion",
            base_url=base,
            api_key=key,
            model=model,
            system=system,
            user_text=instruction,
            temperature=min(0.8, max(0.1, self.llm_temp_spin.value())),
            top_p=self.llm_topp_spin.value(),
            image_paths=images,
            tag="MOTION",
            mode_label=VIDEO_MOTION_LABELS[mode],
            clear_existing=False,
            status_start=f"Streaming motion prompt [{VIDEO_MOTION_LABELS[mode]}] from {n_txt}\u2026",
            timeout=300.0,
        )

    # ---- Tab 6: Queue & In-Memory Diagnostic Logs ---------------------------
    def _build_queue_tab(self) -> QWidget:
        w = QWidget()
        lay = QVBoxLayout(w)
        lay.setContentsMargins(7, 7, 7, 7)
        lay.setSpacing(5)

        self.queue_split = QSplitter(Qt.Orientation.Vertical)
        self.queue_split.setObjectName("VSplit")

        queue_box = QWidget()
        queue_box.setObjectName("Transparent")
        ql = QVBoxLayout(queue_box)
        ql.setContentsMargins(0, 0, 0, 0)
        ql.setSpacing(5)

        hdr = SectionHeader("Request Queue")
        self.pause_btn = QToolButton()
        self.pause_btn.setObjectName("Small")
        self.pause_btn.setText("PAUSE")
        self.pause_btn.setCheckable(True)
        self.pause_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        self.pause_btn.toggled.connect(self._on_pause_toggled)
        hdr.add_right(self.pause_btn)
        ql.addWidget(hdr)

        # v12: Live Offline / Auto-Reconnecting Status Banner (hidden while online)
        self.offline_banner = QFrame()
        self.offline_banner.setObjectName("OfflineBanner")
        ob_lay = QHBoxLayout(self.offline_banner)
        ob_lay.setContentsMargins(7, 4, 6, 4)
        ob_lay.setSpacing(6)
        self.offline_banner_icon = QLabel()
        self.offline_banner_icon.setFixedSize(18, 18)
        self.offline_banner_icon.setPixmap(ANIM_ASSETS.pixmap("anim_reconnecting", 0, 18))
        self.offline_banner_lbl = ElideLabel("OFFLINE — holding queued tasks & auto-reconnecting…")
        self.offline_banner_lbl.setStyleSheet("font-weight: bold;")
        self.offline_retry_btn = make_button(
            "Retry Now", self.queue.retry_network_now, small=True,
            tip="Immediately test connectivity and wake waiting tasks",
            icon_key="reconnect", icon_size=12,
        )
        ob_lay.addWidget(self.offline_banner_icon, 0)
        ob_lay.addWidget(self.offline_banner_lbl, 1)
        ob_lay.addWidget(self.offline_retry_btn, 0)
        self.offline_banner.setVisible(False)
        ql.addWidget(self.offline_banner)

        self.queue_view = QListView()
        self.queue_view.setModel(self.queue)
        self.queue_view.setItemDelegate(QueueDelegate(False, self.queue_view))
        self.queue_view.setSelectionMode(QAbstractItemView.SelectionMode.SingleSelection)
        self.queue_view.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.queue_view.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        self.queue_view.customContextMenuRequested.connect(lambda pos: self._queue_menu(pos, self.queue_view))
        self.queue_view.doubleClicked.connect(self._queue_show_result)
        self.queue_view.clicked.connect(self._queue_clicked)
        ql.addWidget(self.queue_view, 1)

        r1 = QHBoxLayout()
        r1.setSpacing(3)
        r1.addWidget(make_button("Cancel", lambda: self._queue_act("cancel"), small=True, compress=True), 2)
        r1.addWidget(make_button("Retry", lambda: self._queue_act("retry"), small=True, compress=True), 2)
        r1.addWidget(make_button("Del", lambda: self._queue_act("remove"), small=True, compress=True), 2)
        r1.addWidget(make_button("\u25B2", lambda: self._queue_act("up"), small=True, compress=True,
                                 tip="Move selected queued job earlier"), 1)
        r1.addWidget(make_button("\u25BC", lambda: self._queue_act("down"), small=True, compress=True,
                                 tip="Move selected queued job later"), 1)
        ql.addLayout(r1)
        r1b = QHBoxLayout()
        r1b.setSpacing(3)
        self.queue_maint_btn = QToolButton()
        self.queue_maint_btn.setObjectName("Small")
        self.queue_maint_btn.setText("MAINTENANCE \u25BE")
        self.queue_maint_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        self.queue_maint_btn.setPopupMode(QToolButton.ToolButtonPopupMode.InstantPopup)
        self.queue_maint_btn.setToolTip("Queue maintenance: clear finished, retry failed, cancel everything")
        mm = QMenu(self.queue_maint_btn)
        mm.addAction("Clear Finished", self.queue.clear_finished)
        mm.addAction("Retry Failed", self.retry_failed)
        mm.addAction("Cancel All\u2026", self.cancel_all)
        self.queue_maint_btn.setMenu(mm)
        self.queue_retry_failed_btn = make_button(
            "Retry Failed", self.retry_failed, small=True, accent=True, compress=True,
            tip="Immediately re-queue every failed task",
        )
        self.queue_retry_failed_btn.setVisible(False)
        r1b.addWidget(self.queue_maint_btn)
        r1b.addWidget(self.queue_retry_failed_btn)
        r1b.addStretch(1)
        ql.addLayout(r1b)

        # Structured In-Memory Diagnostic Console (Horde & LLM API error handling)
        log_box = QWidget()
        log_box.setObjectName("Transparent")
        ll = QVBoxLayout(log_box)
        ll.setContentsMargins(0, 2, 0, 0)
        ll.setSpacing(3)
        fbar = QHBoxLayout()
        fbar.setSpacing(3)
        self.log_filter_combo = QComboBox()
        self.log_filter_combo.addItems(["ALL", "HORDE", "LLM", "BRIDGE", "ST", "UPSCALE", "SYS"])
        self.log_filter_combo.currentIndexChanged.connect(lambda _i: self._refresh_log_console())
        self.log_level_combo = QComboBox()
        self.log_level_combo.addItems(["ALL", "ERROR", "WARN", "NET", "OK", "INFO"])
        self.log_level_combo.setCurrentText("ALL")
        self.log_level_combo.currentIndexChanged.connect(lambda _i: self._refresh_log_console())
        fbar.addWidget(self.log_filter_combo)
        fbar.addWidget(self.log_level_combo)
        fbar.addStretch(1)
        ll.addLayout(fbar)
        fbar2 = QHBoxLayout()
        fbar2.setSpacing(3)
        self.log_search_edit = QLineEdit()
        self.log_search_edit.setPlaceholderText("Filter log text\u2026")
        self.log_search_edit.setClearButtonEnabled(True)
        self.log_search_edit.textChanged.connect(lambda _t: self._refresh_log_console())
        self.log_autoscroll_btn = QToolButton()
        self.log_autoscroll_btn.setObjectName("Small")
        self.log_autoscroll_btn.setText("AUTO")
        self.log_autoscroll_btn.setCheckable(True)
        self.log_autoscroll_btn.setChecked(True)
        self.log_autoscroll_btn.setToolTip("Auto-scroll the console to newest entries")
        fbar2.addWidget(self.log_search_edit, 1)
        fbar2.addWidget(self.log_autoscroll_btn)
        fbar2.addWidget(make_button("COPY", lambda: QApplication.clipboard().setText(self.log_edit.toPlainText()), small=True,
                                  tip="Copy the visible log to the clipboard"))
        fbar2.addWidget(make_button("CLEAR", self._clear_logs, small=True))
        ll.addLayout(fbar2)

        self.log_edit = QPlainTextEdit()
        self.log_edit.setObjectName("SmallEdit")
        self.log_edit.setReadOnly(True)
        self.log_edit.setMaximumBlockCount(1400)
        self.log_edit.setMinimumHeight(95)
        ll.addWidget(self.log_edit, 1)
        # v11: logs start MINIMIZED — the whole tab belongs to the active
        # task list; the log console is one click away when needed.
        self.log_section = CollapsibleSection("In-Memory Backend Logs (Horde & LLM)", log_box, expanded=False)
        self.log_section.toggled.connect(lambda _b: self._schedule_save())

        self.queue_split.addWidget(queue_box)
        self.queue_split.addWidget(self.log_section)
        self.queue_split.setStretchFactor(0, 7)
        self.queue_split.setStretchFactor(1, 3)
        lay.addWidget(self.queue_split, 1)

        self.queue.image_ready.connect(self.on_image_ready)
        self.queue.job_finished.connect(self._on_queue_job_finished)
        self.queue.summary_changed.connect(self._update_summary)
        self.queue.rowsInserted.connect(lambda *_a: self._update_summary())
        self.queue.rowsRemoved.connect(lambda *_a: self._update_summary())
        self.queue.modelReset.connect(self._update_summary)
        return w

    # ---- Tab 7: Horde, Bridge VPN & SillyTavern -----------------------------
    def _horde_group(self, title: str, build: Callable[[QVBoxLayout], None], expanded: bool = False) -> CollapsibleSection:
        inner = QWidget()
        inner.setObjectName("Transparent")
        gl = QVBoxLayout(inner)
        gl.setContentsMargins(2, 4, 2, 2)
        gl.setSpacing(4)
        build(gl)
        return CollapsibleSection(title, inner, expanded=expanded)

    def _build_horde_tab(self) -> QWidget:
        scroll, lay = self._scroll_tab()
        self.settings_scroll = scroll

        # ---- 1. Appearance, 7-Theme Swatch Gallery, UI Scale & Theme Sound Scheme ----
        def build_sounds(g: QVBoxLayout) -> None:
            # Interactive Visual 7-Theme Swatch Gallery (zero horizontal overflow at 800x600!)
            th_kick = ElideLabel("Theme Gallery (7 Themes \u00b7 Click to Apply)")
            th_kick.setObjectName("Kicker")
            g.addWidget(th_kick)
            self._theme_swatch_flow = FlowContainer(hgap=4, vgap=4)
            self._theme_swatch_cards: Dict[str, ThemeSwatchCard] = {}
            self._theme_swatch_group = QButtonGroup(self)
            self._theme_swatch_group.setExclusive(True)
            for tkey in THEME_ORDER:
                card = ThemeSwatchCard(tkey)
                card.clicked.connect(lambda _c=False, tk=tkey: self._select_theme_by_key(tk))
                self._theme_swatch_group.addButton(card)
                self._theme_swatch_cards[tkey] = card
                self._theme_swatch_flow.add_widget(card)
            g.addWidget(self._theme_swatch_flow)

            # Synced Theme dropdown + UI Scale % dropdown + Theme Chime Audition button
            top_g = QGridLayout()
            top_g.setHorizontalSpacing(4)
            top_g.setVerticalSpacing(4)
            self.settings_theme_combo = QComboBox()
            self.settings_theme_combo.setMinimumWidth(0)
            self.settings_theme_combo.setSizeAdjustPolicy(QComboBox.SizeAdjustPolicy.AdjustToMinimumContentsLengthWithIcon)
            self.settings_theme_combo.setMinimumContentsLength(6)
            self.settings_theme_combo.setCursor(Qt.CursorShape.PointingHandCursor)
            for tkey in THEME_ORDER:
                self.settings_theme_combo.addItem(
                    VECTOR_ASSETS.icon_for_theme("theme_badge", tkey, 14),
                    str(THEMES[tkey]["name"]),
                    tkey,
                )
            self.settings_theme_combo.currentIndexChanged.connect(self._on_settings_theme_combo_changed)
            self.settings_theme_chime_btn = make_button(
                "\u266A Sampler", lambda: self._audition_suite(), small=True,
                tip="Audition a six-cue sampler of the active theme's sound scheme",
            )
            self.settings_scale_combo = QComboBox()
            self.settings_scale_combo.setMinimumWidth(0)
            self.settings_scale_combo.setSizeAdjustPolicy(QComboBox.SizeAdjustPolicy.AdjustToMinimumContentsLengthWithIcon)
            self.settings_scale_combo.setMinimumContentsLength(4)
            self.settings_scale_combo.setCursor(Qt.CursorShape.PointingHandCursor)
            for pct in UI_SCALE_PRESETS:
                self.settings_scale_combo.addItem(f"{pct}%", pct)
            self.settings_scale_combo.setToolTip("Select interface scale percentage (75%\u2013150%)")
            self.settings_scale_combo.currentIndexChanged.connect(self._on_settings_scale_combo_changed)
            top_g.addWidget(make_label("Theme", "Caption"), 0, 0)
            top_g.addWidget(self.settings_theme_combo, 0, 1)
            top_g.addWidget(self.settings_theme_chime_btn, 0, 2)
            top_g.addWidget(make_label("Scale", "Caption"), 1, 0)
            top_g.addWidget(self.settings_scale_combo, 1, 1, 1, 2)
            top_g.setColumnStretch(1, 1)
            g.addLayout(top_g)

            # Three-option audio policy + Windows Plus! per-theme sound scheme banner + dual mixer
            mode_card = QFrame()
            mode_card.setObjectName("SoundModeCard")
            mc_lay = QVBoxLayout(mode_card)
            mc_lay.setContentsMargins(6, 5, 6, 5)
            mc_lay.setSpacing(3)
            sm_kick = ElideLabel("Sound Scheme")
            sm_kick.setObjectName("Kicker")
            mc_lay.addWidget(sm_kick)
            self.sound_theme_tagline = make_label(
                sound_scheme_caption(theme_name()),
                "Caption",
            )
            self.sound_theme_tagline.setWordWrap(True)
            mc_lay.addWidget(self.sound_theme_tagline)
            self.sound_mode_group = QButtonGroup(self)
            self.sound_mode_group.setExclusive(True)
            self.sound_mode_radios: Dict[str, QRadioButton] = {}
            for mkey, mlabel, mtip in SOUND_MODES:
                rb = QRadioButton(mlabel)
                rb.setMinimumWidth(0)
                rb.setCursor(Qt.CursorShape.PointingHandCursor)
                rb.setToolTip(mtip)
                rb.toggled.connect(lambda checked, mk=mkey: self._on_sound_mode_radio(mk, checked))
                self.sound_mode_group.addButton(rb)
                self.sound_mode_radios[mkey] = rb
                mc_lay.addWidget(rb)
            self.sound_mode_desc = make_label("", "Caption")
            self.sound_mode_desc.setWordWrap(True)
            mc_lay.addWidget(self.sound_mode_desc)

            vol_g = QGridLayout()
            vol_g.setHorizontalSpacing(4)
            vol_g.setVerticalSpacing(2)
            self.sound_master_sl = _ResettableSlider(Qt.Orientation.Horizontal, default_value=85)
            self.sound_master_sl.setMinimumWidth(36)
            self.sound_master_sl.setRange(0, 100)
            self.sound_master_sl.setValue(int(round(SOUNDS.master_volume * 100)))
            self.sound_master_sl.setToolTip("Master sound volume (double-click to reset to 85%)")
            self.sound_master_val = make_label(f"{self.sound_master_sl.value()}%", "Value")
            self.sound_master_val.setFixedWidth(32)
            self.sound_master_val.setAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
            self.sound_ui_sl = _ResettableSlider(Qt.Orientation.Horizontal, default_value=78)
            self.sound_ui_sl.setMinimumWidth(36)
            self.sound_ui_sl.setRange(0, 100)
            self.sound_ui_sl.setValue(int(round(SOUNDS.ui_sfx_volume * 100)))
            self.sound_ui_sl.setToolTip("Secondary UI menu SFX volume relative to master (double-click to reset to 78%)")
            self.sound_ui_val = make_label(f"{self.sound_ui_sl.value()}%", "Value")
            self.sound_ui_val.setFixedWidth(32)
            self.sound_ui_val.setAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
            self.sound_master_sl.valueChanged.connect(self._on_sound_volumes_changed)
            self.sound_ui_sl.valueChanged.connect(self._on_sound_volumes_changed)
            vol_g.addWidget(make_label("Master", "Caption"), 0, 0)
            vol_g.addWidget(self.sound_master_sl, 0, 1)
            vol_g.addWidget(self.sound_master_val, 0, 2)
            vol_g.addWidget(make_label("UI SFX", "Caption"), 1, 0)
            vol_g.addWidget(self.sound_ui_sl, 1, 1)
            vol_g.addWidget(self.sound_ui_val, 1, 2)
            vol_g.setColumnStretch(1, 1)
            mc_lay.addLayout(vol_g)
            g.addWidget(mode_card)

            # Soft videogame-menu UI SFX audition strip for active theme
            sfx_cap = ElideLabel("Audition Interface Sounds")
            sfx_cap.setObjectName("Caption")
            g.addWidget(sfx_cap)
            sfx_flow = FlowContainer(hgap=3, vgap=3)
            for sfx_key in (
                "ui_hover", "ui_click", "ui_toggle_on", "ui_toggle_off",
                "ui_tab", "ui_subtab", "ui_menu_open", "ui_dropdown",
                "ui_menu_hover", "ui_slider", "ui_dialog_open", "ui_dialog_close",
                "ui_copy", "ui_delete", "ui_resize", "theme",
            ):
                b_sfx = make_button(
                    UI_SFX_LABELS[sfx_key],
                    lambda _c=False, e=sfx_key: self._audition_sound(e),
                    small=True,
                    tip=f"Audition active theme's '{UI_SFX_LABELS[sfx_key]}' secondary UI SFX",
                )
                sfx_flow.add_widget(b_sfx)
            g.addWidget(sfx_flow)
            self.sound_test_status = make_label("Click any cue to audition it at the current volumes.", "Caption")
            self.sound_test_status.setWordWrap(True)
            g.addWidget(self.sound_test_status)

            # Primary notification individual toggles + TEST buttons
            pri_cap = ElideLabel("Notification Sounds (toggle / TEST)")
            pri_cap.setObjectName("Caption")
            g.addWidget(pri_cap)
            self.sound_event_checks: Dict[str, QCheckBox] = {}
            sgrid = QGridLayout()
            sgrid.setHorizontalSpacing(4)
            sgrid.setVerticalSpacing(2)
            for i, ev in enumerate(SOUND_EVENT_LABELS):
                cb = QCheckBox(SOUND_EVENT_LABELS[ev])
                cb.setMinimumWidth(0)
                cb.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Fixed)
                cb.setCursor(Qt.CursorShape.PointingHandCursor)
                cb.setToolTip(f"Toggle primary notification sound: {SOUND_EVENT_LABELS[ev]}")
                cb.toggled.connect(lambda _v: self._on_sound_prefs_changed())
                self.sound_event_checks[ev] = cb
                sgrid.addWidget(cb, i, 0)
                sgrid.addWidget(make_button("TEST", lambda _c=False, e=ev: self._audition_sound(e), small=True,
                                            tip=f"Audition: {SOUND_EVENT_LABELS[ev]}"), i, 1)
            sgrid.setColumnStretch(0, 1)
            g.addLayout(sgrid)
            self.sound_backend_lbl = make_label(
                f"Engine: {SOUNDS.backend_label()} \u2022 {len(THEME_ORDER)} themes \u00d7 {len(SOUNDS.ALL_EVENTS)} embedded DSP cues",
                "Caption",
            )
            self.sound_backend_lbl.setWordWrap(True)
            g.addWidget(self.sound_backend_lbl)

        lay.addWidget(self._horde_group("Appearance, 7 Themes & Sound Scheme", build_sounds, expanded=True))

        # ---- 2. OpenAI-Compatible LLM / VLM API Settings (shared by Forge, Vision & Arena) ----
        def build_llm_api(g: QVBoxLayout) -> None:
            prow = QHBoxLayout()
            prow.setSpacing(3)
            for plbl, purl, ptip in (
                ("LM Studio", "http://127.0.0.1:1234/v1", "Local LM Studio OpenAI-compatible server"),
                ("Ollama", "http://127.0.0.1:11434/v1", "Local Ollama OpenAI-compatible server"),
                ("OpenRouter", "https://openrouter.ai/api/v1", "OpenRouter unified cloud LLM/VLM gateway"),
                ("OpenAI", "https://api.openai.com/v1", "Official OpenAI API endpoint"),
            ):
                pb = make_button(
                    plbl,
                    lambda _c=False, u=purl: self._apply_llm_endpoint_preset(u),
                    small=True, compress=True, tip=f"Fill {ptip}\n{purl}",
                )
                prow.addWidget(pb, 1)
            g.addLayout(prow)

            lg = QGridLayout()
            lg.setHorizontalSpacing(5)
            lg.setVerticalSpacing(4)

            self.llm_url_edit = QLineEdit()
            self.llm_url_edit.setMinimumWidth(0)
            self.llm_url_edit.setPlaceholderText("http://127.0.0.1:1234/v1  or  https://openrouter.ai/api/v1")
            self.llm_url_edit.setToolTip("OpenAI-compatible /v1 API base URL (used for Prompt Forge, Vision VLM & Self-Improving Arena)")
            self.llm_url_edit.textChanged.connect(self._on_llm_api_field_changed)

            self.llm_key_edit = QLineEdit()
            self.llm_key_edit.setEchoMode(QLineEdit.EchoMode.Password)
            self.llm_key_edit.setPlaceholderText("Optional Bearer API key (leave blank for local servers)")
            self.llm_key_edit.textChanged.connect(self._on_llm_api_field_changed)
            self.llm_key_reveal_btn = QToolButton()
            self.llm_key_reveal_btn.setObjectName("Small")
            self.llm_key_reveal_btn.setText("SHOW")
            self.llm_key_reveal_btn.setCheckable(True)
            self.llm_key_reveal_btn.setFixedWidth(52)
            self.llm_key_reveal_btn.setCursor(Qt.CursorShape.PointingHandCursor)
            self.llm_key_reveal_btn.setToolTip("Show / hide LLM API key")
            self.llm_key_reveal_btn.toggled.connect(self._on_llm_key_reveal)
            kbox = QHBoxLayout()
            kbox.setSpacing(3)
            kbox.addWidget(self.llm_key_edit, 1)
            kbox.addWidget(self.llm_key_reveal_btn, 0)

            self.llm_model_combo = QComboBox()
            self.llm_model_combo.setEditable(True)
            self.llm_model_combo.setSizeAdjustPolicy(QComboBox.SizeAdjustPolicy.AdjustToMinimumContentsLengthWithIcon)
            self.llm_model_combo.setMinimumContentsLength(8)
            self.llm_model_combo.setToolTip("Primary LLM model ID for Prompt Forge & Self-Improving Arena")
            self.llm_model_combo.editTextChanged.connect(self._on_llm_api_field_changed)
            self.llm_models_btn = make_button(
                "FETCH", self.llm_fetch_models, small=True, accent=True,
                tip="Query /models on the configured endpoint to populate the model lists",
            )
            mbox = QHBoxLayout()
            mbox.setSpacing(3)
            mbox.addWidget(self.llm_model_combo, 1)
            mbox.addWidget(self.llm_models_btn, 0)

            self.llm_vision_model_combo = QComboBox()
            self.llm_vision_model_combo.setEditable(True)
            self.llm_vision_model_combo.setSizeAdjustPolicy(QComboBox.SizeAdjustPolicy.AdjustToMinimumContentsLengthWithIcon)
            self.llm_vision_model_combo.setMinimumContentsLength(8)
            self.llm_vision_model_combo.setToolTip("Optional dedicated Vision (VLM) model override — leave blank to use the primary model")
            self.llm_vision_model_combo.editTextChanged.connect(self._on_llm_api_field_changed)

            lg.addWidget(make_label("API URL", "Caption"), 0, 0)
            lg.addWidget(self.llm_url_edit, 0, 1)
            lg.addWidget(make_label("API Key", "Caption"), 1, 0)
            lg.addLayout(kbox, 1, 1)
            lg.addWidget(make_label("Model", "Caption"), 2, 0)
            lg.addLayout(mbox, 2, 1)
            lg.addWidget(make_label("Vision VLM", "Caption"), 3, 0)
            lg.addWidget(self.llm_vision_model_combo, 3, 1)
            lg.setColumnStretch(1, 1)
            g.addLayout(lg)

            # Sampling controls row
            sg = QGridLayout()
            sg.setHorizontalSpacing(5)
            sg.setVerticalSpacing(4)
            self.llm_temp_spin = QDoubleSpinBox()
            self.llm_temp_spin.setRange(0.0, 2.0)
            self.llm_temp_spin.setSingleStep(0.05)
            self.llm_temp_spin.setDecimals(2)
            self.llm_temp_spin.setValue(0.75)
            self.llm_temp_spin.setPrefix("T ")
            self.llm_temp_spin.setToolTip("Sampling temperature (0.0 = deterministic, 0.7–0.9 = creative)")
            self.llm_temp_spin.valueChanged.connect(self._on_llm_api_field_changed)

            self.llm_topp_spin = QDoubleSpinBox()
            self.llm_topp_spin.setRange(0.05, 1.0)
            self.llm_topp_spin.setSingleStep(0.02)
            self.llm_topp_spin.setDecimals(2)
            self.llm_topp_spin.setValue(0.92)
            self.llm_topp_spin.setPrefix("P ")
            self.llm_topp_spin.setToolTip("Nucleus sampling top-p")
            self.llm_topp_spin.valueChanged.connect(self._on_llm_api_field_changed)

            self.llm_maxtok_spin = QSpinBox()
            self.llm_maxtok_spin.setRange(0, 32768)
            self.llm_maxtok_spin.setSingleStep(256)
            self.llm_maxtok_spin.setSpecialValueText("auto")
            self.llm_maxtok_spin.setPrefix("Max ")
            self.llm_maxtok_spin.setToolTip("Max completion tokens (0 = server default / auto)")
            self.llm_maxtok_spin.valueChanged.connect(self._on_llm_api_field_changed)

            sg.addWidget(self.llm_temp_spin, 0, 0)
            sg.addWidget(self.llm_topp_spin, 0, 1)
            sg.addWidget(self.llm_maxtok_spin, 0, 2)
            g.addLayout(sg)

            srow_l = QHBoxLayout()
            srow_l.setSpacing(4)
            self.llm_stream_cb = QCheckBox("Live SSE Streaming")
            self.llm_stream_cb.setChecked(True)
            self.llm_stream_cb.setCursor(Qt.CursorShape.PointingHandCursor)
            self.llm_stream_cb.setToolTip("Stream tokens live via Server-Sent Events (uncheck for single-shot batch JSON)")
            self.llm_stream_cb.toggled.connect(self._on_llm_api_field_changed)
            srow_l.addWidget(self.llm_stream_cb, 1)
            srow_l.addWidget(make_button(
                "OPEN LLM \u25B8", lambda: self.tabs.setCurrentIndex(TAB_LLM), small=True,
                icon_key="tab_llm", icon_size=12,
                tip="Return to LLM Studio tab (Ctrl+5)",
            ))
            g.addLayout(srow_l)

            self.llm_settings_status = make_label(
                "Stored in data/llm_settings.json \u2022 shared by Forge, Vision (VLM) & Self-Improving Arena.",
                "Caption",
            )
            self.llm_settings_status.setWordWrap(True)
            g.addWidget(self.llm_settings_status)

        self.llm_api_settings_section = self._horde_group("LLM / VLM API Settings", build_llm_api, expanded=False)
        lay.addWidget(self.llm_api_settings_section)

        # ---- 3. AI Horde Account & Cluster ----
        def build_account(g: QVBoxLayout) -> None:
            self.key_label = ElideLabel()
            self.key_label.setObjectName("InfoBar")
            g.addWidget(self.key_label)
            self.account_label = make_label("Account not checked yet.", "Caption")
            self.account_label.setWordWrap(True)
            g.addWidget(self.account_label)
            r = QHBoxLayout()
            r.setSpacing(3)
            r.addWidget(make_button("ACCOUNT", self.check_account, small=True, accent=True, compress=True,
                                    tip="Query AI Horde /find_user for username & kudos"), 1)
            r.addWidget(make_button("RELOAD", self.reload_key, small=True, compress=True,
                                    tip="Re-read data/key.txt (picks up external edits)"), 1)
            r.addWidget(make_button("KEY.TXT", lambda: open_path(KEY_FILE), small=True, compress=True,
                                    tip="Open data/key.txt in your default editor"), 1)
            g.addLayout(r)

