        lay.addWidget(self._horde_group("AI Horde Account & Cluster", build_account, expanded=True))

        # ---- 4. Request Options ----
        def build_opts(g: QVBoxLayout) -> None:
            self.opt_checks: Dict[str, QCheckBox] = {}
            labels = [
                ("nsfw", "Enable NSFW (skip censoring workers)"),
                ("censor_nsfw", "Censor NSFW results"),
                ("replacement_filter", "Replace unsafe words"),
                ("shared", "Share images with Horde / LAION"),
                ("slow_workers", "Allow slow workers"),
                ("extra_slow_workers", "Allow extra-slow workers"),
                ("trusted_workers", "Trusted workers only"),
                ("validated_backends", "Validated backends only"),
                ("allow_downgrade", "Allow kudos downgrade"),
                ("disable_batching", "Disable worker batching"),
            ]
            for key, text in labels:
                cb = QCheckBox(text)
                cb.toggled.connect(lambda _v: self._schedule_save())
                self.opt_checks[key] = cb
                g.addWidget(cb)
            g.addWidget(make_button("RESET DEFAULTS", self.reset_options, small=True))

        lay.addWidget(self._horde_group("Request Options", build_opts, expanded=False))

        # ---- 5. Alchemy Interrogation ----
        def build_alch(g: QVBoxLayout) -> None:
            self.aesthetic_check = QCheckBox("Auto aesthetic score (Alchemy)")
            self.aesthetic_check.toggled.connect(lambda _v: self._schedule_save())
            g.addWidget(self.aesthetic_check)

        lay.addWidget(self._horde_group("Alchemy Interrogation", build_alch, expanded=False))

        # ---- 6. Browser Bridge (VPN Tunnel) ----
        def build_bridge(g: QVBoxLayout) -> None:
            self.bridge_check = QCheckBox("Route through browser VPN tunnel")
            self.bridge_check.toggled.connect(self._on_bridge_toggled)
            g.addWidget(self.bridge_check)
            bg = QGridLayout()
            bg.setSpacing(4)
            self.bridge_port_spin = QSpinBox()
            self.bridge_port_spin.setRange(1024, 65535)
            self.bridge_port_spin.setValue(BRIDGE_DEFAULT_PORT)
            self.bridge_port_spin.valueChanged.connect(self._on_bridge_port_changed)
            bg.addWidget(make_label("Port", "Caption"), 0, 0)
            bg.addWidget(self.bridge_port_spin, 0, 1)
            bg.setColumnStretch(1, 1)
            g.addLayout(bg)
            self.bridge_note = make_label(
                "Tokenless — connection itself is the credential. Install the companion "
                "horde_studio_bridge.user.js (shipped beside this .py) in Tampermonkey, "
                "then open https://stablehorde.net/ and keep that tab open: every AI "
                "Horde request then rides your browser, so VPN extensions apply.", "Caption"
            )
            self.bridge_note.setWordWrap(True)
            g.addWidget(self.bridge_note)
            self.bridge_status = make_label("Off.", "Value")
            self.bridge_status.setWordWrap(True)
            g.addWidget(self.bridge_status)

        lay.addWidget(self._horde_group("Browser Bridge (VPN Tunnel)", build_bridge, expanded=False))

        # ---- 7. SillyTavern Local Server ----
        def build_st(g: QVBoxLayout) -> None:
            self.st_check = QCheckBox("Run local A1111 server (SillyTavern)")
            self.st_check.toggled.connect(self._on_st_toggled)
            g.addWidget(self.st_check)
            sg = QGridLayout()
            sg.setSpacing(4)
            self.st_port_spin = QSpinBox()
            self.st_port_spin.setRange(1024, 65535)
            self.st_port_spin.setValue(ST_DEFAULT_PORT)
            self.st_port_spin.valueChanged.connect(self._on_st_port_changed)
            self.st_url_edit = QLineEdit()
            self.st_url_edit.setReadOnly(True)
            sg.addWidget(make_label("Port", "Caption"), 0, 0)
            sg.addWidget(self.st_port_spin, 0, 1)
            sg.addWidget(make_label("Address", "Caption"), 1, 0)
            sg.addWidget(self.st_url_edit, 1, 1)
