        self.edit_dfx_sliders: Dict[str, QSlider] = {}
        self.edit_dfx_vals: Dict[str, QLabel] = {}

        def _add_dfx_group(title: str, specs: Sequence[Tuple[str, str, int, int, int, str, str]]) -> QVBoxLayout:
            gw = QWidget()
            gw.setObjectName("Transparent")
            gl_inner = QVBoxLayout(gw)
            gl_inner.setContentsMargins(0, 2, 0, 2)
            gl_inner.setSpacing(3)
            ggrid = QGridLayout()
            ggrid.setHorizontalSpacing(6)
            ggrid.setVerticalSpacing(2)
            for idx_s, (fk, flbl, flo, fhi, fdef, fsuf, ftip) in enumerate(specs):
                r_p, c_p = divmod(idx_s, 2)
                cell = QVBoxLayout()
                cell.setSpacing(0)
                lr = QHBoxLayout()
                lr.setSpacing(2)
                fl_e = ElideLabel(flbl)
                fl_e.setObjectName("Kicker")
                lr.addWidget(fl_e, 1)
                vl = make_label(f"{fdef}{fsuf}", "Value")
                vl.setAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
                lr.addWidget(vl, 0)
                sl = _ResettableSlider(Qt.Orientation.Horizontal, default_value=fdef)
                sl.setMinimumWidth(0)
                sl.setRange(flo, fhi)
                sl.setValue(fdef)
                sl.setCursor(Qt.CursorShape.PointingHandCursor)
                sl.setToolTip(ftip)
                sl.valueChanged.connect(lambda v, k=fk, suf=fsuf: self._on_depth_fx_slider(k, v, suf))
                cell.addLayout(lr)
                cell.addWidget(sl)
                ggrid.addLayout(cell, r_p, c_p)
                self.edit_dfx_sliders[fk] = sl
                self.edit_dfx_vals[fk] = vl
            ggrid.setColumnStretch(0, 1)
            ggrid.setColumnStretch(1, 1)
            gl_inner.addLayout(ggrid)
            sec = CollapsibleSection(title, gw, expanded=(title.startswith("Lens Bokeh")))
            dwl.addWidget(sec)
            return gl_inner

        # Group 1: Lens Bokeh DOF
