            ("dof_focus", "Focus Plane", 0, 100, 68, "%", "Sharp focal plane depth (100%=near, 0%=far · use D eyedropper!)"),
            ("dof_aperture", "Focal Width", 5, 80, 24, "%", "Depth-of-field width kept tack-sharp"),
            ("dof_bokeh_bloom", "Bokeh Bloom", 0, 100, 25, "%", "Creamy specular highlight expansion in blurred lights"),
