        self.edit_dfx_rim_swatch = QToolButton()
        self.edit_dfx_rim_swatch.setObjectName("Small")
        self.edit_dfx_rim_swatch.setFixedSize(34, 20)
        self.edit_dfx_rim_swatch.setCursor(Qt.CursorShape.PointingHandCursor)
