        def _flow_page() -> Tuple[QWidget, FlowLayout]:
            pg = QWidget()
            pg.setObjectName("Transparent")
            fl_lay = FlowLayout(pg, margin=0, spacing=4)
            return pg, fl_lay

        def _add_flow_sliders(
            fl_lay: FlowLayout,
            items: Sequence[Tuple[str, str, int, int, int, str]],
        ) -> Tuple[Dict[str, QSlider], Dict[str, QLabel]]:
            sliders: Dict[str, QSlider] = {}
            labels: Dict[str, QLabel] = {}
            for key, title, lo, hi, val, tip in items:
                grp = QWidget()
                grp.setObjectName("Transparent")
                gl_s = QHBoxLayout(grp)
                gl_s.setContentsMargins(0, 0, 2, 0)
                gl_s.setSpacing(3)
                gl_s.addWidget(make_label(title, "Kicker"))
                s = QSlider(Qt.Orientation.Horizontal)
                s.setRange(lo, hi)
                s.setValue(val)
                s.setFixedWidth(74)
                s.setCursor(Qt.CursorShape.PointingHandCursor)
                s.setToolTip(tip)
                vlab = make_label(str(val), "Value")
                vlab.setMinimumWidth(28)
                gl_s.addWidget(s)
                gl_s.addWidget(vlab)
                fl_lay.addWidget(grp)
                sliders[key] = s
                labels[key] = vlab
            return sliders, labels

        # -- page 0: NAV ------------------------------------------------------
        page_nav = QWidget()
        page_nav.setObjectName("Transparent")
        nl = QHBoxLayout(page_nav)
        nl.setContentsMargins(0, 1, 0, 1)
